ClinicalChunks.register("data/templates-089.js",[{"id":"templates-9c4b87cfdec557225a18","key":"v1-c9ccc21dfe2a3058|templates-9c4b87cfdec557225a18","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"毒蘑菇中毒","category":"院前急救","raw":{"name":"毒蘑菇中毒","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胃肠炎型：恶心呕吐、腹痛腹泻（进食后0.5-3h）、肝损害型（鹅膏类）：早期胃肠炎，假愈期后出现黄疸、肝衰竭、出血（6-48h）、神经精神型：幻觉、谵妄、抽搐、瞳孔缩小/扩大（0.5-6h）、溶血型：腰痛、酱油色尿、贫血、黄疸（6-12h）、光敏皮炎型：日晒后皮肤红肿。\n【待人工确认·本机素材无此段原文】","现病史":"误食毒蘑菇可致胃肠炎、肝坏死（鹅膏毒肽）、溶血、神经精神症状、光敏性皮炎等。鹅膏类（白毒伞）中毒病死率高。\n常见表现：胃肠炎型：恶心呕吐、腹痛腹泻（进食后0.5-3h）、肝损害型（鹅膏类）：早期胃肠炎，假愈期后出现黄疸、肝衰竭、出血（6-48h）、神经精神型：幻觉、谵妄、抽搐、瞳孔缩小/扩大（0.5-6h）、溶血型：腰痛、酱油色尿、贫血、黄疸（6-12h）、光敏皮炎型：日晒后皮肤红肿。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 血常规＋肝肾功能＋电解质＋凝血功能（PT/APTT）＋心肌酶谱：急诊必查组合，尽早采血送检；高度怀疑肝毒性型（鹅膏肽类毒素）者4-6小时复查肝功能（ALT/AST/胆红素）动态观察\n2. 血气分析＋血乳酸：评估代谢性酸中毒及组织灌注，伴呕吐腹泻、脱水表现者必查，可反复复查\n3. 毒物检测：留取呕吐物、胃内容物及剩余蘑菇样本送毒检/送疾控鉴定，为诊断和解毒治疗提供依据\n4. 心电图＋心肌损伤标志物（肌钙蛋白I）：排查心律失常、心肌损伤及阿托品样症状相关表现\n5. 腹部CT平扫：腹痛剧烈、淀粉酶升高或症状与体征不符时行急诊检查，与急性胰腺炎、肠梗阻等急腹症鉴别\n6. 尿常规＋记录每小时尿量：评估肾损伤（毒伞肽可致急性肾衰竭），尿量减少时及时报告","初步诊断":"1. 食用野生蘑菇史（同食者多人发病是重要线索）\n2. 胃肠炎症状+肝损害/神经症状/溶血\n3. 毒蘑菇鉴定（保留剩余蘑菇或呕吐物）\n4. 肝功能异常（鹅膏类）\n5. 凝血功能异常\n6. 贫血、网织红细胞升高（溶血型）\n1. 毒蘑菇中毒（ICD-10：T62.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%氯化钠/5%葡萄糖 静滴（补液促排）\n\n方案2：\n 用法：阿托品 0.5-1mg 静推（毒蕈碱样症状：流涎、瞳孔缩小、多汗）\n\n方案3：\n 用法：5%二巯丙磺钠 0.125g 肌注（鹅膏类中毒，螯合解毒）\n\n方案4：\n 用法：水飞蓟素/水飞蓟宾 静滴（鹅膏类肝损害）\n\n方案5：\n 用法：青霉素G（大剂量，竞争白蛋白结合，鹅膏类）\n\n方案6：\n 用法：N-乙酰半胱氨酸（NAC，肝损害）\n\n方案7：\n 用法：地塞米松 10-20mg 静滴（溶血、中毒性心肌炎）\n\n方案8：\n 用法：甘露醇（脑水肿）\n\n方案9：\n 用法：5%碳酸氢钠（碱化尿液，溶血型）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：活性炭 50-100g（吸附）\n\n药物2：\n 用法：蒙脱石散\n\n药物3：\n 用法：硫酸镁/甘露醇导泻\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即催吐、洗胃（1:5000高锰酸钾或浓茶）\n活性炭吸附+导泻\n补液、纠正电解质紊乱\n阿托品（毒蕈碱型）\n二巯丙磺钠+水飞蓟素（鹅膏类肝损害）\n血液灌流/血浆置换（重症）\n保肝治疗\n溶血型：激素+碱化尿液+输血\n神经精神型：对症（地西泮控制抽搐）\n肝衰竭：人工肝/肝移植\n\n【处理要点】\n保留剩余蘑菇或拍照（帮助鉴定）\n立即催吐（清醒者），1:5000高锰酸钾或浓茶洗胃\n活性炭50-100g胃管注入+甘露醇导泻\n建立静脉通路，补液纠正脱水和电解质\n阿托品0.5-1mg静推（毒蕈碱样症状：流涎、多汗、瞳孔缩小、心动过缓）\n鹅膏类（白毒伞等）：二巯丙磺钠+水飞蓟宾+大剂量青霉素G+NAC\n监测肝功能、凝血、肾功能、血常规、心肌酶\n溶血型：地塞米松+碳酸氢钠碱化尿液+输血\n抽搐：地西泮\n重症尽早血液灌流/血浆置换\n注意假愈期（鹅膏类胃肠炎症状缓解后1-2天突发肝衰竭），必须住院观察至少1周\n同食者无论有无症状均应就医\n\n【护理】\n尽快配合洗胃：发病6小时内（越早越好）用温清水或1:5000高锰酸钾液洗胃，头偏向一侧防误吸；洗胃后注入活性炭混悬液并硫酸镁导泻；昏迷或呼吸抑制者先配合气管插管保护气道再洗胃\n持续心电监护＋血氧饱和度监测，每15-30分钟记录生命体征，重点观察血压下降、心率增快、呼吸浅促等休克及呼吸衰竭征象\n密切观察意识、瞳孔变化及黄疸、少尿（＜400ml/24h）、呕血、黑便等肝肾功能损伤表现，警惕潜伏期后急性肝衰竭，发现异常立即通知医生\n快速建立两条≥18G静脉通路，按医嘱予平衡液扩容，准确记录出入量，纠正低血容量性休克；提前备好阿托品、抗毒血清及血液净化（血液灌流/血浆置换）物品，配合抢救\n呕吐物、排泄物统一处理并留样送检，做好隔离防护；向家属交代本病潜伏期长，须留观至少24-48小时\n\n【饮食】\n洗胃后禁食水2-4小时，确认无活动性消化道出血后再逐步进食\n恢复进食后予温凉流质（米汤、藕粉、稀粥），少量多餐，忌牛奶、豆浆等易产气食物及高脂饮食，以免加重毒素吸收\n急性期绝对禁酒及含酒精饮品，减轻肝脏负担、避免加重肝损伤\n肝损伤型患者行低脂、适量优质蛋白饮食，配合保肝治疗；恢复期（1-3天）渐过渡至清淡半流质，忌辛辣刺激，补充维生素C、B族\n口服补液盐或静脉补液维持水电解质平衡，呕吐腹泻剧烈者以静脉补液为主，待症状缓解后鼓励少量多次口服\n\n【注意事项】\n鹅膏类（白毒伞）中毒有假愈期，不要因症状缓解而停止治疗\n同食者均需医学观察\n毒蘑菇鉴定很重要，保留样本\n阿托品仅用于毒蕈碱样症状，不是所有毒蘑菇中毒都用\n肝损害型病死率高，需积极治疗\n\n【急诊/急救】\n保留剩余蘑菇/呕吐物样本（或拍照）\n立即催吐，1:5000高锰酸钾/浓茶洗胃\n活性炭50-100g胃管注入+甘露醇导泻\n建立静脉通路补液纠正电解质\n毒蕈碱样症状（流涎、瞳孔缩小、多汗）：阿托品0.5-1mg静推\n鹅膏类肝损害型：二巯丙磺钠0.125g肌注+水飞蓟宾+大剂量青霉素G+NAC\n监测肝肾功能、凝血、血常规、心肌酶\n溶血型：地塞米松+碳酸氢钠碱化尿液+输血\n重症尽早血液灌流/血浆置换\n同食者均需就医，鹅膏类需住院观察至少1周（假愈期）","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T62.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2489,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fb9a1e0ba65de1553eea50ce92e2a613fb765552f7a5dae9935dd5003c4adcdc","pinyin":"dumoguzhongdu","initials":"dmgzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T62.0",30]]},{"id":"templates-5728204569fdd51d9acd","key":"v1-c9ccc21dfe2a3058|templates-5728204569fdd51d9acd","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"毒鼠强中毒(氟乙酰胺类)","category":"中毒/理化","raw":{"name":"毒鼠强中毒(氟乙酰胺类)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】潜伏期短（10分钟-1小时），口服后迅速出现症状、神经系统：头痛头晕、乏力、口唇麻木、烦躁不安、意识模糊、典型表现：反复癫痫大发作（全身强直性阵挛抽搐、口吐白沫、意识丧失、大小便失禁）、抽搐持续状态可导致呼吸肌痉挛、窒息、发绀、消化系统：恶心呕吐、上腹部烧灼感、腹痛、心血管系统：心悸、胸闷、心律失常、血压升高或下降、严重者：昏迷、呼吸衰竭、心力衰竭、多器官功能衰竭、精神症状：部分患者恢复期出现幻觉、妄想等精神障碍。\n【待人工确认·本机素材无此段原文】","现病史":"毒鼠强（化学名四亚甲基二砜四胺；商品名没鼠命、四二四、三步倒）是剧毒灭鼠药。注意：毒鼠强并非氟乙酰胺类鼠药，无特效解毒剂，与氟乙酰胺（可用乙酰胺/解氟灵）不同，两者勿混淆，化学性质稳定，不易降解。主要兴奋中枢神经系统，引起反复癫痫大发作，可致死。无特效解毒剂，以控制抽搐+血液净化为主。\n常见表现：潜伏期短（10分钟-1小时），口服后迅速出现症状、神经系统：头痛头晕、乏力、口唇麻木、烦躁不安、意识模糊、典型表现：反复癫痫大发作（全身强直性阵挛抽搐、口吐白沫、意识丧失、大小便失禁）、抽搐持续状态可导致呼吸肌痉挛、窒息、发绀、消化系统：恶心呕吐、上腹部烧灼感、腹痛、心血管系统：心悸、胸闷、心律失常、血压升高或下降、严重者：昏迷、呼吸衰竭、心力衰竭、多器官功能衰竭、精神症状：部分患者恢复期出现幻觉、妄想等精神障碍。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 毒物检测：血液、尿液毒鼠强及氟乙酰胺定性/定量检测（GC-MS），洗胃后留取胃内容物同步送检，明确毒物种类与浓度，评估中毒严重程度\n2. 动脉血气分析：入院即刻及抽搐发作期、患者地西泮/苯巴比妥后动态复查，评估低氧血症与酸碱失衡\n3. 血电解质（K⁺、Na⁺、Cl⁻、Ca²⁺）及心肌酶谱：动态复查，警惕低钾、低钙血症及心肌损伤\n4. 心电图（12导联）：入院即刻及用药期间动态监测，观察心律失常、QT间期延长及ST-T改变\n5. 肝肾功能、凝血功能：入院后及乙酰胺（解氟灵）用药期间定期复查，评估脏器损伤及药物影响\n6. 头颅CT/脑电图：反复或难控制抽搐者完善检查，排除脑器质性病变并评估中毒性脑损伤程度","初步诊断":"1. 毒鼠强服用/接触史（白色粉末/颗粒，常拌在食物中）\n2. 典型反复癫痫大发作，常规抗癫痫药效果不佳\n3. 血/尿/呕吐物/食物中检出毒鼠强（气相色谱/质谱）\n4. 脑电图：癫痫样放电\n5. 心肌酶升高（CK、CK-MB、LDH）\n6. 白细胞升高，肝肾功能异常（严重者）\n1. 毒鼠强中毒(氟乙酰胺类)（ICD-10：T60.4）","鉴别诊断":"1. 注意：毒鼠强并非氟乙酰胺类鼠药，无特效解毒剂，与氟乙酰胺（可用乙酰胺/解氟灵）不同，两者勿混淆，化学性质稳定，不易降解\n2. 诊断要点：毒鼠强服用/接触史（白色粉末/颗粒，常拌在食物中）\n3. 诊断要点：典型反复癫痫大发作，常规抗癫痫药效果不佳\n4. 诊断要点：血/尿/呕吐物/食物中检出毒鼠强（气相色谱/质谱）\n5. 诊断要点：脑电图：癫痫样放电\n6. 诊断要点：心肌酶升高（CK、CK-MB、LDH）\n7. 诊断要点：白细胞升高，肝肾功能异常（严重者）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：地西泮 10-20mg缓慢静注（抽搐时），必要时15-30分钟重复，24小时总量不超过100mg\n\n方案2：\n 用法：丙戊酸钠 0.4g静滴 q8h（维持抗癫痫）\n\n方案3：\n 用法：苯巴比妥钠 0.1-0.2g肌注 q6-8h（与地西泮交替）\n\n方案4：\n 用法：20%甘露醇 125-250ml静滴 q6-8h（脑水肿）\n\n方案5：\n 用法：呋塞米 20-40mg静注（促进排泄）\n\n方案6：\n 用法：维生素B6 1-2g静滴（辅助，促进脑代谢）\n\n方案7：\n 用法：纳洛酮 0.4-0.8mg静注（意识障碍时）\n\n方案8：\n 用法：5%碳酸氢钠 静滴（纠正酸中毒）\n\n方案9（营养心肌药物）：\n 用法：极化液、维生素C等\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：丙戊酸钠片 0.2-0.4g tid（恢复期维持抗癫痫）\n\n药物2：\n 用法：苯巴比妥片 30-60mg tid（维持）\n\n药物3：\n 用法：维生素B6片 10mg tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（清水/1:5000高锰酸钾），洗胃后活性炭30-50g吸附，硫酸钠导泻\n控制抽搐是首要任务：地西泮静注，无效时丙泊酚/咪达唑仑静脉泵入\n苯巴比妥钠肌注与地西泮交替使用\n保持呼吸道通畅，吸氧，抽搐持续状态时气管插管机械通气\n尽早行血液灌流（HP），可有效清除毒鼠强，重度者可多次灌流\n对症支持：降颅压、营养心肌、保护肝肾、纠正水电解质紊乱\n防治感染，维持内环境稳定\n精神症状明显者给予抗精神病药物\n恢复期进行康复治疗和心理疏导\n\n【处理要点】\n口服者立即刺激咽喉催吐，尽快送医洗胃\n抽搐发作时：将患者平卧，头偏向一侧，解开衣领，清除口鼻分泌物，防止舌咬伤（用牙垫/毛巾）\n不要强行按压抽搐肢体，防止骨折\n保持呼吸道通畅，防止窒息和误吸\n记录抽搐开始时间、持续时间、发作频率\n保留剩余毒饵、呕吐物送检\n抽搐频繁者需专人看护，防止坠床和意外伤害\n严密监测生命体征、血氧饱和度、意识状态\n\n【护理】\n洗胃配合：中毒后6小时内尽早彻底洗胃，用温清水或活性炭混悬液反复冲洗至洗出液澄清，洗胃后经胃管注入活性炭50g吸附残余毒物，遵医嘱予甘露醇导泻；洗胃时头偏一侧、防误吸\n解毒剂观察：遵医嘱静滴乙酰胺（解氟灵）2.5~5g，每日2~4次（重症首剂加倍），观察有无注射部位红肿、过敏反应，用药期间配合监测肝肾功能\n生命体征与抽搐监测：持续心电监护心率、血压、血氧饱和度，重点记录抽搐发作的频率、持续时间及发作时意识、瞳孔变化；床旁备开口器、压舌板、吸痰装置及地西泮等止痉药物\n气道管理：抽搐发作时立即头偏向一侧，及时吸除口鼻分泌物，防舌后坠及误吸窒息；抽搐难以控制或气道不畅者配合气管插管、机械通气\n并发症观察：记录24小时出入量，观察尿量变化警惕急性肾损伤；观察呕血、黑便等应激性溃疡表现；加床栏、约束保护防坠床与自伤\n\n【饮食】\n洗胃后暂禁食水4~6小时，观察有无恶心、呕吐、腹痛及消化道出血（洗胃损伤、应激性溃疡），确认平稳后再逐步恢复进食\n恢复进食初期予温凉流质（米汤、藕粉、无渣果汁），少量多餐，每2~3小时一次，每次100~200ml\n病情稳定后过渡至半流质、软食（粥、烂面条、蛋羹），避免粗糙、辛辣、过冷过热及油腻食物刺激胃黏膜\n保证充足补液：不能口服者遵医嘱静脉补液（平衡液、葡萄糖液）维持水电解质平衡，可口服者少量多次温水促进毒物排泄\n抽搐频繁或意识障碍期间予静脉营养支持，暂不口服进食以防误吸；忌浓茶、咖啡、酒精及碳酸饮料\n\n【注意事项】\n毒鼠强剧毒，人口服致死量约0.1-0.2mg/kg，无特效解毒剂\n毒鼠强化学性质稳定，可造成二次中毒（猫/狗吃了中毒老鼠也会中毒）\n控制抽搐是抢救成功的关键，地西泮+苯巴比妥联合效果好\n血液灌流是最有效的清除手段，应尽早进行，可重复\n毒鼠强排泄慢，可在体内存留数月，需长期随访\n国家已明令禁止生产、销售、使用毒鼠强\n恢复期可能出现精神症状，需精神科干预\n\n【急诊/急救】\n立即催吐，尽快清水/高锰酸钾洗胃\n抽搐发作时保持呼吸道通畅，防止舌咬伤\n地西泮10-20mg缓慢静注，必要时重复\n苯巴比妥钠0.1-0.2g肌注\n吸氧，发绀者人工呼吸\n尽快送医行血液灌流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「毒鼠强中毒(氟乙酰胺类)」原文）"},"icd10_diagnosis":"T60.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2490,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"70f43e83e50877412101e3dc84c483a4fb5f45f26061023d09fc1da5de1636a8","pinyin":"dushuqiangzhongdu(fuyixiananlei)","initials":"dsqzd(fyxal)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T60.4",30]]},{"id":"templates-c2642a1bc26becbd8bbc","key":"v1-c9ccc21dfe2a3058|templates-c2642a1bc26becbd8bbc","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"气管恶性肿瘤","category":"胸外科临床路径（2019年版）","raw":{"name":"气管恶性肿瘤","category":"胸外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、便常规+隐血试验；\r（2）凝血功能、血型、肝功能测定、肾功能测定、电解质、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）、相关肿瘤标志物检查；\r（3）动脉血气分析、心电图；\r（4）支气管镜＋活检（视患者耐受情况）；\r（5）影像学检查：胸部X线片、胸部CT增强扫描、腹部超声或CT。\r2.根据患者病情，可选择的项目：肺功能、超声心动图、CTPA、心肌核素扫描、动态心电图、24小时动态血压监测、喉镜、头颈部CT扫描、食管镜（食管造影）等；\r3.请麻醉科会诊决定气管插管方式，是否需要行体外循环。\r（七）预防性抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。如可疑感染，需做相应的微生物学检查，必要时做药敏试验。\r2.建议使用第一、二代头孢菌素。预防性用抗菌药物，时间为术前30分钟。\r（八）手术日为入院\n6天\r1.麻醉方式：全身麻醉，行气管插管或行体外循环。\r2.术中用药：抗菌药物。\r3.手术置入物：人工修复材料、止血材料。 \r4.输血：视手术出血情况决定。输血前需行血型鉴定、抗体筛选和交叉合血。\r（九）术后住院恢复应\n15天\r1.必须复查的检查项目：\r（1）血常规、肝功能测定、肾功能测定、电解质；\r（2）支气管镜、胸部X线。\r2.根据病情可选择胸部CT扫描。\r3.术后用药：抗菌药物使用按照《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。建议使用第一、二代头孢菌素。如可疑感染，需做相应的微生物学检查，必要时做药敏试验。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n胸外科分册》（中华医学会编著，人民卫生出版社，2009年）。\r1.临床症状：常见症状包括刺激性咳嗽，痰中带血或咯血，气短和呼吸困难，声音嘶哑，以及呼吸道感染症状等。其他症状包括气管肿瘤压迫食管引起吞咽困难、颈部肿块等。\r2.辅助检查：胸部X线平片，胸部增强CT、支气管镜检查及活检。\r（三）\n1. 气管恶性肿瘤（ICD-10：C33）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n胸外科分册》（中华医学会编著，人民卫生出版社，2009年）。\r行气管肿瘤切除+气管重建术。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10: C33气管恶性肿瘤疾病编码。\r2.当患者同时具有其他疾病诊断，但在门诊治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备\n5天\r1.","临床路径·标准住院日":"标准住院日为\n21天\r（五）","临床路径·出院标准":"出院标准\r1.患者病情稳定，体温正常，手术切口愈合良好，生命体征平稳。\r2.无需要住院处理的并发症和（或）合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.有影响手术的合并症，术前需要进行相关的诊断和治疗。\r2.术后出现肺部感染、呼吸功能衰竭、心脏功能衰竭、肝肾功能衰竭、吻合口瘘等并发症，需要延长治疗时间。\r\f二、气管恶性肿瘤","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 胸外科临床路径（2019年版） · 气管恶性肿瘤临床路径（2019年版）.doc"},"icd10_diagnosis":"C33","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2491,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"280362e7f5e67118e57a8d15d1aa44a23162ba9bca8286bd5a2dca33bc2cbbec","pinyin":"qiguanexingzhongliu","initials":"qgexzl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","C33",30]]},{"id":"templates-e2dcb32255541a51ea1d","key":"v1-c9ccc21dfe2a3058|templates-e2dcb32255541a51ea1d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"气道异物梗阻","category":"院前急救","raw":{"name":"气道异物梗阻","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发剧烈呛咳、呼吸困难、喘鸣、面色发绀、双手抓喉（V字征）、无法说话/咳嗽、意识丧失。\n【待人工确认·本机素材无此段原文】","现病史":"异物卡喉导致气道阻塞，表现为突发呛咳、呼吸困难、发绀，严重者数分钟内窒息死亡。海姆立克急救法是首选。\n常见表现：突发剧烈呛咳、呼吸困难、喘鸣、面色发绀、双手抓喉（V字征）、无法说话/咳嗽、意识丧失。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 床旁血气分析：即刻进行，评估低氧血症、CO₂潴留及酸碱失衡程度\n2. 脉搏血氧饱和度监测：持续动态监测，判断梗阻所致缺氧及复苏效果\n3. 胸部X线（正侧位）：用于金属、骨骼等不透X线异物定位，评估肺不张、阻塞性肺气肿及并发症\n4. 喉镜/支气管镜检查：急诊解除梗阻后24小时内明确异物部位、大小并取出，同时可取样培养\n5. 心电图：排除因严重缺氧、误吸诱发的心律失常及心脏骤停\n6. 血常规、C反应蛋白：评估炎症反应，警惕异物滞留继发感染","初步诊断":"1. 目击误吸史\n2. 突发呼吸困难伴呛咳\n3. V字征典型表现\n4. 听诊一侧呼吸音减弱\n5. 严重者发绀、意识障碍\n1. 气道异物梗阻（ICD-10：T17.9）","鉴别诊断":"1. 诊断要点：突发呼吸困难伴呛咳\n2. 诊断要点：V字征典型表现\n3. 诊断要点：听诊一侧呼吸音减弱\n4. 诊断要点：严重者发绀、意识障碍\n5. 海姆立克法可能导致内脏损伤，需告知\n6. 不要盲目用手指抠挖（可能将异物推深）\n7. 梗阻解除后仍需胸片检查\n8. 儿童勿给坚果、果冻等易呛食物","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%氯化钠注射液 250ml 静滴 建立通路\n\n方案2：\n 用法：意识丧失者按心肺复苏流程处理\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：无口服药物，以物理排出为主\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n解除气道梗阻\n吸氧、监护\n必要时环甲膜穿刺/气管切开\n防治并发症（肺炎、肺不张）\n\n【处理要点】\n识别气道异物梗阻（V字征）\n清醒者：海姆立克法（腹部冲击5次）\n肥胖/孕妇：胸部冲击5次\n婴儿：背部拍击5次+胸部按压5次交替\n意识丧失：立即CPR，每次通气前查看口腔\n异物排出后仍需就医检查\n环甲膜穿刺：梗阻无法解除且濒临窒息时\n\n【护理】\n急救配合：立即协助实施海姆立克法（立位腹部冲击）或胸部冲击法，儿童改用拍背压胸法；意识丧失者协助行CPR并配合喉镜直视下取异物，全程备好负压吸引、环甲膜穿刺及气管切开器械\n气道管理：保持头低足高位、侧卧位，及时吸出口腔及咽部分泌物与异物碎屑，确保气道通畅；喉头水肿严重或取物困难时协助建立紧急气道（环甲膜穿刺/气管切开）\n病情观察：持续监测呼吸频率、节律、三凹征、口唇发绀及血氧饱和度，动态评估呼吸困难程度，发现窒息先兆立即呼叫抢救\n生命体征监测：持续心电监护、血压及体温，警惕缺氧后心律失常、心跳骤停及吸入性肺炎的发生\n液体管理：静脉留置针建立双通道快速补液，维持循环稳定，遵医嘱给予糖皮质激素（抗炎消肿）及抗生素预防感染\n\n【饮食】\n急性期：明确异物取出后仍需禁食禁水6小时，确认无喉头水肿、呛咳及吞咽障碍后再开始进食\n恢复期饮食：先从温凉流质（米汤、稀藕粉）开始，少量多餐，逐步过渡至半流质、软食，避免过热刺激喉部\n忌口：2周内避免坚果、果冻、带骨刺鱼类、黏性食物（年糕、汤圆）及碳酸饮料，防止再发误吸\n进食体位：进食时取坐位或半坐卧位，细嚼慢咽，进食中避免说话、大笑、跑动\n补液：吞咽功能恢复前经静脉补液维持水电解质平衡，记录出入量，防止脱水\n\n【注意事项】\n海姆立克法可能导致内脏损伤，需告知\n不要盲目用手指抠挖（可能将异物推深）\n梗阻解除后仍需胸片检查\n儿童勿给坚果、果冻等易呛食物\n\n【急诊/急救】\n立即识别V字征，询问'你卡到了吗？'\n清醒成人/儿童：站于身后，拳头置于脐上两横指，快速向上向内冲击5次\n孕妇/肥胖者：胸骨中部向后冲击5次\n婴儿（<1岁）：俯卧于前臂，掌根拍背5次→翻转胸部按压5次，交替进行\n每次冲击后检查异物是否排出\n意识丧失：立即平放，开始CPR（30:2），每次人工呼吸前看口腔有无异物\n上述无效且濒死者：粗针头环甲膜穿刺（颈前正中、环状软骨与甲状软骨之间）\n持续吸氧，急送耳鼻喉科/支气管镜取异物","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「气道异物梗阻」原文）"},"icd10_diagnosis":"T17.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2492,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8eee0b0da3a2702aaeb9dc4f811fc6fb5f2457e5fcadf21b64de47237c2d2771","pinyin":"qidaoyiwugengzu","initials":"qdywgz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T17.9",30]]},{"id":"templates-f260f75bc68e2a8d63c1","key":"v1-c9ccc21dfe2a3058|templates-f260f75bc68e2a8d63c1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"氨茶碱中毒","category":"中毒/理化","raw":{"name":"氨茶碱中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】消化系统：恶心、呕吐（可呈咖啡色）、腹痛、腹泻、呕血、便血、神经系统：头痛、头晕、烦躁不安、失眠、震颤、腱反射亢进、严重者：抽搐、癫痫大发作、昏迷、脑水肿、心血管系统：心悸、心动过速、心律失常（室早、室速、室颤）、血压下降、呼吸系统：呼吸急促，严重者呼吸衰竭、泌尿系统：蛋白尿、血尿、急性肾衰、代谢紊乱：低钾血症、高血糖、代谢性酸中毒、静脉推注过快可引起心律失常、血压骤降、猝死、严重者可因室颤、呼吸循环衰竭死亡。\n【待人工确认·本机素材无此段原文】","现病史":"氨茶碱是常用平喘药，治疗窗窄（有效血药浓度10-20μg/ml，>20μg/ml即可中毒）。过量或静脉推注过快可引起严重心律失常、抽搐、甚至猝死。无特效解毒剂，以对症支持+血液净化为主。\n常见表现：消化系统：恶心、呕吐（可呈咖啡色）、腹痛、腹泻、呕血、便血、神经系统：头痛、头晕、烦躁不安、失眠、震颤、腱反射亢进、严重者：抽搐、癫痫大发作、昏迷、脑水肿、心血管系统：心悸、心动过速、心律失常（室早、室速、室颤）、血压下降、呼吸系统：呼吸急促，严重者呼吸衰竭、泌尿系统：蛋白尿、血尿、急性肾衰、代谢紊乱：低钾血症、高血糖、代谢性酸中毒、静脉推注过快可引起心律失常、血压骤降、猝死、严重者可因室颤、呼吸循环衰竭死亡。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 茶碱血药浓度监测（治疗窗10-20μg/mL，>20μg/mL提示中毒，急诊抽血送检，作为诊断与疗效判断核心依据）\n2. 动脉血气分析（评估酸碱失衡与低氧血症，呼吸性碱中毒/代谢性酸中毒均可出现，监测呼吸性碱中毒及抽搐后缺氧）\n3. 血电解质（重点钾、钠、氯，氨茶碱致低钾血症常见，需反复复查并监测补钾效果）\n4. 12导联心电图（持续心电监护，警惕室上速、房颤、室速/室颤等恶性心律失常）\n5. 肝肾功能+血糖（氨茶碱经肝代谢、肾排泄，评估代谢清除能力；注意高血糖及乳酸升高）\n6. 血常规、凝血功能及心肌酶（排除合并感染、评估DIC风险及心肌损伤）","初步诊断":"1. 氨茶碱过量服用或静脉推注过快史\n2. 典型症状（恶心呕吐、烦躁、心悸、抽搐、心律失常）\n3. 血药浓度测定>20μg/ml（中毒），>40μg/ml严重中毒\n4. 心电图：窦性心动过速、室性早搏、室速、室颤、QT间期延长\n5. 电解质：低钾血症、高血糖\n6. 血气分析：代谢性酸中毒\n7. 排除其他原因心律失常、抽搐\n1. 氨茶碱中毒（ICD-10：T48.1）","鉴别诊断":"1. 排除其他原因心律失常、抽搐\n2. 诊断要点：氨茶碱过量服用或静脉推注过快史\n3. 诊断要点：典型症状（恶心呕吐、烦躁、心悸、抽搐、心律失常）\n4. 诊断要点：血药浓度测定>20μg/ml（中毒），>40μg/ml严重中毒\n5. 诊断要点：心电图：窦性心动过速、室性早搏、室速、室颤、QT间期延长\n6. 诊断要点：电解质：低钾血症、高血糖\n7. 诊断要点：血气分析：代谢性酸中毒","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：洗胃后活性炭30-50g灌胃（吸附，可反复使用）\n\n方案2：\n 用法：生理盐水/林格液 静滴（补液，维持血压）\n\n方案3：\n 用法：氯化钾 静滴（纠正低钾血症，注意监测）\n\n方案4：\n 用法：地西泮 10-20mg静注（抽搐时）\n\n方案5：\n 用法：苯巴比妥钠 0.1-0.2g肌注（抗抽搐，与地西泮交替）\n\n方案6（抗心律失常药）：\n 用法：利多卡因（室性心律失常）、β受体阻滞剂（心动过速，无禁忌时）\n\n方案7：\n 用法：奥美拉唑 40mg静注（保护胃黏膜，止血）\n\n方案8：\n 用法：20%甘露醇 125ml静滴（脑水肿时）\n\n方案9：\n 用法：碳酸氢钠（纠正酸中毒）\n\n方案10：\n 用法：升压药（低血压时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：活性炭（口服吸附）\n\n药物2：\n 用法：氯化钾片（纠正低钾）\n\n药物3：\n 用法：奥美拉唑胶囊（胃黏膜保护）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（温水），洗胃后活性炭30-50g吸附，硫酸钠导泻\n活性炭可反复使用（每2-4小时一次，每次20-30g），加速茶碱清除\n静脉补液，纠正水电解质紊乱（尤其低钾血症）\n控制抽搐：地西泮+苯巴比妥钠\n抗心律失常：利多卡因治疗室性心律失常，β受体阻滞剂治疗心动过速（无禁忌时）\n对症支持：保护胃黏膜、降颅压、纠正酸中毒、维持血压\n严重中毒者尽早行血液灌流（HP）或血液透析（HD），可有效清除茶碱\n持续心电监护，监测血药浓度、电解质、血气\n呼吸衰竭者机械通气\n禁用：肾上腺素、异丙肾上腺素（加重心律失常）\n\n【处理要点】\n口服者立即催吐，尽快送医洗胃\n让患者平卧，保持安静，减少刺激（避免诱发抽搐）\n监测心率、血压、呼吸、意识状态\n记录服药剂量、时间、给药途径\n抽搐发作时保持呼吸道通畅，防止舌咬伤\n心悸者做心电图检查\n静脉给药时必须稀释后缓慢滴注，严禁推注\n长期使用氨茶碱者应定期监测血药浓度\n老年人、肝肾功能不全者、心衰者剂量应减少\n\n【护理】\n洗胃配合：中毒6小时内或服药量大者尽早催吐/洗胃，清醒者取左侧卧位防误吸，昏迷者洗胃前先气管插管保护气道\n解毒剂与活性炭观察：遵医嘱予活性炭（成人50g）反复口服或鼻饲吸附毒物，配合硫酸镁导泻，观察排便及活性炭排出情况\n血液净化护理：重度中毒（血药浓度>60μg/mL或伴恶性心律失常、反复抽搐）配合血液灌流/血液透析，观察管路通畅、血压及出血倾向\n生命体征与心律监测：持续心电监护，警惕室速/室颤，备好除颤仪及利多卡因、胺碘酮；密切观察心率、血压、呼吸\n气道与抽搐护理：床旁备吸引器与口咽通气管，发生抽搐时防舌咬伤、防坠床，注意呼吸抑制与误吸\n\n【饮食】\n洗胃及活性炭治疗后暂禁食2-4小时，观察无恶心呕吐、无消化道出血后再进流质\n首餐给予温凉米汤、藕粉等清淡流质，少量多餐，逐步过渡至半流质、软食\n补充含钾丰富食物（香蕉、橙汁、土豆泥等），纠正低钾血症，需结合血钾复查结果调整\n忌浓茶、咖啡、可可、可乐等含咖啡因饮料及茶碱类药品，避免加重中枢兴奋与心律失常\n鼓励少量多次饮温开水促进药物排泄，同时观察尿量；呕吐剧烈者遵医嘱静脉补液维持水电解质平衡\n\n【注意事项】\n氨茶碱治疗窗窄，个体差异大，应监测血药浓度（10-20μg/ml）\n静脉推注过快是引起严重中毒和猝死的常见原因，必须稀释后缓慢滴注与红霉素、西咪替丁、氟喹诺酮类等合用可升高氨茶碱血药浓度，需减量\n低钾血症可加重心律失常，应积极纠正\n活性炭反复使用可显著增加茶碱清除（肠肝循环阻断）\n血液灌流是严重中毒的有效治疗手段\n老年人、儿童、肝肾功能不全者对氨茶碱耐受性差，易中毒\n中毒症状可突然加重，需严密监护\n\n【急诊/急救】\n口服者立即催吐，尽快温水洗胃\n活性炭30-50g灌胃吸附\n平卧，持续心电监护\n抽搐者地西泮10-20mg静注\n室性心律失常者利多卡因静注\n静脉补液纠正低钾\n严重者尽快血液灌流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「氨茶碱中毒」原文）"},"icd10_diagnosis":"T48.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2493,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1b428002819fd66eb46789aaee5e80407f82799effbc0ec387852f8247257a0a","pinyin":"anchajianzhongdu","initials":"acjzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T48.1",30]]},{"id":"templates-23a124ecfc33ba30a80b","key":"v1-c9ccc21dfe2a3058|templates-23a124ecfc33ba30a80b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"氯氮平中毒(抗精神病药)","category":"中毒/理化","raw":{"name":"氯氮平中毒(抗精神病药)","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】中枢神经系统：嗜睡、昏睡、昏迷、意识模糊、烦躁不安、严重者：癫痫发作、抽搐、呼吸抑制、心血管系统：体位性低血压、心动过速、心律失常、心肌炎、心包炎、抗胆碱能症状：口干、视力模糊、尿潴留、便秘、皮肤潮红、锥体外系反应：震颤、肌张力增高（较少，氯氮平EPS轻）、血液系统：粒细胞缺乏（最严重，可发生在治疗剂量，过量更危险）、高热、意识障碍、自主神经紊乱（恶性综合征样表现）、严重者：呼吸循环衰竭、多器官功能衰竭、死亡、代谢紊乱：心肌炎、心肌酶升高。\n【待人工确认·本机素材无此段原文】","现病史":"氯氮平（商品名氯氮平）是非典型抗精神病药，过量可引起严重中枢抑制、低血压、心律失常、粒细胞缺乏、癫痫发作。氯氮平中毒可引起致命性粒细胞缺乏症和心肌炎，需密切监测。\n常见表现：中枢神经系统：嗜睡、昏睡、昏迷、意识模糊、烦躁不安、严重者：癫痫发作、抽搐、呼吸抑制、心血管系统：体位性低血压、心动过速、心律失常、心肌炎、心包炎、抗胆碱能症状：口干、视力模糊、尿潴留、便秘、皮肤潮红、锥体外系反应：震颤、肌张力增高（较少，氯氮平EPS轻）、血液系统：粒细胞缺乏（最严重，可发生在治疗剂量，过量更危险）、高热、意识障碍、自主神经紊乱（恶性综合征样表现）、严重者：呼吸循环衰竭、多器官功能衰竭、死亡、代谢紊乱：心肌炎、心肌酶升高。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 心电图：入院即刻行十二导联心电图，持续心电监护动态复查，重点评估 QT/QRS 间期延长及恶性心律失常\n2. 动脉血气分析：昏迷或呼吸抑制者急诊送检，评估低氧血症、CO₂潴留及酸碱失衡\n3. 血电解质及心肌酶：查血钾、钠、钙、镁及 CK、cTnI，纠正低钾低镁（可加重 QT 延长），筛查横纹肌溶解\n4. 血常规（动态复查）：监测白细胞及粒细胞计数，警惕氯氮平相关粒细胞缺乏\n5. 肝肾功能及凝血功能：评估多脏器损伤与药物代谢排泄功能\n6. 毒物检测：留取血/尿标本行氯氮平及抗精神病药定性定量检测，明确中毒程度（疑混合中毒时同步筛查）","初步诊断":"1. 氯氮平过量服用史\n2. 中枢抑制+低血压+心动过速+抗胆碱能症状\n3. 心电图：窦性心动过速、QT间期延长、ST-T改变\n4. 血常规：粒细胞减少/缺乏（治疗剂量也可发生）\n5. 心肌酶：CK、CK-MB、LDH升高（心肌炎）\n6. 血药浓度测定（临床少用）\n7. 排除其他原因昏迷、心律失常\n8. 肌酸激酶升高（恶性综合征）\n1. 氯氮平中毒(抗精神病药)（ICD-10：T43.5）","鉴别诊断":"1. 排除其他原因昏迷、心律失常\n2. 诊断要点：氯氮平过量服用史\n3. 诊断要点：中枢抑制+低血压+心动过速+抗胆碱能症状\n4. 诊断要点：心电图：窦性心动过速、QT间期延长、ST-T改变\n5. 诊断要点：血常规：粒细胞减少/缺乏（治疗剂量也可发生）\n6. 诊断要点：心肌酶：CK、CK-MB、LDH升高（心肌炎）\n7. 诊断要点：血药浓度测定（临床少用）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：洗胃后活性炭30-50g灌胃（吸附）\n\n方案2：\n 用法：生理盐水/林格液 静滴（纠正低血压）\n\n方案3：\n 用法：纳洛酮 0.4-0.8mg静注（促醒，辅助）\n\n方案4：\n 用法：地西泮 10-20mg静注（抽搐时）\n\n方案5（升压药）：\n 用法：去甲肾上腺素/多巴胺（低血压时，禁用肾上腺素）\n\n方案6：\n 用法：抗心律失常药（根据类型，避免QT延长药物）\n\n方案7：\n 用法：5%碳酸氢钠（酸中毒、QRS增宽时）\n\n方案8：\n 用法：维生素C 静滴（辅助）\n\n方案9（升白细胞药）：\n 用法：粒细胞集落刺激因子（G-CSF，粒细胞缺乏时）\n\n方案10：\n 用法：营养心肌药物（心肌炎时）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：活性炭（口服吸附）\n\n药物2：\n 用法：升白细胞药物（恢复期）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n口服者立即催吐、洗胃（温水），洗胃后活性炭30-50g吸附，导泻\n保持呼吸道通畅，吸氧，必要时气管插管机械通气\n静脉补液，纠正低血压（生理盐水，禁用肾上腺素）\n控制抽搐：地西泮静注\n对症支持：抗心律失常、纠正酸中毒、保护心肌\n粒细胞缺乏者：立即停药，G-CSF治疗，保护性隔离，防治感染\n心肌炎者：营养心肌、激素、对症治疗\n恶性综合征者：降温、补液、溴隐亭/丹曲林治疗\n严重者可行血液灌流（脂溶性高）\n持续监测血常规、心电图、心肌酶、生命体征\n\n【处理要点】\n口服者立即催吐，尽快送医洗胃\n让患者平卧，头偏向一侧，防止误吸\n保持呼吸道通畅，吸氧\n监测血压、心率、呼吸、意识状态\n记录服药剂量、时间、平时用药情况\n抽搐发作时保持呼吸道通畅，防止舌咬伤\n定期复查血常规（粒细胞缺乏风险）\n告知患者氯氮平需定期监测血常规\n不要给患者灌水/喂食（昏迷时）\n\n【护理】\n气道管理与防误吸：意识障碍者取侧卧位、头偏一侧，床头抬高30°，昏迷伴呼吸抑制者配合气管插管并备吸引器；洗胃前务必确认气道保护\n洗胃与活性炭配合：服毒6小时内（昏迷者气管插管后）配合温清水洗胃，洗胃毕经胃管注入活性炭，准确记录洗出量及出入量\n生命体征与心电监测：持续心电监护，严密监测心率、血压、体温（氯氮平易致低血压休克及体温异常），低血压者配合扩容及患者血管活性药物\n抗胆碱能综合征观察：观察瞳孔散大、口干、尿潴留、肠鸣音减弱、谵妄等表现；尿潴留者予导尿，严重抗胆碱能症状遵医嘱使用毒扁豆碱并备阿托品\n并发症预防与观察：观察抽搐先兆，发作时保护患者并遵医嘱予苯二氮䓬类；定时翻身防压疮，预防深静脉血栓及吸入性肺炎\n\n【饮食】\n洗胃后暂禁食6-8小时，待肠鸣音恢复、无呕吐呛咳后先试饮少量温水\n恢复进食后予温凉流质（米汤、藕粉、无渣果汁），少量多餐，观察有无腹胀、呕吐\n忌辛辣、油腻、过烫及产气食物；暂忌咖啡、浓茶等含咖啡因饮品，以免加重心动过速\n鼓励适量饮水或口服补液盐促进药物排泄；持续低血压者遵医嘱静脉补液（平衡液/生理盐水）\n肠麻痹恢复且无胃肠道症状后，逐步过渡至半流质、软食，恢复正常饮食\n\n【注意事项】\n氯氮平最严重的不良反应是粒细胞缺乏症，即使治疗剂量也可发生，过量风险更高\n粒细胞缺乏症多发生在用药前6个月，需每周监测血常规\n氯氮平可引起心肌炎和心包炎，尤其是用药初期\n氯氮平过量禁用肾上腺素（可加重低血压，β受体激动导致血管扩张）\n氯氮平脂溶性高，血液灌流效果好\n氯氮平与其他中枢抑制剂（酒精、苯二氮卓类）合用可加重呼吸抑制\n恶性综合征（高热、肌强直、意识障碍、自主神经紊乱）是严重并发症，需紧急处理\n恢复期需重新评估精神科用药方案\n\n【急诊/急救】\n口服者立即催吐，尽快温水洗胃\n保持呼吸道通畅，吸氧\n平卧，监测血压心率\n抽搐者地西泮10-20mg静注\n生理盐水补液纠正低血压（禁用肾上腺素）\n纳洛酮0.4-0.8mg静注（辅助）\n尽快送医，监测血常规和心肌酶","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「氯氮平中毒(抗精神病药)」原文）"},"icd10_diagnosis":"T43.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2494,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"92702abcd048b062d03281ce713ceae632367510507e0caf079d43048abe42ed","pinyin":"lvdanpingzhongdu(kangjingshenbingyao)","initials":"ldpzd(kjsby)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T43.5",30]]},{"id":"templates-4a420b2717d0bba63405","key":"v1-c9ccc21dfe2a3058|templates-4a420b2717d0bba63405","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"氰化物中毒","category":"中毒/理化","raw":{"name":"氰化物中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】吸入高浓度：4-6秒内昏迷、呼吸心跳骤停、口服：舌尖麻木、恶心呕吐、头晕头痛、呼吸困难、呼吸深快→呼吸浅慢、皮肤黏膜呈樱桃红色、抽搐、昏迷、瞳孔散大、呼出气有苦杏仁味。\n【待人工确认·本机素材无此段原文】","现病史":"氰化物（氰化钾、氰化钠、苦杏仁、木薯等）中毒，细胞内窒息，病情凶险\n常见表现：吸入高浓度：4-6秒内昏迷、呼吸心跳骤停、口服：舌尖麻木、恶心呕吐、头晕头痛、呼吸困难、呼吸深快→呼吸浅慢、皮肤黏膜呈樱桃红色、抽搐、昏迷、瞳孔散大、呼出气有苦杏仁味。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 血气分析+血乳酸：急诊即刻抽血，乳酸显著升高（常＞8~10mmol/L）伴高阴离子间隙代谢性酸中毒是氰化物中毒典型线索，治疗中动态复查评估解毒效果\n2. 氰化物血药浓度（全血氰化物测定）：解毒剂给药前留取标本，虽不能即时指导抢救，但可确诊并留作证据\n3. 心电图+心肌损伤标志物（cTnI、CK-MB）：即刻并动态复查，氰化物抑制细胞色素氧化酶可致心肌缺血、心律失常甚至心搏骤停\n4. 血常规+电解质+肝肾功能+血糖：入院即查并复查，评估酸碱电解质紊乱及肝、肾多器官损伤\n5. 高铁血红蛋白浓度：使用亚硝酸盐类解毒剂前测基线，防止药物性高铁血红蛋白血症叠加缺氧\n6. 头颅CT：昏迷或反复抽搐者完善，排除颅内出血、卒中等其他病因（视病情酌情）","初步诊断":"1. 氰化物接触/误食史（电镀、炼金、化工、苦杏仁、木薯）\n2. 呼出气苦杏仁味\n3. 皮肤黏膜樱桃红色\n4. 动静脉血氧差缩小（静脉血呈鲜红色）\n5. 血乳酸显著升高\n6. 毒物检测可确诊\n1. 氰化物中毒（ICD-10：T65.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：【急救方案一（经典）】亚硝酸异戊酯1-2支 吸入（每次15-30秒，每2-3分钟1次）→ 亚硝酸钠3% 10ml 缓慢静注（2-3ml/min）→ 硫代硫酸钠25% 50ml 缓慢静注（10分钟）\n\n方案2：\n 用法：【急救方案二（推荐）】羟钴胺（维生素B12a）5g ivgtt（15分钟），必要时重复2.5g\n\n方案3：\n 用法：【方案三】4-二甲氨基苯酚（4-DMAP）2ml im（10%溶液），随后硫代硫酸钠25% 50ml iv\n\n方案4：\n 用法：高流量吸氧（10-15L/min），高压氧治疗\n\n方案5（洗胃（口服者））：\n 用法：大量温水或1:5000高锰酸钾，洗胃后予硫酸亚铁溶液\n\n方案6：\n 用法：50%葡萄糖50ml iv + 胰岛素8U（促进氰离子代谢）\n\n方案7：\n 用法：甘露醇125ml ivgtt（防治脑水肿）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：恢复期可予维生素B12 500μg im qd\n\n药物2：\n 用法：对症支持治疗\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n特效解毒：亚硝酸钠+硫代硫酸钠（经典方案）或羟钴胺（推荐）\n高压氧治疗\n清除毒物：洗胃、皮肤清洗\n防治脑水肿、肺水肿\n对症支持：维持呼吸循环功能\n\n【处理要点】\n立即脱离中毒环境，脱去污染衣物\n皮肤接触者用大量清水冲洗\n监测生命体征、意识、血气分析、血乳酸\n呼吸心跳骤停者立即CPR\n注意施救者防护，避免吸入中毒\n\n【护理】\n立即予100%高浓度氧疗（储氧面罩/气囊面罩），建立双通道静脉，持续心电、血压、血氧、呼吸监护，警惕心律失常与呼吸抑制\n经口中毒者尽早洗胃：神志清醒者先催吐后洗胃；昏迷者先气管插管再洗胃，洗胃液用温水或1:5000高锰酸钾溶液，洗胃后留置胃管、头偏向一侧防误吸\n解毒剂观察：遵医嘱静滴羟钴胺（用药后尿、皮肤、黏膜可呈红色属正常反应，需提前告知家属并避免误判为出血）或亚硝酸钠-硫代硫酸钠联合方案；密切监测血压（亚硝酸盐可致低血压）、发绀程度及高铁血红蛋白血症表现\n惊厥防护：床挡保护、备开口器与牙垫，抽搐时防坠床、防舌咬伤，记录发作时间与频次并及时报告\n气道与并发症管理：昏迷者取侧卧或半卧位，及时吸痰，备好气管插管与呼吸机，观察有无肺水肿、脑水肿及迟发性神经系统损害\n\n【饮食】\n洗胃后暂禁食水4~6小时，确认无呕吐、胃肠功能恢复后再少量试饮温水\n病情稳定后由流质（米汤、藕粉）逐步过渡至半流质、软食，少量多餐，避免一次进食过饱\n忌辛辣刺激、过冷过热食物及烟酒，防止刺激胃黏膜和诱发呕吐\n静脉补液维持水电解质平衡，遵医嘱补碱纠正酸中毒，准确记录24小时出入量\n恢复期给予高蛋白、富含B族维生素及维生素C饮食（蛋、鱼、瘦肉、新鲜果蔬），促进组织修复\n\n【注意事项】\n病情进展极快，抢救必须争分夺秒\n亚硝酸钠可致低血压、高铁血红蛋白血症，休克者慎用\n羟钴胺安全有效，但价格较高，需尽早使用\n口服中毒者洗胃时施救者需戴防护口罩\n苦杏仁、木薯含氰苷，大量食用可致中毒\n\n【急诊/急救】\n【第一步】立即脱离中毒环境，脱去污染衣物，皮肤用大量清水冲洗（施救者戴防护）\n【第二步】评估意识呼吸：无呼吸立即CPR，有呼吸高流量吸氧10-15L/min\n【第三步】建立静脉通路，心电监护\n【第四步】特效解毒（立即！）：\n方案A：亚硝酸异戊酯1-2支吸入（15-30秒/次，每2-3分钟1次）→ 3%亚硝酸钠10ml缓慢静注（2-3ml/min）→ 25%硫代硫酸钠50ml缓慢静注（10分钟）\n方案B：羟钴胺5g ivgtt（15分钟），必要时重复2.5g\n【第五步】口服者：大量温水或1:5000高锰酸钾洗胃，洗胃后予硫酸亚铁溶液\n【第六步】50%葡萄糖50ml iv + 胰岛素8U，促进氰离子代谢\n【第七步】防治脑水肿：甘露醇125ml ivgtt q6-8h，地塞米松10-20mg iv\n【第八步】呼吸抑制：尼可刹米0.375g iv，必要时气管插管机械通气\n【第九步】循环衰竭：快速补液，多巴胺5-10μg/kg/min iv泵控\n【第十步】监测：血气、血乳酸、生命体征，必要时重复半量解毒剂\n【注意】抢救必患者数分钟内开始；亚硝酸钠注意低血压；施救者防中毒","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T65.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2495,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"24855a9d04c617b003e7bbea5235ad9700886e2487e8e0faeebde72f89b00041","pinyin":"qinghuawuzhongdu","initials":"qhwzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T65.0",30]]},{"id":"templates-464753978aef2dc963d2","key":"v1-c9ccc21dfe2a3058|templates-464753978aef2dc963d2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水痘(中医辨证)","category":"中医","raw":{"name":"水痘(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】邪伤肺卫：发热轻微或无热，鼻塞流涕，喷嚏咳嗽，疹色红润，疱浆清亮，根盘红晕不明显，点粒稀疏，苔薄白，脉浮数、毒炽气营：壮热烦躁，口渴欲饮，面红目赤，痘疹密布，疹色紫暗，疱浆混浊，或伴口疮、牙龈肿痛，便秘溲赤，舌红绛苔黄糙，脉洪数。\n【待人工确认·本机素材无此段原文】","现病史":"水痘是由水痘时邪（水痘-带状疱疹病毒）引起的急性出疹性传染病，以发热、皮肤分批出现斑丘疹、疱疹、结痂为特征。分邪伤肺卫、毒炽气营等证型。\n常见表现：邪伤肺卫：发热轻微或无热，鼻塞流涕，喷嚏咳嗽，疹色红润，疱浆清亮，根盘红晕不明显，点粒稀疏，苔薄白，脉浮数、毒炽气营：壮热烦躁，口渴欲饮，面红目赤，痘疹密布，疹色紫暗，疱浆混浊，或伴口疮、牙龈肿痛，便秘溲赤，舌红绛苔黄糙，脉洪数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压、体重\n望诊：神（得神/少神/失神）、色（常色/病色）、形态（胖瘦/发育）、头面五官、指纹（3岁以下看虎口三关：风关/气关/命关）、舌诊（舌质/舌苔）\n闻诊：哭声、咳声、呼吸声、口气、二便气味\n问诊：年龄（月龄）、喂养史、生长发育史、预防接种史、既往史、现病史、大小便、睡眠\n切诊：脉诊（小儿脉象：浮沉迟数有力无力）、按诊（囟门/腹部/四肢）\n辨证：八纲辨证、脏腑辨证、卫气营血辨证、指纹辨证","辅助检查":"检查计划：患儿以发热、皮肤分批出现斑丘疹、疱疹、结痂为主要表现，疱浆清亮、根盘红晕不明显属邪伤肺卫证，或见壮热烦躁、痘疹密布、疱浆混浊属毒炽气营证，符合水痘（水痘-带状疱疹病毒感染）诊断，本病以临床诊断为主，但需完善下列检查以明确病原、评估病情并早期发现肺炎、脑炎等并发症。就诊当日完善血常规检查，了解白细胞计数及分类、血小板计数，因水痘为病毒感染，白细胞多正常或降低、淋巴细胞比例升高，如白细胞及中性粒细胞明显升高提示继发细菌感染；完善C反应蛋白（CRP）及红细胞沉降率检查，评估炎症反应程度，动态观察有助于判断有无继发细菌感染及病情进展。必要时完善水痘-带状疱疹病毒抗体（IgM、IgG）检测，或行疱疹液病毒核酸检测，明确病原学诊断，尤其对临床表现不典型或需与手足口病、丘疹性荨麻疹鉴别者；完善肝功能、心肌酶检查，了解有无肝功能损害及心肌受累，因水痘可并发心肌炎、肝炎；完善肾功能及血电解质检查，评估全身状况及有无水电解质紊乱。如出现咳嗽气促、肺部体征，完善胸部X线或胸部CT检查，明确有无水痘肺炎；如出现头痛、呕吐、抽搐、意识改变，急诊完善头颅CT或腰椎穿刺脑脊液检查，明确有无水痘脑炎。病情稳定后定期复查皮疹变化及体温，必要时复查炎症指标，观察结痂与痊愈情况，评估疗效及有无继发感染。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 发热1-2天后出现斑丘疹→疱疹→结痂，分批出现\n2. 临床诊断为主，必要时查水痘病毒抗体\n3. 注意观察有无肺炎、脑炎等并发症\n1. 水痘(中医辨证)（ICD-10：B01.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！儿童用药剂量务必按体重精确计算！\n\n方案1：\n 用法：一般不需输液，口服中药为主\n\n方案2（发热/脱水）：\n 用法：5%GS 100-250ml+维生素C1.0g ivgtt qd（按体重调整）；口服补液盐（ORS）按需\n\n方案3（合并细菌感染）：\n 用法：NS 50-100ml+头孢呋辛50mg/kg·d 分2次 ivgtt（皮试后，按体重计算）\n\n📌 儿童输液务必严格控制滴速与液体量，用药前核对体重、剂量、过敏史！\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患儿病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n儿童剂量需按体重/年龄精确计算，务必遵医嘱。\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（邪伤肺卫）：银翘解毒颗粒（小儿量）5g tid\n药物2（毒炽气营）：清瘟败毒饮（遵医嘱），或羚羊角口服液（小儿量）\n药物3（外治）：炉甘石洗剂涂皮疹止痒；疱疹破溃处涂甲紫溶液\n\n【治疗】\n邪伤肺卫：疏风清热，利湿解毒，银翘散加减\n毒炽气营：清气凉营，解毒化湿，清胃解毒汤加减\n\n【处理要点】\n隔离至全部疱疹结痂干燥（约2周）\n剪短指甲，避免搔抓，防止继发感染\n衣被清洁，勤换内衣\n\n【护理】\n病情观察：每日测体温2～4次，重点观察痘疹透发与疱浆变化——疹色红润、疱浆清亮、透发有序为顺证；若壮热不退、疹色紫暗、疱浆混浊甚至呈血性，伴烦躁口渴、神昏抽搐，为热毒炽盛之逆证，立即报告医师。同时查看口腔、咽部黏膜疱疹及有无破溃感染，记录疱疹出齐、结痂时间。\n皮肤外治护理：衣被宜柔软清洁、勤洗勤换，剪短指甲或戴棉布手套，劝止搔抓以防抓破继发感染留疤；未破疱疹外涂炉甘石洗剂止痒，破溃处遵医嘱以青黛散外敷，口腔疱疹用西瓜霜或锡类散喷敷，每日2～3次。\n隔离与起居调护：自发病至全部疱疹结痂干燥期间实行呼吸道隔离，病室定时通风、温湿度适宜，避免汗出当风复感外邪；发热期卧床休息，汗出后及时擦干更衣，保持皮肤清洁干燥。\n情志护理：患儿瘙痒烦躁易哭闹，宜以讲故事、玩玩具等转移注意力，耐心安抚，避免哭闹躁动加重瘙痒；对年长儿疏导对皮疹外观的顾虑，使其安心配合隔离与治疗。\n煎药服药护理：汤药温服、少量频服，疏风清热之剂忌发汗太过，以免耗伤津液、邪毒内陷；热毒炽盛者药液可偏凉服；内服与外用药物分装并贴标签防止误用；禁用激素类药物，避免病毒播散。\n\n【饮食】\n饮食宜清淡、易消化、富营养：予米粥、烂面条、山药粥及新鲜蔬菜，少量多餐，多饮温开水以助邪毒外透；避免过饱碍脾。\n辨证忌口：忌辛辣炙煿之品（辣椒、生姜、大蒜、芥末、酒类）、肥甘厚味及煎炸油腻食物，以免助热生湿、毒邪壅盛；忌鱼虾蟹、牛羊肉、公鸡、香菇等发物，防痘疹增多或诱发过敏。\n宜食清热利湿解毒之品：绿豆、赤小豆、冬瓜、丝瓜、薏苡仁、百合、苦瓜、胡萝卜等；热毒炽盛、口渴津伤者，可饮鲜芦根水、梨汁、藕汁以清热生津。\n药膳食疗：①三豆饮——绿豆、赤小豆、黑豆各适量煮汤代茶饮，清热解毒利湿；②绿豆薏米粥——绿豆、薏苡仁、粳米煮粥，适于湿热偏盛、疱浆清亮者；③金银花甘草茶——金银花10g、生甘草3g沸水冲泡代茶，适于风热犯卫之轻证。\n口腔疱疹疼痛、进食困难者，予温凉流质或半流质饮食，汤药与茶饮放温后少量慢咽，避免过烫刺激破溃面。\n\n【注意事项】\n高热不退、咳嗽气促（并发肺炎）、头痛呕吐（并发脑炎）立即住院\n免疫功能低下者水痘易重症，及早抗病毒（阿昔洛韦）\n孕妇、新生儿接触水痘患者需就医评估\n\n【急诊/急救】\n一般不需急救\n高热惊厥：物理降温，地西泮0.3-0.5mg/kg iv（遵医嘱）\n呼吸困难/发绀/精神萎靡：立即转儿科急诊","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】水痘\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、邪伤肺卫（轻证）\n    症状舌脉：发热轻微，或无热，鼻塞流涕，咳嗽，1-2天后出疹，疹色红润，疱浆清亮，根盘红晕不著，点粒稀疏，此起彼伏，以躯干为多，舌苔薄白，脉浮数\n    治法：疏风清热、利湿解毒\n    方剂：银翘散\n\n二、邪炽气营（重证）\n    症状舌脉：壮热不退，烦躁不安，口渴欲饮，面红目赤，水痘分布较密，根盘红晕显著，疹色紫暗，疱浆混浊，甚至出现出血性皮疹、皮肤感染，大便干结，小便黄赤，舌质红绛、苔黄糙而干，脉洪数\n    治法：清气凉营、解毒化湿\n    方剂：清胃解毒汤。来源：《中医儿科学》（中国中医药出版社“十四五”规划教材）·传染病·水痘。提示：须隔离至疱疹全部结痂；禁用糖皮质激素；继发细菌感染者抗感染治疗\n\n【方剂参考】\n  银翘散：组成 金银花15g、连翘15g、薄荷6g、荆芥穗6g、淡豆豉12g、牛蒡子9g、桔梗9g、生甘草6g、竹叶6g、芦根30g；功效 辛凉透表，清热解毒\n      用法：诸药杵为粗末，每次18g，以鲜芦根汤煎，香气大出即取服，勿过煮；病重者约四小时一服，日三夜一服。\n      注意：外感风寒及湿温初起而无咽痛口渴者忌用；方中多轻宣芳香之品，煎煮过久则药力耗散；脾胃虚寒者慎用。【别名】本方在《温病条辨》原名「银翘散」，临证作汤剂时通称「银翘汤」（与《伤寒论》另有「银翘汤」名方同名，本条指《温病条辨》银翘散）。来源：《温病条辨·卷一·上焦篇》\n\n【西医诊断】\n  水痘\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"B01.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2496,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"058d444fa302a0a2298c3846ff2fb23b55c72062dfc5c145c3579b1d296a5cfa","pinyin":"shuidou(zhongyibianzheng)","initials":"sd(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","B01.9",30]]},{"id":"templates-60c63cd2184c6be25e9e","key":"v1-c9ccc21dfe2a3058|templates-60c63cd2184c6be25e9e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"水肿(中医辨证)","category":"中医","raw":{"name":"水肿(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】风水相搏：眼睑浮肿，继则四肢及全身皆肿，来势迅速，多有恶寒发热，肢节酸楚、湿毒浸淫：眼睑浮肿，延及全身，皮肤光亮，尿少色赤，身发疮痍、水湿浸渍：全身水肿，下肢明显，按之没指，小便短少，身体困重，胸闷纳呆、湿热壅盛：遍体浮肿，皮肤绷急光亮，胸脘痞闷，烦热口渴，小便短赤，大便干结、脾阳虚衰：身肿日久，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳减便溏，面色不华、肾阳衰微：水肿反复消长不已，面浮身肿，腰以下甚，按之凹陷不起，腰酸冷痛，四肢厥冷。\n【待人工确认·本机素材无此段原文】","现病史":"以头面、眼睑、四肢、腹背甚至全身浮肿为主要表现。分阳水（风水相搏、湿毒浸淫、水湿浸渍、湿热壅盛）和阴水（脾阳虚衰、肾阳衰微、瘀水互结）。\n常见表现：风水相搏：眼睑浮肿，继则四肢及全身皆肿，来势迅速，多有恶寒发热，肢节酸楚、湿毒浸淫：眼睑浮肿，延及全身，皮肤光亮，尿少色赤，身发疮痍、水湿浸渍：全身水肿，下肢明显，按之没指，小便短少，身体困重，胸闷纳呆、湿热壅盛：遍体浮肿，皮肤绷急光亮，胸脘痞闷，烦热口渴，小便短赤，大便干结、脾阳虚衰：身肿日久，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳减便溏，面色不华、肾阳衰微：水肿反复消长不已，面浮身肿，腰以下甚，按之凹陷不起，腰酸冷痛，四肢厥冷。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以头面、眼睑、四肢、腹背甚至全身浮肿为主要表现，属中医水肿范畴，需区分阳水与阴水，并明确为肾源性、心源性、肝源性还是营养不良性水肿，故完善下列检查以明确病因、鉴别诊断并指导治疗。就诊当日完善尿常规检查，了解有无蛋白尿、血尿、管型尿，是判断肾源性水肿的首要筛查项目；完善肾功能检查（血肌酐、尿素氮、尿酸及估算肾小球滤过率），评估肾脏滤过功能，明确有无肾功能不全所致水钠潴留；完善肝功能及血清白蛋白检查，了解有无低蛋白血症及肝病所致水肿，因肝源性水肿常以腹水伴下肢浮肿为特点；完善甲状腺功能检查，排除甲状腺功能减退所致黏液性水肿，本病常表现为面浮身肿、按之凹陷不起、畏寒肢冷，与中医肾阳衰微证候需鉴别。完善血常规检查，评估有无贫血、感染及营养不良，为营养不良性水肿提供依据；完善血电解质检查，了解有无低钠、低钾等电解质紊乱，尤其在使用利尿剂前后必须监测，以防利尿过度致电解质失衡；完善血糖及血脂检查，评估有无糖尿病、高脂血症等代谢因素所致肾损害。完善心脏彩超及心电图检查，了解心脏结构、射血分数及有无心包积液，明确有无心源性水肿；必要时完善NT-ProBNP检查，明确有无心力衰竭及其程度；病情需要时完善24小时尿蛋白定量、尿蛋白电泳及免疫学检查，进一步明确肾小球疾病类型。病情稳定后行腹部B超检查，了解肝脾大小、有无腹水及肾脏形态，指导中医辨证分型与利水方案调整；治疗期间定期复查尿常规、肾功能、电解质及体重变化，评估水肿消退情况与疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 以水肿为主要表现\n2. 查尿常规、肾功能、肝功能、甲状腺功能\n3. 区分肾源性、心源性、肝源性、营养不良性\n1. 水肿(中医辨证)（ICD-10：R60.9）","鉴别诊断":"1. 区分肾源性、心源性、肝源性、营养不良性","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急性肾炎）：\n 用法：NS250ml+丹参注射液20ml ivgtt qd\n\n方案2（阳虚）：\n 用法：NS250ml+参附注射液40ml ivgtt qd\n\n方案3（严重水肿）：\n 用法：利尿剂\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（风水相搏）：\n 用法：越婢加术汤1袋 tid，或肾炎解热片4片 tid\n\n药物2（湿毒浸淫）：\n 用法：麻黄连翘赤小豆汤1袋 tid，或肾炎四味片4片 tid\n\n药物3（水湿浸渍）：\n 用法：五皮饮1袋 tid，或胃苓丸1袋 tid\n\n药物4（湿热壅盛）：\n 用法：疏凿饮子1袋 tid，或八正合剂1支 tid\n\n药物5（脾阳虚衰）：\n 用法：实脾饮1袋 tid，或参苓白术散1袋 tid\n\n药物6（肾阳衰微）：\n 用法：济生肾气丸1丸 tid，或真武汤颗粒1袋 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n风水相搏：疏风清热，宣肺行水，越婢加术汤\n湿毒浸淫：宣肺解毒，利湿消肿，麻黄连翘赤小豆汤合五味消毒饮\n水湿浸渍：健脾化湿，通阳利水，五皮饮合胃苓汤\n湿热壅盛：分利湿热，疏凿饮子\n脾阳虚衰：健脾温阳利水，实脾饮\n肾阳衰微：温肾助阳，化气行水，济生肾气丸合真武汤\n\n【处理要点】\n低盐饮食\n记录出入量\n避免劳累\n预防感染\n\n【护理】\n病情观察：准确记录24小时出入量，每日晨起定时测体重、量腹围，观察水肿部位、程度及消长变化；注意小便色、量、浑浊度，若见尿量骤减（24小时少于500ml）、无尿或伴气促、咳粉红泡沫痰，立即报告医生。\n起居调护：重度水肿者绝对卧床休息，半卧位并抬高下肢以利回流；阴水（脾肾阳虚）者注意保暖，避风寒侵袭，防止复感外邪加重水肿；轻度水肿者适当活动，但避免久立久坐及劳累耗气。\n情志护理：水肿病程缠绵、易反复，患者多焦虑悲观，宜耐心疏导，鼓励其树立信心，避免暴怒、忧思等情志刺激伤及肝脾，保持心情舒畅以助气化水行。\n煎药服药护理：利水渗湿药宜武火急煎、不宜久煎；发汗利水药宜温服，服后加盖衣被取微汗，切忌发汗太过耗伤阳气；攻下逐水药（如十枣汤）宜清晨空腹服，服药后密切观察泻下次数及尿量，中病即止，并防虚脱。\n外治护理：可予温水浸泡双足或用艾条温和灸水分、神阙、关元穴以温阳利水；皮肤水肿处保持清洁干燥，防破溃感染，破溃处禁贴敷药物；湿热壅盛者忌艾灸。\n\n【饮食】\n严格控制钠盐：轻度水肿每日食盐不超过3g，重度水肿予无盐饮食，忌咸菜、腊肉、酱制品、腌制品及含碱面食，调味可用醋、糖等代替。\n辨证忌口：阳水（风水、湿热、湿毒证）忌辛辣、油腻炙煿、肥甘厚味及酒类，以免助湿生热、酿湿成毒；阴水（脾肾阳虚）忌生冷寒凉之品，如冷饮、西瓜、苦瓜、蟹，以免更伤脾肾之阳。\n适宜食物：宜清淡利水之品，如冬瓜、赤小豆、薏苡仁、玉米须、茯苓、鲤鱼、鲫鱼、丝瓜等，可常用煮汤或煮粥食用。\n药膳食疗：鲤鱼赤小豆汤（鲤鱼1条约250g去鳞杂，赤小豆60g共煮）利水消肿；薏苡仁赤小豆粥健脾渗湿；脾肾阳虚者予黄芪山药粥、核桃黑豆汤温补脾肾。\n饮食宜少量多餐，宜温、软、易消化，忌过饱，以免碍脾运化、水湿更甚；尿少者同时控制饮水量，口渴可含服少许温开水润口。\n\n【注意事项】\n水肿伴大量蛋白尿需肾内科就诊\n忌长期使用峻下逐水药\n定期复查肾功能\n\n【急诊/急救】\n一般不需急救\n急性左心衰：端坐位，吸氧，利尿剂，急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「水肿（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】水肿\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、风水相搏\n    症状舌脉：眼睑先肿，继而四肢及全身皆肿，来势迅速，多有恶寒、发热、肢节酸楚、小便不利等症，偏于风热者伴咽喉肿痛，舌质红、脉浮滑数；偏于风寒者兼恶寒、咳喘，舌苔薄白、脉浮滑或浮紧\n    治法：疏风清热、宣肺行水\n    方剂：越婢加术汤\n\n二、湿毒浸淫\n    症状舌脉：眼睑浮肿，延及全身，皮肤光亮，尿少色赤，身发疮痍，甚则溃烂，恶风发热，舌质红、苔薄黄，脉浮数或滑数\n    治法：宣肺解毒、利湿消肿\n    方剂：麻黄连翘赤小豆汤合五味消毒饮\n\n三、水湿浸渍\n    症状舌脉：全身水肿，下肢明显，按之没指，小便短少，身体困重，胸闷，纳呆，泛恶，苔白腻，脉沉缓，起病缓慢、病程较长\n    治法：运脾化湿、通阳利水\n    方剂：五皮饮合胃苓汤\n\n四、湿热壅盛\n    症状舌脉：遍体浮肿，皮肤绷急光亮，胸脘痞闷，烦热口渴，小便短赤，或大便干结，舌红、苔黄腻，脉沉数或濡数\n    治法：分利湿热\n    方剂：疏凿饮子\n\n五、脾阳虚衰\n    症状舌脉：身肿日久，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳减便溏，面色不华，神疲乏力，四肢倦怠，小便短少，舌质淡、苔白腻或白滑，脉沉缓或沉弱\n    治法：健脾温阳利水\n    方剂：实脾饮\n\n六、肾阳衰微\n    症状舌脉：水肿反复消长不已，面浮身肿，腰以下甚，按之凹陷不起，尿量减少或反多，腰酸冷痛，四肢厥冷，怯寒神疲，面色㿠白，甚者心悸胸闷、喘促难卧、腹大胀满，舌质淡胖、苔白，脉沉细或沉迟无力\n    治法：温肾助阳、化气行水\n    方剂：济生肾气丸合真武汤\n\n七、瘀水互结\n    症状舌脉：水肿延久不退，肿势轻重不一，四肢或全身浮肿，以下肢为主，皮肤瘀斑，腰部刺痛，或伴血尿，舌紫暗、苔白，脉沉细涩\n    治法：活血祛瘀、化气行水\n    方剂：桃红四物汤合五苓散。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肾系病证·水肿\n\n【方剂参考】\n  麻黄连翘赤小豆汤：组成 麻黄6g、连翘12g、杏仁9g、赤小豆30g、大枣4枚、生梓白皮12g（现代多以桑白皮12g代）、生姜6g、炙甘草6g；功效 解表散邪，清热利湿\n      用法：水煎温服，日一剂，分二次服；服后取微汗。\n      注意：湿热发黄无表证者不宜单用；表虚自汗、阴虚者忌用；生梓白皮现代多以桑白皮代，须注明；高血压、心脏病患者慎用麻黄。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·解表剂（辛凉解表）；原方出自《伤寒论·辨阳明病脉证并治》第262条\n  五皮饮：组成 桑白皮12g、陈皮9g、生姜皮6g、大腹皮12g、茯苓皮15g；功效 利水消肿，理气健脾\n      用法：水煎温服，日一剂，分二次服。\n      注意：阴虚水停、脾肾阳虚水肿者须配伍扶正；水肿须先明确病因（心、肝、肾源性）；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（利水渗湿）；原方出自《太平惠民和剂局方·卷三》（原名五皮散）\n  实脾饮：组成 厚朴9g、白术9g、木瓜9g、木香6g、草果6g、大腹皮12g、制附子6g（先煎）、白茯苓12g、干姜6g、炙甘草3g、生姜3片、大枣3枚；功效 温阳健脾，行气利水\n      用法：水煎，制附子先煎30-60分钟，温服，日一剂，分二次服。\n      注意：⚠ 制附子有毒须先煎30-60分钟；阳水（湿热壅盛、遍身悉肿、烦渴、尿赤）者忌用；水肿须先明确病因（心、肝、肾源性），并在医师指导下治疗；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（温化寒湿）；原方出自《严氏济生方·水肿门》（原名实脾散）\n  肾气丸：组成 干地黄24g、山药12g、山茱萸12g、泽泻9g、茯苓9g、牡丹皮9g、桂枝3g、附子3g；功效 补肾助阳\n      用法：上药为末，炼蜜为丸如梧桐子大，每次15-25丸（约6-9g），酒或温开水送服，日二次；亦可作汤剂。\n      注意：阴虚火旺、咽干口燥、小便黄赤者忌用；感冒发热及湿热下注者不宜；孕妇慎用附子、桂枝。【别名】本方在《中医内科学》等教材与临床常称「金匮肾气丸」（《金匮要略》肾气丸），另有「八味肾气丸」「桂附地黄丸」等异名；本库《名方》收作「肾气丸（金匮肾气丸／八味肾气丸）」。来源：《金匮要略·血痹虚劳病脉证并治第六》\n  四物汤：组成 当归9g、川芎6g、白芍9g、熟地黄12g；功效 补血调血\n      用法：水煎温服，日二次，食前空腹服；调经者可经前、经后各服数剂，或经净后连服。\n      注意：脾胃虚寒、食少便溏者慎用（熟地滋腻）；血热妄行、月经过多者及孕妇慎用川芎。\n\n【西医诊断】\n  水肿（需查因）\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R60.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2497,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"ec2cc3cd7f5b13329f02da1019cdb1afdc5bce8e30651fef4c6b9741c70f151e","pinyin":"shuizhong(zhongyibianzheng)","initials":"sz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R60.9",30]]},{"id":"templates-01b5d507c8d007756bf6","key":"v1-c9ccc21dfe2a3058|templates-01b5d507c8d007756bf6","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"汗证(中医辨证)","category":"中医","raw":{"name":"汗证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肺卫不固：汗出恶风，稍劳汗出尤甚，或表现半身、某一局部出汗，易于感冒，体倦乏力，面色少华，苔薄白，脉细弱、心血不足：自汗或盗汗，心悸少寐，神疲气短，面色不华，舌淡苔薄白，脉细、阴虚火旺：夜寐盗汗或有自汗，五心烦热，或兼午后潮热，两颧色红，口渴，舌红少苔，脉细数、邪热郁蒸：蒸蒸汗出，汗液黏腻或使衣服黄染，面赤烘热，烦躁，口苦，小便色黄，舌苔薄黄，脉弦数。\n【待人工确认·本机素材无此段原文】","现病史":"汗证是由于阴阳失调、腠理不固，而致汗液外泄失常的病证。分自汗（肺卫不固、心血不足、阴虚火旺、邪热郁蒸）与盗汗（阴虚火旺为主）。可见于自主神经功能紊乱、甲亢、结核病、更年期综合征等。\n常见表现：肺卫不固：汗出恶风，稍劳汗出尤甚，或表现半身、某一局部出汗，易于感冒，体倦乏力，面色少华，苔薄白，脉细弱、心血不足：自汗或盗汗，心悸少寐，神疲气短，面色不华，舌淡苔薄白，脉细、阴虚火旺：夜寐盗汗或有自汗，五心烦热，或兼午后潮热，两颧色红，口渴，舌红少苔，脉细数、邪热郁蒸：蒸蒸汗出，汗液黏腻或使衣服黄染，面赤烘热，烦躁，口苦，小便色黄，舌苔薄黄，脉弦数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以汗液外泄异常为主症，自汗盗汗并见，稍劳汗出尤甚，伴体倦乏力、面色少华，入院即刻完善血常规检查了解有无贫血、感染等基础疾病；汗出过多易致津液与电解质丢失，完善电解质及肾功能检查排除低钾、低钠等电解质紊乱及肾功能不全；患者汗出可呈阵发性，查空腹血糖及发作时即时血糖，排除低血糖所致大汗，同时明确有无糖尿病；结合怕热多汗、心悸消瘦、烦躁易怒等表现，完善甲状腺功能（TSH、FT3、FT4）检查排除甲状腺功能亢进；患者夜寐盗汗、午后潮热、两颧色红，需完善胸部X线或胸部CT检查、结核菌素试验（PPD）及结核感染T细胞检测，排除肺结核等结核感染所致盗汗；查红细胞沉降率、C反应蛋白了解有无活动性炎症及结缔组织病；中年女性伴五心烦热者完善性激素六项（FSH、LH、E2）检查了解卵巢功能，明确是否为更年期综合征；查心电图、心肌酶排除心肌缺血及心功能不全所致代偿性汗出；完善肝功能检查，为后续中药及抗焦虑药物治疗提供用药依据；对汗出伴头晕、四肢无力者，完善颈部血管彩超了解颈部血管情况，必要时查头颅CT进一步明确诊断，并完善尿常规、尿17-羟皮质类固醇及肾上腺超声检查，鉴别嗜铬细胞瘤、肾上腺疾病等继发因素。血常规、血糖、心电图入院即刻完成，其余项目病情稳定后择期完善；治疗期间定期复查电解质及肝肾功能，评估汗出程度与疗效。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 汗液异常外泄，自汗（清醒时）或盗汗（睡中）为主症\n2. 甲状腺功能、血糖、胸片、PPD等排查病因\n3. 排除低血糖、休克等急症所致大汗\n1. 汗证(中医辨证)（ICD-10：R61）","鉴别诊断":"1. 排除低血糖、休克等急症所致大汗","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肺卫不固）：玉屏风颗粒5g tid，或黄芪颗粒4g tid\n药物2（心血不足）：归脾丸6g tid，或柏子养心丸6g tid\n药物3（阴虚火旺）：六味地黄丸6g bid，或知柏地黄丸6g bid\n药物4（邪热郁蒸）：龙胆泻肝丸6g bid，或当归六黄丸6g bid\n\n【治疗】\n肺卫不固：益气固表，玉屏风散加减\n心血不足：养血补心，归脾汤加减\n阴虚火旺：滋阴降火，当归六黄汤加减\n邪热郁蒸：清肝泄热，化湿和营，龙胆泻肝汤加减\n\n【处理要点】\n汗出后及时擦干更衣，避免当风受凉\n加强锻炼，增强体质\n饮食清淡，忌辛辣刺激\n\n【护理】\n病情观察：观察汗出部位（头面、胸背、手足、半身）、时间（白昼醒时或夜间寐时）、汗量、汗色及气味，记录24小时汗出情况与伴随症状（畏寒、乏力、心悸、低热、口燥等）；若见汗出如珠、淋漓不止，伴四肢厥冷、脉微欲绝，属脱汗亡阳之兆，须立即报告医生并配合抢救。\n起居调护：汗出后及时用干毛巾拭干，避免当风直吹，湿衣湿被随汗随换；自汗者避风寒，宜适度活动（如八段锦、太极拳）以固卫气，不可运动至大汗；盗汗属阴虚者应保证休息、忌熬夜劳神，午后避免剧烈活动。\n情志护理：汗证多随情志波动加重，恼怒、焦虑、惊恐均可诱发汗出，宜以语言开导、音乐、静坐宁心等方式疏泄情志；阴虚者尤忌忧思劳神，气虚者避免思虑过度耗气，防止汗出反复。\n煎药服药护理：气虚自汗之补气固表剂宜温服，服后稍事休息并避风；阴虚盗汗之滋阴敛汗剂宜温凉服，可于临睡前分次服用以助安神止汗；服药期间注意汗出变化，汗止后及时告知医生调整方药。\n外治与皮肤护理：可遵医嘱以五倍子、煅龙骨、麻黄根研末敷脐或扑撒局部敛汗，注意脐部及腋下、腹股沟等皱褶处皮肤清洁干燥，防止汗疹、湿疹及继发感染；汗出多者予少量多次温开水或淡盐水补充。\n\n【饮食】\n辨证忌口：肺卫不固、气虚自汗者忌食生冷瓜果及苦寒之品，以免更伤卫阳；阴虚火旺盗汗者忌辛辣燥热之品（辣椒、生姜、葱蒜、羊肉、狗肉、酒）及浓茶、咖啡，以免助火伤阴；湿热内蕴、汗出黏腻者忌肥甘厚味及甜腻之品，以防助湿生热。\n适宜食物：气虚自汗者宜食黄芪、山药、大枣、浮小麦、粳米、鸡肉、牛肉等健脾益气、固表敛汗之品；阴虚盗汗者宜食百合、银耳、黑豆、乌梅、黑芝麻、鸭肉、甲鱼等滋阴清热之品；湿热者宜食薏苡仁、赤小豆、冬瓜、绿豆等清利湿热之品。\n药膳食疗：可选用黄芪炖鸡（补气固表，适用于气虚自汗）、浮小麦大枣汤或糯稻根大枣茶（敛汗止汗，自汗者宜）、乌梅大枣汤（酸甘化阴敛汗，阴虚盗汗者宜）、百合银耳羹（滋阴润燥，盗汗伴口干者宜）。\n食养宜忌：饮食宜清淡、易消化，定时定量、少食多餐，避免过饱而加重汗出；汗出过多者适当增加饮水并少量加盐以补充汗液丢失，但睡前不宜多饮，以免夜尿频多扰动睡眠、加重盗汗。\n\n【注意事项】\n夜间盗汗伴低热咳嗽需排查结核\n多食易饥饿、心悸手抖需查甲状腺功能\n大汗淋漓伴神志改变需急诊\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「汗证（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】汗证\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肺卫不固\n    症状舌脉：汗出恶风，稍劳汗出尤甚，或表现半身、某一局部出汗，易于感冒，体倦乏力，周身酸楚，面色㿠白少华，苔薄白，脉细弱\n    治法：益气固表\n    方剂：桂枝加黄芪汤或玉屏风散\n\n二、心血不足\n    症状舌脉：自汗或盗汗，心悸少寐，神疲气短，面色不华，舌质淡、脉细\n    治法：养血补心\n    方剂：归脾汤\n\n三、阴虚火旺\n    症状舌脉：夜寐盗汗，或有自汗，五心烦热，或兼午后潮热，两颧色红，口渴，舌红少苔，脉细数\n    治法：滋阴降火\n    方剂：当归六黄汤\n\n四、邪热郁蒸\n    症状舌脉：蒸蒸汗出，汗黏，汗液易使衣服黄染，面赤烘热，烦躁，口苦，小便色黄，舌苔薄黄，脉象弦数\n    治法：清肝泄热、化湿和营\n    方剂：龙胆泻肝汤。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·气血津液病证·汗证。提示：盗汗须排查结核、淋巴瘤、甲状腺功能亢进等\n\n【方剂参考】\n  玉屏风散：组成 防风6g、黄芪12g、白术12g；功效 益气固表止汗\n      用法：上药为末，每次6-9g，加生姜3片、大枣1枚，水煎温服，日二次；亦可作汤剂，宜久服（1-3个月）巩固。\n      注意：阴虚盗汗、湿热内盛及外感发热者忌用；本方温补固表，实邪未尽者用之易闭门留寇。\n  归脾汤：组成 白术9g、当归9g、白茯苓9g、黄芪12g、龙眼肉12g、远志6g、酸枣仁12g、人参9g、木香6g、炙甘草3g、生姜3片、大枣3枚；功效 益气补血，健脾养心\n      用法：加生姜3片、大枣3枚，水煎温服，日二次；亦可服归脾丸，每次6-9g，日二次。\n      注意：痰湿内盛、肝火扰心之失眠及外感发热者不宜；本方偏温补，有实火者忌用。\n  当归六黄汤：组成 当归6g、生地黄6g、熟地黄6g、黄芩6g、黄柏6g、黄连6g、黄芪12g；功效 滋阴泻火，固表止汗\n      用法：水煎温服，日二次，食前服；亦可研末为散，每次15g，水煎温服。\n      注意：脾胃虚弱、纳差便溏者慎用（苦寒伤胃）；阴虚而火不旺者不宜（黄芩、黄连、黄柏苦寒）；感冒发热期间停服。（本方黄连6g超《中国药典》2020年版一部黄连用量2-5g，系教材原方折算，临床宜酌减）\n  龙胆泻肝汤：组成 龙胆草6g、黄芩9g、栀子9g、泽泻12g、川木通6g（禁用关木通）、车前子9g、当归3g、生地黄9g、柴胡6g、生甘草6g；功效 清泻肝胆实火，清利肝经湿热\n      用法：水煎温服，日二次，饭后服；亦可制丸，每次6-9g，日二次。\n      注意：脾胃虚寒、孕妇及阴虚阳亢者忌用；苦寒渗利之品久服伤胃耗阴，一般不超过7-14剂；木通用量宜小。木通须用川木通；关木通含马兜铃酸、2005 年起取消药用标准，禁止使用。\n\n【西医诊断】\n  多汗症\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R61","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2498,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3066652cd164021699522c5a57e0c122c6c6b0e3bf6bf0122a1ddd65f1813423","pinyin":"hanzheng(zhongyibianzheng)","initials":"hz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R61",30]]},{"id":"templates-20b3efedf8014992954a","key":"v1-c9ccc21dfe2a3058|templates-20b3efedf8014992954a","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"汞中毒","category":"中毒/理化","raw":{"name":"汞中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】慢性中毒（常见）：易兴奋症（失眠、多梦、易激动、记忆力减退）、震颤（手指、眼睑与舌，精细动作困难如写字）与口腔炎（流涎、牙龈红肿与汞线）、神经系统：头痛、头晕、肢体麻木、周围神经病与情绪障碍（抑郁与焦虑）、肾脏：蛋白尿、肾病综合征（膜性肾病，无机汞）与肾功能损害、消化道（急性）：口腔与咽部烧灼痛、恶心呕吐、腹痛、血性腹泻（腐蚀性胃肠炎）、其他：皮疹（汞过敏）、唾液增多、食欲减退与体重下降。\n【待人工确认·本机素材无此段原文】","现病史":"汞中毒由金属汞蒸气（职业暴露：仪表、冶炼与牙科）、无机汞（含汞中药与化妆品）或有机汞（甲基汞，污染鱼贝类）引起。急性中毒表现为腐蚀性胃肠炎与肾损害，慢性中毒以神经精神症状（易兴奋症）、震颤与口腔炎为特征。治疗核心是脱离接触+驱汞治疗（二巯丙磺钠、二巯丁二酸）。\n常见表现：慢性中毒（常见）：易兴奋症（失眠、多梦、易激动、记忆力减退）、震颤（手指、眼睑与舌，精细动作困难如写字）与口腔炎（流涎、牙龈红肿与汞线）、神经系统：头痛、头晕、肢体麻木、周围神经病与情绪障碍（抑郁与焦虑）、肾脏：蛋白尿、肾病综合征（膜性肾病，无机汞）与肾功能损害、消化道（急性）：口腔与咽部烧灼痛、恶心呕吐、腹痛、血性腹泻（腐蚀性胃肠炎）、其他：皮疹（汞过敏）、唾液增多、食欲减退与体重下降。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压、心率、呼吸与体温（急性中毒）\n口腔：牙龈红肿与汞线（蓝黑色）、流涎与口腔黏膜糜烂（急性腐蚀性损伤）\n神经系统：震颤（手指、眼睑与舌，意向性加重）、腱反射、感觉与共济（周围神经病）\n精神情绪：易激惹、失眠、情绪不稳与认知减退（易兴奋症）\n肾脏：水肿（肾病综合征）、尿量与血压（肾损害）\n皮肤：皮疹与瘙痒（汞过敏）、色素沉着\n职业与环境：工作场所（仪表、冶炼与牙科）、化妆品与中药使用史、饮食（大量深海鱼）","辅助检查":"1. 血汞（急性暴露）+尿汞（慢性暴露）：诊断与随访（尿汞>0.25μmol/L需驱汞试验）\n2. 驱汞试验（二巯丙磺钠/二巯丁二酸后尿汞）：诊断与治疗指征\n3. 尿常规+24小时尿蛋白定量+肾功能：肾损害（肾病综合征与肾小管损害）评估\n4. 肝功能+电解质+血常规（驱汞监测）：药物不良反应与器官功能\n5. 神经传导+肌电图（周围神经病）：神经损害评估\n6. 甲状腺功能（鉴别震颤病因）+头颅MRI（必要时）：鉴别诊断\n7. 发汞/指甲汞（慢性暴露评估，必要时）：长期暴露标志（参考价值有限）","初步诊断":"1. 血汞（急性暴露）：>1.5μmol/L（30μg/L）提示中毒；尿汞（慢性暴露）：>0.25μmol/L（50μg/L）需驱汞试验\n2. 驱汞试验（二巯丙磺钠或二巯丁二酸后测尿汞）：诊断与治疗指征（尿汞明显增加支持中毒）\n3. 尿常规+24小时尿蛋白定量+肾功能：肾损害评估（蛋白尿与肾病综合征）\n4. 肝功能+电解质：器官功能评估\n5. 神经与精神评估：震颤程度、情绪与认知（易兴奋症）\n6. 暴露史（关键）：职业（仪表、冶炼、牙科与荧光灯制造）、饮食（大量深海鱼）、含汞化妆品与中药（朱砂、轻粉）\n7. 鉴别诊断：帕金森病（震颤但无汞暴露）、甲状腺功能亢进（震颤+易激动）、酒精戒断（震颤）与肾病综合征其他病因\n1. 汞中毒（ICD-10：T56.1）","鉴别诊断":"1. 鉴别诊断：帕金森病（震颤但无汞暴露）、甲状腺功能亢进（震颤+易激动）、酒精戒断（震颤）与肾病综合征其他病因\n2. 慢性汞中毒的典型三联征是『易兴奋症+震颤+口腔炎』（常被误诊为神经衰弱或甲亢）\n3. 诊断要点：血汞（急性暴露）：>1.5μmol/L（30μg/L）提示中毒；尿汞（慢性暴露）：>0.25μmol/L（50μg/L）需驱汞试验\n4. 诊断要点：驱汞试验（二巯丙磺钠或二巯丁二酸后测尿汞）：诊断与治疗指征（尿汞明显增加支持中毒）\n5. 诊断要点：尿常规+24小时尿蛋白定量+肾功能：肾损害评估（蛋白尿与肾病综合征）\n6. 诊断要点：肝功能+电解质：器官功能评估\n7. 诊断要点：神经与精神评估：震颤程度、情绪与认知（易兴奋症）\n8. 诊断要点：暴露史（关键）：职业（仪表、冶炼、牙科与荧光灯制造）、饮食（大量深海鱼）、含汞化妆品与中药（朱砂、轻粉）","处理方案":"【药物治疗·输液】\n⚠️ 驱汞治疗患者确诊后进行，急性中毒需先处理腐蚀性损伤！\n\n方案1（慢性/亚急性中毒，二巯丙磺钠）：\n 用法：二巯丙磺钠 125～250mg 肌注 qd（或 5%二巯丙磺钠 2～3ml 肌注 qd，疗程3～4天，间歇3～4天后再用，共2～3个疗程）\n\n方案2（急性无机汞中毒/腐蚀性损伤）：\n 用法：二巯丙磺钠 250mg 肌注 q4～6h（首日）→ 减量（疗程5～7天）；0.9%氯化钠/葡萄糖 静滴（补液与纠正电解质）；禁洗胃（腐蚀性损伤，可口服牛奶或蛋清保护黏膜）\n\n方案3（急性肾损伤与支持）：\n 用法：0.9%氯化钠 静滴（维持尿量）；碳酸氢钠 静滴（碱化尿液，遵医嘱）；必要时CRRT/血液透析（急性肾衰竭与汞清除）\n\n方案4（对症与营养支持）：\n 用法：0.9%氯化钠 静滴；维生素C 2g 静滴 qd；维生素B1 100mg 肌注 qd（神经损害）；白蛋白（低蛋白）\n\n📌 急性腐蚀性汞中毒禁洗胃（可致穿孔）；驱汞药物有肾毒性与骨髓抑制（监测尿量、肾功能与血常规）；严重肾衰竭时血液净化可清除汞-螯合物。\n\n【药物治疗·口服】\n⚠️ 驱汞与对症口服用药：\n\n药物1（口服驱汞，轻中度）：\n 用法：二巯丁二酸 10mg/kg tid（疗程5天，或按方案重复）；青霉胺 250mg qid（备选，青霉素过敏禁用）\n\n药物2（口腔炎与神经症状）：\n 用法：复方氯己定含漱液 含漱 bid（口腔炎）；甲钴胺 0.5mg tid + 维生素B1 10mg tid（周围神经病）；普瑞巴林 75mg bid（神经痛，遵医嘱）\n\n药物3（震颤与情绪）：\n 用法：普萘洛尔 10mg bid（震颤，按心率调整）；必要时抗焦虑药（劳拉西泮 0.5mg bid，短期）\n\n药物4（营养与支持）：\n 用法：维生素C 0.2g tid；复合维生素B 2片 tid；锌剂（竞争吸收，葡萄糖酸锌 1片 bid）\n\n📌 慢性汞中毒恢复慢（震颤与神经精神症状可持续数月至数年）；治疗期间须彻底脱离汞接触（包括更换牙科汞合金与停用含汞化妆品/中药）；定期复查尿汞与肾功能。\n\n【治疗】\n脱离接触（根本）：调离职业岗位、停用含汞化妆品与中药（朱砂等）、去除环境汞污染（汞泄漏清理与通风）、更换牙科汞合金（必要时）\n驱汞治疗：二巯丙磺钠（静脉/肌注，慢性与急性）或二巯丁二酸（口服），按疗程重复并监测不良反应\n急性腐蚀性损伤处理：禁洗胃，口服牛奶或蛋清保护黏膜，补液与纠正电解质，必要时胃镜评估；急性肾衰竭行血液净化\n肾损害处理：肾病综合征（激素±免疫抑制剂，肾内科指导）、保护肾功能与避免肾毒性药物\n神经系统症状处理：营养神经（B族维生素、甲钴胺）、震颤用普萘洛尔、情绪障碍心理治疗与抗焦虑药\n口腔炎处理：口腔卫生（含漱液）、避免刺激性食物、必要时止痛\n血液净化（重症/急性）：血液透析或CRRT（急性肾衰竭与汞-螯合物清除），必要时血浆置换\n随访：尿汞与血汞复查（治疗后）、肾功能与尿蛋白（每1～3个月）、神经精神症状评估与康复\n\n【处理要点】\n症状与暴露观察：记录震颤、口腔炎、情绪与尿量变化；了解并指导脱离汞暴露源（职业防护与环境清理）\n驱汞护理：按时给药并观察不良反应（过敏、皮疹与肾功能），监测尿量与尿汞\n肾功能监测：尿常规与尿蛋白（每日或隔日）、记录出入量，观察水肿与尿量变化\n口腔护理：口腔清洁（含漱液）、观察牙龈红肿与汞线、避免刺激性食物与烟酒\n心理精神护理：易兴奋症与情绪障碍常见（易激惹、失眠与抑郁），提供心理支持与情绪疏导\n环境与卫生宣教：汞泄漏处理（硫磺粉覆盖与通风）、职业防护（口罩与手套）、洗手与更衣、避免含汞化妆品与中药\n宣教：汞中毒恢复慢（需坚持治疗与随访）、彻底脱离接触是关键、避免使用含汞偏方与化妆品（尤其美白产品）\n\n【护理】\n症状观察：记录震颤程度（写字与持物）、口腔炎与情绪变化，观察尿量与水肿（肾损害）\n驱汞护理：按时给药并监测尿量、肾功能与血常规；观察皮疹与过敏反应，异常立即报告\n口腔护理：口腔清洁与含漱、观察牙龈与汞线、避免刺激性食物与烟酒\n心理护理：易兴奋症致情绪不稳与失眠（易与家属冲突），提供心理支持、环境安静与情绪疏导\n环境与卫生宣教：汞泄漏处理（硫磺粉、通风与密闭收集）、职业防护（口罩手套与更衣）、勤洗手、停用含汞化妆品与中药\n宣教：慢性汞中毒恢复慢（数月至数年）、彻底脱离接触是关键、遵医嘱完成驱汞疗程并定期复查尿汞与肾功能\n\n【饮食】\n高蛋白、高维生素饮食（促进汞排泄与组织修复）；急性期口腔损伤者流质或半流质温凉饮食\n补充富含锌与硒食物（竞争吸收与抗氧化）：海产品、瘦肉、坚果与全谷物\n避免大量食用深海大型鱼类（甲基汞蓄积：鲨鱼、旗鱼与金枪鱼）\n避免含汞中药（朱砂、轻粉）与含汞化妆品；避免饮酒（加重肝肾负担）\n肾功能损害者：限制蛋白与钠盐（按肾功能分期），监测电解质\n\n【注意事项】\n慢性汞中毒的典型三联征是『易兴奋症+震颤+口腔炎』（常被误诊为神经衰弱或甲亢）\n急性腐蚀性汞中毒禁止洗胃（可致消化道穿孔）；应先保护黏膜与补液\n驱汞药物均有肾毒性与骨髓抑制，需监测尿量、肾功能与血常规\n含汞化妆品（美白产品）与中药（朱砂、轻粉、水银）是常见的隐匿汞来源（需详细询问）\n严重肾衰竭时血液净化可清除汞-螯合物（但单纯汞难以透析清除，需先螯合）\n\n【急诊/急救】\n急性汞盐摄入伴口腔烧灼痛、血性腹泻与休克 → 禁洗胃、口服牛奶/蛋清、补液抗休克与驱汞治疗\n急性肾衰竭（少尿、无尿与肌酐升高）→ 驱汞+CRRT/血液透析，监测电解质\n汞中毒伴喉头水肿与呼吸困难 → 吸氧、激素与气道管理\n严重震颤影响进食与生活（无法自理）→ 住院驱汞治疗与康复评估\n汞泄漏事故致多人头痛与呼吸道刺激（吸入性汞蒸气中毒）→ 立即脱离现场、通风与吸氧，评估血汞与尿汞","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「汞中毒」原文）"},"icd10_diagnosis":"T56.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2499,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"fa798dd90235085d9dfc21c293adc5015ae49abf90f252b236bc3ced97f3c722","pinyin":"gongzhongdu","initials":"gzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T56.1",30]]},{"id":"templates-82eea57fd0b769f69276","key":"v1-c9ccc21dfe2a3058|templates-82eea57fd0b769f69276","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"河豚毒素中毒","category":"中毒/理化","raw":{"name":"河豚毒素中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】口唇舌尖麻木、四肢无力、共济失调、呼吸困难、心律失常、呼吸循环衰竭。\n【待人工确认·本机素材无此段原文】","现病史":"食用河豚鱼引起的神经毒素中毒\n常见表现：口唇舌尖麻木、四肢无力、共济失调、呼吸困难、心律失常、呼吸循环衰竭。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 河豚毒素检测（留取血液、尿液及洗胃液尽早送检定性/定量，明确诊断）\n2. 动脉血气分析（动态监测，评估低氧血症及呼吸性酸中毒，指导气管插管与机械通气时机）\n3. 血电解质（血钾、血钠、血镁等，低钾可加重肌无力，动态复查）\n4. 肝肾功能及心肌酶谱（肌酐、尿素氮、ALT、AST、CK、肌钙蛋白，评估横纹肌溶解及多器官损害）\n5. 心电图（床旁并持续心电监护，警惕窦性心动过缓、房室传导阻滞及室性心律失常）\n6. 胸部X线或CT（评估误吸性肺炎，机械通气者确认导管位置）","初步诊断":"1. 进食河豚史\n2. 临床表现\n3. 排除其他中毒\n1. 河豚毒素中毒（ICD-10：T61.0）","鉴别诊断":"1. 排除其他中毒\n2. 诊断要点：排除其他中毒\n3. 无特效解毒药\n4. 毒素耐热，烹饪不能破坏\n5. 呼吸肌麻痹是主要死因","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（洗胃（1）：\n 用法：1:5000高锰酸钾溶液洗胃）\n\n方案2：\n 用法：补液利尿\n\n方案3：\n 用法：呼吸兴奋剂\n\n方案4：\n 用法：糖皮质激素\n\n方案5：\n 用法：对症\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：无特效解毒药\n\n药物2：\n 用法：对症\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n催吐洗胃导泻\n对症支持\n呼吸支持\n促进毒素排泄\n预防感染\n\n【处理要点】\n观察呼吸\n监测生命体征\n保持呼吸道通畅\n记录出入量\n\n【护理】\n配合洗胃及吸附：进食后1～2小时内尽早洗胃，洗胃毕经胃管注入活性炭混悬液30～50g吸附残存毒素，洗胃时取头低侧卧位防误吸\n气道与呼吸管理：严密监测呼吸频率、幅度及血氧饱和度，警惕呼吸肌麻痹先兆（口唇麻木蔓延、构音障碍、进行性四肢无力、呼吸浅慢），出现呼吸抑制立即通知医生并配合气管插管、机械通气\n生命体征及心电监护：持续心电监护，警惕心动过缓、房室传导阻滞，床旁备阿托品；监测血压，低血压者遵医嘱补液及使用血管活性药物\n神经系统与出入量观察：TTX无特效解毒剂，重点观察感觉异常→肌无力→延髓麻痹的演变并记录肌力变化；留置导尿管记录出入量，预防急性肾损伤\n防误吸护理：昏迷者禁食、侧卧位、及时吸痰，保持呼吸道通畅\n\n【饮食】\n洗胃后暂禁食禁水4～6小时，无恶心呕吐、肠鸣音恢复后开始进食\n进食初选温凉流质（米汤、藕粉、稀释果汁），少量多餐，逐步过渡至半流质、软食\n忌油腻、生冷、辛辣及粗糙食物，避免刺激胃肠道；严格禁食河豚及来源不明的鱼类\n神志清楚、无呕吐者可多饮温水促进毒素排泄；经口摄入不足者予静脉补液维持水电解质平衡\n恢复期予高蛋白、富含B族维生素饮食（蛋、奶、瘦肉、谷类），促进神经功能恢复\n\n【注意事项】\n无特效解毒药\n毒素耐热，烹饪不能破坏\n呼吸肌麻痹是主要死因\n\n【急诊/急救】\n呼吸肌麻痹：气管插管机械通气\n心律失常：对症处理\n休克：抗休克","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「河豚毒素中毒」原文）"},"icd10_diagnosis":"T61.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2500,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"97402ffdf0c7f8669fe31e55f1d60fc7cbcda0e98856e62b1c36c26a332b5d21","pinyin":"hetundusuzhongdu","initials":"htdszd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T61.0",30]]},{"id":"templates-12987c0e118f99a02e4f","key":"v1-c9ccc21dfe2a3058|templates-12987c0e118f99a02e4f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泄泻(中医辨证)","category":"中医","raw":{"name":"泄泻(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】排便次数增多、粪质稀溏、完谷不化、泻出如水样、腹痛腹胀。\n【待人工确认·本机素材无此段原文】","现病史":"泄泻是以排便次数增多，粪质稀溏或完谷不化，甚至泻出如水样为主症的病证。\n常见表现：排便次数增多、粪质稀溏、完谷不化、泻出如水样、腹痛腹胀。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以排便次数增多、粪质稀溏、完谷不化，甚则泻出如水样为主症，日行三五次乃至十数次以上，伴腹胀腹痛、肠鸣纳呆，起病与饮食不节、感受寒湿相关，入院即刻完善大便常规加隐血检查，了解有无白细胞、红细胞及寄生虫卵，初步明确系感染性抑或非感染性腹泻；查大便培养加药物敏感试验及艰难梭菌毒素检测，排除细菌性痢疾、沙门菌感染及抗生素相关性肠炎；查血常规、C反应蛋白、降钙素原及红细胞沉降率，评估感染与炎症活动程度；因泻下频繁、纳呆食少，患者易出现脱水及电解质紊乱，完善电解质、肾功能检查排除低钾、低钠血症及肾前性肾功能不全；查肝功能、血清白蛋白了解营养状况及有无低蛋白血症；腹泻日久需排除内分泌及全身性疾病，完善甲状腺功能（TSH、FT3、FT4）检查排除甲状腺功能亢进所致腹泻；对中老年、病程在4～6周以上或伴消瘦、黏液脓血便等报警症状者，完善结肠镜检查并多段多点活检，明确有无溃疡性结肠炎、克罗恩病、肠结核及结肠肿瘤，必要时完善小肠CT或小肠镜检查；查腹部超声了解肝胆胰脾及肠管情况，排除慢性胰腺炎、胆道疾病所致消化不良性腹泻；查粪便钙卫蛋白评估肠道炎症程度，必要时行乳糖氢呼气试验及食物不耐受检测鉴别吸收不良。血常规、大便常规、电解质入院即刻完成，结肠镜等有创检查待病情稳定、肠道准备充分后择期进行；治疗期间定期复查大便常规、电解质及肾功能。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 以大便粪质稀溏为诊断的主要依据，或完谷不化，或粪质清稀，甚则如水样，大便次数增多，每日三五次以至十数次以上。\n2. 常兼有腹胀、腹痛、肠鸣、纳呆。\n3. 起病或急或缓，常由外感寒热湿邪、内伤饮食情志、劳倦、脏腑功能失调等诱发或加重。\n1. 泄泻(中医辨证)（ICD-10：K52.9）","鉴别诊断":"1. 泄泻与痢疾鉴别：痢疾以腹痛、里急后重、便下赤白脓血为特征","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（湿热伤中）：\n 用法：葛根素注射液0.4g+5%GS250ml静滴qd\n\n方案2（脾胃虚弱）：\n 用法：参麦注射液40ml+5%GS250ml静滴qd\n\n方案3（肾阳虚衰）：\n 用法：参附注射液20ml+5%GS250ml静滴qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（寒湿内盛）：\n 用法：藿香正气散加减（藿香9g 紫苏9g 白芷6g 白术9g 茯苓9g 陈皮6g 半夏9g 厚朴9g 大腹皮9g 桔梗6g 甘草3g 生姜3片 大枣3枚）\n\n药物2（湿热伤中）：\n 用法：葛根芩连汤加减（葛根15g 黄芩9g 黄连6g 甘草3g 车前子9g 茯苓9g）\n\n药物3（食滞肠胃）：\n 用法：保和丸加减（山楂9g 神曲9g 半夏9g 茯苓9g 陈皮6g 连翘9g 莱菔子9g 麦芽9g）\n\n药物4（肝气乘脾）：\n 用法：痛泻要方加减（白术9g 白芍9g 陈皮6g 防风6g 柴胡9g 木香6g）\n\n药物5（脾胃虚弱）：\n 用法：参苓白术散加减（人参6g 白术9g 茯苓9g 甘草3g 山药9g 白扁豆9g 莲子肉9g 薏苡仁9g 砂仁3g 桔梗6g）\n\n药物6（肾阳虚衰）：\n 用法：四神丸加减（补骨脂12g 肉豆蔻6g 五味子6g 吴茱萸3g 生姜3片 大枣5枚）\n\n药物7（中气下陷）：\n 用法：补中益气汤加减（黄芪15g 人参6g 白术9g 炙甘草3g 当归9g 陈皮6g 升麻3g 柴胡6g）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针灸：取天枢、上巨虚、阴陵泉、水分；寒湿加神阙，湿热加内庭，食滞加中脘，肝郁加太冲，脾虚加脾俞、足三里，肾虚加肾俞、命门\n耳针：大肠、胃、脾、肝、肾、交感\n穴位注射：天枢、上巨虚，维生素B1或黄连素注射液\n推拿：摩腹，按揉中脘、天枢、足三里，捏脊\n\n【处理要点】\n注意饮食卫生，忌生冷油腻\n腹部保暖，避免受寒\n保持心情舒畅\n慢性泄泻适当锻炼，增强体质\n\n【护理】\n观察并记录大便次数、性状、颜色、气味及有无黏液脓血，注意观察精神、尿量、口渴及皮肤弹性，发现口干尿少、眼眶凹陷等伤津脱液之象及时报告并配合补液；泄泻频作时便后以温水清洗肛周、外涂油膏护臀，防止皮肤破损。\n寒湿困脾、肾阳虚衰者注意腹部与腰背保暖，避免受凉、冒雨涉水、汗出当风，可予热水袋温熨腹部或艾灸神阙、天枢、足三里以温中止泻。\n湿热伤中者居室宜通风凉爽，勤换衣被床单，做好便器消毒，腹泻频繁者注意隔离防护，防止交叉感染；急性期卧床休息，减少肠道刺激。\n肝气乘脾者重视情志护理，劝导其戒怒解郁、避免忧思恼怒，可通过聊天、听乐、移情易性等法疏导情绪，并指导家属减少不良刺激。\n服药护理：虚寒证汤剂宜温服、饭前服，补益之剂文火久煎；食滞者服消导药后观察泻下情况；泄泻止后不可骤然停药，遵医嘱巩固调理，忌自行加用收敛止泻之品闭门留寇。\n\n【饮食】\n湿热伤中者忌肥甘厚味、辛辣煎炸及酒酪甜腻之品，宜清淡易消化，可食马齿苋粥、薏苡仁绿豆粥以清热利湿。\n寒湿困脾者忌生冷瓜果、凉拌菜及冷饮，宜温热饮食，可用生姜、陈皮煮粥或代茶饮以散寒化湿止泻。\n食滞肠胃者宜控制食量，忌暴饮暴食及油腻难化之物，暂进米汤、烂面等流质半流质，可饮山楂、麦芽、萝卜煎水消食导滞。\n脾胃虚弱、肾阳虚衰者忌生冷、坚硬及粗纤维过多之品，宜细软温热、少食多餐，常食山药、莲子、芡实、小米粥；肾阳虚者可加羊肉、核桃、韭菜温补脾肾。\n肝气乘脾者忌进食时生气动怒，宜进餐环境平和、少食多餐，可用陈皮、佛手、玫瑰花代茶饮疏肝理气；同时注意饮食卫生，饭前便后洗手，餐具煮沸消毒。\n\n【注意事项】\n泄泻与痢疾鉴别：痢疾以腹痛、里急后重、便下赤白脓血为特征；泄泻以排便次数增多、粪质稀溏为特征，无里急后重和脓血便。\n\n【急诊/急救】\n泄泻伴严重脱水、电解质紊乱、休克，立即静脉补液，纠正水电解质紊乱。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「泄泻（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】泄泻\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、寒湿泄泻\n    症状舌脉：泻下清稀，甚则如水样，腹痛肠鸣，脘闷食少，或兼恶寒发热、头痛身痛，舌淡苔白腻，脉濡缓\n    治法：芳香化湿、解表散寒\n    方剂：藿香正气散\n\n二、湿热泄泻\n    症状舌脉：腹痛即泻，泻下急迫，势如水注，粪色黄褐臭秽，肛门灼热，烦热口渴，小便短黄，舌红苔黄腻，脉滑数\n    治法：清热利湿、分利止泻\n    方剂：葛根芩连汤\n\n三、食滞肠胃\n    症状舌脉：腹痛肠鸣，泻下臭如败卵，泻后痛减，嗳腐酸臭，脘腹胀满，不思饮食，舌苔垢腻，脉滑\n    治法：消食导滞、和中止泻\n    方剂：保和丸\n\n四、脾虚泄泻\n    症状舌脉：大便时溏时泻，迁延反复，稍进油腻则便次增多，食少腹胀，神疲乏力，面色萎黄，舌淡胖有齿痕、苔白，脉缓弱\n    治法：健脾益气、化湿止泻\n    方剂：参苓白术散\n\n五、肾阳虚衰\n    症状舌脉：黎明之前脐腹作痛，肠鸣即泻，泻后则安，完谷不化，形寒肢冷，腰膝酸冷，舌淡胖苔白，脉沉细\n    治法：温肾健脾、固涩止泻\n    方剂：四神丸\n\n六、肝气乘脾\n    症状舌脉：腹痛肠鸣，泻后痛减，每因情志不遂而发作，胸胁胀闷，嗳气食少，苔薄白，脉弦\n    治法：抑肝扶脾、理气止泻\n    方剂：痛泻要方\n\n【方剂参考】\n  藿香正气散：组成 藿香9g、紫苏6g、白芷6g、半夏曲6g、陈皮6g、白术6g、茯苓6g、厚朴6g、桔梗6g、大腹皮6g、甘草3g、生姜3片、大枣1枚；功效 解表化湿，理气和中\n      用法：上药为散，每次6-9g，加生姜3片、大枣1枚，水煎热服，日二次；亦可服藿香正气水、软胶囊（水剂含酒精，服后勿驾车）。\n      注意：湿热霍乱（吐泻物臭秽、舌红苔黄）及阴虚火旺者忌用；服含酒精剂型者禁与头孢类药物同用；孕妇慎用。\n  葛根芩连汤：组成 葛根15g、甘草6g、黄芩9g、黄连9g；功效 解表清里\n      用法：葛根先煎，再入黄芩、黄连、甘草同煎，去滓分二次温服；亦可研末制丸。\n      注意：虚寒下利（泻下清稀、腹冷喜温）及脾胃虚寒者忌用；孕妇慎用；苦寒之剂不宜久服。（本方黄连9g超《中国药典》2020年版一部黄连用量2-5g，系教材原方折算，临床宜酌减）\n  保和丸：组成 山楂18g、神曲6g、半夏9g、茯苓9g、陈皮6g、连翘6g、莱菔子6g；功效 消食和胃\n      用法：上药为末，炊饼为丸如梧桐子大，每次6-9g，麦芽汤或温开水送服，日二至三次；亦可作汤剂。\n      注意：脾虚无食积者不宜久服（消导伤正）；孕妇慎用山楂、莱菔子；忌与滋补药同服。\n  参苓白术散：组成 人参9g、白术9g、茯苓9g、甘草9g、山药15g、莲子肉9g、白扁豆12g、薏苡仁15g、砂仁6g、桔梗6g；功效 益气健脾，渗湿止泻\n      用法：上药为末，每次6g，以大枣汤（或温开水）调服，日二至三次；亦可作汤剂，日二次。\n      注意：湿热内盛、实热泄泻者忌用；感冒发热期间停服；本方偏温补，阴虚者慎用。\n  四神丸：组成 肉豆蔻6g、补骨脂12g、五味子6g、吴茱萸3g、生姜4片、大枣10枚；功效 温肾暖脾，固肠止泻\n      用法：上药为末，生姜、大枣同煮取枣肉为丸，每次6-9g，空腹或食前淡盐汤送服，日二次；亦可作汤剂，宜睡前服。\n      注意：湿热泄泻、伤食泄泻及急性肠炎者忌用；本方温涩，久痢阴虚及有实热者不宜。\n  痛泻要方：组成 白术9g、白芍9g、陈皮6g、防风6g；功效 补脾柔肝，祛湿止泻\n      用法：水煎温服，日二次；亦可为丸或散，每次6-9g，日二至三次。\n      注意：湿热或虚寒泄泻（非肝旺脾虚者）不宜；伤食泄泻者忌用。\n\n【西医诊断】\n  肠易激综合征 / 慢性肠炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"K52.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2501,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a15bbdfc5372229e16a021b023a9e25994d7750c3bb1b269e1e54294e9a4963b","pinyin":"xiexie(zhongyibianzheng)","initials":"xx(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","K52.9",30]]},{"id":"templates-7560f3cffb96530ee92c","key":"v1-c9ccc21dfe2a3058|templates-7560f3cffb96530ee92c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泌尿系结石(鉴别诊断)","category":"鉴别诊断速查","raw":{"name":"泌尿系结石(鉴别诊断)","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肾绞痛：突发腰部剧痛向会阴部放射、血尿（镜下/肉眼）、恶心呕吐、尿频尿急（输尿管下段结石）、肾区叩击痛、合并感染：发热寒战。\n【待人工确认·本机素材无此段原文】","现病史":"鉴别要点：患者有腹胀、腹痛、恶心、呕吐等表现，查体可有双肾区叩击痛及双输尿管行经处压痛。泌尿系彩超及X线检查有助于鉴别。\n常见表现：肾绞痛：突发腰部剧痛向会阴部放射、血尿（镜下/肉眼）、恶心呕吐、尿频尿急（输尿管下段结石）、肾区叩击痛、合并感染：发热寒战。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）\n一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿\n皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）\n头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸\n胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）\n腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征\n外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）\n四肢：水肿（凹陷性）、关节痛、肾性骨病体征\n其他：尿量观察（少尿/无尿/多尿）、尿色","辅助检查":"1. 泌尿系超声（双肾+输尿管+膀胱）：首选检查，明确结石部位、大小、数目及有无肾积水\n2. 尿常规+尿沉渣镜检：查血尿、脓尿，伴发热寒战者加做尿培养+药敏\n3. 肾功能（血肌酐、尿素氮、eGFR）：评估梗阻性肾病及肾功能损害程度\n4. 泌尿系CT平扫（必要时CT尿路成像）：明确结石位置、大小、密度及梗阻情况，指导治疗方案\n5. 血电解质+血气分析：肾绞痛剧烈呕吐或疑尿路梗阻时，评估水电解质及酸碱紊乱\n6. 24小时尿液成分分析：反复发作或代谢异常者明确结石成因，指导预防复发","初步诊断":"1. 典型肾绞痛+血尿\n2. 尿常规：红细胞\n3. 泌尿系超声（首选，可发现结石和肾积水）\n4. CT平扫（最敏感，可发现微小/尿酸结石）\n5. KUB平片（不透X线结石）\n1. 泌尿系结石(鉴别诊断)（ICD-10：N39.0）","鉴别诊断":"1. 泌尿系彩超及X线检查有助于鉴别\n2. 鉴别要点：患者有腹胀、腹痛、恶心、呕吐等表现，查体可有双肾区叩击痛及双输尿管行经处压痛\n3. 诊断要点：患者有腹胀、腹痛、恶心、呕吐等表现，查体可有双肾区叩击痛及双输尿管行经处压痛。泌尿系彩超及X线检查有助于鉴别。","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：山莨菪碱 10mg 静滴（解痉）\n\n方案2：\n 用法：帕瑞昔布 40mg 静推（止痛）\n\n方案3：\n 用法：0.9%氯化钠 500-1000ml 静滴（补液利尿）\n\n方案4：\n 用法：间苯三酚 80mg 静滴\n\n方案5（合并感染）：\n 用法：头孢曲松+甲硝唑\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：双氯芬酸钠 50mg（NSAIDs首选止痛）\n\n药物2：\n 用法：坦索罗辛 0.4mg qd（α受体阻滞剂，促进排石）\n\n药物3：\n 用法：排石颗粒（中成药辅助）\n\n药物4：\n 用法：碳酸氢钠（尿酸结石碱化尿液）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n止痛：NSAIDs首选（双氯芬酸钠/帕瑞昔布）\n解痉：山莨菪碱/间苯三酚\n补液利尿\nα受体阻滞剂促进排石（坦索罗辛）\n<6mm结石：保守排石（大量饮水+运动）\nESWL体外冲击波碎石（6-20mm肾结石/输尿管上段）\n输尿管镜/经皮肾镜（较大/复杂结石）\n合并感染+梗阻：紧急引流\n\n【处理要点】\n大量饮水（2000-3000ml/d）\n适当运动（跳绳、爬楼梯，促进排石）\n坦索罗辛松弛输尿管助排石\n收集排出的结石做成分分析\n根据结石成分调整饮食（草酸钙结石：限草酸；尿酸结石：低嘌呤+碱化尿液）\n合并感染发热需紧急处理\n\n【护理】\n疼痛护理：评估肾绞痛部位及程度，遵医嘱解痉镇痛，观察疗效与不良反应\n病情观察：观察尿色、尿量，指导排尿后尿液过筛网，收集排出结石送成分分析\n出入量管理：记录24h出入量，鼓励多饮水，保持尿量>2000ml/d（心肾功能不全者酌情调整）\n感染监测：每日监测体温，结石梗阻合并发热寒战警惕尿源性脓毒血症，立即报告医师\n管路护理：留置导尿或输尿管支架者妥善固定、保持引流通畅，每日会阴护理2次防逆行感染\n\n【饮食】\n大量饮水：日饮水量2000-3000ml均匀分配，睡前饮水防夜间尿液浓缩\n限嘌呤饮食：忌动物内脏、海鲜、浓肉汤、啤酒，尿酸结石者多食新鲜蔬果碱化尿液\n限草酸饮食：少食菠菜、浓茶、坚果、巧克力，草酸钙结石者含草酸蔬菜焯水后食用\n低盐限蛋白：每日食盐<6g，避免过量高蛋白饮食，减少尿钙排泄\n成分针对性调整：含钙结石不宜盲目限钙（适量奶制品可减少草酸吸收），行结石成分分析后个体化饮食指导\n\n【注意事项】\n【鉴别要点】鉴别要点：患者有腹胀、腹痛、恶心、呕吐等表现，查体可有双肾区叩击痛及双输尿管行经处压痛。泌尿系彩超及X线检查有助于鉴别。\nNSAIDs是肾绞痛首选镇痛\n结石<6mm自行排出率高\n合并感染+梗阻是急症（可致脓肾/脓毒症）\n双侧梗阻/孤立肾结石梗阻致无尿需急诊\n尿酸结石X线不显影（CT可发现）\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n合并发热寒战（脓肾）、无尿、剧烈疼痛不缓解→急诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「泌尿系结石（鉴别诊断）」原文）"},"icd10_diagnosis":"N39.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2502,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"74194ccead23a22ffd83883a74a60fca3932f050e7638aa3033e69377418ad61","pinyin":"miniaoxijieshi(jianbiezhenduan)","initials":"mnxjs(jbzd)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","N39.0",30]]},{"id":"templates-43822a5b661684a652e9","key":"v1-c9ccc21dfe2a3058|templates-43822a5b661684a652e9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"泌尿系统感染","category":"鉴别诊断速查","raw":{"name":"泌尿系统感染","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】膀胱炎：尿频、尿急、尿痛、下腹痛、血尿、肾盂肾炎：发热、寒战、腰痛、肾区叩痛+尿路刺激征、尿液浑浊、老年/糖尿病患者症状可不典型。\n【待人工确认·本机素材无此段原文】","现病史":"包括肾盂肾炎、肾周脓肿等，病因多为输尿管结石或尿路梗阻所致，细菌感染后可出现对应侧腰痛、腹痛、胀痛或绞痛，高热，行腹部CT或B超可进一步明确诊断。\n常见表现：膀胱炎：尿频、尿急、尿痛、下腹痛、血尿、肾盂肾炎：发热、寒战、腰痛、肾区叩痛+尿路刺激征、尿液浑浊、老年/糖尿病患者症状可不典型。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（尿路感染发热）、脉搏、呼吸、血压（肾性高血压）\n一般情况：神志、精神状态、面容（贫血貌/尿毒症面容）、体位、有无水肿\n皮肤黏膜：苍白（肾性贫血）、尿素霜（尿毒症）、出血点、水肿（眼睑/下肢/腰骶部）\n头颈部：眼睑水肿、巩膜苍白、口腔溃疡（尿毒症）、尿素味呼吸\n胸部：心率心律、心音（心包摩擦音提示尿毒症心包炎）、双肺啰音（肺水肿）\n腹部：肾区压痛及叩击痛（肋脊角）、输尿管点压痛（腹直肌外缘与脐水平线/髂前上棘连线）、膀胱区充盈/压痛、腹部包块（多囊肾）、腹水征\n外生殖器：根据需要检查（尿道口分泌物、睾丸附睾）\n四肢：水肿（凹陷性）、关节痛、肾性骨病体征\n其他：尿量观察（少尿/无尿/多尿）、尿色","辅助检查":"1. 尿常规（清洁中段尿）：首选初筛，评估白细胞酯酶、亚硝酸盐及镜检白细胞/红细胞，留取晨尿或膀胱停留≥4h的中段尿\n2. 尿培养+药敏：治疗前留取清洁中段尿送检，明确病原菌及耐药情况；反复发作或治疗无效者必要时行导尿管或耻骨上穿刺留取标本\n3. 肾功能（血肌酐、尿素氮、eGFR）：评估肾实质受累程度及基础肾功能，指导抗菌药物剂量调整\n4. 泌尿系超声（双肾、输尿管、膀胱）：排查结石、梗阻、积水、膀胱残余尿等解剖易感因素，必要时行CT尿路造影\n5. 血常规+C反应蛋白：评估全身炎症反应，伴发热寒战者加做血培养（发热时采血）\n6. 血压监测及24h尿蛋白：急性肾盂肾炎或合并肾损伤者监测血压、评估蛋白尿及肾小管损伤","初步诊断":"1. 典型尿路刺激征\n2. 尿常规：白细胞尿、脓尿、血尿\n3. 尿培养：菌落计数≥10⁵/ml（确诊）\n4. 血常规（肾盂肾炎WBC升高）\n5. 泌尿系超声（排除结石/梗阻/畸形）\n1. 泌尿系统感染（ICD-10：N39.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：左氧氟沙星 0.4g 静滴 qd 或头孢曲松 2g 静滴 qd（肾盂肾炎/重症）\n\n方案2：\n 用法：0.9%氯化钠 静滴\n\n方案3（退热）：\n 用法：对乙酰氨基酚\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（急性单纯性膀胱炎）：\n 用法：左氧氟沙星 0.4g qd×3天、头孢克肟 0.1g bid×3-7天、呋喃妥因 0.1g qid×5天、磷霉素氨丁三醇 3g 单次\n\n药物2（肾盂肾炎）：\n 用法：左氧氟沙星/头孢类 10-14天\n\n药物3（反复发作）：\n 用法：长程低剂量抑菌治疗\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n抗感染（根据尿培养结果调整）\n多饮水、勤排尿\n碱化尿液（碳酸氢钠，缓解刺激症状）\n去除诱因（结石、梗阻、糖尿病）\n绝经后反复发作者可局部雌激素\n\n【处理要点】\n多饮水（2000ml/d以上），勤排尿（不要憋尿）\n注意个人卫生（从前向后擦拭）\n避免辛辣刺激饮食\n急性期注意休息\n抗生素足疗程（不要症状缓解就停药）\n反复发作者查找诱因（结石、糖尿病、妇科炎症）\n性生活后排尿\n\n【护理】\n病情观察：密切监测体温、寒战、腰痛及膀胱刺激征（尿频、尿急、尿痛）变化，发热者每4h测体温，警惕感染性休克早期表现\n多饮水利尿：无心肾功能禁忌时指导每日饮水量2000ml以上，少量多次饮用，勤排尿、勿憋尿，以冲洗尿道减轻刺激\n标本留取护理：指导正确留取清洁中段尿（清洁外阴、弃去前段尿），标本采集后2h内送检，避免污染\n会阴及皮肤护理：每日温水清洗会阴并勤换内裤，保持干燥；留置导尿管者每日尿道口消毒2次，保持引流袋低于膀胱\n用药观察：观察抗菌药物不良反应（皮疹、胃肠道反应、耳鸣、血尿等），强调足量足疗程用药、勿自行停药或减量\n\n【饮食】\n多饮水多排尿：每日饮水量2000~2500ml（心肾功能正常者），分次饮用，使每日尿量维持1500ml以上，起到机械冲刷尿路作用\n清淡饮食：避免辛辣刺激性食物（辣椒、酒、浓茶、咖啡、烧烤），减少对尿路的化学刺激\n适量优质蛋白：以鸡蛋、瘦肉、鱼肉、牛奶等优质蛋白为主；合并肾功能不全者按0.6~0.8g/(kg·d)限制蛋白摄入\n限制高嘌呤及高糖食物：少食海鲜、动物内脏、浓肉汤及含糖饮料，避免尿液过度酸化及滋生细菌\n可选利尿通淋食物：适量食用冬瓜、西瓜、芹菜、玉米须水等辅助增加尿量（限钾限水者除外）\n\n【注意事项】\n【鉴别要点】包括肾盂肾炎、肾周脓肿等，病因多为输尿管结石或尿路梗阻所致，细菌感染后可出现对应侧腰痛、腹痛、胀痛或绞痛，高热，行腹部CT或B超可进一步明确诊断。\n膀胱炎3天疗法，肾盂肾炎10-14天\n尿培养在使用抗生素前留取\n糖尿病患者尿路感染易上行致肾盂肾炎/肾脓肿\n男性尿路感染需查找诱因（前列腺增生、结石）\n孕妇无症状菌尿也需治疗\n【2023/2024指南更新】急性单纯性膀胱炎经验性用药首选呋喃妥因（0.1g qid×5天）、磷霉素氨丁三醇（3g单次）或头孢类（已收录），疗程3-5天；鉴于大肠埃希菌对氟喹诺酮耐药率持续升高，左氧氟沙星不作膀胱炎一线、仅作备选（已收录）；肾盂肾炎可用静脉β-内酰胺类或氟喹诺酮，疗程7-14天。\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n高热寒战、腰痛剧烈、血压下降、糖尿病患者→可能肾盂肾炎/脓毒症，急诊","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"N39.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2503,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3aafc51f592e76f272cb624d42b44c8c3ae8a28b13fff5dd31bb5267088372f3","pinyin":"miniaoxitongganran","initials":"mnxtgr","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","N39.0",30]]},{"id":"templates-651015ce1b64e87e3227","key":"v1-c9ccc21dfe2a3058|templates-651015ce1b64e87e3227","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"洋地黄类药物中毒","category":"中毒/理化","raw":{"name":"洋地黄类药物中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】胃肠道：恶心呕吐、食欲减退、腹泻（最早出现）、神经系统：头痛、乏力、眩晕、失眠、烦躁、视觉异常（黄视、绿视、视物模糊）、心脏：各种心律失常（室早二联律、房室传导阻滞、房颤伴房室传导阻滞、室速、室颤）、高钾血症（抑制Na-K-ATP酶）。\n【待人工确认·本机素材无此段原文】","现病史":"地高辛、西地兰等洋地黄类药物过量，致各种心律失常和胃肠道症状\n常见表现：胃肠道：恶心呕吐、食欲减退、腹泻（最早出现）、神经系统：头痛、乏力、眩晕、失眠、烦躁、视觉异常（黄视、绿视、视物模糊）、心脏：各种心律失常（室早二联律、房室传导阻滞、房颤伴房室传导阻滞、室速、室颤）、高钾血症（抑制Na-K-ATP酶）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 血清地高辛浓度测定：末次服药≥6h后（谷浓度）采血，肾功能不全、联合胺碘酮/维拉帕米等药物时结合游离地高辛浓度评估\n2. 12导联心电图＋持续心电监护：动态复查，重点识别房室传导阻滞、窦性心动过缓、双向性室速、房速伴房室阻滞等洋地黄中毒特征性心律失常\n3. 血钾、血镁、血钙及血气分析：急查并反复监测——高钾血症为中毒严重程度的重要标志，同时警惕低钾诱发洋地患者感性增加\n4. 肾功能（血肌酐、eGFR）及电解质全套：肾功能不全显著增加中毒风险，需评估排泄能力与补钾时机\n5. 肝功能、心肌损伤标志物（cTnI、CK-MB、BNP）：排除急性心肌缺血/心梗、心衰加重所致心律失常与恶心呕吐\n6. 毒物筛查（血/尿，必要时送检）：明确是否合并其他药物（如β受体阻滞剂、钙通道阻滞剂、抗心律失常药）过量，避免漏诊混合中毒","初步诊断":"1. 洋地黄类药物用药史（地高辛、西地兰、毒毛花苷K）\n2. 胃肠道症状+视觉异常+心律失常\n3. 血地高辛浓度>2.0ng/ml（治疗窗0.5-2.0ng/ml）\n4. 心电图：室早二联律、房室传导阻滞、ST-T鱼钩样改变\n5. 高钾血症\n1. 洋地黄类药物中毒（ICD-10：T46.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：【特效解毒】地高辛特异性抗体（Digibind）：\n\n方案2：\n 用法：剂量（瓶数）= 摄入总量(mg) ÷ 0.5mg/瓶 或 血浓度(ng/ml) × 体重(kg) ÷ 100\n\n方案3：\n 用法：用灭菌注射用水稀释后ivgtt（30分钟）\n\n方案4（停药）：\n 用法：立即停用洋地黄类药物及排钾利尿剂\n\n方案5（补钾）：\n 用法：10%氯化钾10-15ml + 5%GS500ml ivgtt（血钾<5.0mmol/L时）\n\n方案6（补镁）：\n 用法：25%硫酸镁10ml + 5%GS250ml ivgtt\n\n方案7：\n 用法：苯妥英钠100-200mg 缓慢静注（50mg/min），治疗室性心律失常\n\n方案8：\n 用法：利多卡因50-100mg iv，随后1-4mg/min iv泵控（室速时）\n\n方案9：\n 用法：阿托品0.5-1mg iv（缓慢性心律失常、房室传导阻滞）\n\n方案10：\n 用法：洗胃（口服过量1小时内），活性炭口服\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：氯化钾缓释片1g tid（血钾正常偏低时）\n\n药物2：\n 用法：门冬氨酸钾镁2片 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即停药\n特效解毒：地高辛特异性抗体（严重中毒首选）\n纠正电解质紊乱：补钾补镁\n抗心律失常：苯妥英钠、利多卡因（室性），阿托品（缓慢性）\n禁用电复律（可致室颤，除非室颤）\n对症支持\n\n【处理要点】\n持续心电监护\n监测血钾、血镁、肾功能、地高辛血药浓度\n记录出入量\n观察心律、心率、血压变化\n备好抢救设备\n\n【护理】\n洗胃配合：口服中毒4~6h内（缓释剂型可延至12h）置胃管洗胃，洗胃后予活性炭50g口服（洋地黄类存在肠肝循环，可间隔4~6h重复给药），操作中头偏一侧、防误吸防窒息\n解毒剂观察：使用地高辛特异性抗体片段（DigiFab/Digibind）时密切监测血压、心律及血钾——用药后血钾可骤降，警惕低钾诱发心律失常；观察皮疹、支气管痉挛等过敏反应\n生命体征与心电监护：持续心电监护重点观察心率与心律（心动过缓、传导阻滞、室性心律失常），床旁备阿托品、苯妥英钠、利多卡因，遵医嘱给药并记录\n气道与呕吐管理：频繁呕吐者及时吸引、侧卧位防误吸性肺炎，意识障碍或呼吸抑制者监测SpO₂，必要时协助气管插管\n出入量及用药观察：准确记录出入量与尿量（评估肾排泄），避免快速大量补液加重心衰；禁用钙剂处理高钾（可诱发或加重洋地黄心律失常），低钾者按医嘱补钾并监测\n\n【饮食】\n洗胃后暂禁食4~6h，观察有无呕吐、误吸及消化道出血后再逐步恢复进食\n恢复期予流质→半流质过渡（米汤、藕粉、稀粥），少量多餐，避免一次进食过多诱发恶心呕吐\n呕吐明显者暂禁食，予静脉补液维持水电解质平衡，遵医嘱根据血钾水平补钾或限钾\n血钾偏高时忌高钾食物（香蕉、橙汁、土豆、菠菜等）；低钾纠正期可适当补充含钾食物\n忌浓茶、咖啡及酒精等刺激性饮品，记录进食与呕吐情况，出现吞咽困难、黄疸等及时报告\n\n【注意事项】\n洋地黄中毒最常见诱因：低钾、低镁、肾功能不全、心肌缺血、甲状腺功能减退\n电复律可诱发室颤，禁用（除非室颤）\n钙剂可加重洋地黄毒性，禁用\n地高辛特异性抗体起效快（30分钟内），但可使地高辛浓度检测失真\n老年人、肾功能不全者易中毒，需减量并监测血药浓度\n\n【急诊/急救】\n【第一步】立即停用洋地黄类药物及排钾利尿剂\n【第二步】心电监护，建立静脉通路，查电解质（尤其血钾）、肾功能、地高辛血药浓度\n【第三步】清除毒物：口服过量1小时内洗胃，活性炭50-100g口服\n【第四步】特效解毒（严重中毒）：地高辛特异性抗体，剂量=摄入量(mg)÷0.5 或 血浓度×体重÷100，ivgtt 30分钟\n【第五步】补钾补镁：10%氯化钾10-15ml+5%GS500ml ivgtt，25%硫酸镁10ml+5%GS250ml ivgtt（血钾<5.0时）\n【第六步】室性心律失常：苯妥英钠100-200mg缓慢静注（50mg/min），或利多卡因50-100mg iv后1-4mg/min泵控\n【第七步】缓慢性心律失常/房室传导阻滞：阿托品0.5-1mg iv，必要时临时起搏\n【第八步】高钾血症：胰岛素+葡萄糖、碳酸氢钠、钙剂（注意钙剂可加重毒性，慎用）\n【第九步】室颤：立即电除颤（唯一可用电复律的情况）\n【第十步】监测：持续心电监护，每2-4小时复查电解质，监测地高辛浓度\n【禁忌】禁用钙剂、电复律（室颤除外）、拟交感神经药","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T46.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2504,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"759c9bc118f8e8d88c6c2c3fa21f147a3fcddf4e6fcbd46339e8f1c4698afd53","pinyin":"yangdihuangleiyaowuzhongdu","initials":"ydhlywzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T46.0",30]]},{"id":"templates-5ff5e591ac6751ccaa66","key":"v1-c9ccc21dfe2a3058|templates-5ff5e591ac6751ccaa66","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消化性溃疡穿孔(鉴别诊断)","category":"鉴别诊断速查","raw":{"name":"消化性溃疡穿孔(鉴别诊断)","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】突发上腹部刀割样剧痛，迅速蔓延至全腹、恶心、呕吐、面色苍白、出冷汗、四肢发凉（休克早期）、全腹压痛、反跳痛、肌紧张（板状腹）、肝浊音界缩小或消失，肠鸣音减弱或消失、发热（继发感染后）。\n【待人工确认·本机素材无此段原文】","现病史":"鉴别要点：患者既往有近十年复合性溃疡病史，此次虽出现持续性上腹痛，但查体全腹无鸣音正常反跳痛、肌紧张。\n常见表现：突发上腹部刀割样剧痛，迅速蔓延至全腹、恶心、呕吐、面色苍白、出冷汗、四肢发凉（休克早期）、全腹压痛、反跳痛、肌紧张（板状腹）、肝浊音界缩小或消失，肠鸣音减弱或消失、发热（继发感染后）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压（有无休克）、血氧\n一般情况：神志、精神状态、面容（痛苦/贫血/休克）、体位（被迫体位）\n皮肤黏膜：苍白（失血）、黄染（梗阻性黄疸）、发绀、出血点、伤口/瘢痕\n头颈部：浅表淋巴结肿大（肿瘤转移）、甲状腺、颈静脉\n胸部：胸廓、呼吸动度、语颤、叩诊、呼吸音、心音心律\n腹部视诊：膨隆/凹陷、胃肠型蠕动波、腹壁静脉曲张、手术瘢痕、疝\n腹部触诊：腹肌紧张、压痛/反跳痛（部位）、Murphy征、麦氏点、肝脾肿大、腹部包块（大小/质地/活动度/压痛）、液波震颤\n腹部叩诊：肝浊音界、移动性浊音、肾区叩痛、鼓音\n腹部听诊：肠鸣音（亢进/减弱/消失）、血管杂音\n肛门直肠指诊：肿物、压痛、指套染血\n外生殖器：根据需要检查\n四肢脊柱：畸形、肿胀、压痛、活动度、血管搏动","辅助检查":"1. 立位腹部X线平片：观察膈下游离气体，急症入院后尽快完成，为穿孔首选确诊检查\n2. 腹部CT平扫（必要时口服稀释泛影葡胺）：明确穿孔部位、腹腔积液及污染程度，X线阴性而高度怀疑时选用\n3. 血常规+C反应蛋白：评估感染程度及白细胞变化，术前及术后第1、3日复查\n4. 凝血功能+血型鉴定+交叉配血：术前必备，备术中出血及输血\n5. 血生化（电解质、肝肾功能、血糖）+血气分析：评估水电解质紊乱及酸碱失衡，术前及术后每日复查至平稳\n6. 心电图+胸部X线：年龄较大或合并心肺基础疾病者，术前评估麻醉及手术耐受性","初步诊断":"1. 溃疡病史+突发剧烈腹痛+板状腹\n2. 腹部立位X线：膈下游离气体（80%阳性）\n3. 腹部CT：腹腔游离气体、穿孔部位\n4. 血常规：白细胞升高\n5. 诊断性腹腔穿刺：抽出含胆汁或食物残渣的液体\n1. 消化性溃疡穿孔(鉴别诊断)（ICD-10：K27.9）","鉴别诊断":"1. 鉴别要点：患者既往有近十年复合性溃疡病史，此次虽出现持续性上腹痛，但查体全腹无鸣音正常反跳痛、肌紧张\n2. 诊断要点：患者既往有近十年复合性溃疡病史，此次虽出现持续性上腹痛，但查体全腹无鸣音正常反跳痛、肌紧张。","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：0.9%NS 1000ml + 5%GNS 500ml ivgtt（快速补液）\n\n方案2：\n 用法：奥美拉唑40mg+0.9%NS 100ml ivgtt bid（抑酸）\n\n方案3：\n 用法：头孢呋辛1.5g+0.9%NS 100ml ivgtt bid\n\n方案4：\n 用法：甲硝唑0.5g ivgtt bid\n\n方案5：\n 用法：生长抑素250μg/h 持续泵入\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：术前禁食水，不口服\n\n药物2（术后）：\n 用法：奥美拉唑20mg qd（连用4-6周）\n\n药物3：\n 用法：阿莫西林1g bid + 克拉霉素0.5g bid（Hp阳性，根除治疗）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n1. 禁食水、胃肠减压、静脉补液、抗感染、抑酸\n2. 穿孔时间短（<6-8小时）、腹腔污染轻：腹腔镜穿孔修补术\n3. 穿孔时间长、腹腔污染重：开腹修补+腹腔冲洗引流\n4. 顽固性溃疡、伴有出血/梗阻/癌变：胃大部切除术\n5. 空腹小穿孔、症状轻者可保守治疗（胃肠减压+抗感染）\n\n【处理要点】\n术前禁食水，胃肠减压\n半卧位，利于腹腔渗液积聚盆腔\n术后胃肠减压至肠蠕动恢复\n术后饮食从流质逐渐过渡到普食\n术后规范抗溃疡治疗，根除Hp\n戒烟酒，避免辛辣刺激食物\n\n【护理】\n术前管理：禁食禁水，持续胃肠减压并记录引流液颜色、量及性状，观察腹痛腹胀及腹膜炎体征变化，遵医嘱补液、抗感染\n病情观察：密切监测生命体征、腹部体征及尿量，警惕血压下降、心率增快等休克征象，准确记录出入量\n术后体位与活动：全麻清醒后取半卧位（床头抬高30°），鼓励早期床上活动并尽早下床，预防肺部感染及深静脉血栓\n引流管护理：妥善固定胃管及腹腔引流管并保持通畅，观察引流液颜色、性状及逐日量变，引流由浑浊转清、量递减为正常趋势，异常立即报告\n切口及并发症观察：观察切口敷料有无渗血渗液、按时换药，监测体温，警惕切口感染、吻合口瘘及腹腔残余脓肿，指导有效咳嗽排痰\n\n【饮食】\n术前及术后早期：严格禁食禁水，持续胃肠减压，禁食期间予肠外营养支持并维持水电解质平衡\n进食时机与起始：待肠鸣音恢复、肛门排气并拔除胃管后，先试饮少量温开水（每次20～30ml），无腹胀不适再过渡至流质饮食（米汤、藕粉、去油肉汤、稀果汁）\n逐步过渡：流质耐受3日后改半流质（粥、烂面条、蒸蛋羹、菜泥、肉糜），少量多餐，每2～3小时一次，每次约100～200ml\n忌口与长期管理：避免粗糙、过冷过热及辛辣刺激食物，忌浓茶、咖啡、酒精；规律进餐、戒烟，遵医嘱长期口服抑酸药，并复查及根除幽门螺杆菌\n远期饮食：术后2～4周逐步恢复软食、普食，坚持少食多餐、避免暴饮暴食，定期门诊随访复查\n\n【注意事项】\n【鉴别要点】鉴别要点：患者既往有近十年复合性溃疡病史，此次虽出现持续性上腹痛，但查体全腹无鸣音正常反跳痛、肌紧张。\n穿孔前常有溃疡病症状加重，或有暴饮暴食、劳累等诱因\n老年人穿孔症状可能不典型，腹痛轻但腹膜炎重，易延误诊断\n穿孔后6-8小时内手术效果好，超过12小时腹腔感染重，并发症多\n术后需复查胃镜，排除胃癌穿孔\n长期服用非甾体抗炎药（NSAIDs）是重要诱因\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n突发剧烈腹痛、板状腹→立即禁食水，急诊手术","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「消化性溃疡穿孔（鉴别诊断）」原文）"},"icd10_diagnosis":"K27.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2505,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"b2747828a44517e3339114bd4b18480c43cb5ad533f0137db7ce747067adeda3","pinyin":"xiaohuaxingkuiyangchuankong(jianbiezhenduan)","initials":"xhxkyck(jbzd)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K27.9",30]]},{"id":"templates-6203e199b7e1b7efa0d1","key":"v1-c9ccc21dfe2a3058|templates-6203e199b7e1b7efa0d1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消化系溃疡","category":"鉴别诊断速查","raw":{"name":"消化系溃疡","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】上腹痛（慢性、周期性、节律性）、DU：饥饿痛/夜间痛，进食缓解、GU：餐后0.5-1h痛、反酸、嗳气、并发症：出血（黑便/呕血）、穿孔（突发剧痛）、幽门梗阻（呕吐宿食）、癌变（GU）。\n【待人工确认·本机素材无此段原文】","现病史":"患者有反复上腹痛病史，伴反酸、嗳气、上腹饱胀，查体：腹软、剑突下压痛，无反跳痛，行胃镜检查可予以确证。\n常见表现：上腹痛（慢性、周期性、节律性）、DU：饥饿痛/夜间痛，进食缓解、GU：餐后0.5-1h痛、反酸、嗳气、并发症：出血（黑便/呕血）、穿孔（突发剧痛）、幽门梗阻（呕吐宿食）、癌变（GU）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压（有无休克表现）\n一般情况：神志、精神状态、面色（苍白/黄染）、体位（蜷曲位/辗转不安）、有无脱水貌\n皮肤黏膜：有无黄染（巩膜/皮肤）、苍白、出血点、蜘蛛痣、肝掌、水肿\n头颈部：巩膜黄染、口唇苍白、颈静脉怒张、左锁骨上淋巴结肿大（Virchow淋巴结，胃癌转移）\n腹部视诊：腹部膨隆/凹陷、胃肠型及蠕动波、腹壁静脉曲张、皮疹、手术瘢痕、脐疝\n腹部触诊：腹肌紧张（板状腹/柔韧感）、压痛（部位）、反跳痛、Murphy征、麦氏点压痛、肝脾肿大（大小/质地/压痛）、腹部包块（部位/大小/质地/活动度/压痛）、液波震颤、振水音\n腹部叩诊：肝浊音界（缩小/消失提示胃肠穿孔）、脾浊音界、移动性浊音、肾区叩痛、鼓音区\n腹部听诊：肠鸣音（亢进/减弱/消失）、有无血管杂音、振水音\n肛门直肠及外生殖器：根据需要检查（指诊、肛裂、痔疮、肿物）","辅助检查":"1. 胃镜检查：确诊首选，溃疡活动期伴出血者待生命体征平稳后24–48h内行急诊胃镜并评估镜下止血；疑恶变者溃疡边缘活检\n2. 幽门螺杆菌检测：13C/14C-尿素呼气试验或胃镜下快速尿素酶试验，规范治疗前必查，根除后停药4周复查\n3. 血常规＋粪便隐血：评估有无出血及贫血程度，黑便或呕血者动态复查\n4. 肝肾功能、电解质、凝血功能：评估全身状况，指导抑酸药剂量及用药安全\n5. 腹部超声或CT：疑穿孔、穿透、幽门梗阻或排除恶性病变时选用","初步诊断":"1. 胃镜检查（确诊首选）\n2. Hp检测\n3. 上消化道钡餐（龛影）\n4. 大便潜血\n5. 血常规（贫血）\n1. 消化系溃疡（ICD-10：K27.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：出血/内镜止血后高危者：奥美拉唑80mg静注后8mg/h持续泵入（维持胃内pH>6）；无出血高危者40mg静滴 qd-bid\n\n方案2：\n 用法：0.9%氯化钠 静滴\n\n方案3（出血）：\n 用法：消化性溃疡（非静脉曲张性）出血不推荐生长抑素/奥曲肽，首选大剂量PPI（见方案1出血用法）；生长抑素类仅用于疑诊静脉曲张性出血\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（PPI）：\n 用法：奥美拉唑/雷贝拉唑 20mg qd（DU 4周，GU 8周）\n\n药物2（Hp阳性）：\n 用法：四联疗法14天\n\n药物3：\n 用法：铝碳酸镁 1g tid\n\n药物4：\n 用法：康复新液 10ml tid（促进愈合）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n抑酸治疗（PPI首选）\n根除Hp\n黏膜保护\n停用NSAIDs（如可能）\n并发症处理：出血（内镜止血）、穿孔（手术）、梗阻（胃肠减压/手术）\n\n【处理要点】\n规律饮食，避免辛辣、酒精、咖啡\n戒烟，避免NSAIDs/激素\nHp阳性规范根除\nPPI早餐前30min服用\nGU需胃镜复查确认愈合（排除癌变）\n警惕并发症信号\n\n【护理】\n严密观察腹痛部位、性质及规律变化，监测呕血、黑便及生命体征，警惕穿孔、大出血等并发症\n活动期溃疡伴明显疼痛或出血者绝对卧床休息，取半卧位或舒适体位，减少胃蠕动刺激\n急性出血或穿孔者暂禁食水，必要时胃肠减压，准确记录出入量，观察引流液性状\n遵医嘱按时予PPI抑酸、胃黏膜保护及止血药物，观察疗效与不良反应\n做好心理疏导，指导规律作息、戒烟戒酒，避免情绪紧张诱发或加重病情\n\n【饮食】\n急性出血或穿孔期暂禁食，出血停止24–48h后试进温凉流质（米汤、藕粉），无不适渐过渡\n恢复期少食多餐，每日5–6餐，进易消化软食或半流质，细嚼慢咽，避免过饱\n忌辛辣刺激、过冷过热、油炸及粗糙坚硬食物，忌浓茶、咖啡、酒精，避免服用NSAIDs等损伤胃黏膜药物\n推荐高蛋白、富含维生素饮食，如烂粥、烂面条、蒸蛋、去皮鱼肉、瘦肉末等，长期规律进餐\n伴幽门梗阻者严格禁食并行胃肠减压，症状缓解后由全流质逐步加餐\n\n【注意事项】\n【鉴别要点】患者有反复上腹痛病史，伴反酸、嗳气、上腹饱胀，查体：腹软、剑突下压痛，无反跳痛，行胃镜检查可予以确证。\nDU几乎不癌变，GU有癌变风险需复查\n黑便/呕血是出血信号，需紧急就医\n突发剧烈腹痛+板状腹提示穿孔\n老年人症状可不典型\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n呕血/黑便、突发剧烈腹痛、频繁呕吐宿食→急诊","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"K27.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2506,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"932fc1f0ecdd3ca624157be4c8ddba30ecc6f59de99c24174863dd0e71cd5348","pinyin":"xiaohuaxikuiyang","initials":"xhxky","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","K27.9",30]]},{"id":"templates-5a799c1b356031676ad1","key":"v1-c9ccc21dfe2a3058|templates-5a799c1b356031676ad1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消化道吻合口瘘","category":"胃肠外科","raw":{"name":"消化道吻合口瘘","category":"胃肠外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】术后5～7天出现发热（常为持续高热或体温再次升高）、腹痛、腹胀、腹膜炎体征（压痛、反跳痛、肌紧张）、引流管引出浑浊液体、肠内容物、胆汁样或粪样液体、心率增快、呼吸急促、白细胞与CRP升高、重者出现血压下降、少尿、意识改变（脓毒症）。\n【待人工确认·本机素材无此段原文】","现病史":"消化道吻合口瘘是胃肠手术后严重并发症，多见于食管胃吻合、结直肠吻合、小肠吻合术后，常发生于术后5～7天。表现为发热、腹痛、腹膜炎体征、引流液异常，重者可致腹腔感染、脓毒症与多器官功能障碍。\n常见表现：术后5～7天出现发热（常为持续高热或体温再次升高）、腹痛、腹胀、腹膜炎体征（压痛、反跳痛、肌紧张）、引流管引出浑浊液体、肠内容物、胆汁样或粪样液体、心率增快、呼吸急促、白细胞与CRP升高、重者出现血压下降、少尿、意识改变（脓毒症）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压、血氧（评估脓毒症）\n一般情况：精神、面色、皮肤弹性（脱水）、营养状态\n腹部视诊：切口有无红肿渗液、腹部膨隆、肠型\n腹部触诊：压痛、反跳痛、肌紧张（腹膜炎范围）、有无包块（脓肿）\n腹部叩诊：移动性浊音（腹腔积液）、肝浊音界\n腹部听诊：肠鸣音减弱或消失（麻痹性肠梗阻）\n引流管：位置、引流量与性状（浑浊、胆汁样、粪样）、周围皮肤情况","辅助检查":"1. 血常规+CRP+PCT：评估感染严重程度，每2～3天复查\n2. 引流液生化（胆红素、淀粉酶、肌酐）：判断是否为消化液，协助定位瘘口\n3. 血培养+引流液培养及药敏：指导目标性抗感染\n4. 肝功能+白蛋白+前白蛋白：评估营养状态与肝脏功能\n5. 电解质+肾功能+血气分析：评估脱水、酸碱失衡与器官功能\n6. 腹部CT（含口服造影剂）：明确瘘口位置、腹腔积液与脓肿\n7. 消化道造影（泛影葡胺）：明确瘘口部位、大小及是否通畅引流","初步诊断":"1. 引流液检查：引流液胆红素、淀粉酶、肌酐测定（与血清比较判断是否为消化液）\n2. 口服亚甲蓝试验：口服亚甲蓝后引流液变蓝提示吻合口瘘\n3. 腹部CT（含口服造影剂）：明确瘘口位置、腹腔积液与脓肿范围（首选）\n4. 上消化道造影/泛影葡胺造影：明确瘘口部位与大小（食管胃吻合口瘘）\n5. 血常规+CRP+PCT+血培养：评估感染程度与脓毒症\n6. 腹部超声：评估腹腔积液、脓肿位置（可引导穿刺）\n7. 内镜检查：谨慎使用，必要时明确瘘口情况\n1. 消化道吻合口瘘（ICD-10：T81.8）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 按病情选择方案，切勿全部同时使用！\n\n方案1（抗感染，覆盖G-杆菌+厌氧菌+肠球菌）：\n 用法：哌拉西林他唑巴坦 4.5g 静滴 q8h 或 美罗培南 1g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h（重症/腹腔感染）\n\n方案2（营养支持）：\n 用法：全肠外营养（葡萄糖+氨基酸+脂肪乳+电解质+维生素），经中心静脉输注；必要时补充白蛋白\n\n方案3（液体复苏/器官支持）：\n 用法：平衡盐溶液按需补液；去甲肾上腺素泵入（脓毒症休克者）；艾司奥美拉唑 40mg 静推 q12h\n\n📌 抗感染需覆盖肠道菌群并按培养结果调整；营养支持优先考虑肠内（瘘口远端造瘘喂养）。\n\n【药物治疗·口服】\n⚠️ 急性期需禁食，不宜口服给药；恢复期遵医嘱：\n\n药物1（抑酸）：\n 用法：艾司奥美拉唑 20mg qd（减少消化液分泌）\n\n药物2（消化酶/止泻，恢复期）：\n 用法：胰酶肠溶胶囊 1～2粒 随餐；蒙脱石散 3g tid（腹泻者）\n\n药物3（益生菌）：\n 用法：双歧杆菌三联活菌 2粒 bid（恢复期调节肠道菌群）\n\n📌 恢复饮食须经主管医师评估瘘口愈合情况后逐步进行。\n\n【治疗】\n充分引流：最关键措施——经皮穿刺置管引流（超声/CT引导）或原引流管冲洗引流，避免脓液积聚\n禁食+胃肠减压：减少消化液经瘘口漏出，食管胃吻合口瘘需持续胃肠减压\n抗感染：早期经验性广谱，据培养调整，注意腹腔脓肿形成\n营养支持：早期肠外营养，条件允许时行瘘口远端肠内营养（肠瘘远端造瘘喂养）\n生长抑素/奥曲肽：减少消化液分泌，促进瘘口愈合\n手术指征：引流不畅伴弥漫性腹膜炎、保守治疗无效、瘘口大（>1cm）或吻合口完全裂开、大出血\n器官功能支持：脓毒症休克、ARDS、急性肾损伤的相应处理\n\n【处理要点】\n严密监测：体温、心率、血压、尿量、腹痛及腹膜刺激征，动态评估脓毒症（qSOFA、SOFA）\n引流管护理：保持通畅（低压冲洗、避免负压过大），准确记录引流量与性状变化\n皮肤护理：瘘口周围皮肤用皮肤保护剂/造口粉保护，防止消化液腐蚀\n营养评估与支持：每日计算热量与氮量，监测前白蛋白、白蛋白与体重\n出入量管理：准确记录24小时出入量，纠正水电解质与酸碱失衡\n心理护理与家属沟通：病程长、费用高，需耐心解释并取得配合\n\n【护理】\n病情观察：每小时监测生命体征（发热、心率增快、血压下降提示病情恶化），观察腹痛与腹膜炎体征变化\n引流护理：保持引流管通畅，记录引流量与性状，冲洗时严格无菌，避免负压过大损伤组织\n皮肤护理：瘘口周围皮肤及时清洁，涂抹氧化锌软膏或造口护肤粉，防止消化液腐蚀\n营养护理：肠外营养配置与输注规范（现配现用、定时定量），肠内营养注意温度、速度与耐受\n发热护理：物理降温、补充水分，观察有无寒战与感染加重\n\n【饮食】\n急性期严格禁食禁水，行胃肠减压与肠外营养\n瘘口愈合、引流减少、肠功能恢复后：从少量温开水试饮开始\n逐步过渡：清流质→流质→低渣半流质→软食，避免高纤维、产气与刺激性食物\n高蛋白、高热量、易消化饮食，少量多餐促进愈合\n食管胃吻合口瘘患者进食后保持半卧位30分钟以上，防反流\n\n【注意事项】\n吻合口瘘的关键是『充分引流+营养支持+抗感染』，多数可通过保守治疗愈合\n引流不彻底是治疗失败的主要原因，脓肿形成必须及时穿刺或手术引流\n术后5～7天是吻合口瘘高发期，此期间出现不明原因发热、心率增快、腹痛需高度警惕\n营养状况差、低蛋白、糖尿病、长期使用激素者吻合口瘘风险高\n\n【急诊/急救】\n弥漫性腹膜炎伴血压下降（吻合口裂开+腹腔感染性休克）→ 急诊手术探查\n引流管引出大量新鲜血液（吻合口出血）→ 急诊内镜/手术止血\n呼吸困难、血氧下降（脓毒症致ARDS）→ 转ICU机械通气支持","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T81.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2507,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"895e85127a406c6250e8fa0468f214b60912315f9a0eb2fea0de23a5995dbdf1","pinyin":"xiaohuadaowenhekoulou","initials":"xhdwhkl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T81.8",30]]},{"id":"templates-7758376a50c3a969cf33","key":"v1-c9ccc21dfe2a3058|templates-7758376a50c3a969cf33","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"消渴(糖尿病中医辨证)","category":"中医","raw":{"name":"消渴(糖尿病中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】上消：烦渴多饮，口干舌燥，尿频量多、中消胃热：多食易饥，形体消瘦，大便干燥、中消气阴：口渴引饮，能食与便溏并见，神疲乏力、下消肾阴：尿频量多，混浊如脂膏，腰膝酸软，头晕耳鸣、下消阴阳：小便频数，混浊如膏，甚至饮一溲一，面容憔悴，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","现病史":"以多饮、多食、多尿、形体消瘦为主要表现，即糖尿病。分上消（肺热津伤）、中消（胃热炽盛、气阴亏虚）、下消（肾阴亏虚、阴阳两虚）。\n常见表现：上消：烦渴多饮，口干舌燥，尿频量多、中消胃热：多食易饥，形体消瘦，大便干燥、中消气阴：口渴引饮，能食与便溏并见，神疲乏力、下消肾阴：尿频量多，混浊如脂膏，腰膝酸软，头晕耳鸣、下消阴阳：小便频数，混浊如膏，甚至饮一溲一，面容憔悴，畏寒肢冷。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以多饮、多食、多尿伴形体消瘦为主症，口渴引饮、尿频量多，属消渴上消、中消之候，入院即刻查空腹血糖、餐后2小时血糖及随机血糖，明确血糖水平是否符合糖尿病诊断标准；查血酮体、血气分析排除糖尿病酮症酸中毒等急性代谢紊乱；完善糖化血红蛋白检查了解近2～3个月平均血糖水平，指导降糖方案制定；行胰岛素释放试验及C肽检查评估胰岛β细胞功能，必要时查谷氨酸脱羧酶抗体等糖尿病自身抗体，鉴别1型与2型糖尿病；查尿常规及尿微量白蛋白/肌酐比值，了解有无泌尿系感染并早期筛查糖尿病肾病；查肾功能、电解质了解有无糖尿病相关肾损害及电解质紊乱；查血脂四项、血尿酸、肝功能及腹部超声，了解血脂水平及有无脂肪肝，指导调脂治疗；查甲状腺功能排除甲状腺功能亢进等引起多食消瘦的疾病；糖尿病患者须系统筛查并发症，完善眼底检查明确有无糖尿病视网膜病变，查颈动脉超声及下肢动脉超声评估大血管病变情况，查心电图、心脏彩超了解有无冠心病及心功能不全，完善肌电图及神经传导速度检查明确有无周围神经病变；对下消阴阳两虚、腰膝酸软、头晕耳鸣者，加做尿沉渣及泌尿系超声，评估肾脏损害程度。血糖、血酮、电解质入院即刻完成，并发症筛查待病情稳定后择期完善；住院期间每日监测空腹及餐后血糖，出院后每3个月复查糖化血红蛋白。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 三多一少症状\n2. 空腹血糖≥7.0mmol/L或餐后2h≥11.1mmol/L\n3. 糖化血红蛋白、胰岛素释放试验\n1. 消渴(糖尿病中医辨证)（ICD-10：E14.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液\n\n方案2（酮症酸中毒）：\n 用法：大量补液，小剂量胰岛素静滴\n\n方案3（并发症）：\n 用法：NS250ml+丹参注射液20ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（上消）：\n 用法：消渴丸5-10丸 tid，或玉泉丸6g tid\n\n药物2（中消胃热）：\n 用法：玉女煎颗粒1袋 tid，或白虎加人参汤1袋 tid\n\n药物3（中消气阴）：\n 用法：参芪降糖颗粒1袋 tid，或玉泉颗粒1袋 tid\n\n药物4（下消肾阴）：\n 用法：六味地黄丸1丸 tid，或知柏地黄丸1丸 tid\n\n药物5（下消阴阳）：\n 用法：金匮肾气丸1丸 tid，或右归丸1丸 tid\n\n药物6（并发症）：\n 用法：糖脉康颗粒1袋 tid，或木丹颗粒1袋 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n上消：清热润肺，生津止渴，消渴方\n中消胃热：清胃泻火，养阴增液，玉女煎\n中消气阴：益气健脾，生津止渴，七味白术散\n下消肾阴：滋阴固肾，六味地黄丸\n下消阴阳：滋阴温阳，补肾固涩，金匮肾气丸\n\n【处理要点】\n糖尿病饮食，控制总热量\n规律运动\n监测血糖\n足部护理，预防感染\n\n【护理】\n病情观察：密切观察血糖、尿糖变化及\"三多一少\"症状消长，记录体重；注意有无恶心呕吐、呼吸深快、呼气烂苹果味等酮症酸中毒先兆及头昏心悸、汗出乏力等低血糖表现，低血糖者即刻给予糖水并报告医师。\n情志护理：消渴阴虚燥热，五志过极皆能化火，忧思恼怒易致肝郁化火、耗伤阴津，宜多予开导抚慰，鼓励听音乐、散步以畅情志，忌劳神思虑过度。\n起居调护：阴虚者忌熬夜劳神，宜早睡早起、劳逸适度，起居有常；适当行八段锦、太极拳以助脾运，注意足部保暖防破损，每日检查双足皮肤，防糖尿病足及感染。\n煎药服药护理：滋阴清热、生津止渴之剂宜文火久煎，两餐间温服；服降糖药或注射胰岛素者须按时定量进餐，随身备糖果以防低血糖，用药后观察疗效及不良反应。\n外治护理：可予中药足浴温经活血，水温以37～40℃为宜、忌过烫防烫伤，足部破溃者禁浴；或耳穴压豆选胰胆、内分泌、脾、肾等穴以助调糖。\n\n【饮食】\n辨证忌口：阴虚燥热者忌辛辣炙煿、温燥之品，如辣椒、羊肉、狗肉、酒及油炸食品，忌食糖类及甜食；脾气亏虚者忌生冷瓜果、冷饮以护脾阳。\n适宜食物：宜清淡低糖高纤维，主食粗细搭配，可食苦瓜、冬瓜、黄瓜、山药、南瓜、燕麦、荞麦、豆制品、瘦肉、鱼虾、绿叶蔬菜等。\n定时定量：三餐定时定量、少食多餐，饥饱适度，忌暴饮暴食，忌空腹饮酒及睡前加餐，严格控制每日总热量摄入。\n药膳食疗：可常食山药薏米粥健脾益气，苦瓜炒瘦肉清胃热生津，枸杞麦冬煎水代茶养阴润燥；黄芪山药炖鸡适于气阴两虚者，阴虚火旺者忌用辛温补品。\n\n【注意事项】\n中西医结合，不可擅自停用西药\n低血糖时立即补充糖分\n定期查眼底、肾功能、神经病变\n\n【急诊/急救】\n低血糖：立即口服糖水或糖果\n酮症酸中毒：大量补液，胰岛素静滴，急诊\n高渗昏迷：补液，小剂量胰岛素，急诊","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】消渴\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肺热津伤\n    症状舌脉：口渴多饮，口干舌燥，尿频量多，烦热多汗，咽干，舌边尖红、苔薄黄而燥，脉洪数\n    治法：清热润肺、生津止渴\n    方剂：消渴方\n\n二、胃热炽盛\n    症状舌脉：多食易饥，口渴多饮，尿频量多，大便干燥，形体消瘦，舌红苔黄燥，脉滑实有力\n    治法：清胃泻火、养阴增液\n    方剂：玉女煎\n\n三、肾阴亏虚\n    症状舌脉：尿频量多，混浊如脂膏，腰膝酸软，头晕耳鸣，口干唇燥，皮肤干燥瘙痒，舌红少苔，脉细数\n    治法：滋阴固肾、润燥止渴\n    方剂：六味地黄丸\n\n四、气阴两虚\n    症状舌脉：口渴喜饮，倦怠乏力，气短懒言，自汗盗汗，五心烦热，形体消瘦，舌淡红少津、苔薄白，脉细弱\n    治法：益气养阴、生津止渴\n    方剂：生脉散合六味地黄丸\n\n五、阴阳两虚\n    症状舌脉：小便频数，混浊如膏，甚则饮一溲一，腰膝酸冷，畏寒肢冷，面色黧黑，耳轮焦干，舌淡胖苔白，脉沉细无力\n    治法：温阳滋阴、补肾固摄\n    方剂：金匮肾气丸\n\n【方剂参考】\n  玉女煎：组成 石膏15g、熟地黄15g、麦冬6g、知母5g、牛膝5g；功效 清胃热，滋肾阴\n      用法：石膏先煎，再入余药同煎，去滓温服，日二次，分温二服；亦可冷服。\n      注意：脾胃虚寒、大便溏泄者忌用；本方清胃滋肾，纯胃火而无阴虚者不宜。\n  六味地黄丸：组成 熟地黄24g、山茱萸12g、山药12g、泽泻9g、牡丹皮9g、茯苓9g；功效 滋补肝肾\n      用法：上药为末，炼蜜为丸，每次6-9g，空腹温开水或淡盐汤送服，日二至三次；亦可作汤剂（六味地黄汤）。\n      注意：脾虚便溏、痰湿内盛及感冒发热者忌用；本品滋腻，久服宜配健脾理气之品；肾阳虚（畏寒肢冷）者不宜。\n  生脉散：组成 人参9g、麦冬9g、五味子6g；功效 益气生津，敛阴止汗\n      用法：水煎温服，日二至三次；气阴欲脱时可频服或代茶饮，亦可服生脉口服液、注射液（急症）。\n      注意：外感表证未解、湿热内盛及实热证者忌用；五味子酸收，痰多者慎用；人参反藜芦，不宜同用。\n  肾气丸：组成 干地黄24g、山药12g、山茱萸12g、泽泻9g、茯苓9g、牡丹皮9g、桂枝3g、附子3g；功效 补肾助阳\n      用法：上药为末，炼蜜为丸如梧桐子大，每次15-25丸（约6-9g），酒或温开水送服，日二次；亦可作汤剂。\n      注意：阴虚火旺、咽干口燥、小便黄赤者忌用；感冒发热及湿热下注者不宜；孕妇慎用附子、桂枝。【别名】本方在《中医内科学》等教材与临床常称「金匮肾气丸」（《金匮要略》肾气丸），另有「八味肾气丸」「桂附地黄丸」等异名；本库《名方》收作「肾气丸（金匮肾气丸／八味肾气丸）」。来源：《金匮要略·血痹虚劳病脉证并治第六》\n\n【西医诊断】\n  2型糖尿病\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"E14.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2508,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"00b3448b2fa39ea2d96f5d368c43c1fc3e8b2d2911e3975d1d632e174ee3282c","pinyin":"xiaoke(tangniaobingzhongyibianzheng)","initials":"xk(tnbzybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","E14.9",30]]},{"id":"templates-0aaecd8cfd200705a05b","key":"v1-c9ccc21dfe2a3058|templates-0aaecd8cfd200705a05b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"淋证(中医辨证)","category":"中医","raw":{"name":"淋证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】热淋：小便短数，灼热刺痛，溺色黄赤，少腹拘急胀痛，或有寒热，口苦，呕恶，或有腰痛拒按，苔黄腻，脉滑数、石淋：尿中时夹砂石，小便艰涩，或排尿时突然中断，尿道窘迫疼痛，少腹拘急，或腰腹绞痛难忍，尿中带血，舌红苔薄黄，脉弦或带数、血淋：排尿时尿色红赤，或夹血块，疼痛满急加剧；实证者心烦，舌尖红苔薄黄，脉数；虚证者痛势不重，色淡红，舌淡红苔薄白，脉细数、气淋：郁怒之后小便涩滞，淋沥不宜，少腹胀满疼痛，苔薄白，脉弦、膏淋：小便浑浊如米泔水，置之沉淀如絮状，上有浮油如脂，或夹凝块，或混血液，尿道热涩疼痛，舌红苔黄腻，脉濡数、劳淋：小便不甚赤涩，但淋沥不已，时作时止，遇劳即发，腰膝酸软，神疲乏力，舌淡脉细弱。\n【待人工确认·本机素材无此段原文】","现病史":"淋证是以小便频急、淋沥不尽、尿道涩痛、小腹拘急或痛引腰腹为主症的肾系病证。分热淋、石淋、血淋、气淋、膏淋、劳淋六种。可见于泌尿系感染、结石、乳糜尿等。\n常见表现：热淋：小便短数，灼热刺痛，溺色黄赤，少腹拘急胀痛，或有寒热，口苦，呕恶，或有腰痛拒按，苔黄腻，脉滑数、石淋：尿中时夹砂石，小便艰涩，或排尿时突然中断，尿道窘迫疼痛，少腹拘急，或腰腹绞痛难忍，尿中带血，舌红苔薄黄，脉弦或带数、血淋：排尿时尿色红赤，或夹血块，疼痛满急加剧；实证者心烦，舌尖红苔薄黄，脉数；虚证者痛势不重，色淡红，舌淡红苔薄白，脉细数、气淋：郁怒之后小便涩滞，淋沥不宜，少腹胀满疼痛，苔薄白，脉弦、膏淋：小便浑浊如米泔水，置之沉淀如絮状，上有浮油如脂，或夹凝块，或混血液，尿道热涩疼痛，舌红苔黄腻，脉濡数、劳淋：小便不甚赤涩，但淋沥不已，时作时止，遇劳即发，腰膝酸软，神疲乏力，舌淡脉细弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以小便频急、淋沥不尽、尿道涩痛、少腹拘急为主症，入院即刻完善尿常规及尿沉渣镜检，了解有无白细胞、红细胞及管型，明确是否存在泌尿系感染及血尿；留取清洁中段尿行尿培养加药物敏感试验，明确致病菌并指导抗生素选择；查血常规、C反应蛋白及降钙素原评估感染程度，排除全身性感染及脓毒症；患者可有寒热、腰痛拒按，完善泌尿系超声检查明确有无肾结石、输尿管结石、肾积水及膀胱病变；查肾功能、电解质排除感染或尿路梗阻所致肾功能受损及电解质紊乱，对高热、腰痛剧烈者尤须密切监测；石淋者见尿中夹砂石、排尿时突然中断、腰腹绞痛难忍，需完善泌尿系平片及泌尿系CT（或CT尿路造影），明确结石部位、大小及有无梗阻；对反复尿路感染者，必要时行静脉肾盂造影或膀胱镜检查，明确有无尿路畸形、梗阻及膀胱内占位；血淋者尿色红赤或夹血块，查尿脱落细胞学排除泌尿系肿瘤；膏淋者小便浑浊如米泔水、上有浮油如脂，行尿乳糜试验（乙醚试验）明确有无乳糜尿，必要时查血微丝蚴；中老年男性完善前列腺液检查及前列腺超声，明确有无前列腺增生、前列腺炎；女性患者结合妇科检查排除盆腔炎性疾病；对淋证反复发作、遇劳即发者，查空腹血糖及糖化血红蛋白，排除糖尿病所致尿路感染易感。尿常规、尿培养、血常规、泌尿系超声入院即刻完成，造影及膀胱镜等待感染控制后择期进行；急性期治疗后定期复查尿常规、尿培养及肾功能。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 小便频急、淋沥涩痛为主症\n2. 尿常规、尿培养、泌尿系B超明确病因\n3. 高热、腰痛剧烈、肾功能受损者积极处理\n1. 淋证(中医辨证)（ICD-10：N39.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（热淋）：三金片4片 tid，或热淋清颗粒8g tid\n药物2（石淋）：排石颗粒5g tid，或肾石通丸6g tid\n药物3（血淋）：云南白药胶囊2粒 tid（血止即停）\n药物4（气淋）：舒肝丸1丸 tid\n药物5（劳淋）：六味地黄丸6g bid，或金匮肾气丸6g bid\n药物6（配合）：头孢克肟0.1g bid（感染时，遵医嘱）\n\n【治疗】\n热淋：清热利湿通淋，八正散加减\n石淋：清热利湿，排石通淋，石韦散加减\n血淋：清热通淋，凉血止血，小蓟饮子加减\n气淋：理气疏导，通淋利尿，沉香散加减\n膏淋：清热利湿，分清泄浊，程氏萆薢分清饮加减\n劳淋：健脾益肾，分清泌浊，无比山药丸加减\n\n【处理要点】\n多饮水，每日2000-3000ml\n注意个人卫生，勤换内裤\n忌辛辣刺激食物，忌酒\n\n【护理】\n病情观察：密切观察小便次数、尿量、颜色及有无砂石、血丝，疼痛部位与性质；记24小时出入量，急性期发热恶寒者测体温，热淋高热者防惊厥，血淋出血量多者及时报告。\n起居调护：急性期卧床休息，避免劳累及久站久坐，以防气淋、劳淋诱发；注意外阴清洁，勤换内裤，多饮水（每日1500～2000ml）以稀释尿液、冲刷尿路，石淋者饮水后适当跳跃活动以助排石。\n情志护理：淋证多与情志抑郁、恼怒相关，气淋尤甚，应耐心疏导，避免忧思恼怒，告之疾病可愈，稳定情绪以利气机通畅。\n煎药服药护理：汤剂宜温服，饭前服用；石淋服药后嘱多饮温开水并活动；血淋服药后观察尿色变化；含化石通淋药（如金钱草、鸡内金）宜文火久煎。\n外治护理：小腹拘急疼痛者可行小腹热敷或温水坐浴以缓急止痛；膏淋尿液浑浊者注意会阴部清洗，防止继发感染；虚证劳淋者注意腰腹保暖，勿受寒凉。\n\n【饮食】\n忌口：热淋、血淋忌辛辣炙煿、醇酒厚味及羊肉、狗肉等助热生火之品；膏淋、劳淋忌肥甘厚腻，以免酿湿生浊；石淋者据结石成分忌相应食物（如草酸钙结石少食菠菜、浓茶、豆腐）。\n适宜：饮食宜清淡而富含水分，多食冬瓜、赤小豆、绿豆、薏苡仁、芹菜、荸荠等清热利湿通淋之品，多饮温开水、淡竹叶茶，保持大便通畅。\n药膳食疗：热淋宜车前草粥、竹叶粥清热通淋；石淋宜核桃仁、鸡内金研末冲服以化石，金钱草炖瘦肉；血淋宜藕节粥、白茅根饮凉血止血。\n调补：劳淋、气淋久病者宜山药莲子粥、黄芪炖鸡健脾益气，虚寒者加生姜、葱白温阳化气，忌过食生冷瓜果以防中阳受损。\n\n【注意事项】\n反复发作的泌尿系感染需排查尿路梗阻、糖尿病等\n石淋反复发作者B超随访，结石>1cm或合并肾积水者转泌尿外科\n妊娠期、儿童用药谨慎\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】淋证\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、热淋\n    症状舌脉：小便频数短涩，灼热刺痛，尿色黄赤，少腹拘急胀痛，或有寒热口苦，腰痛拒按，大便秘结，舌红苔黄腻，脉滑数\n    治法：清热利湿通淋\n    方剂：八正散\n\n二、石淋\n    症状舌脉：尿中夹砂石，排尿涩痛，或排尿时突然中断，尿道窘迫疼痛，腰腹绞痛难忍，尿中带血，舌红苔薄黄，脉弦或弦数\n    治法：清热利湿、排石通淋\n    方剂：石韦散\n\n三、气淋\n    症状舌脉：郁怒之后小便涩滞，淋沥不畅，少腹胀满疼痛，胸闷善太息，舌淡红苔薄白，脉弦\n    治法：理气疏导、通淋利尿\n    方剂：沉香散\n\n四、血淋\n    症状舌脉：小便热涩刺痛，尿色深红或夹血块，疼痛满急加剧，心烦，舌尖红、苔黄，脉滑数\n    治法：清热通淋、凉血止血\n    方剂：小蓟饮子\n\n五、膏淋\n    症状舌脉：小便混浊如米泔水，置之沉淀如絮状，上有浮油，尿道热涩疼痛，舌红苔黄腻，脉濡数\n    治法：清热利湿、分清泄浊\n    方剂：程氏萆薢分清饮\n\n六、劳淋\n    症状舌脉：小便不甚赤涩，但淋沥不已，时作时止，遇劳即发，腰膝酸软，神疲乏力，舌淡苔薄白，脉细弱\n    治法：健脾益肾、利尿通淋\n    方剂：无比山药丸。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肾系病证·淋证\n\n【方剂参考】\n  八正散：组成 车前子9g、瞿麦9g、萹蓄9g、滑石9g、山栀子9g、甘草9g、川木通6g、大黄9g；功效 清热泻火，利水通淋\n      用法：上药为末，每次6-9g，加灯心草（或竹叶）煎汤送服，食后临卧服；亦可作汤剂，日二次。\n      注意：孕妇忌用；脾胃虚寒、久病体弱及无湿热者不宜；木通苦寒，肾功能不全者慎用，不宜久服。木通须用川木通；关木通含马兜铃酸、已禁用，肾功能不全者慎用。\n  石韦散：组成 石韦12g、瞿麦9g、车前子12g（包煎）、冬葵子9g、滑石15g（包煎）、甘草3g（原方有当归、赤芍、王不留行、白术等版本，本条取《证治汇补》通行组成）；功效 清热利湿，通淋排石\n      用法：水煎，车前子、滑石包煎，温服，日一剂，分二次服；宜多饮水并配合运动。\n      注意：孕妇慎用；虚寒证不宜；结石较大、伴严重梗阻或感染、无尿者须立即泌尿外科处理，不可仅服中药；本品同名方有多种（《外台秘要》《证治汇补》），本方组成版本分歧见《中医方剂大辞典》。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（利水渗湿）；原方出自《外台秘要·卷二十七》引《古今录验》（《证\n  沉香散：组成 沉香3g（后下）、石韦12g、滑石15g（包煎）、当归9g、陈皮9g、白芍12g、冬葵子9g、甘草3g、王不留行9g；功效 行气利水，通淋\n      用法：水煎，沉香后下，滑石包煎，温服，日一剂，分二次服。\n      注意：孕妇慎用；气虚下陷之小便不畅不宜；排尿困难明显者须先除外前列腺增生、尿道狭窄及泌尿系肿瘤。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《三因极一病证方论·卷十二》\n  小蓟饮子：组成 生地黄30g、小蓟15g、滑石15g、川木通6g（禁用关木通）、蒲黄9g、藕节9g、淡竹叶9g、当归6g、山栀子9g、甘草6g；功效 凉血止血，利水通淋\n      用法：水煎温服，日二次，食前服；亦可研末为散，每次12g，水煎温服。\n      注意：孕妇慎用；血淋日久属虚或脾不统血者不宜；木通苦寒，肾功能不全者慎用。木通须用川木通；关木通含马兜铃酸、已禁用，肾功能不全者慎用。\n  程氏萆薢分清饮：组成 萆薢12g、黄柏9g、石菖蒲9g、茯苓12g、白术9g、莲子心3g、丹参12g、车前子12g（包煎）；功效 清热利湿，分清别浊\n      用法：水煎，车前子包煎，温服，日一剂，分二次服。\n      注意：下焦虚寒之膏淋（《丹溪心法》萆薢分清饮证）忌用；脾胃虚寒者慎用；须先除外乳糜尿、泌尿系感染等。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（清热祛湿）；原方出自《医学心悟·卷四》\n  无比山药丸：组成 山药15g、肉苁蓉12g、熟地黄15g、山茱萸12g、茯神12g、菟丝子12g、五味子6g、赤石脂12g（先煎）、巴戟天12g、泽泻9g、杜仲12g、牛膝12g；功效 健脾补肾，固涩精气\n      用法：水煎，赤石脂先煎，温服，日一剂，分二次服；原方为蜜丸，每服6-9g，日二次，温酒或米饮送下。\n      注意：湿热内盛、阴虚火旺者忌用；外感未解者不宜；赤石脂不宜与肉桂同用（十九畏）；脾虚湿盛、食少便溏者慎用熟地黄。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阳）；原方出自《太平惠民和剂局方·卷五》（原名无比山药丸，即《金匮》薯蓣丸类方化裁）\n\n【西医诊断】\n  尿路感染\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"N39.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2509,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3b664b2e303cded76b6ae4d13c84612e23c6efefed6686a48e595687c5677b40","pinyin":"linzheng(zhongyibianzheng)","initials":"lz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","N39.0",30]]},{"id":"templates-e4d65d9dfbe8d004eab2","key":"v1-c9ccc21dfe2a3058|templates-e4d65d9dfbe8d004eab2","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"渗透性脱髓鞘综合征(ODS)","category":"神经外科","raw":{"name":"渗透性脱髓鞘综合征(ODS)","category":"神经外科","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者诊断渗透性脱髓鞘综合征，多存在低钠血症纠正过快、慢性酒精中毒、营养不良、严重肝病或消耗性疾病等基础，入院即刻并每日复查血电解质（钾、钠、氯）、血糖及血浆渗透压、尿渗透压、尿钠，明确低钠血症的类型并严格限制血钠上升速度（24小时不超过8～10mmol/L），此项为预防与治疗该病的核心依据；查肝肾功能、血清白蛋白及血气分析，了解有无肝功能不全、低蛋白血症及酸碱失衡，评估营养状态与代谢紊乱程度；查糖化血红蛋白排除糖尿病性渗透压改变；对慢性酒精中毒或长期进食差者，完善维生素B1、维生素B12、叶酸及血氨检查，鉴别Wernicke脑病、肝性脑病等代谢性脑病；查甲状腺功能及血清皮质醇、促肾上腺皮质激素，排除甲状腺功能减退、肾上腺皮质功能减退等内分泌疾病所致低钠血症；完善头颅MRI检查（含T1、T2、FLAIR及DWI、ADC序列），明确有无脑桥中央对称性异常信号及脑桥外（基底节、丘脑、皮层下白质）受累，评估病灶范围以判断预后；对诊断不明确或需鉴别中枢神经系统感染、脱髓鞘疾病者，必要时行腰椎穿刺查脑脊液常规、生化、寡克隆区带及病原学检查；查胸部CT、腹部超声及肿瘤标志物，排查肺癌等可引起抗利尿激素分泌不当综合征的肿瘤。血钠、渗透压及肝肾功能入院即刻完成并每日复查，头颅MRI应在病情允许时尽快完成；治疗期间密切监测血钠及神经系统体征，定期复查头颅MRI评估病灶演变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 渗透性脱髓鞘综合征(ODS)","鉴别诊断":"1. 4. 排除其他原因：脑干梗死、多发性硬化、脑干脑炎、Wernicke脑病","处理方案":"【待人工确认·本机素材无此段原文】","资料来源":"鉴别诊断库 ddx_local.json（条目「渗透性脱髓鞘综合征（ODS）」原文）"},"icd10_diagnosis":"","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2510,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"1b34554c1cf9204f016438bc4f78679700a623c59c61e863483e4e5c995c84af","pinyin":"shentouxingtuosuiqiaozonghezheng(ODS)","initials":"stxtsqzhz(","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","",30]]},{"id":"templates-31512b0acc0bd5571954","key":"v1-c9ccc21dfe2a3058|templates-31512b0acc0bd5571954","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"湿疹(中医辨证)","category":"中医","raw":{"name":"湿疹(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】湿热浸淫：发病急，皮损潮红灼热，瘙痒无休，渗液流滋，伴身热心烦，大便干、脾虚湿蕴：发病较缓，皮损潮红，瘙痒，抓后糜烂渗出，可见鳞屑，纳少神疲、血虚风燥：病程久，反复发作，皮损色暗或色素沉着，或皮损粗糙肥厚，剧痒。\n【待人工确认·本机素材无此段原文】","现病史":"以多形性皮损、对称分布、易于渗出、自觉瘙痒、反复发作、慢性化为特征，即湿疮。分湿热浸淫、脾虚湿蕴、血虚风燥等证型。\n常见表现：湿热浸淫：发病急，皮损潮红灼热，瘙痒无休，渗液流滋，伴身热心烦，大便干、脾虚湿蕴：发病较缓，皮损潮红，瘙痒，抓后糜烂渗出，可见鳞屑，纳少神疲、血虚风燥：病程久，反复发作，皮损色暗或色素沉着，或皮损粗糙肥厚，剧痒。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者以多形性皮损、对称分布、易于渗出、自觉瘙痒、反复发作为特点，属中医湿疮范畴，入院后查血常规了解嗜酸性粒细胞及白细胞计数，评估过敏状态并排除感染性皮疹；查血清总IgE及特异性IgE，必要时行过敏原点刺试验，明确有无尘螨、花粉、食物等致敏因素，指导回避与脱敏治疗；对皮损局限于接触部位、边界清楚、疑为接触性皮炎者，完善斑贴试验明确接触性致敏物以资鉴别；查C反应蛋白、红细胞沉降率了解有无系统性炎症；皮损伴鳞屑、边缘活跃者行皮肤真菌镜检及培养，排除体癣、股癣等浅部真菌病；指缝、腋下等部位瘙痒剧烈者行疥虫镜检排除疥疮；对水疱、大疱性皮损或诊断困难者，行皮肤活检及直接免疫荧光检查，鉴别天疱疮、类天疱疮等自身免疫性大疱病；瘙痒亦可为系统性疾病的表现，完善空腹血糖、糖化血红蛋白排除糖尿病所致皮肤瘙痒，查肝功能、肾功能及胆红素排除肝胆疾病及尿毒症性瘙痒，查甲状腺功能排除甲状腺功能异常；用药前完善血常规、肝肾功能及电解质，为系统应用抗组胺药、糖皮质激素或免疫抑制剂提供安全依据；对病程久、反复发作、皮损粗糙肥厚者，查血清白蛋白及营养指标，评估营养状况并与中医血虚风燥辨证相互印证。血常规、肝肾功能、血糖入院后尽快完成，斑贴试验及过敏原检测待急性渗出控制、病情稳定后择期进行；治疗期间定期复查血常规及肝肾功能，观察药物不良反应，必要时复查过敏原。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 多形性皮损，对称分布，剧烈瘙痒\n2. 反复发作，慢性倾向\n3.与接触性皮炎、神经性皮炎鉴别\n1. 湿疹(中医辨证)（ICD-10：L30.9）","鉴别诊断":"1.与接触性皮炎、神经性皮炎鉴别","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（急性泛发）：\n 用法：NS250ml+甘草酸苷40ml ivgtt qd\n\n方案2（湿热）：\n 用法：NS250ml+清开灵30ml ivgtt qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（湿热浸淫）：\n 用法：龙胆泻肝丸1袋 tid，或湿毒清胶囊4粒 tid\n\n药物2（脾虚湿蕴）：\n 用法：参苓白术散1袋 tid，或除湿丸1丸 tid\n\n药物3（血虚风燥）：\n 用法：当归饮子1袋 tid，或润燥止痒胶囊4粒 tid\n\n药物4（瘙痒明显）：\n 用法：防风通圣丸1袋 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n湿热浸淫：清热利湿，解毒止痒，龙胆泻肝汤合萆薢渗湿汤\n脾虚湿蕴：健脾利湿，除湿胃苓汤\n血虚风燥：养血润肤，祛风止痒，当归饮子或四物消风饮\n\n【处理要点】\n避免搔抓、热水烫洗\n穿宽松棉质衣物\n忌辛辣、海鲜、酒\n避免接触过敏原\n\n【护理】\n皮损护理：急性期糜烂渗液者忌热水烫洗、肥皂刺激及搔抓，以黄柏、苦参煎水冷湿敷，每次20～30分钟、每日2～3次，湿敷后遵医嘱涂药，敷料随湿随换，保持局部清洁干燥。\n病情观察：每日观察皮损部位、范围、渗出量、皮色及瘙痒程度，渗液由多转少、潮红转暗为顺；若见局部红肿灼热、脓性分泌物伴发热，为继发感染，立即报告医师。\n起居调护：着宽松纯棉衣物，避免化纤、羊毛及紧身摩擦刺激；床单被褥勤换洗曝晒，居室通风除湿，避免潮湿闷热环境助长湿邪；瘙痒夜甚者注意防搔抓致破。\n情志护理：本病瘙痒反复、缠绵难愈，患者多烦躁焦虑，宜耐心解释病机与转归，嘱其情志舒畅、勿郁怒急躁，防止肝郁化火引动湿热加重皮损；血虚风燥证者病程日久易忧思，需多予安慰鼓励。\n服药与外治护理：内服汤药温服，服药后避风寒；外用药严格按医嘱方法、频次使用，药膏涂薄而匀，渗液期忌涂油膏以防闭门留寇；湿敷药液现煎现用，观察有无过敏反应。\n\n【饮食】\n辨证忌口：忌辛辣炙煿、肥甘厚味及酒、浓茶；忌鱼虾蟹、牛羊肉等腥膻发物及笋、香菇等动风之品，以防加重瘙痒渗出。\n湿热浸淫证：忌甜腻生湿之品，宜食薏苡仁、赤小豆、冬瓜、绿豆、马齿苋、丝瓜等清热利湿之品，烹调清淡少油。\n脾虚湿蕴证：忌生冷瓜果、滋腻碍胃之品，宜食山药、白扁豆、茯苓、莲子、薏苡仁等健脾化湿之品，少食多餐，细嚼慢咽以顾护脾胃。\n血虚风燥证：忌辛辣燥烈之品，宜食黑芝麻、桑葚、百合、猪皮冻、蜂蜜等滋阴养血润燥之品，多饮温水。\n药膳食疗：湿热证可食薏苡仁赤小豆粥（薏苡仁、赤小豆各30g煮粥）；脾虚证食山药茯苓粥（山药30g、茯苓15g、粳米适量）；血虚风燥证食桑葚百合羹（桑葚15g、百合15g、冰糖少许），随证选用。\n\n【注意事项】\n急性渗出期忌用软膏\n慢性期注意皮肤保湿\n顽固病例需皮肤科系统治疗\n\n【急诊/急救】\n一般不需急救\n严重过敏：肾上腺素0.5mg im，糖皮质激素","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「湿疹（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】湿疹\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、湿热浸淫\n    症状舌脉：起病急，皮损潮红灼热，丘疹水疱密集，渗液流滋，瘙痒剧烈，心烦口渴，大便干，小便黄，舌红苔黄腻，脉滑数\n    治法：清热利湿、祛风止痒\n    方剂：龙胆泻肝汤合萆薢渗湿汤\n\n二、脾虚湿蕴\n    症状舌脉：发病较缓，皮损淡红，水疱渗液，瘙痒，面色萎黄，食少便溏，腹胀，舌淡胖有齿痕、苔白腻，脉濡缓\n    治法：健脾利湿、祛风止痒\n    方剂：除湿胃苓汤\n\n三、血虚风燥\n    症状舌脉：病程日久，皮损色暗或色素沉着，粗糙肥厚，脱屑，瘙痒剧烈，夜间尤甚，口干，舌淡苔薄白，脉细弦\n    治法：养血润肤、祛风止痒\n    方剂：当归饮子合消风散。【证型核对说明】本条证型依《中医外科学》（中国中医药出版社“十四五”规划教材）·皮肤病·湿疮（湿疹）之辨证分型原貌，该教材本病即列“湿热浸淫”“脾虚湿蕴”“血虚风燥”3 型，未另增列证型，以免凑数\n\n【方剂参考】\n  龙胆泻肝汤：组成 龙胆草6g、黄芩9g、栀子9g、泽泻12g、川木通6g（禁用关木通）、车前子9g、当归3g、生地黄9g、柴胡6g、生甘草6g；功效 清泻肝胆实火，清利肝经湿热\n      用法：水煎温服，日二次，饭后服；亦可制丸，每次6-9g，日二次。\n      注意：脾胃虚寒、孕妇及阴虚阳亢者忌用；苦寒渗利之品久服伤胃耗阴，一般不超过7-14剂；木通用量宜小。木通须用川木通；关木通含马兜铃酸、2005 年起取消药用标准，禁止使用。\n  除湿胃苓汤：组成 苍术9g、厚朴9g、陈皮9g、猪苓9g、泽泻9g、赤茯苓12g、白术9g、滑石15g（包煎）、防风9g、栀子9g、木通（须用川木通，禁用关木通）6g、肉桂3g（；功效 健脾除湿，清热止痒\n      用法：水煎，滑石包煎，肉桂后下，温服，日一剂，分二次服。\n      注意：木通须用川木通（或木通）；关木通含马兜铃酸、2005年起取消药用标准，禁止使用；阴虚血燥之皮损不宜；孕妇慎用；须配合外治并避免搔抓、忌食辛辣鱼腥。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛湿剂（清热祛湿）；原方出自《外科正宗·卷四》\n  消风散：组成 当归6g、生地黄6g、防风6g、蝉蜕6g、知母6g、苦参6g、胡麻仁6g、荆芥6g、苍术6g、牛蒡子6g、生石膏6g（先煎）、川木通3g（禁用关木通）、生甘草3；功效 疏风除湿，清热养血\n      用法：水煎，石膏先煎，温服，日一剂，分两次服；亦可研末，每服6~9g，开水送下。\n      注意：气血虚弱、内无风湿热邪者不宜用；服药期间忌辛辣、鱼腥、烟酒；不宜与温热补益之品同用。木通须用川木通；关木通含马兜铃酸、2005 年起取消药用标准，禁止使用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·治风剂（疏散外风）；原方出自《外科正宗》\n\n【西医诊断】\n  湿疹\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L30.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2511,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"237a406d27a0488bdc54292cbc4e875f383267201599e41d61cf4b9f1885e261","pinyin":"shizhen(zhongyibianzheng)","initials":"sz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L30.9",30]]},{"id":"templates-7f2bb910496e948bd8d9","key":"v1-c9ccc21dfe2a3058|templates-7f2bb910496e948bd8d9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"溃疡性结肠炎中度","category":"消化病临床路径（2019年版）","raw":{"name":"溃疡性结肠炎中度","category":"消化病临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】有持续或反复发作的腹泻、黏液脓血便伴腹痛、里急后重和不同程度的全身症状。病程多在4～6周以上。可有皮肤、黏膜、关节、眼、肝胆等肠外表现。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：有持续或反复发作的腹泻、黏液脓血便伴腹痛、里急后重和不同程度的全身症状。病程多在4～6周以上。可有皮肤、黏膜、关节、眼、肝胆等肠外表现。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"检查计划：患者有持续或反复发作的腹泻、黏液脓血便伴腹痛、里急后重，病程4～6周以上，结肠镜示病变自直肠起呈连续性弥漫性分布、血管纹理消失伴糜烂及接触性出血，诊断为溃疡性结肠炎中度，入院后查血常规了解有无贫血、白细胞及血小板升高，评估疾病活动度；查C反应蛋白、红细胞沉降率了解炎症活动程度，作为疗效评价的基线指标；查肝功能、肾功能、电解质及血清白蛋白，评估营养状况及有无低蛋白血症，并为应用氨基水杨酸制剂、糖皮质激素及免疫抑制剂提供安全依据；查凝血功能及D-二聚体，本病活动期存在高凝状态，需排除血栓风险；查大便常规加隐血、大便培养及艰难梭菌毒素检测，排除细菌性痢疾、阿米巴肠炎、艰难梭菌感染等感染性结肠炎，此为确立诊断的前提；查粪便钙卫蛋白评估肠道炎症程度；完善结肠镜检查并多段多点活检，明确病变范围、内镜严重度分级及组织学改变，必要时行染色内镜评估有无上皮内瘤变；对疑有小肠受累或肠腔狭窄者，完善小肠CT成像或小肠磁共振成像；查腹部超声了解肠壁增厚、肠腔狭窄及有无腹腔脓肿；查胸部X线、结核感染T细胞检测及乙型肝炎、丙型肝炎、艾滋病、梅毒筛查，为使用生物制剂及免疫抑制剂做前置排查；对重症或难治病例查巨细胞病毒DNA，排除巨细胞病毒结肠炎。血常规、大便常规及感染筛查入院即刻完成，结肠镜应在肠道准备充分后尽早进行；治疗期间定期复查血常规、C反应蛋白、粪便钙卫蛋白及肝肾功能。\n\n（检查清单）\n【临床路径·住院期间检查项目】\n住院期间检查项目\n1.","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《炎症性肠病诊断与治疗的共识意见》（中华医学会消化病学分会炎症性肠病学组编著，中华消化杂志，2018年）。\n1.诊断标准：UC缺乏诊断的金标准，需结合临床表现、实验室检查、影像学检查、内镜检查和组织病理学表现进行综合分析，在排除感染性和其他非感染性结肠炎的基础上进行诊断。\n（1）临床表现：有持续或反复发作的腹泻、黏液脓血便伴腹痛、里急后重和不同程度的全身症状。病程多在4～6周以上。可有皮肤、黏膜、关节、眼、肝胆等肠外表现。\n（2）结肠镜检查：病变多从直肠开始，呈连续性、弥漫性分布。中度炎症的内镜特征为血管形态消失，出血黏附在黏膜表面、糜烂，常伴有粗糙呈颗粒状的外观及黏膜脆性增加（接触性出血）。\n（3）黏膜活检：建议多段、多点取材。组织学上可见以下主要改变。活动期：\n固有膜内有弥漫性、急性、慢性炎症细胞浸润，尤其是上皮细胞间有中性粒细胞浸润（即隐窝炎），乃至形成隐窝脓肿；\n隐窝结构改变，隐窝大小、形态不规则；\n可见黏膜表面糜烂、浅溃疡形成和肉芽组织。 \n（4）其他检查：无条件行结肠镜检查的单位可行钡剂灌肠检查。肠腔狭窄时如结肠镜无法通过，可患者钡剂灌肠检查、CT结肠成像检查显示结肠镜检查未及部位。\n（5）手术切除标本病理检查：大体和组织学改变可见上述UC的特点。\n在排除其他疾病如急性感染性肠炎、阿米巴肠病、肠道血吸虫病、肠结核等感染性结肠炎及克罗恩病结肠炎、缺血性结肠炎、放射性结肠炎等疾病的基础上，可按下列要点诊断。\n（1）具有上述典型临床表现者为临床疑诊，安排进一步检查。\n（2）同时具备上述结肠镜和（或）放射影像学特征者，可临床拟诊。\n（3）如再具备上述黏膜活检和（或）手术切除标本组织病理学特征者，可以确诊。\n（4）初发病例如临床表现、结肠镜检查和活检组织学改变不典型者，暂不确诊UC，应予密切随访。\n2.病情评估\n（1）临床类型：UC临床类型分为初发型和慢性复发型。\n（2）病变范围：采用蒙特利尔分型，分为直肠型、左半结肠型、广泛结肠型。\n（3）临床活动性的严重程度：依据改良Turelove和Witts疾病严重程度分型。\n轻度：排便次数＜4次/日，便血轻或无，体温和脉搏正常，血红蛋白和红细胞沉降率正常。\n中度：介于轻度和重度之间。\n重度：排便次数\n6次/日，便血重，体温＞37.8\n，脉搏＞90次/min，血红蛋白＜75%的正常值，红细胞沉降率＞30mm/1h。\n（三）\n1. 溃疡性结肠炎中度（ICD-10：K51.002）","鉴别诊断":"1. 1.诊断标准：UC缺乏诊断的金标准，需结合临床表现、实验室检查、影像学检查、内镜检查和组织病理学表现进行综合分析，在排除感染性和其他非感染性结肠炎的基础上进行诊断\n2. 在排除其他疾病如急性感染性肠炎、阿米巴肠病、肠道血吸虫病、肠结核等感染性结肠炎及克罗恩病结肠炎、缺血性结肠炎、放射性结肠炎等疾病的基础上，可按下列要点诊断\n3. □ 根据临床、实验室检查结果、结肠镜结果和既往资料，进行鉴别诊断和确定诊断","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\n根据《炎症性肠病诊断与治疗的共识意见》（中华医学会消化病学分会炎症性肠病学组，中华消化杂志2018;38(5):292-311）。\n中度溃疡性结肠炎活动期： \n1.氨基水杨酸类制剂：是主要药物。可选用柳氮磺胺吡啶（SASP）制剂，每日4g，分次口服；或用相当剂量的5-氨基水杨酸（5-ASA）制剂。对于直肠或直乙病变为主的患者，可联合局部给予上述药物栓剂纳肛或灌肠治疗。\n2.糖皮质激素：足量氨基水杨酸制剂治疗后（一般2～4周）症状控制不佳者，尤其是病变较广泛者，应予糖皮质激素。如泼尼松0.75～1mg/（kg\nd）（其他类型全身作用激素的剂量按相当于上述泼尼松剂量折算）。达到症状缓解后开始逐渐缓慢减量至停药。对于直肠或直乙病变为主的患者，可局部给予糖皮质激素类药物灌肠治疗。\n3.硫嘌呤类药物：包括硫唑嘌呤和6-巯基嘌呤。适用于激素无效或依赖者。推荐剂量从低剂量开始，缓慢加量，严密监测骨髓抑制等不良反应。\n4.英夫利西单克隆抗体（infliximab，IFX）：当激素和上述免疫抑制剂治疗无效或激素依赖或不能耐受上述药物治疗时，可考虑IFX治疗。\n5.营养治疗药物：包括肠内营养剂及胃肠外营养液。首选肠内营养剂。\n6.选择性白细胞吸附疗法：有条件的单位，特别是合并机会性感染者可考虑患者。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：K51.002溃疡性结肠炎疾病编码。\n2.符合需要住院的指征：临床严重程度为中度，即介于轻度与重度之间（见上述疾病活动度的严重程度评估）。\n3.临床病程符合慢性复发型。\n4.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理，也不影响第一诊断的临床路径流程实施时，可以进入路径。\n（六）","临床路径·标准住院日":"标准住院日为17～18天\n（五）","临床路径·出院标准":"出院标准\n（1）少渣饮食情况下，便次、便血情况较入院有较好改善，体温基本正常。\n（2）营养摄入状况改善或营养状态稳定。\n（九）","临床路径·变异及原因分析":"变异及原因分析\n1.合并机会性感染的患者；如艰难梭菌、巨细胞病毒感染的患者需退出该路径。\n2.病情活动程度由中度活动发展至重度活动者，需退出该路径。\n3.结肠镜活检病理提示存在不典型增生或癌变的患者，需退出该路径。","资料来源":"鉴别诊断库 ddx_local.json（条目「溃疡性结肠炎中度」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 消化病临床路径（2019年版） · 溃疡性结肠炎中度临床路径（2019年版）.docx"},"icd10_diagnosis":"K51.002","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2512,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"77897fa78df7ee316055bab770cfa0cbbf6ca4180ed9c24ed3d6259dcf0379be","pinyin":"kuiyangxingjiechangyanzhongdu","initials":"kyxjcyzd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K51.002",30]]},{"id":"templates-527ab925814ea24e4c26","key":"v1-c9ccc21dfe2a3058|templates-527ab925814ea24e4c26","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"溺水","category":"院前急救","raw":{"name":"溺水","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】溺水史、呼吸困难、发绀、意识障碍、咳嗽、咳粉红色泡沫痰、心跳呼吸停止。\n【待人工确认·本机素材无此段原文】","现病史":"淹没于水中导致呼吸障碍，可迅速致死。\n常见表现：溺水史、呼吸困难、发绀、意识障碍、咳嗽、咳粉红色泡沫痰、心跳呼吸停止。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 动脉血气分析（急诊必查，评估低氧血症与酸碱失衡，淡水溺水示稀释性低钠低氯，海水溺水示高钠高氯）\n2. 血常规、血电解质、血糖、肾功能（肌酐/尿素氮）、凝血功能（入院即抽血送检，动态复查）\n3. 十二导联心电图（持续心电监护，警惕低体温所致心律失常与QT延长）\n4. 胸部CT（生命体征允许时尽早完成，明确肺水肿及吸入性肺炎程度；危重无法搬动者以床旁胸片替代）\n5. 颅脑CT（意识障碍或疑似外伤者，排除颅内损伤及脑水肿）\n6. 毒物筛查（怀疑自杀或药物相关溺水时送检；后续加做血培养、痰培养监测继发感染）","初步诊断":"1. 溺水史\n2. 典型表现\n3. 不需特殊检查即可诊断\n1. 溺水（ICD-10：T75.1）","鉴别诊断":"1. 诊断要点：不需特殊检查即可诊断\n2. 不要因倒水延误CPR\n3. 所有溺水者均应就医观察（迟发性肺水肿）\n4. 低温溺水可延长复苏时间\n5. 注意颈椎损伤（跳水溺水）\n6. 儿童溺水多发生在家中","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：建立静脉通路\n\n方案2：\n 用法：NS 250-500ml ivgtt（限制液体）\n\n方案3：\n 用法：50%GS40ml iv（低血糖）\n\n方案4（脑水肿）：\n 用法：甘露醇125ml ivgtt\n\n方案5（酸中毒）：\n 用法：碳酸氢钠\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：抢救时不能口服\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即救离水面\n清除口鼻异物，保持气道通畅\n倒水（膝顶法/肩背法），时间不宜过长\n呼吸心跳停止：立即CPR\n不要因倒水延误CPR\n吸氧，必要时气管插管\n建立静脉通路，限制液体\n防治脑水肿、肺水肿\n保暖\n120转院（所有溺水者均应就医观察）\n\n【处理要点】\n立即救离水面\n清除口鼻异物\n侧卧倒水\nCPR（必要时）\n保暖\n监测生命体征\n不要轻易放弃（低温溺水可长时间复苏）\n\n【护理】\n保持气道通畅，及时清除口鼻泥沙水草，取侧卧位防误吸；配合气管插管及呼吸机通气，机械通气者监测气道压与SpO₂变化\n持续心电、SpO₂、血压、体温监测，密切观察意识（GCS评分）、瞳孔及呼吸频率节律，警惕ARDS、脑水肿及迟发性呼吸衰竭\n低体温者行缓慢复温（加温毯、温液输注，肛温升至37～38℃后停止），避免快速复温诱发心律失常\n留置胃管抽吸胃内液体，准确记录出入量并监测尿量；补液严格遵医嘱控制滴速，防止加重肺水肿\n急救配合：床旁备好除颤仪，配合心肺复苏及用药；抽搐者防坠床、防舌咬伤，加强安全防护\n\n【饮食】\n复苏期及意识未完全清醒者严格禁食禁水，防止误吸引发窒息\n意识清醒、生命体征平稳后先试饮少量温水，无呛咳、呕吐再逐步加量\n给予温流质或半流质（米汤、藕粉、稀粥），少食多餐，避免过饱\n忌生冷、辛辣、油腻及高盐食物；海水溺水者注意适量补充淡水以纠正高钠血症\n恢复期加强高蛋白、易消化饮食（蒸蛋、鱼汤、烂面条），监测电解质，必要时口服补液盐补液\n\n【注意事项】\n不要因倒水延误CPR\n所有溺水者均应就医观察（迟发性肺水肿）\n低温溺水可延长复苏时间\n注意颈椎损伤（跳水溺水）\n儿童溺水多发生在家中\n\n【急诊/急救】\n立即救离水面\n清除口鼻异物，保持气道通畅\n短暂倒水（不要延误CPR）\n呼吸心跳停止：立即CPR（30:2）\n吸氧，必要时气管插管\n建立静脉通路，限制液体\n保暖\n120转院（所有溺水者均需观察）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「溺水」原文）"},"icd10_diagnosis":"T75.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2513,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6fbe957802284e1c7da56b7a9492c7b484f7ac4cc535a976ff9ef178428f71a4","pinyin":"nishui","initials":"ns","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T75.1",30]]},{"id":"templates-9e60a523222619170704","key":"v1-c9ccc21dfe2a3058|templates-9e60a523222619170704","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"漏斗胸","category":"胸外科临床路径（2019年版）","raw":{"name":"漏斗胸","category":"胸外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】胸闷，胸痛，心律不齐，运动耐力下降，易发生呼吸道感染，食欲低下。\r3.体征：胸骨体向背侧下陷，下部肋软骨向背侧弯曲，双侧肋外翻，特殊体形：头颅前伸、两肩前倾、前胸下陷、后背弓状、腹部膨隆。\r4.辅助检查：胸部X线片、胸部CT重建、心电图、超声心动图、肺功能等。\r胸部CT：胸骨体向后凹陷，胸骨后与脊柱。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：胸闷，胸痛，心律不齐，运动耐力下降，易发生呼吸道感染，食欲低下。\r3.体征：胸骨体向背侧下陷，下部肋软骨向背侧弯曲，双侧肋外翻，特殊体形：头颅前伸、两肩前倾、前胸下陷、后背弓状、腹部膨隆。\r4.辅助检查：胸部X线片、胸部CT重建、心电图、超声心动图、肺功能等。\r胸部CT：胸骨体向后凹陷，胸骨后与脊柱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、血型；\r（2）凝血功能、肝功能测定、肾功能测定、电解质、感染性疾病筛查（乙型肝炎，丙型肝炎，梅毒，艾滋病）；\r（3）X线胸片、心电图、肺功能；\r（4）胸部CT；\r（5）超声心动图。\r2.根据患者病情可选择的检查项目：24小时动态心电图、心肌酶、脊柱X线片、血气分析、维生素和微量元素等相关检查等。\r（七）预防性抗菌药物选择与使用时机\r抗菌药物使用：按照《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。可使用第二代头孢菌素。\r（八）手术日为入院\n3天\r1.麻醉方式：气管插管全身麻醉。\r2.手术方式：NUSS术。\r3.手术置入物：NUSS钢板及固定装置。\r4.输血：视术中具体情况而定。\r5.胸腔闭式引流：先天性心脏病术后、合并肺部疾病或复杂漏斗胸患者，视术中具体情况而定。\r6.术中保温：术中监测体温，可采用预加温、提高手术室室温、使用液体加温装置、加温毯、暖风机等措施维持患者术中中心体温＞36\n。\r（九）术后住院恢复\n7天\r1.必须复查的检查项目:\r（1）血常规;\r（2）X线胸片。\r2.基本治疗方案：嘱患者术后矫正站姿、坐姿。\r3.抗菌药物使用：按照《抗菌药物临床患者指导原则（2015年版）》（国卫办医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。可使用第二代头孢菌素。如出现术后感染或排斥，可适当延长抗菌药患者时间，并结合药敏结果选择抗菌药物。\r4.术后镇痛：依据患者年龄及身高体重等一般状况，选择适当镇痛药物，充分镇痛。预防性镇痛和多模式镇痛方法：（1）神经阻滞；（2）椎管内镇痛；（3）静脉镇痛；（4）口服给药。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n小儿外科学分册》（中华医学会编著，人民卫生出版社，2005年）和《临床技术操作规范\n小儿外科学分册》（中华医学会编著，人民军医出版社，2005年）。\r1.病史：发现前胸壁凹陷。\r2.临床表现：胸闷，胸痛，心律不齐，运动耐力下降，易发生呼吸道感染，食欲低下。\r3.体征：胸骨体向背侧下陷，下部肋软骨向背侧弯曲，双侧肋外翻，特殊体形：头颅前伸、两肩前倾、前胸下陷、后背弓状、腹部膨隆。\r4.辅助检查：胸部X线片、胸部CT重建、心电图、超声心动图、肺功能等。\r胸部CT：胸骨体向后凹陷，胸骨后与脊柱前间隙距离明显缩短，心脏受压移位。\r5.病情分级：\r胸部CT测量Haller指数（HI）。\r轻度：HI＜3.2\r中度：3.2\nHI\n3.5\r重度：HI＞3.5\r（三）\n1. 漏斗胸（ICD-10：Q67.6）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n小儿外科学分册》（中华医学会编著，人民卫生出版社，2005年）和《临床技术操作规范\n小儿外科学分册》（中华医学会编著，人民军医出版社，2005年）。\r（四）临床路径","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：Q67.6漏斗胸疾病编码。\r2.胸部有明显畸形。\r3.年龄大于3岁。\r4.当患者同时具有其他疾病诊断，但在门诊治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备\n2天\r1.","临床路径·标准住院日":"标准住院日\n10天\r（五）","临床路径·出院标准":"出院标准\r1.切口愈合良好，或门诊可处理的愈合不良切口。\r2.体温正常。\r3.血常规基本正常，X线胸片呈正常术后改变，无明显异常。\r4.无需要住院处理的其他并发症或合并症。\r\n肚幮\n脈\n憁\n漀\n脈\n憁\n漀\n伀\n倀\n儀\n尀脈\n敨\n伀\n倀\n儀\n漀\n敨\n伀\n倀\n儀\n愀\n漀\n剨荮\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n脈\n伀\n倀\n儀\n尀脈\n 桰\n脈\n伀\n倀\n儀\n尀脈\n 桰\n脈\n伀\n倀\n儀\n尀脈\n瀁h\n脈\n,\n,\n脈\n,\n,\n萑\n搒\n葠\n最\n洀\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n摧\n搒\n愀\n摧\n朁\n洀\n搒\n朁\n洀\n愁\n摧\n渆\n渆\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n伀\n倀\n愀\n脈\n憁\n漀\n脈\n憁\n漀\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n最\n洀\n伀\n倀\n愀\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n脈\n憁\n漀\n脈\n憁\n漀\n愀\n摧\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n最\n堍洀\n萑\n搒\n葠\n摧\n萑\n搒\n葠\n最\n洀\n貞嵴\n剨荮\n瀁h\n剨荮\n憁\n漀\n桰\n憁\n瀀h\n堍\n伀\n倀\n愀\n漀\n唃\n脈\n憁\n漀\n脈\n憁\n漀\n伀\n倀\n愀\n伀\n倀\n愀\n漀\n伀\n倀\n愀\n漀\n（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.存在影响手术的合并症，术前需要进行相关的诊断和治疗。\r2.术后出现肺部感染、置入物移位、切口愈合不良等并发症，需要延长治疗时间。\r\f二、漏斗胸","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 胸外科临床路径（2019年版） · 漏斗胸临床路径（2019年版）.doc"},"icd10_diagnosis":"Q67.6","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2514,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1ba46d9b0f2d19b0ec0409c002902ee49bb348f0dea5a73964d2fdc451edfb5","pinyin":"loudouxiong","initials":"ldx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","Q67.6",30]]},{"id":"templates-deb71db010270a5bdb8f","key":"v1-c9ccc21dfe2a3058|templates-deb71db010270a5bdb8f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"灭鼠药中毒-抗凝血类","category":"中毒/理化","raw":{"name":"灭鼠药中毒-抗凝血类","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】恶心呕吐、腹痛、皮肤黏膜出血：瘀斑、紫癜、牙龈出血、鼻衄、内脏出血：呕血、黑便、血尿、阴道出血、严重者颅内出血、失血性休克、潜伏期：误食后1-7天出现症状。\n【待人工确认·本机素材无此段原文】","现病史":"溴敌隆、大隆等抗凝血灭鼠药中毒，以全身广泛出血为特征\n常见表现：恶心呕吐、腹痛、皮肤黏膜出血：瘀斑、紫癜、牙龈出血、鼻衄、内脏出血：呕血、黑便、血尿、阴道出血、严重者颅内出血、失血性休克、潜伏期：误食后1-7天出现症状。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 凝血功能（PT、APTT、INR）：最核心检查，入院即刻查，此后每12小时复查至INR恢复正常，评估抗凝程度及维生素K1疗效\n2. 血常规+网织红细胞：动态监测血红蛋白、血小板，评估隐性失血\n3. 毒物检测：血清/尿中抗凝血类鼠药（华法林、溴敌隆、溴鼠灵等）定性定量，明确毒物种类以指导疗程\n4. 肝肾功能、电解质：评估肝脏代谢功能及内环境，指导用药与补液\n5. 大便隐血、尿常规：筛查消化道及泌尿道隐性出血\n6. 心电图：排除心律失常及基础心脏疾病；出现剧烈头痛、呕吐、意识改变时立即行头颅CT排除颅内出血","初步诊断":"1. 灭鼠药接触/误食史\n2. 全身多部位出血倾向\n3. 凝血功能异常：PT、APTT延长，INR升高\n4. 血小板正常\n5. 毒物检测可确诊\n1. 灭鼠药中毒-抗凝血类（ICD-10：T60.4）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：维生素K1 10-20mg 缓慢静注（<5mg/min），随后10-20mg ivgtt qd\n\n方案2（严重出血）：\n 用法：维生素K1 50mg ivgtt，同时输新鲜冰冻血浆400-800ml\n\n方案3：\n 用法：凝血酶原复合物（PCC）20-40U/kg ivgtt\n\n方案4（洗胃（误食6小时内））：\n 用法：温水或1:5000高锰酸钾\n\n方案5（导泻）：\n 用法：硫酸镁20-30g 口服\n\n方案6：\n 用法：活性炭50-100g 口服（吸附毒物）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：维生素K1 10mg po tid（出血控制后维持1-2个月）\n\n药物2：\n 用法：维生素C 200mg po tid\n\n药物3：\n 用法：避免使用影响凝血的药物（阿司匹林、非甾体抗炎药）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n特效解毒：维生素K1（唯一特效解毒剂）\n补充凝血因子：新鲜冰冻血浆、PCC\n清除毒物：洗胃、导泻、活性炭\n对症支持：止血、补液、纠正休克\n监测凝血功能，调整维生素K1剂量\n\n【处理要点】\n绝对卧床，避免外伤\n监测生命体征、意识、出血情况\n监测PT、APTT、INR、血常规\n颅内出血者神经外科会诊\n维生素K1治疗需维持至凝血功能正常后1-2周\n\n【护理】\n洗胃配合：口服中毒4-6小时内（超华法林类可延至6-8小时）温清水洗胃，头偏一侧防误吸，保留首次胃内容物送毒物检测\n解毒剂观察：维生素K1静滴控制滴速，观察有无面色潮红、皮疹、胸闷等过敏反应，动态监测PT/INR评估疗效并警惕INR反跳\n出血观察：密切观察皮肤瘀斑、牙龈出血、鼻衄、血尿、黑便，警惕颅内出血（剧烈头痛、呕吐、意识障碍），异常立即报告并备血\n生命体征监测：心电监护监测血压、心率、呼吸、血氧，每班评估出血征象，记录24小时出入量\n安全护理：绝对卧床休息，防跌倒磕碰；尽量避免肌肉注射及深静脉穿刺，必须穿刺时延长按压5-10分钟\n\n【饮食】\n洗胃后禁食4-6小时，观察无恶心、呕吐、腹痛后再开始进食\n由温凉流质逐步过渡至半流质、软食，宜高蛋白、高维生素饮食，可适当摄入含维生素K的绿叶蔬菜辅助凝血功能恢复\n忌过热、辛辣刺激及粗糙坚硬食物（坚果、油炸、带骨刺食物），避免损伤消化道黏膜加重出血\n鼓励适量饮水，出血明显或进食不足者予静脉补液维持水电解质平衡\n观察大便颜色及性状，出现黑便、血便立即报告，必要时禁食\n\n【注意事项】\n维生素K3、K4无效，必须用维生素K1\n维生素K1静注过快可致面部潮红、出汗、血压下降、过敏性休克\n潜伏期长，误食后即使无症状也应观察并预防性使用维生素K1\n凝血功能正常后仍需维持治疗，防止反跳\n\n【急诊/急救】\n【第一步】评估生命体征：意识、呼吸、血压、心率\n【第二步】保持呼吸道通畅，吸氧，建立静脉通路\n【第三步】清除毒物：误食6小时内温水洗胃，活性炭50-100g口服，硫酸镁导泻\n【第四步】特效解毒：维生素K1 10-20mg 缓慢静注（<5mg/min），随后10-20mg ivgtt\n【第五步】严重出血：维生素K1 50mg ivgtt + 新鲜冰冻血浆400-800ml + PCC 20-40U/kg\n【第六步】颅内出血：脱水降颅压（甘露醇125ml ivgtt q6-8h），神经外科会诊\n【第七步】失血性休克：快速补液、输血、血管活性药物\n【第八步】监测：PT、APTT、INR、血常规、生命体征，每4-6小时复查凝血\n【第九步】维持：维生素K1 10-20mg ivgtt qd，至凝血正常后改口服维持1-2个月\n【注意】禁用维生素K3/K4；维生素K1静注需缓慢；潜伏期长需密切观察","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T60.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2515,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"6181a6754bb5ae7a9e8372ab8e4808736363c769c871bb2885a28dbeb4af4527","pinyin":"mieshuyaozhongdu-kangningxuelei","initials":"msyzd-knxl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T60.4",30]]},{"id":"templates-04a06b83c10159c19e06","key":"v1-c9ccc21dfe2a3058|templates-04a06b83c10159c19e06","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"烧伤休克","category":"烧伤整形科","raw":{"name":"烧伤休克","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】口渴（最早症状）、烦躁不安（脑缺氧）、意识淡漠/嗜睡（严重）、尿少（<0.5ml/kg/h）、心率增快（>120次/分）、脉搏细速、血压下降（晚期，早期血压可正常或偏高）、末梢循环差（肢端凉、发绀、毛细血管再充盈延迟）、恶心呕吐、血液浓缩（红细胞压积升高）。。\n【待人工确认·本机素材无此段原文】","现病史":"大面积烧伤后由于毛细血管通透性增加，大量血浆样液体渗出至组织间隙和创面，导致有效循环血量不足引起的低血容量性休克。是烧伤后第一个死亡高峰（伤后48小时内）。烧伤面积成人>15%（儿童>10%）即可发生休克。\n常见表现：口渴（最早症状）、烦躁不安（脑缺氧）、意识淡漠/嗜睡（严重）、尿少（<0.5ml/kg/h）、心率增快（>120次/分）、脉搏细速、血压下降（晚期，早期血压可正常或偏高）、末梢循环差（肢端凉、发绀、毛细血管再充盈延迟）、恶心呕吐、血液浓缩（红细胞压积升高）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：心率、血压（脉压减小是早期信号）、呼吸、体温；意识状态（烦躁→淡漠→昏迷）；末梢循环：肢端温度、颜色、毛细血管再充盈时间；尿量（最可靠监测指标，留置尿管）；烧伤面积和深度评估。","辅助检查":"血常规（红细胞压积HCT升高提示血液浓缩，目标HCT 0.45-0.50）、血气分析（代谢性酸中毒）、电解质（低钠、低钾、低蛋白）、肝肾功能、凝血功能、血型+交叉配血、尿常规（尿比重升高）、中心静脉压(CVP，监测补液)。","初步诊断":"大面积烧伤史（成人>15%、儿童>10%）+ 休克表现（口渴、烦躁、尿少、心率快、脉压小、末梢循环差）+ 血液浓缩。休克期：伤后2-3小时渗出最快，8小时达高峰，持续36-48小时。\n1. 烧伤休克（ICD-10：T31 + T79.4）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【补液公式（国内通用）】第一个24小时：晶体液=体重(kg)×烧伤面积(%)×1.0ml，胶体液=体重×面积×0.5ml（晶胶比2:1；III度面积大或小儿可1:1），基础水分=2000ml（5%葡萄糖，成人）；前8小时输入晶胶体总量的一半，后16小时输入另一半；第二个24小时：晶胶体为第一个24小时的一半，水分不变。晶体首选乳酸林格液，胶体用血浆（首选）/白蛋白/右旋糖酐40。【监测调整】目标：尿量0.5-1ml/kg/h（成人30-50ml/h）、心率<120、收缩压>90mmHg、意识清楚、HCT 0.45-0.50。尿量不足→加快补液；尿量过多→减慢。\n\n【药物治疗·口服】\n休克期一般禁食（胃肠功能受抑制），可少量饮水（不能替代静脉补液）；镇痛：哌替啶50-100mg im 或 吗啡5-10mg im（血压稳定时）；预防应激性溃疡：奥美拉唑静脉。\n\n【治疗】\n【立即建立静脉通路】大面积烧伤应建立2条以上大孔径静脉通路，必要时静脉切开；【留置尿管】监测每小时尿量；【吸氧】合并吸入性损伤时；【保暖】低体温加重休克；【镇痛】减少疼痛刺激（但血压低时慎用镇静镇痛）；【纠正酸中毒】严重酸中毒时5%碳酸氢钠；【血管活性药】补液充足后仍低血压时用多巴胺/去甲肾上腺素（不推荐早期使用，应先补足容量）。\n\n【处理要点】\n休克期管理的核心是\"及时、快速、足量补液\"，以尿量为金标准调整；每小时记录尿量、心率、血压、意识、末梢循环；准确记录出入量；定期复查HCT和血气；避免补液不足（休克加重）和补液过多（肺水肿、脑水肿）。\n\n【护理】\n每小时记录尿量（最关键）；监测生命体征q1h；准确记录出入量；保持静脉通路通畅；保暖（室温28-32℃）；体位（头低脚高位增加回心血量，但合并颅脑损伤时不用）；心理护理。\n\n【饮食】\n休克期禁食或少量饮水；胃肠功能恢复后（肠鸣音正常、无腹胀）开始肠内营养，从少量开始逐渐增加。\n\n【注意事项】\n①烧伤休克是低血容量性休克，治疗核心是补液，不是升压药；②尿量是调整补液速度最可靠的指标，比血压更敏感；③第一个8小时是关键，渗出最快，必须补入一半量；④胶体液在伤后8小时内使用效果最好（毛细血管通透性尚不完全丧失），8小时后胶体也会渗出，效果下降；⑤烧伤面积估算要准确，面积算少了会导致补液不足；⑥不要因为患者\"能喝水\"就减少静脉补液，口服不能替代静脉补液；⑦HCT目标0.45-0.50，过高提示补液不足，过低提示补液过多或溶血。\n\n【急诊/急救】\n【补液无反应】快速补液后尿量仍<20ml/h、血压不升→检查静脉通路是否通畅、是否有吸入性损伤/复合伤、考虑心功能不全，加用血管活性药；【肺水肿】呼吸困难、咳粉红色泡沫痰、肺部湿啰音→减慢补液、利尿、强心、吸氧；【脑水肿】头痛、呕吐、意识改变、瞳孔变化→脱水（甘露醇）、限制水分。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T31 + T79.4","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2516,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3fdc081d5fc63232184c2b689c774d413d61a9e611be8710f3124206fae169b9","pinyin":"shaoshangxiuke","initials":"ssxk","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T31 + T79.4",30]]},{"id":"templates-7a9f50b6e2e53cf70308","key":"v1-c9ccc21dfe2a3058|templates-7a9f50b6e2e53cf70308","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"烧伤后瘢痕挛缩","category":"烧伤整形科","raw":{"name":"烧伤后瘢痕挛缩","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】瘢痕增生：红色/暗红色隆起、坚硬、瘙痒疼痛；挛缩：关节活动受限（肘关节不能伸直、手指屈曲畸形、颈部后仰受限、小口畸形）；器官移位：眼睑外翻（闭眼不全、角膜暴露）、口唇外翻（流涎、进食困难）、鼻翼畸形；手部畸形：爪形手（掌指关节过伸、指间关节屈曲、拇指内收）；功能障碍：穿衣、进食、行走困难；儿童可影响生长发育（瘢痕限制骨骼生长）。。\n【待人工确认·本机素材无此段原文】","现病史":"深度烧伤愈合后形成的增生性瘢痕发生收缩，导致关节活动受限、器官移位、功能障碍。是烧伤后最常见的致残原因。好发于关节屈侧（肘窝、腘窝、腋窝）、颈部、手部、面部（眼睑/口唇外翻）。\n常见表现：瘢痕增生：红色/暗红色隆起、坚硬、瘙痒疼痛；挛缩：关节活动受限（肘关节不能伸直、手指屈曲畸形、颈部后仰受限、小口畸形）；器官移位：眼睑外翻（闭眼不全、角膜暴露）、口唇外翻（流涎、进食困难）、鼻翼畸形；手部畸形：爪形手（掌指关节过伸、指间关节屈曲、拇指内收）；功能障碍：穿衣、进食、行走困难；儿童可影响生长发育（瘢痕限制骨骼生长）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"瘢痕评估：部位、厚度、质地、颜色、瘙痒疼痛；关节活动度测量（主动/被动活动范围，与健侧对比）；器官功能评估：眼睑闭合不全程度、张口度、手指活动；肌力评估；瘢痕成熟度判断（充血期/增生期/成熟期）。","辅助检查":"检查计划：患者深度烧伤愈合后瘢痕增生并发生挛缩，关节活动受限、器官移位、功能障碍，拟行瘢痕松解或植皮手术，入院后完善术前常规检查：查血常规了解有无贫血、感染及血小板计数，为手术耐受与备血提供依据；查凝血功能（PT、APTT、INR、纤维蛋白原）排除凝血功能障碍，避免术中术后出血；查肝肾功能、电解质及空腹血糖，评估麻醉与手术耐受性，排除肝肾功能不全及糖尿病等影响创面愈合的因素；查血型及交叉配血，做好术中输血准备；完善乙型肝炎、丙型肝炎、艾滋病、梅毒等感染性疾病筛查，既是术前常规亦为职业防护要求；查心电图、胸部X线，对高龄或合并心肺疾病者加做心脏彩超及肺功能检查，评估心肺储备功能；因长期挛缩可致关节脱位或僵硬，完善关节X线检查明确关节对位关系、有无脱位半脱位及继发骨关节改变；手部爪形手畸形者完善手部X线检查，明确掌指关节过伸、指间关节屈曲程度及骨骼发育情况，为手术方案设计提供依据；对疑有肌腱、关节囊挛缩或儿童骨骺受累者，必要时完善关节MRI或超声检查，评估软组织及骨骺情况；用超声多普勒评估瘢痕区及拟用皮瓣区血供，指导皮瓣设计；眼睑外翻、闭眼不全者请眼科会诊，行视力及角膜荧光素染色检查，明确有无角膜暴露性损伤；小口畸形影响进食者行口腔检查并评估张口度；瘢痕破溃渗液者行创面分泌物细菌培养及药物敏感试验，指导抗感染治疗。术前检查急诊完成，MRI、多普勒等视病情择期完善；术后定期复查血常规、肝肾功能及电解质，并评估瘢痕与关节功能恢复情况。\n\n（检查清单）\n一般不需特殊检查；术前常规：血常规、凝血功能、肝肾功能；影像学：关节X线（长期挛缩可致关节脱位/僵硬）、手部X线（爪形手畸形）。","初步诊断":"深度烧伤史 + 瘢痕增生 + 关节活动受限/器官移位。分度：轻度（活动受限<20%）、中度（20-50%）、重度（>50%或关节脱位）。\n1. 烧伤后瘢痕挛缩（ICD-10：L90.5 / T31）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【手术前后】按整形外科手术常规；【术后预防感染】头孢唑林1g ivgtt 术前30分钟。\n\n【药物治疗·口服】\n【止痒】氯雷他定10mg qd、西替利嗪10mg qd；【抗瘢痕】积雪苷片2-4片tid；【止痛】布洛芬0.3g prn。\n\n【治疗】\n【预防（最重要）】①早期功能位固定：手功能位（腕背伸20-30°、掌指关节屈曲70-90°、指间关节伸直、拇指外展对掌）、踝关节90°、肘伸直、颈后仰；②早期功能锻炼：创面愈合后即开始主动+被动活动，每日多次；③压力治疗：弹力套/弹力绷带，压力20-30mmHg，每日23小时，持续6-12个月（预防瘢痕增生最有效）；④硅酮制剂：瘢痕贴/凝胶，每日12小时以上。【非手术治疗】①瘢痕内激素注射：曲安奈德10-20mg/ml，每4-6周一次（增生期瘢痕）；②激光：脉冲染料激光（改善充血瘙痒）、点阵激光（改善质地）；③康复治疗：关节松动、牵伸、支具（动态/静态支具维持关节位置）；④水疗。【手术治疗】适应证：①非手术治疗无效的严重挛缩；②关节脱位/僵硬；③器官功能障碍（眼睑外翻致角膜暴露、小口畸形影响进食）；④儿童影响发育。术式：①瘢痕切除+植皮（中厚皮片，适用于大面积瘢痕）；②瘢痕切除+皮瓣转移（功能部位、深部组织暴露、关节处，皮瓣耐磨有弹性）；③局部皮瓣（Z成形术、五瓣成形术，适用于条索状挛缩）；④皮肤扩张器（大面积瘢痕，利用正常皮肤扩张后修复）；⑤关节松解+固定（关节僵硬时）。术后：继续压力治疗、功能锻炼、支具固定（防止再挛缩）。\n\n【处理要点】\n瘢痕成熟前（6-12个月）以非手术治疗为主（压力、锻炼、支具）；手术患者瘢痕成熟后（变白、变软、无瘙痒）进行，除非严重功能障碍；术后必须配合康复治疗（否则再挛缩）；长期随访（儿童需至发育成熟）。\n\n【护理】\n压力治疗指导（弹力套穿戴、压力适中、观察末梢循环）；功能锻炼指导（每日多次、循序渐进）；支具佩戴指导；瘢痕瘙痒护理（避免搔抓、冷敷、抗组胺药）；术后伤口护理和康复训练监督；心理护理（外观和功能障碍导致的心理问题）。\n\n【饮食】\n高蛋白高热量；富含维生素C；避免辛辣刺激（加重瘙痒）；戒烟。\n\n【注意事项】\n①烧伤后瘢痕挛缩的预防重于治疗，早期功能位固定+压力治疗+功能锻炼可显著减少挛缩；②压力治疗是预防瘢痕增生最有效的方法，需坚持6-12个月，每日23小时以上，不要因为\"不痒了\"就停止；③手术时机很重要：患者瘢痕成熟后（通常伤后6-12个月）手术，增生期手术出血多、复发率高，但严重功能障碍（如角膜暴露）应尽早手术；④Z成形术是条索状瘢痕挛缩的经典术式，可延长瘢痕线、改变瘢痕方向；⑤手部烧伤后\"爪形手\"畸形是严重的功能障碍，需早期康复和手术，否则可致永久性关节僵硬；⑥儿童烧伤后瘢痕挛缩可影响骨骼发育，需长期随访和多次手术；⑦术后再挛缩是常见问题，必须配合压力治疗、功能锻炼和支具，单纯手术效果差。\n\n【急诊/急救】\n【角膜暴露溃疡】眼睑外翻致闭眼不全、角膜干燥、溃疡→急诊眼科处理（眼膏保护、眼睑缝合/手术矫正）；【关节脱位】长期挛缩致关节脱位→手术松解+固定。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"L90.5 / T31","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2517,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d8a120c25a93718f470bb35c990c5ca1d00740f501239483bcc842e001141903","pinyin":"shaoshanghoubanhenluansuo","initials":"sshbhls","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","L90.5 / T31",30]]},{"id":"templates-acd105bd52c05f80812b","key":"v1-c9ccc21dfe2a3058|templates-acd105bd52c05f80812b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"烧伤脓毒症","category":"烧伤整形科","raw":{"name":"烧伤脓毒症","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】体温：高热>39℃或低体温<36℃（\"两低一高\"：低体温、低白细胞、高心率是革兰阴性菌感染特征）；心率>120次/分；呼吸急促>28次/分；意识改变：烦躁、谵妄、淡漠、昏迷；创面恶化：创面灰暗、坏死斑、出血点、异味、创缘炎症反应消退；腹胀、肠麻痹；多器官功能障碍：少尿/无尿、黄疸、凝血障碍、ARDS。。\n【待人工确认·本机素材无此段原文】","现病史":"烧伤患者因皮肤屏障破坏、大量坏死组织、免疫功能低下，微生物侵入并在体内繁殖产生毒素，导致的全身炎症反应综合征和器官功能障碍。是烧伤患者第二个死亡高峰（伤后1-3周）。常见致病菌：铜绿假单胞菌、金黄色葡萄球菌（含MRSA）、大肠杆菌、鲍曼不动杆菌、真菌。\n常见表现：体温：高热>39℃或低体温<36℃（\"两低一高\"：低体温、低白细胞、高心率是革兰阴性菌感染特征）；心率>120次/分；呼吸急促>28次/分；意识改变：烦躁、谵妄、淡漠、昏迷；创面恶化：创面灰暗、坏死斑、出血点、异味、创缘炎症反应消退；腹胀、肠麻痹；多器官功能障碍：少尿/无尿、黄疸、凝血障碍、ARDS。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（体温、心率、呼吸、血压）；意识状态；创面检查（颜色、渗出、气味、坏死斑、创缘）；腹部（腹胀、肠鸣音）；皮肤（出血点、瘀斑）；肺部（啰音）。","辅助检查":"检查计划：患者大面积烧伤后皮肤屏障破坏、大量坏死组织存留，于伤后1-3周出现高热、心率增快、呼吸急促、意识改变及创面灰暗坏死、异味，高度提示创面侵袭性感染继发脓毒症；入院即刻完善血常规检查，明确白细胞有无>12×10⁹/L或<4×10⁹/L及核左移，并了解有无贫血、血小板下降；查CRP评估全身炎症反应程度，其显著升高提示感染活动；查降钙素原(PCT)明确有无细菌感染，PCT升高对细菌感染特异性较高，可用于鉴别全身炎症反应综合征与脓毒症；患者寒战或高热时双侧双瓶采血完善血培养，明确致病菌及药敏，为抗菌药物降阶梯治疗提供依据；患者创面恶化伴分泌物增多，留取创面分泌物培养+药敏，明确优势致病菌并排除混合感染；患者需经肝肾代谢应用抗菌药物，完善肝肾功能检查排除肝肾功能不全并指导剂量调整；患者出现出血点及凝血障碍表现，完善凝血功能检查排除弥散性血管内凝血，即DIC筛查；患者呼吸急促、氧合下降，急诊完成血气分析明确有无低氧血症及代谢性酸中毒；查乳酸评估组织灌注情况，乳酸持续升高提示组织低灌注与预后不良；患者免疫功能低下、广谱抗菌药物使用时间长，若持续发热而细菌培养阴性，完善真菌G试验/GM试验排除侵袭性真菌感染。上述标本均应在抗菌药物使用前采集，培养结果回报前先经验性覆盖铜绿假单胞菌、MRSA及鲍曼不动杆菌，并动态复查血常规、CRP、PCT评估抗感染疗效。\n\n（检查清单）\n血常规（白细胞>12×10⁹/L或<4×10⁹/L，核左移）、CRP显著升高、PCT升高（细菌感染特异性指标）、血培养（寒战或高热时采血，双侧双瓶）、创面分泌物培养+药敏、肝肾功能、凝血功能（DIC筛查）、血气分析、乳酸（组织灌注）、降钙素原(PCT)、真菌G试验/GM试验（怀疑真菌感染）。","初步诊断":"烧伤基础上出现：①体温>39℃或<36℃；②心率>120次/分；③呼吸>28次/分；④意识改变；⑤创面恶化；⑥白细胞异常；⑦血培养阳性或临床感染证据。符合2项以上+感染证据即可诊断。\n1. 烧伤脓毒症（ICD-10：T31 + A41.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【经验性抗生素（立即，不等培养）】广谱联合：哌拉西林他唑巴坦4.5g q6h ivgtt 或 头孢哌酮舒巴坦3g q8h ivgtt + 万古霉素15mg/kg q12h ivgtt（覆盖MRSA）+ 甲硝唑0.5g q8h ivgtt（厌氧菌）；严重/耐药菌：美罗培南1g q8h + 万古霉素 + 甲硝唑。根据药敏降阶梯。【抗真菌】氟康唑0.4g qd ivgtt（念珠菌）或 卡泊芬净50mg qd（首剂70mg，曲霉菌/耐药念珠菌）。【液体复苏】晶体液快速输注，目标MAP≥65mmHg。【血管活性药】去甲肾上腺素0.05-0.5μg/kg/min泵入（感染性休克）。【免疫调节】丙种球蛋白20g/d×3天、胸腺肽α1。【营养支持】肠内营养优先。\n\n【药物治疗·口服】\n感染控制后口服抗生素序贯；益生菌（调节肠道菌群，预防肠源性感染）。\n\n【治疗】\n【创面处理（最关键）】①积极清创：清除坏死组织，减少细菌负荷；②早期切痂植皮：深度烧伤患者伤后3-7天内切痂，消除感染源；③创面局部抗菌：磺胺嘧啶银乳膏、银离子敷料、碘伏纱布；④生物敷料/异体皮覆盖（暂时覆盖创面）。【抗生素】根据培养药敏调整，疗程根据感染部位和严重程度（通常2-4周）。【支持治疗】营养支持（高热量高蛋白）、纠正水电解质紊乱、保护器官功能。【感染源控制】静脉导管相关感染→拔管；肺部感染→加强排痰、雾化；尿路感染→更换尿管、膀胱冲洗。\n\n【处理要点】\n密切监测生命体征、意识、尿量、乳酸；定期血培养（发热时）、创面培养；器官功能监测（心、肺、肾、肝、凝血）；严格无菌操作和保护性隔离；血糖控制（应激性高血糖，目标8-10mmol/L）；预防应激性溃疡和深静脉血栓。\n\n【护理】\n持续生命体征监测；创面护理（观察创面变化、按时换药）；准确记录出入量；高热护理（物理降温，避免用阿司匹林）；保护性隔离（限制探视、空气消毒）；营养管护理；心理护理。\n\n【饮食】\n高蛋白（1.5-2.5g/kg/d）、高热量（35-40kcal/kg/d）；肠内营养优先；不能进食者肠外营养；多饮水。\n\n【注意事项】\n①烧伤脓毒症的治疗关键是\"创面处理+抗生素\"，单纯抗生素不清除坏死感染灶效果差；②\"两低一高\"（低体温、低白细胞、高心率）是革兰阴性菌脓毒症的典型表现，出现即提示危重；③血培养患者使用抗生素前、寒战或高热时采集，双侧双瓶；④深度烧伤创面是主要感染源，早期切痂植皮是预防脓毒症最有效的措施；⑤烧伤患者免疫功能低下，真菌感染风险高，长期广谱抗生素后需警惕真菌感染；⑥PCT对细菌感染有较好特异性，可指导抗生素使用和疗程；⑦脓毒症抗生素使用要\"早、广、足\"，培养结果出来后及时降阶梯。\n\n【急诊/急救】\n【感染性休克】血压下降、乳酸升高、少尿→快速液体复苏+广谱抗生素+血管活性药+ICU；【DIC】皮肤瘀斑、穿刺点出血、凝血异常→补充凝血因子（血浆、血小板）、抗凝（低分子肝素，需权衡）；【多器官功能衰竭】→ICU器官支持（机械通气、血液净化）。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T31 + A41.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2518,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7bd7fd061c78212f196a5da1e67c612670cc5d5cf0c6fb022b2309ef0585a363","pinyin":"shaoshangnongduzheng","initials":"ssndz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T31 + A41.9",30]]},{"id":"templates-08f2ae5b2e1df2482e6c","key":"v1-c9ccc21dfe2a3058|templates-08f2ae5b2e1df2482e6c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"热力烧伤","category":"烧伤整形科","raw":{"name":"热力烧伤","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】疼痛（I度/浅II度剧痛，III度因神经末梢破坏反而无痛）；皮肤红斑（I度）；水疱（浅II度大水疱、深II度小水疱）；创面渗出、水肿；焦痂（III度，皮革样、蜡白/焦黄/炭化）；大面积烧伤：口渴、尿少、心率快、血压下降（休克期）；发热、创面脓性分泌物（感染期）。。\n【待人工确认·本机素材无此段原文】","现病史":"由火焰、热液、高温气体、炽热金属等热力因素引起的皮肤/黏膜甚至深部组织损伤。烧伤严重程度取决于面积（%TBSA）和深度（I度/浅II度/深II度/III度/IV度），大面积烧伤可致休克、感染、多器官功能衰竭。\n常见表现：疼痛（I度/浅II度剧痛，III度因神经末梢破坏反而无痛）；皮肤红斑（I度）；水疱（浅II度大水疱、深II度小水疱）；创面渗出、水肿；焦痂（III度，皮革样、蜡白/焦黄/炭化）；大面积烧伤：口渴、尿少、心率快、血压下降（休克期）；发热、创面脓性分泌物（感染期）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"烧伤面积估算：中国九分法（头面颈9%、双上肢18%、躯干27%、双下肢46%、会阴1%）、手掌法（患者手掌=1%）；深度判断：I度-红斑、痛觉过敏；浅II度-大水疱、基底潮红、剧痛；深II度-小水疱、基底红白相间、痛觉迟钝；III度-焦痂、无水泡、痛觉消失、可见树枝状栓塞血管；吸入性损伤：鼻毛烧焦、声音嘶哑、喘鸣、碳痰。","辅助检查":"检查计划：患者火焰及热液致伤后创面渗出、水肿明显，口渴、尿少、心率快、血压下降，提示烧伤休克期液体丢失严重；入院即刻完善血常规检查，了解红细胞压积有无升高以判断血液浓缩程度，并评估有无贫血及感染；患者有火焰、高温气体致伤史，急诊完成血气分析，明确有无吸入性损伤所致低氧血症及休克所致代谢性酸中毒，指导氧疗与液体复苏；患者创面大量渗出、进食受限，完善电解质检查排除低钾、低钠等电解质紊乱，指导补液成分调整；查肝肾功能检查了解有无休克所致肝肾功能损害并指导用药；查凝血功能检查排除烧伤后凝血功能异常；大面积烧伤患者需早期液体复苏及后期切削痂植皮手术，完善血型鉴定+交叉配血做好输血准备；患者创面渗出、焦痂形成，感染风险高，留取创面分泌物培养+药敏明确创面细菌定植与感染情况，为创面用药及手术时机提供依据；若出现高热、创面脓性分泌物，完善血培养排除脓毒症；患者有吸入性损伤可能，查胸部CT明确有无气道及肺实质损伤及其程度，必要时行纤维支气管镜检查；查尿常规了解有无血红蛋白尿、肌红蛋白尿，提示深度烧伤或电烧伤所致肌肉组织破坏，并动态监测尿量指导抗休克治疗。\n\n（检查清单）\n血常规（红细胞压积升高提示血液浓缩）、血气分析（吸入性损伤/休克）、电解质、肝肾功能、凝血功能、血型+交叉配血（大面积烧伤）、创面分泌物培养+药敏、血培养（怀疑脓毒症）、胸部CT（吸入性损伤）、尿常规（血红蛋白尿提示深度烧伤/电烧伤）。","初步诊断":"明确热力接触史 + 典型创面表现 + 面积深度评估。严重程度分级：轻度-总面积<10%（儿童<5%），无III度；中度-10-30%（儿童5-15%），III度<10%；重度-31-50%（儿童16-25%），III度10-20%；合并严重吸入性损伤、复合伤或重要脏器损伤者即使面积不足也可按重度及以上处理；特重度->50%（儿童>25%），III度>20%。\n1. 热力烧伤（ICD-10：T30）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【休克期补液（伤后24-48小时）】晶胶公式：第一个24小时=体重(kg)×面积(%)×1.5ml（晶体:胶体=2:1，III度面积大可1:1）+ 基础水分2000ml（5%葡萄糖）；前8小时输入一半，后16小时输入另一半；第二个24小时晶胶体减半，水分不变。晶体用乳酸林格液/生理盐水，胶体用血浆/白蛋白/右旋糖酐。【抗感染】重度烧伤：哌拉西林他唑巴坦4.5g q8h ivgtt 或 头孢哌酮舒巴坦3g q8h ivgtt + 甲硝唑0.5g q8h，MRSA风险加万古霉素15mg/kg q12h。【营养支持】肠内营养制剂（短肽型/整蛋白型），必要时肠外营养。\n\n【药物治疗·口服】\n【止痛】布洛芬0.3g tid 或 氨酚待因1片prn（中重度疼痛用吗啡/哌替啶注射）；【预防应激性溃疡】奥美拉唑20mg qd 或 雷尼替丁150mg bid；【抗凝】低分子肝素4000-6000IU qd皮下（预防深静脉血栓，大面积烧伤）；【抗瘢痕】积雪苷片2-4片tid（愈合后）。\n\n【治疗】\n【急救】脱离热源、冷水冲洗（15-25℃流水冲洗15-30分钟，I/II度适用，III度慎用）、剪开衣物（不可强行剥脱）、清洁敷料覆盖、不涂有色药物（影响深度判断）。【创面处理】I度：冷敷、烫伤膏；浅II度：水疱>1cm低位剪破引流，保留疱皮，磺胺嘧啶银乳膏/银离子敷料；深II度/III度：早期切削痂+自体皮移植（大张中厚皮片/微粒皮/Meek植皮）；手/关节功能部位：大张自体皮。【手术】削痂术（深II度，伤后3-5天）、切痂术（III度，伤后3-7天）、植皮术、皮瓣转移（深部组织暴露）。【吸入性损伤】气道湿化、雾化、必要时气管切开、机械通气。\n\n【处理要点】\n【休克期】监测尿量（目标0.5-1ml/kg/h）、心率、血压、神志、红细胞压积，调整补液速度；【感染期】严格无菌操作、保护性隔离、定期创面培养、合理使用抗生素；【修复期】营养支持（热量35-40kcal/kg/d，蛋白1.5-2.5g/kg/d）、早期功能锻炼、抗瘢痕治疗；【心理支持】大面积烧伤患者心理干预。\n\n【护理】\n休克期：每小时记录尿量、生命体征，准确记录出入量；创面护理：暴露疗法（烤灯/热风）保持创面干燥，包扎疗法保持敷料清洁干燥；翻身床/气垫床预防压疮；疼痛管理（换药前镇痛）；营养管护理（肠内营养）；功能位摆放（手功能位、踝关节90°）。\n\n【饮食】\n高蛋白（1.5-2.5g/kg/d）、高热量（35-40kcal/kg/d）、富含维生素；大面积烧伤分解代谢旺盛，需加强营养；不能经口进食者肠内/肠外营养；戒烟酒。\n\n【注意事项】\n①烧伤面积估算用患者本人手掌（1%），儿童头大下肢小需调整；②III度烧伤不会自行愈合，必须植皮；③早期冷水冲洗仅限中小面积，大面积烧伤冷水冲洗可致低体温；④不要在创面上涂牙膏、酱油、紫药水等；⑤大面积烧伤患者转运前应先建立静脉通路补液，不可单纯转运；⑥烧伤后6-8小时是休克期关键时段；⑦深度烧伤愈合后必然留瘢痕，需早期抗瘢痕治疗和功能锻炼。；⑧深度-愈合-预后对照：Ⅰ度约3-7天愈合；浅Ⅱ度约1-2周愈合、多不留瘢痕；深Ⅱ度约3-4周愈合、常留瘢痕并可能需手术；Ⅲ度不自行愈合、必须植皮；⑨中国九分法参考：头面颈9%、双上肢18%、躯干前后各13%+会阴1%、双下肢（含臀部）46%，儿童头面部比例更大、双下肢相对小，结合手掌法(1%)综合估算\n\n【急诊/急救】\n【烧伤休克】大面积烧伤后口渴、尿少、心率快、血压下降→立即建立静脉通路、快速补液、监测尿量；【吸入性损伤窒息】鼻毛烧焦、声音嘶哑、呼吸困难、碳痰→立即气道管理、必要时气管切开；【烧伤脓毒症】高热/低体温、心率快、意识改变、创面恶化→血培养+广谱抗生素+创面处理+ICU。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T30","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2519,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5834570b02bd92c9b69f8c749b87cd01feb121f9df3a25d916f7208a8c294c62","pinyin":"relishaoshang","initials":"rlss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T30",30]]},{"id":"templates-a8958636ab6c4c076329","key":"v1-c9ccc21dfe2a3058|templates-a8958636ab6c4c076329","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙列缺失行种植体支持式可摘义齿修复","category":"口腔医学临床路径（2019年版）","raw":{"name":"牙列缺失行种植体支持式可摘义齿修复","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r1.血常规、凝血功能、肝肾功能、感染性疾病筛查。\r2.单颌牙列缺失者，行对颌牙周健康状况检查及基础治疗。\r3.X线片（曲面体层片、根尖片、锥形束CT）。\r4.双侧颞下颌关节检查。\r5.取研究模型，行模型分析。\r（七）抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r2.建议使用第一代头孢菌素，可加用甲硝唑。使用口腔抗菌含漱液，预防性用药时间为术前30分钟。\r（八）手术日为第3次门诊日\r1.麻醉方式：局部麻醉，必要时镇静下治疗。\r2.术中用药：局部麻醉药物。\r3.输血：无。\r（九）术后门诊复查3次\r1.必须复查的项目\r（1）曲面体层片、根尖片或锥形束CT。\r（2）术区愈合情况。\r2.根据患者当时病情决定其他检查项目。\r（十）术后用药\r1.第一代头孢菌素，可加用甲硝唑。\r2.患者口腔抗菌含漱液。\r（十一）种植修复治愈标准\r1.X线片显示种植体位置、轴向良好，周围无透射区。\r2.种植体无动度。\r3.种植修复体能正常行使功能。\r4.伤口愈合良好。\r5.无持续性或不可逆的症状，没有需要临床处理的并发症和（或）合并症。\r（十二）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.全口牙缺失，或单颌牙列缺失。\r2.全身健康状况能满足常规牙槽突外科手术。\r3.口腔软硬组织健康，上下颌骨局部形态及\n关系、颌间距离等均满足种植体支持式可摘义齿修复要求。 \r4.X线片显示拟种植区的局部骨量满足种植体植入要求。\r（三）\n1. 牙列缺失行种植体支持式可摘义齿修复（ICD-10：K08.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床技术操作规范\n口腔医学分册（2017修订版）》（中华口腔医学会编著，人民卫生出版社,2017）。\r1.临床及影像学检查符合上述","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K08.0、K80.1牙列缺失疾病编码。\r2.当患者同时具有其他疾病诊断，但在门诊治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备3次","临床路径·变异及原因分析":"变异及原因分析\r1.患有全身性疾病者，必要时请相关学科会诊及检查。\r2.解剖结构异常。\r3.种植术区伴有骨量不足，需要同期行骨增量手术，或先行骨增量手术二期种植。\r4.拔牙即刻种植治疗。\r5.种植后，需种植体支持过渡义齿修复。\r\r\r\r\f二、牙列缺失行种植体支持式可摘义齿修复","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 牙列缺失行种植体支持式可摘义齿修复临床路径（2019年版）.doc"},"icd10_diagnosis":"K08.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2520,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"799375a6ccd98c78eecc02e482b8e5dd810bcd721fabb6f4971bca643e8cd8a4","pinyin":"yaliequeshixingzhongzhitizhichishikezhaiyichixiufu","initials":"ylqsxzztzcskzycxf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K08.0",30]]},{"id":"templates-91b550f64f8244d40064","key":"v1-c9ccc21dfe2a3058|templates-91b550f64f8244d40064","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙列缺失行种植体支持式固定义齿修复","category":"口腔医学临床路径（2019年版）","raw":{"name":"牙列缺失行种植体支持式固定义齿修复","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r1.血常规、凝血功能、肝肾功能、感染性疾病筛查。 \r2.单颌牙列缺失者，行对颌牙周健康状况检查及基础治疗。\r3.X线片（曲面体层片、根尖片、锥形束CT）。 \r4.双侧颞下颌关节检查。\r5.取研究模型，行模型分析。 \r（七）抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r2.建议使用第一代头孢菌素，可加用甲硝唑。使用口腔抗菌含漱液，预防性用药时间为术前30 分钟。\r（八）手术日为第4次门诊日\r1.麻醉方式：局部麻醉，必要时镇静下治疗。 \r2.术中用药：局部麻醉用药。\r3.输血：无。\r（九）术后复查\r1.必须复查的项目\r（1）曲面体层片、根尖片或锥形束CT。\r（2）术区愈合情况。\r2.根据患者当时病情决定其他检查项目。\r（十）术后用药\r1.第一代头孢菌素，可加用甲硝唑。\r2.患者口腔抗菌含漱液。\r（十一）种植修复治愈标准\r1.X线片显示种植体位置、轴向良好，周围无透射区。\r2.种植体无动度。\r3.种植修复体能正常行使功能。\r4.伤口愈合良好。\r5.无持续性或不可逆的症状，无需要临床处理的并发症和（或）合并症。\r（十二）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.全口牙缺失，或单颌牙列缺失。\r2.全身健康状况能满足常规牙槽突外科手术。\r3.口腔软硬组织健康，上下颌骨局部形态及\n关系、颌间距离等均满足种植固定义齿要求。\r4.X线片显示拟种植区的上下颌骨局部骨量满足种植修复要求。\r（三）\n1. 牙列缺失行种植体支持式固定义齿修复（ICD-10：K08.101）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床技术操作规范\n口腔医学分册（2017修订版）》（中华口腔医学会编著，人民卫生出版社,2017）。\r1.临床及影像学检查符合上述","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10:K08.101或K08.104牙列缺失疾病编码。\r2.当患者同时具有其他疾病诊断，但在门诊治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备","临床路径·变异及原因分析":"变异及原因分析\r1.患有全身性疾病者，必要时请相关学科会诊及检查。\r2.解剖结构异常。\r3.种植术区伴有骨量不足，需要同期行骨增量手术，或先行骨增量手术二期种植。\r4.拔牙即刻种植治疗。\r5.种植后，需种植体支持过渡义齿修复。\r\f二、牙列缺失","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 牙列缺失行种植体支持式固定义齿修复临床路径（2019年版）.doc"},"icd10_diagnosis":"K08.101","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2521,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c6db5f4de528a4d51f6e308ce352f54b2e2264771e00c9964422ac328b220ce0","pinyin":"yaliequeshixingzhongzhitizhichishigudingyichixiufu","initials":"ylqsxzztzcsgdycxf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K08.101",30]]},{"id":"templates-dfed05007b5dbcb80f49","key":"v1-c9ccc21dfe2a3058|templates-dfed05007b5dbcb80f49","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙列缺损行种植体支持式固定义齿修复","category":"口腔医学临床路径（2019年版）","raw":{"name":"牙列缺损行种植体支持式固定义齿修复","category":"口腔医学临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r1.血常规、凝血功能、肝肾功能、感染性疾病筛查。\r2.全口牙周健康状况、邻牙牙体牙髓状况检查及种植固定义齿修复术及基础治疗。\r3.X线片（曲面体层片、根尖片、锥形束CT）。 \r4.双侧颞下颌关节及咬合关系。\r（七）抗菌药物选择与使用时机\r1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，并根据患者的病情决定抗菌药物的选择与使用时间。\r2.建议使用第一代头孢菌素，可加用甲硝唑。使用具有消毒抗菌作用的口腔含漱液，预防性用药时间为术前30 分钟。\r（八）手术日为第3次门诊日\r1.麻醉方式：局部麻醉，必要时镇静下治疗。\r2.术中用药：局部麻醉药物。\r3.输血：无。\r（九）术后复查\r1.必须复查的项目\r（1）根尖片、曲面体层片或锥形束CT。\r（2）术区愈合情况。\r2.根据患者当时病情决定其他检查项目。\r（十）术后用药\r1.第一代头孢菌素，可加用甲硝唑。\r2.患者具有消毒抗菌作用的口腔含漱液。\r（十一）二期手术和修复治疗\r1.二期手术1次。\r2.术后种植修复治疗2\n3次。\r（十二）种植修复成功标准\r1.X线片显示种植体位置、轴向良好，周围无透射区。\r2.种植体无动度。\r3.种植修复体能正常行使功能。\r4.伤口愈合良好。\r5.无持续性或不可逆的症状，无需要临床处理的并发症和（或）合并症。\r（十三）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n口腔医学分册（2016修订版）》（中华口腔医学会编著，人民卫生出版社，2016）。\r1.牙列中1个或数个牙缺失，拔牙后愈合3个月以上。\r2.年龄18岁以上，颌骨已发育成熟。\r3.全身健康状况能满足常规牙槽突外科手术要求。\r4.口腔软硬组织健康，剩余牙列情况、缺牙间隙大小、龈\n距离、咬合关系、颌骨形态、张口度等均满足种植修复要求。\r5.X线片示拟种植区的牙槽骨量满足种植要求。\r（三）\n1. 牙列缺损行种植体支持式固定义齿修复（ICD-10：K08.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n治疗方案的选择\r根据《临床技术操作规范\n口腔医学分册（2017修订版）》（中华口腔医学会编著，人民卫生出版社，2017）。 \r1.经临床及影像学检查符合上述","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD-10：K08.0、K08.1牙列缺损疾病编码。\r2.当患者同时具有其他疾病诊断，但在门诊治疗期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备","临床路径·变异及原因分析":"变异及原因分析\r1.患有全身性疾病者，必要时请相关学科会诊及检查。\r2.解剖结构异常。\r3.种植术区伴有骨量不足，需要同期行骨增量手术，或先行骨增量手术二期种植。\r4.拔牙即刻行种植治疗。\r5.需行固定桥和联冠修复。\r6.种植后，需种植体支持过渡义齿修复。\r\f二、牙列缺损","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 口腔医学临床路径（2019年版） · 牙列缺损行种植体支持式固定义齿修复临床路径（2019年版）.doc"},"icd10_diagnosis":"K08.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2522,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a6aa2530896454e95b25fed37eacd9a56013768d2f59634af629b816fb8b72c3","pinyin":"yaliequesunxingzhongzhitizhichishigudingyichixiufu","initials":"ylqsxzztzcsgdycxf","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","K08.0",30]]},{"id":"templates-ca3d8aa22c53ac74397c","key":"v1-c9ccc21dfe2a3058|templates-ca3d8aa22c53ac74397c","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"牙外伤急诊处理","category":"口腔","raw":{"name":"牙外伤急诊处理","category":"口腔","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】牙齿疼痛、松动、移位、伸长或嵌入（脱位）、牙齿缺损（冠折）、露髓（可见红点与剧痛）、牙冠变色（牙髓坏死）、牙龈与口腔黏膜撕裂出血、牙槽突骨折（多牙整体移动、咬合错乱）、完全脱位：牙齿脱落（需询问离体牙保存方式与时间）、合并伤：颌面部骨折、颅脑损伤、软组织裂伤（需优先评估）。\n【待人工确认·本机素材无此段原文】","现病史":"牙外伤包括牙震荡、牙脱位（部分/完全脱位、嵌入）、牙折（冠折、根折、冠根折）与牙槽突骨折，多见于儿童与青少年（跌倒、运动、交通事故）。处理关键是及时（尤其完全脱位牙再植的黄金时间30分钟内）与正确保存离体牙（生理盐水、牛奶或口腔前庭）。\n常见表现：牙齿疼痛、松动、移位、伸长或嵌入（脱位）、牙齿缺损（冠折）、露髓（可见红点与剧痛）、牙冠变色（牙髓坏死）、牙龈与口腔黏膜撕裂出血、牙槽突骨折（多牙整体移动、咬合错乱）、完全脱位：牙齿脱落（需询问离体牙保存方式与时间）、合并伤：颌面部骨折、颅脑损伤、软组织裂伤（需优先评估）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征与意识：有无颅脑损伤（意识、瞳孔、呕吐）与颌面部多发伤\n牙齿：松动度、移位、伸长、嵌入、缺牙（记录牙位与数目）、叩诊反应\n牙髓活力：电活力测试与冷测（伤后即刻结果可能不准确，需复查）\n牙冠：缺损范围、露髓（可见红点）、颜色（变色提示牙髓坏死）\n牙龈与黏膜：裂伤、出血、撕裂范围与深度\n牙槽突：骨台阶感、多牙整体移动（牙槽突骨折）、咬合错乱\n颌面部：面部肿胀与畸形、张口受限、下颌运动异常（骨折评估）","辅助检查":"1. 根尖片+口腔全景X线（必查）：根折、牙槽突骨折、脱位与恒牙胚评估\n2. CBCT（复杂病例）：根折位置、牙槽骨骨折细节与异物定位\n3. 牙髓活力测试（电活力/冷测）：伤后即刻与随访（1、3、6、12个月）对比\n4. 血常规+凝血功能（拟手术/出血多者）：术前评估\n5. 破伤风预防评估（污染伤口）：破伤风抗毒素/免疫球蛋白接种\n6. 颌面部CT（疑骨折）：明确骨折部位与范围\n7. 头颅CT（合并颅脑损伤嫌疑）：优先评估颅内损伤","初步诊断":"1. 病史：受伤时间与方式、离体牙保存方式与时间（再植预后关键）\n2. 牙齿检查：松动度、移位、叩诊、牙髓活力测试（电活力/冷测）、露髓与颜色\n3. 牙龈与牙槽突：裂伤、出血、骨台阶感、多牙移动（牙槽突骨折）\n4. X线（根尖片+全景片）：牙根折、牙槽突骨折、脱位与邻牙情况、恒牙胚（儿童）\n5. CBCT（复杂病例）：根折位置、牙槽骨骨折细节与异物\n6. 全身评估：是否合并颌面部骨折、颅脑损伤（按ATLS原则优先处理）\n7. 儿童注意：区分乳牙与恒牙（乳牙损伤处理原则不同），评估恒牙胚受损风险\n1. 牙外伤急诊处理（ICD-10：S03.2）","鉴别诊断":"1. 儿童注意：区分乳牙与恒牙（乳牙损伤处理原则不同），评估恒牙胚受损风险\n2. 诊断要点：病史：受伤时间与方式、离体牙保存方式与时间（再植预后关键）\n3. 诊断要点：牙齿检查：松动度、移位、叩诊、牙髓活力测试（电活力/冷测）、露髓与颜色\n4. 诊断要点：牙龈与牙槽突：裂伤、出血、骨台阶感、多牙移动（牙槽突骨折）\n5. 诊断要点：X线（根尖片+全景片）：牙根折、牙槽突骨折、脱位与邻牙情况、恒牙胚（儿童）\n6. 诊断要点：CBCT（复杂病例）：根折位置、牙槽骨骨折细节与异物\n7. 诊断要点：全身评估：是否合并颌面部骨折、颅脑损伤（按ATLS原则优先处理）","处理方案":"【药物治疗·输液】\n⚠️ 牙外伤以局部处理为主，全身用药用于污染重/合并骨折/免疫低下者！\n\n方案1（抗感染，再植牙/开放性损伤/牙槽突骨折）：\n 用法：阿莫西林 0.5g 静滴 q8h（或口服 0.5g tid，疗程5～7天）；青霉素过敏者 克林霉素 0.6g 静滴 q8h\n\n方案2（破伤风预防，污染伤口）：\n 用法：破伤风抗毒素 1500IU 皮下注射（皮试后）或 破伤风免疫球蛋白 250IU 肌注\n\n方案3（镇痛与支持）：\n 用法：对乙酰氨基酚 0.5g 静滴 必要时（儿童按体重10～15mg/kg）；0.9%氯化钠 静滴\n\n方案4（合并颌面部骨折/需手术）：\n 用法：头孢呋辛 1.5g 静滴 q8h + 甲硝唑 0.5g 静滴 q8h；地塞米松 10mg 静推（减轻水肿，短期）\n\n📌 完全脱位牙再植是关键：黄金时间30分钟内，离体牙只能握牙冠（勿触碰牙根）、用生理盐水/牛奶/唾液保存湿润；再植后抗生素+破伤风预防+牙髓治疗评估。\n\n【药物治疗·口服】\n⚠️ 局部处理+口服药物辅助：\n\n药物1（抗感染）：\n 用法：阿莫西林 0.5g tid（疗程5～7天，儿童按体重25～45mg/kg/日分次）；青霉素过敏者 克林霉素 0.3g tid\n\n药物2（镇痛）：\n 用法：对乙酰氨基酚 0.5g 必要时（儿童10～15mg/kg）；必要时布洛芬 0.3g bid（餐后）\n\n药物3（局部用药与护理）：\n 用法：0.2%氯己定含漱液 含漱 bid（儿童用棉签涂抹，避免吞咽）；康复新液 含漱促愈合\n\n药物4（牙髓相关，按医嘱）：\n 用法：根管治疗期间必要时口服抗生素；牙髓坏死需行根管治疗（不做药物替代）\n\n📌 牙外伤后需避免硬食与咬合刺激、保持口腔清洁、按时复查牙髓活力与X线（牙髓坏死与根吸收可延迟出现）。\n\n【治疗】\n完全脱位牙：立即再植（黄金30分钟内）——握牙冠、生理盐水冲洗（勿刮牙根）、尽量复位并弹性固定2周；不能立即再植者保存于生理盐水/牛奶/唾液，尽快就诊；再植后按医嘱抗生素+破伤风预防+2周内根管治疗（成人恒牙）\n部分脱位/移位：局麻下复位+弹性固定2～4周，监测牙髓活力（1、3、6、12个月）\n嵌入性脱位：乳牙可观察自行萌出；恒牙（嵌入>7mm或牙根发育完成）需正畸牵引或手术复位\n冠折（未露髓）：树脂修复+脱敏；露髓（<24小时、牙根未发育完成）行活髓切断/直接盖髓；露髓时间长或牙根发育完成者行根管治疗+桩核冠\n根折：冠1/3（去除冠部+根管治疗后桩核修复）；中1/3（复位固定观察，必要时根管治疗）；根尖1/3（多为观察+固定）\n牙槽突骨折：局麻下复位+牙弓夹板/正畸托槽固定4～6周，抗生素+破伤风预防，必要时手术\n乳牙外伤：以保护恒牙胚为原则，避免不必要的手术与固定；乳牙完全脱位一般不再植\n随访：伤后1、3、6、12个月复查（牙髓活力、X线与根吸收），青春期前儿童需长期随访\n\n【处理要点】\n急救与保存：完全脱位牙立即指导正确保存（勿触碰牙根、湿润保存），快速就诊（再植黄金时间30分钟）\n疼痛与出血护理：评估疼痛并镇痛；牙龈与黏膜裂伤清创、压迫止血，必要时缝合\n固定护理：固定期间避免咬硬物与剧烈运动、软食、保持口腔清洁（含漱液），按医嘱复查拆除固定\n牙髓监测：按时评估牙髓活力（电活力/冷测）与牙齿颜色变化（变色提示牙髓坏死），异常报告并安排根管治疗\n感染预防：抗感染与破伤风预防（污染伤口）；观察牙龈肿胀与溢脓（根尖感染）\n儿童与家长宣教：乳牙与恒牙区分与随访重要性、运动时戴护齿、避免再次外伤、按时复查（牙髓坏死与根吸收可延迟数月至数年）\n多学科协作：合并颌面部骨折或颅脑损伤时与口腔颌面外科、神经外科协作\n\n【护理】\n急救与牙保存指导：指导患者/家长正确保存离体牙（握牙冠、湿润保存、尽快就诊），并记录受伤与保存时间\n疼痛与出血护理：评估疼痛并镇痛；局部压迫止血、协助清创缝合、观察出血量\n固定期护理：指导软食、避免咬硬物与剧烈运动、口腔清洁（含漱液）、按时复诊拆除固定\n牙髓监测与随访提醒：按时复查牙髓活力与X线（1、3、6、12个月），变色或疼痛立即就诊\n感染预防：遵医嘱抗生素与破伤风预防，观察牙龈肿胀、溢脓与发热\n宣教：儿童与家长共同教育（运动戴护齿、避免再次外伤、牙外伤需长期随访）、口腔卫生维护\n\n【饮食】\n固定期：软食、温凉食物，避免过硬、过热与刺激性食物（减少牙齿受力与出血）\n高蛋白、高维生素（维生素C）饮食促进牙龈与组织愈合\n避免用患牙咀嚼；儿童避免吮指与咬硬物（玩具、笔）\n保持口腔清洁：餐后漱口、含漱液使用（按医嘱）\n避免含糖食物与饮料（防龋与感染）；戒烟酒（成人）\n\n【注意事项】\n完全脱位牙再植的黄金时间是30分钟内，离体牙只能握牙冠、勿触碰牙根，用生理盐水/牛奶/唾液湿润保存（不可干燥）\n牙外伤后牙髓坏死与根吸收可延迟出现（数月至数年），必须长期随访（1、3、6、12个月）\n乳牙外伤以保护恒牙胚为原则（避免不必要的手术与固定）；乳牙完全脱位一般不再植\n牙外伤常提示运动防护不足（运动时佩戴护齿可显著降低发生率）\n合并颌面部骨折或颅脑损伤时按多发伤原则优先处理危及生命的损伤\n\n【急诊/急救】\n完全脱位牙（30分钟内）→ 立即再植+弹性固定，抗感染与破伤风预防，2周内评估根管治疗\n牙齿露髓伴剧痛 → 尽早（24小时内）行活髓切断/盖髓或根管治疗，镇痛处理\n牙外伤伴颌面部骨折（咬合错乱、面部畸形）→ 口腔颌面外科急诊评估与手术\n牙槽突骨折伴多牙移位 → 局麻下复位固定+抗生素，必要时手术\n牙外伤伴颅脑损伤（意识改变、呕吐）→ 优先按颅脑损伤处理（头颅CT），口腔处理延后","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「牙外伤急诊处理」原文）"},"icd10_diagnosis":"S03.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2523,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c60d287a7c1b1229f808c16e8ffe68f2ab73888a6b707e60e4ebca032c0432a3","pinyin":"yawaishangjizhenchuli","initials":"ywsjzcl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","S03.2",30]]},{"id":"templates-793ab6c049ead0a28b8b","key":"v1-c9ccc21dfe2a3058|templates-793ab6c049ead0a28b8b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"特发性肺纤维化","category":"内科-呼吸","raw":{"name":"特发性肺纤维化","category":"内科-呼吸","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文·卫健委临床路径原文】进行性加重的劳力性呼吸困难、干咳、双肺底爆裂音（Velcro啰音）、杵状指、乏力、消瘦。\n【待人工确认·本机素材无此段原文】","现病史":"原因不明的慢性进行性纤维化性间质性肺炎，以进行性呼吸困难和肺功能下降为特征，预后差\n常见表现：进行性加重的劳力性呼吸困难、干咳、双肺底爆裂音（Velcro啰音）、杵状指、乏力、消瘦。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：静息时呼吸平稳，活动后呼吸频率明显增快，可伴低氧血症\n肺部：双肺底吸气末爆裂音（Velcro啰音）\n一般情况：口唇发绀、杵状指（病程长者）\n心脏：肺动脉瓣第二心音亢进（合并肺动脉高压时）\n下肢：踝部水肿（合并右心功能不全时）","辅助检查":"1. 胸部HRCT：诊断核心，典型UIP表现（双肺底胸膜下网格影、蜂窝肺）\n2. 肺功能+DLCO：评估限制性通气障碍及弥散功能下降程度\n3. 6分钟步行试验：评估运动耐量及运动后血氧饱和度变化\n4. 动脉血气分析：评估低氧血症及呼吸衰竭程度\n5. 自身抗体谱及结缔组织病相关检查：排除继发性间质性肺病\n6. （拟肺移植者）心脏彩超及右心导管检查\n\n【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、大便常规。\r（2）感染性疾病筛查（乙型肝炎、丙型肝炎、梅毒、艾滋病等）。\r（3）肝肾功能、血糖、电解质。\r（4）红细胞沉降率、C反应蛋白（CRP）、蛋白电泳、IgG 等。\r（5）抗核抗体（ANA）谱、抗中性粒细胞胞质抗体（ANCA）、抗环瓜氨酸抗体（CCP）、类风湿因子（RF）。\r（6）胸部HRCT、心电图。\r（7）肺功能（病情允许时）：常规通气功能、弥散功能。\r（8）动脉血气分析。\r（9）支气管肺泡灌洗液检查（HRCT为非典型UIP型时）；\r（10）外科肺活检（HRCT为非典型UIP型时，且病情许可时）。\r2.根据患者情况可选择： D\n二聚体、肿瘤标志物、病原学检查、超声心动图、6分钟步行试验、经支气管镜肺活检（TBLB）等。\r（七）药物选择\r1.酌情使用的药物：吡非尼酮、尼达尼布、N-乙酰半胱氨酸，抑酸药物。\r2.不推荐使用的药物：\n 1 \n GB3 \n泼尼松、硫唑嘌呤联合N-乙酰半胱氨酸；\n 2 \n GB3 \n抗凝药物；\n 3 \n GB3 \n西地那非；\n 4 \n GB3 \n波生坦、马西替坦；\n 5 \n GB3 \n伊马替尼。\r（八）","初步诊断":"1. HRCT示双肺底、胸膜下网格状影伴蜂窝肺（UIP型）\n2. 肺功能：限制性通气功能障碍，弥散功能（DLCO）下降\n3. 排除职业暴露、结缔组织病等所致的其他间质性肺病\n4. （必要时）外科肺活检示UIP改变\n【临床路径·诊断依据】\n诊断依据\r根据《特发性肺纤维化诊断和治疗中国专家共识》（中华结核和呼吸杂志，2016年），《特发性肺纤维化诊治循证指南》（美国胸科学会、欧洲呼吸学会、日本呼吸学会、拉丁美洲胸科协会，2015年）。\r（1）排除其他已知原因的间质性肺病（如家庭或职业环境暴露、结缔组织病和药物毒性）.\r（2）胸部高分辨CT（HRCT）表现为UIP型（此类患者不建议行外科肺活检）。\r（3）已进行外科肺活检的患者，根据HRCT和外科肺活检病理的特定组合进行诊断。\r（三）\n1. 特发性肺纤维化（ICD-10：J84.1）","鉴别诊断":"1. 排除职业暴露、结缔组织病等所致的其他间质性肺病\n2. 诊断需多学科讨论（呼吸、影像、病理），排除其他间质性肺病\n3.与结缔组织病相关ILD、慢性过敏性肺炎、石棉肺等鉴别\n4. （1）排除其他已知原因的间质性肺病（如家庭或职业环境暴露、结缔组织病和药物毒性）.","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：NS100ml+甲泼尼龙500mg ivgtt qd×3天（急性加重期冲击治疗，据病情评估）\n\n方案2：\n 用法：NS500ml ivgtt qd（急性加重期补液支持，严格控制液体总量，监测心肺功能）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：吡非尼酮胶囊：起始200mg tid，每1-2周递增，维持600mg tid（抗纤维化，随餐服用）\n\n药物2：\n 用法：尼达尼布软胶囊150mg bid（抗纤维化，间隔12小时，餐时服用）\n\n药物3：\n 用法：乙酰半胱氨酸泡腾片600mg tid（抗氧化及祛痰辅助）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n抗纤维化治疗（吡非尼酮或尼达尼布）\n急性加重期糖皮质激素冲击治疗\n长期氧疗：静息低氧血症者予长期家庭氧疗\n肺康复训练及对症止咳治疗\n评估肺移植适应证（合适者及早转诊）\n\n【处理要点】\n戒烟，避免粉尘及有害气体接触\n预防呼吸道感染：每年接种流感疫苗和肺炎球菌疫苗\n积极控制胃食管反流，避免诱发急性加重\n定期随访：复查肺功能、HRCT、6分钟步行试验及血氧\n\n【护理】\n氧疗护理：遵医嘱给予氧疗，监测血氧饱和度，指导家庭氧疗注意事项\n用药护理：指导吡非尼酮/尼达尼布正确服用及不良反应（恶心、腹泻、光敏反应）观察与处理\n呼吸康复：指导缩唇呼吸、腹式呼吸训练，循序渐进活动\n预防感染：注意保暖，避免去人群密集场所，出现感染症状及时就医\n心理护理：疏导焦虑情绪，增强治疗信心，指导定期随访及肺移植评估\n\n【饮食】\n高蛋白、高热量饮食，保证营养支持，防止消瘦\n少食多餐，避免过饱加重呼吸困难\n多食富含维生素及抗氧化物质的新鲜蔬果\n戒烟酒，避免辛辣刺激性食物\n吞咽功能减退者注意进食安全，防误吸\n\n【注意事项】\n诊断需多学科讨论（呼吸、影像、病理），排除其他间质性肺病\n急性加重是死亡主要原因，出现呼吸困难急剧加重需及时就诊与结缔组织病相关ILD、慢性过敏性肺炎、石棉肺等鉴别\n不建议常规长期使用糖皮质激素维持治疗（仅急性加重期使用）\n\n【急诊/急救】\n急性加重（呼吸困难急剧加重、发绀、低氧）：立即吸氧，呼叫120送医\n合并气胸（突发胸痛伴呼吸困难加重）：保持安静，尽快送医\n大咯血（罕见但危及生命）：头偏向一侧保持呼吸道通畅，立即转运\n\n【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《特发性肺纤维化诊断和治疗中国专家共识》（中华结核和呼吸杂志，2016年）。\r1.非药物治疗：戒烟、氧疗、肺康复等。\r2.抗纤维化治疗：\r（1）抗纤维化药物。\r（2）抗氧化治疗。\r3.合并症治疗：抗胃食管反流治疗等。\r4.对症、支持治疗：镇咳、祛痰，抗焦虑，酌情中医中药等。\r5.肺移植。\r（四）","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合ICD\n10：J84.104特发性肺纤维化疾病编码。\r2.当患者同时具有其他疾病诊断，但在住院期间不需要特殊处理，也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）住院期间的检查项目\r1.","临床路径·标准住院日":"标准住院日为10～14天\r（五）","临床路径·出院标准":"出院标准\r症状好转，生命体征平稳。\r（九）","临床路径·变异及原因分析":"变异及原因分析\r1.伴有影响本病治疗效果的合并症，需要进行相关诊断和治疗，导致住院时间延长。\r2.病情较重，出现并发症（如气胸、呼吸衰竭、严重肺部感染等），退出本路径，转入相应路径。\r3.常规治疗无效或加重，退出本路径。\r\r\r\r\f二、特发性肺纤维化","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「特发性肺纤维化」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 呼吸病临床路径（2019年版） · 特发性肺纤维化临床路径（2019年版）.doc"},"icd10_diagnosis":"J84.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2524,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a7e149edb616cbd28b731f1e673ad87960cbdb7d7077c08f6ecda7d8f9971e34","pinyin":"tefaxingfeixianweihua","initials":"tfxfxwh","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","J84.1",30]]},{"id":"templates-27573cb0b3a81d752813","key":"v1-c9ccc21dfe2a3058|templates-27573cb0b3a81d752813","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"狂犬病暴露处置","category":"院前急救","raw":{"name":"狂犬病暴露处置","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】动物抓咬伤口、暴露分级：I级（接触/喂养，完好皮肤被舔）无需处置、II级（裸露皮肤轻咬、无出血抓伤）接种疫苗、III级（出血咬伤/抓伤、破损皮肤被舔、蝙蝠接触）疫苗+免疫球蛋白、狂犬病发病：恐水、怕风、咽肌痉挛、进行性瘫痪（发病后几乎100%死亡）。\n【待人工确认·本机素材无此段原文】","现病史":"狂犬病毒感染致死率近100%，被犬/猫/蝙蝠等动物抓咬伤后需立即规范处理伤口并接种疫苗，III级暴露需注射免疫球蛋白。\n常见表现：动物抓咬伤口、暴露分级：I级（接触/喂养，完好皮肤被舔）无需处置、II级（裸露皮肤轻咬、无出血抓伤）接种疫苗、III级（出血咬伤/抓伤、破损皮肤被舔、蝙蝠接触）疫苗+免疫球蛋白、狂犬病发病：恐水、怕风、咽肌痉挛、进行性瘫痪（发病后几乎100%死亡）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 伤口暴露分级评估：检查伤口深度、出血量、有无贯通伤，重点排查头面部、颈部、手部等高危部位，判定I/II/III级暴露以决定是否使用狂犬病免疫球蛋白（就诊即刻完成）\n2. 血常规、C反应蛋白（CRP）：评估全身感染及伤口继发感染风险（急诊初查）\n3. 破伤风抗毒素（TAT）/破伤风免疫球蛋白（TIG）皮试：深大伤口或有污染时于注射前完成皮试，皮试阳性改TIG（注射前15～20分钟）\n4. 传染病四项筛查（乙肝、丙肝、HIV、梅毒）：拟注射狂犬病免疫球蛋白（血制品）前完成并签署知情同意书\n5. 伤肢X线摄片：深咬伤、疑有骨折或异物残留时检查（伤口处置前完成）\n6. 凝血功能、血糖：伤口深出血多，或合并肝病、糖尿病、长期抗凝治疗者酌情检测","初步诊断":"1. 动物抓咬/舔舐史\n2. 暴露分级评估\n3. 伤口部位（头面颈手部为高风险）\n4. 动物健康状况（是否可疑疯动物、能否观察10天）\n1. 狂犬病暴露处置（ICD-10：A82.9）","鉴别诊断":"1. 诊断要点：动物抓咬/舔舐史\n2. 诊断要点：暴露分级评估\n3. 诊断要点：伤口部位（头面颈手部为高风险）\n4. 诊断要点：动物健康状况（是否可疑疯动物、能否观察10天）\n5. 伤口冲洗是最有效的现场处理，不要跳过\n6. 狂犬病致死率近100%，不要心存侥幸\n7. 免疫球蛋白必患者首针疫苗后7天内使用（超过7天疫苗已开始产生抗体，不再需要）\n8. 伤口不要缝合（面部等特殊部位需缝合时先浸润免疫球蛋白，且不紧密缝合）\n9. 即使被咬已过数天/数月也应接种\n10. 蝙蝠接触即使没看到明显伤口也按III级处理","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（狂犬病疫苗 肌注（5针法）：\n 用法：0/3/7/14/28天；或4针法：0天2针+7/21天各1针）\n\n方案2：\n 用法：狂犬病人免疫球蛋白（HRIG）20IU/kg 浸润注射伤口周围（III级暴露，首针疫苗后7天内使用）\n\n方案3：\n 用法：破伤风抗毒素/免疫球蛋白\n\n方案4：\n 用法：头孢类/阿莫西林克拉维酸钾（抗感染，尤其伤口深/污染重）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：无口服药物可预防狂犬病\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n立即彻底冲洗伤口（最重要！）\n肥皂水+流动清水交替冲洗≥15min\n碘伏/酒精消毒\n伤口一般不缝合、不包扎（保持开放引流）\n狂犬病疫苗接种\nIII级暴露：免疫球蛋白浸润注射\n破伤风预防\n抗感染（必要时）\n\n【处理要点】\n立即用肥皂水（或其他弱碱性清洁剂）和流动清水交替彻底冲洗伤口≥15min（这是最关键的一步！）\n冲洗后用碘伏或75%酒精消毒伤口\n伤口原则上不缝合、不包扎、不涂软膏（便于排血引流）\n评估暴露分级：II级及以上立即接种狂犬病疫苗\nIII级暴露：疫苗+狂犬病人免疫球蛋白（HRIG 20IU/kg），尽可能浸润注射到伤口周围，剩余剂量肌注（远离疫苗接种部位）\n头面部咬伤、严重咬伤、免疫功能低下者按III级处理\n破伤风抗毒素/免疫球蛋白\n抗感染（猫咬伤用阿莫西林克拉维酸覆盖巴斯德菌）\n即使延迟也应接种（发病前接种产生抗体即有效）\n家养动物可观察10天（10天观察法），但暴露后立即开始处置，不要等观察结果\n通知疾控中心/犬伤门诊\n\n【护理】\n伤口冲洗配合：用20%肥皂水与流动清水交替冲洗伤口至少15分钟（压力适中），冲洗后以生理盐水冲净、稀碘伏消毒，指导患者全程配合，防止冲洗液喷溅污染\n伤口处理原则：表浅伤口不缝合、不包扎、保持开放引流；深大伤口、活动性出血或累及神经血管者立即通知外科清创，先止血包扎再转运\n生命体征监测：监测体温、脉搏、呼吸、血压，重点警惕疫苗及免疫球蛋白注射后过敏反应（皮疹、喉头水肿、呼吸困难），床旁备肾上腺素、地塞米松及气管插管抢救设备\n注射配合：狂犬病疫苗于三角肌肌内注射（严格执行0、3、7、14、28天5针法或2-1-1程序），免疫球蛋白按20IU/kg于伤口周围浸润注射，剩余剂量远离疫苗注射部位肌注，两药严禁同部位、同注射器\n健康宣教与心理护理：安抚患者恐惧情绪，详细记录暴露时间、致伤动物种类及暴露方式，交代按时接种、伤口自我观察及随访复查事项\n\n【饮食】\n接种疫苗及免疫球蛋白后1周内忌饮酒，忌浓茶、咖啡等刺激性饮品\n忌辛辣刺激食物（辣椒、生蒜、海鲜等），避免诱发或加重疫苗不良反应\n清淡饮食、保证营养，多饮温开水，适量补充维生素C\n伤口较重者加强优质蛋白摄入（瘦肉、蛋、奶、鱼），促进创面愈合\n忌剧烈运动与过度劳累，保证充足休息，以免影响免疫应答\n\n【注意事项】\n伤口冲洗是最有效的现场处理，不要跳过\n狂犬病致死率近100%，不要心存侥幸\n免疫球蛋白必患者首针疫苗后7天内使用（超过7天疫苗已开始产生抗体，不再需要）\n伤口不要缝合（面部等特殊部位需缝合时先浸润免疫球蛋白，且不紧密缝合）\n即使被咬已过数天/数月也应接种\n蝙蝠接触即使没看到明显伤口也按III级处理\n\n【急诊/急救】\n立即肥皂水+流动清水交替冲洗伤口≥15min（最关键！）\n碘伏/75%酒精消毒，伤口不缝合不包扎\n评估暴露分级：II级→立即接种狂犬疫苗（5针法或4针法）\nIII级（出血咬伤、头面颈手部咬伤、破损皮肤被舔、蝙蝠接触）→疫苗+狂犬病人免疫球蛋白20IU/kg伤口周围浸润注射\n破伤风预防+抗感染（猫咬伤用阿莫西林克拉维酸）\n头面部/严重咬伤按III级处理，立即就医犬伤门诊\n不要因动物看起来正常而不处理（10天观察法不能替代暴露后处置）","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「狂犬病暴露处置」原文）"},"icd10_diagnosis":"A82.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2525,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d0d9f2fe10b9822c8ad31d1f9438e445429bf8a48607b805e740944a7c2ea180","pinyin":"kuangquanbingbaoluchuzhi","initials":"kqbblcz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","A82.9",30]]},{"id":"templates-e608a490dcbbcff43f8e","key":"v1-c9ccc21dfe2a3058|templates-e608a490dcbbcff43f8e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲亢危象","category":"院前急救","raw":{"name":"甲亢危象","category":"院前急救","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】高热（>39℃，大汗）、心动过速（>140次/分，可房颤）、烦躁、谵妄、昏迷、恶心呕吐、腹泻、黄疸、心衰、肺水肿、体重锐减、手抖、突眼加重。\n【待人工确认·本机素材无此段原文】","现病史":"甲亢未控制/未治疗，在感染、手术、创伤等诱因下病情急剧恶化，高热、心动过速、心衰、意识障碍，病死率20%-30%。\n常见表现：高热（>39℃，大汗）、心动过速（>140次/分，可房颤）、烦躁、谵妄、昏迷、恶心呕吐、腹泻、黄疸、心衰、肺水肿、体重锐减、手抖、突眼加重。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征（快速评估ABC）：意识（清醒/呼之能应/无反应）、气道（通畅/梗阻）、呼吸（存在/停止/频率/节律）、脉搏（桡动脉/颈动脉/股动脉，存在/停止）、血压（可测/不可测）、血氧\n一般情况：神志、面色（苍白/发绀/潮红）、体位、有无大汗\n皮肤黏膜：温度/湿度/颜色、出血点/瘀斑、伤口/出血（部位/量/活动性）、烧伤（面积/深度）、发绀\n头颈部：瞳孔（大小/对光反射）、耳鼻出血/脑脊液漏、颈椎损伤（固定）、颈静脉怒张\n胸部：胸廓对称/畸形（连枷胸）、呼吸动度、心尖搏动、心率心律、心音、双肺呼吸音（单侧消失提示气胸/血胸）、皮下气肿\n腹部：膨隆/凹陷、压痛（观察反应）、肌紧张、移动性浊音、外出血\n骨盆：挤压分离试验（骨盆骨折）\n四肢：畸形/肿胀/压痛/反常活动（骨折）、脉搏（桡/足背）、毛细血管充盈、感觉运动（脊髓损伤评估）\n脊柱：轴线对位、压痛（脊髓损伤风险）\n其他：GCS评分、创伤评分、现场环境安全","辅助检查":"1. 甲状腺功能全套（FT3、FT4、TSH）：急查，确诊及评估危象严重程度的核心指标\n2. 动脉血气分析＋血乳酸：判断缺氧、酸中毒及组织灌注，指导补液与氧疗\n3. 电解质＋血糖（钾、钠、氯、钙、镁）：甲亢危象常见低钾、低镁及血糖异常，反复监测及时纠正\n4. 心电图＋床旁心电监护：连续监测心率与心律，尽早识别房颤、室上速等恶性心律失常\n5. 血常规、肝肾功能、心肌损伤标志物（cTnI、BNT/NT-proBNP）：评估感染诱因及心、肝、肾受累程度\n6. 血培养、尿常规、胸片（或CT）：感染为最常见诱因，入院即查并留取标本","初步诊断":"1. 甲亢病史/未规律治疗\n2. 感染/手术/创伤/碘剂诱因\n3. 高热+心动过速与体温不成比例\n4. 中枢神经系统症状\n5. 心衰/消化道症状\n6. FT3/FT4显著升高、TSH降低\n7. Burch-Wartofsky评分≥45分\n1. 甲亢危象（ICD-10：E05.9）","鉴别诊断":"1. 诊断要点：甲亢病史/未规律治疗\n2. 诊断要点：感染/手术/创伤/碘剂诱因\n3. 诊断要点：高热+心动过速与体温不成比例\n4. 诊断要点：中枢神经系统症状\n5. 诊断要点：心衰/消化道症状\n6. 诊断要点：FT3/FT4显著升高、TSH降低\n7. 诊断要点：Burch-Wartofsky评分≥45分\n8. 碘剂必患者PTU之后1h使用（否则为甲状腺提供原料）\n9. 禁用阿司匹林（可使游离甲状腺素升高）\n10. 普萘洛尔心衰/哮喘/严重慢阻肺禁用\n11. 高热+心动过速不成比例是特征\n12. PTU和甲巯咪唑均可，PTU因抑制T4→T3而首选","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：丙硫氧嘧啶（PTU）500-1000mg 首剂口服/胃管，后250mg q4h（抑制甲状腺素合成+T4→T3转化）\n\n方案2：\n 用法：复方碘溶液（Lugol液）5滴 q6h（PTU用后1h给，抑制甲状腺素释放）\n\n方案3：\n 用法：普萘洛尔 1-2mg 静推（或40-80mg口服q6h，控制心率）\n\n方案4：\n 用法：氢化可的松 100mg q6h 静滴（抑制T4→T3、支持肾上腺）\n\n方案5：\n 用法：0.9%氯化钠+葡萄糖 补液\n\n方案6：\n 用法：对乙酰氨基酚 退热（禁用阿司匹林）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1：\n 用法：PTU/甲巯咪唑（首选PTU）\n\n药物2：\n 用法：普萘洛尔\n\n药物3：\n 用法：对乙酰氨基酚退热\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n抑制甲状腺素合成：PTU\n抑制甲状腺素释放：碘剂（PTU后1h）\n抑制外周T4→T3：PTU、普萘洛尔、激素\n控制心率：β受体阻滞剂\n糖皮质激素\n退热、补液、营养支持\n处理诱因（感染）\n血液净化（难治性）\n\n【处理要点】\n立即吸氧、监护、物理降温（冰毯/冰袋，避免阿司匹林）\n建立静脉通路，补液（葡萄糖盐水，每日3000-5000ml）\nPTU 500-1000mg负荷量口服/胃管，后250mg q4h\n1h后复方碘溶液5滴q6h（或碘化钠1g+5%GS静滴）\n普萘洛尔1mg缓慢静推（心衰/哮喘禁用），或口服\n氢化可的松100mg q6h静滴\n对乙酰氨基酚退热，物理降温\n维生素B族、营养支持\n查找并控制诱因（抗感染）\n监测甲功、电解质、血糖、心功能\n心衰者利尿、强心\n上述无效考虑血浆置换/透析\n\n【护理】\n生命体征监测：心电监护连续监测心率、血压、呼吸、血氧，每15~30分钟测体温及神志，记录烦躁程度变化\n高热护理：冰袋、冰毯物理降温，必要时冰盐水灌洗；禁用阿司匹林（竞争TBG致游离激素升高），退热用对乙酰氨基酚并防止寒战\n液体管理：建立双通道静脉通路，快速补液纠正脱水（日量可达3000~5000ml），严密监测出入量与心衰征象，防液体过负荷\n急救配合：按顺序备好并执行抗甲状腺药（PTU）→碘剂→β受体阻滞剂→糖皮质激素，先抗甲状腺药后给碘剂，密切观察心率、血压及药物不良反应\n安全防护：烦躁、谵妄者加床栏并适当约束，防坠床、防自伤，保持环境安静，动作轻柔避免刺激\n\n【饮食】\n危象期（高热、呕吐、神志不清者）暂禁食，经静脉补液维持水电解质平衡，遵医嘱评估后逐步进食\n清醒可进食后予高热量、高蛋白、高维生素流质或半流质（米汤、藕粉、蛋羹、牛奶），少食多餐，每日5~6次\n严格忌碘：禁食海带、紫菜、海鱼虾贝等海产品及含碘调味品，停用一切含碘药物与造影剂\n忌刺激性饮食：浓茶、咖啡、酒精及辛辣食物一律避免，以免加重交感兴奋\n恢复期：补充富含B族维生素与钙、镁的食物，由半流质逐步过渡至软食、普食，并鼓励足量饮水\n\n【注意事项】\n碘剂必患者PTU之后1h使用（否则为甲状腺提供原料）\n禁用阿司匹林（可使游离甲状腺素升高）\n普萘洛尔心衰/哮喘/严重慢阻肺禁用\n高热+心动过速不成比例是特征\nPTU和甲巯咪唑均可，PTU因抑制T4→T3而首选\n\n【急诊/急救】\n吸氧、监护、物理降温（冰袋/冰毯，禁用阿司匹林）\n建立静脉通路，输注葡萄糖盐水3000-5000ml/d\nPTU 500-1000mg口服/胃管注入（首剂负荷），随后250mg q4h\nPTU用后1h：复方碘溶液5滴口服q6h（或碘化钠1g静滴）\n普萘洛尔1mg缓慢静推（哮喘/心衰禁用），或40-80mg口服q6h\n氢化可的松100mg静滴q6h\n对乙酰氨基酚退热，躁动者地西泮\n抗感染（查找诱因），营养支持+维生素B\n监测心功能，心衰者利尿强心\n无效考虑血浆置换/血液灌流","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「甲亢危象」原文）"},"icd10_diagnosis":"E05.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2526,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"f3a548028e905c1d3bad6c9ad33828a0c99ffc58c87d5c0785875ad7583d8584","pinyin":"jiakangweixiang","initials":"jkwx","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E05.9",30]]},{"id":"templates-a84f5b2a9d7e46463f89","key":"v1-c9ccc21dfe2a3058|templates-a84f5b2a9d7e46463f89","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状旁腺功能亢进(外科治疗)","category":"甲状腺乳腺外科","raw":{"name":"甲状旁腺功能亢进(外科治疗)","category":"甲状腺乳腺外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】骨骼系统：骨痛（腰背、四肢）、骨质疏松、病理性骨折、骨囊性变（棕色瘤）、泌尿系统：反复肾结石（肾绞痛、血尿）、多尿、多饮、肾钙化、消化系统：食欲减退、恶心、便秘、腹痛、消化性溃疡、急性胰腺炎、神经精神：乏力、嗜睡、情绪改变、记忆力下降、抑郁、高钙危象（血钙>3.5mmol/L）：恶心呕吐、脱水、意识障碍、心律失常（急症）。\n【待人工确认·本机素材无此段原文】","现病史":"甲状旁腺功能亢进（甲旁亢）分原发性（甲状旁腺腺瘤/增生致PTH分泌过多，血钙升高）、继发性（慢性肾病所致低钙刺激PTH升高）与三发性。原发性甲旁亢表现为高钙血症相关症状（骨痛、肾结石、消化道症状）与骨质疏松，手术切除病变甲状旁腺是唯一根治手段。\n常见表现：骨骼系统：骨痛（腰背、四肢）、骨质疏松、病理性骨折、骨囊性变（棕色瘤）、泌尿系统：反复肾结石（肾绞痛、血尿）、多尿、多饮、肾钙化、消化系统：食欲减退、恶心、便秘、腹痛、消化性溃疡、急性胰腺炎、神经精神：乏力、嗜睡、情绪改变、记忆力下降、抑郁、高钙危象（血钙>3.5mmol/L）：恶心呕吐、脱水、意识障碍、心律失常（急症）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：血压（高血压常见）、心率与心律（高钙致心律失常）、体重\n颈部：有无甲状旁腺区肿块（多不可触及）、甲状腺大小与结节、颈部手术瘢痕\n骨骼：骨痛部位（腰背、四肢）、脊柱后凸与身高变化、病理性骨折、骨囊性变（局部膨隆与压痛）\n泌尿系统：肾区叩击痛（结石）、多尿与脱水征\n神经肌肉：乏力、嗜睡、情绪与认知改变、腱反射、Chvostek征（术后低钙）\n消化系统：腹部压痛（胰腺炎/溃疡）、便秘与腹胀\n眼科与软组织：带状角膜病变（钙沉积）、皮肤钙化（严重者）","辅助检查":"1. 血钙（含离子钙）+血磷+白蛋白（校正血钙）+碱性磷酸酶：诊断与随访核心指标\n2. 甲状旁腺激素（PTH）：升高或不被抑制（原发性），与血钙同步评估\n3. 24小时尿钙+尿磷+肌酐：鉴别FHH、评估结石风险与肾功能\n4. 肾功能（肌酐、肌酐清除率）+电解质（钾、镁）：鉴别继发性甲旁亢与围手术期评估\n5. 维生素D（25-羟维生素D）+1,25-二羟维生素D：评估维生素D缺乏与代谢状态\n6. 颈部超声+99mTc-sestamibi核素显像（±SPECT-CT）：术前定位（首选联合）\n7. 骨密度（DEXA）+肾脏超声/尿路平片：骨质疏松、肾结石与肾钙化评估","初步诊断":"1. 血钙（含离子钙）+血磷+碱性磷酸酶：高钙（>2.75mmol/L）伴低磷、ALP升高提示原发性甲旁亢\n2. 甲状旁腺激素（PTH）：升高或不被抑制（原发性）；继发性者PTH明显升高伴低钙或正常钙（CKD）\n3. 24小时尿钙+尿磷：排除家族性低尿钙性高钙血症（FHH）\n4. 颈部超声：定位增大的甲状旁腺（腺瘤多>1cm），术前定位首选\n5. 核素显像（99mTc-sestamibi 双时相显像/SPECT-CT）：定位腺瘤（尤其异位甲状旁腺），与超声联合提高准确率\n6. 颈部增强CT/MRI：超声与核素定位不一致或复发者\n7. 骨密度（DEXA）+肾脏超声/X线：评估骨质疏松、肾结石与骨囊性变；肾功能+肌酐（鉴别继发性）\n1. 甲状旁腺功能亢进(外科治疗)（ICD-10：E21.0）","鉴别诊断":"1. 24小时尿钙+尿磷：排除家族性低尿钙性高钙血症（FHH）\n2. 肾功能+肌酐（鉴别继发性）\n3. 诊断要点：血钙（含离子钙）+血磷+碱性磷酸酶：高钙（>2.75mmol/L）伴低磷、ALP升高提示原发性甲旁亢\n4. 诊断要点：甲状旁腺激素（PTH）：升高或不被抑制（原发性）；继发性者PTH明显升高伴低钙或正常钙（CKD）\n5. 诊断要点：24小时尿钙+尿磷：排除家族性低尿钙性高钙血症（FHH）\n6. 诊断要点：颈部超声：定位增大的甲状旁腺（腺瘤多>1cm），术前定位首选\n7. 诊断要点：核素显像（99mTc-sestamibi 双时相显像/SPECT-CT）：定位腺瘤（尤其异位甲状旁腺），与超声联合提高准确率\n8. 诊断要点：颈部增强CT/MRI：超声与核素定位不一致或复发者","处理方案":"【药物治疗·输液】\n⚠️ 围手术期与高钙危象处理用药，切勿全部同时使用！\n\n方案1（高钙危象抢救，血钙>3.5mmol/L）：\n 用法：0.9%氯化钠 1000～2000ml 静滴（快速补液扩容，首24小时3～4L）；呋塞米 20～40mg 静推 q6～12h（补液后利尿）；唑来膦酸 4mg + 0.9%氯化钠 100ml 静滴（>15分钟）或 帕米膦酸二钠 60～90mg 静滴（抑制骨吸收）；必要时降钙素 4IU/kg 皮下注射 q12h\n\n方案2（术后低钙，饥饿骨综合征）：\n 用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（>10分钟，必要时重复）；继以 10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（监测血钙与心电图QT间期）\n\n方案3（术前准备与支持）：\n 用法：0.9%氯化钠 静滴（维持充分水化，降低血钙）；维生素D与钙剂按医嘱\n\n方案4（术后补钙与维生素D）：\n 用法：0.9%氯化钠 静滴；葡萄糖酸钙 1g + 维生素C 2g 静滴 qd（必要时）\n\n📌 高钙危象补液是关键（禁用噻嗪类利尿剂，可加重高钙）；术后低钙多在24～72小时出现，需密切监测血钙。\n\n【药物治疗·口服】\n⚠️ 术前术后与长期用药，按医嘱选择：\n\n药物1（术前降钙与骨保护）：\n 用法：碳酸钙 0.6g tid 随餐（继发性甲旁亢降磷用）；西那卡塞 25～50mg qd（继发性/不能手术者，监测血钙）\n\n药物2（术后补钙与维生素D，低钙者）：\n 用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd（按血钙调整，饥饿骨综合征需较大剂量，疗程数周至数月）\n\n药物3（骨质疏松治疗）：\n 用法：阿仑膦酸钠 70mg 每周一次（空腹服后直立30分钟）或 唑来膦酸 5mg 每年一次静滴；碳酸钙D3 600mg qd + 维生素D 800IU/日\n\n药物4（通便与对症）：\n 用法：乳果糖 15ml bid（高钙致便秘）；必要时镇痛\n\n📌 术后低钙可呈'饥饿骨综合征'（持续数周至数月），需按血钙与症状调整补钙剂量并定期复查。\n\n【治疗】\n手术治疗（原发性甲旁亢的根治手段）：单发腺瘤行微创甲状旁腺切除（术中PTH监测，切除后10分钟PTH下降>50%提示成功）；增生者行次全切除或全切+自体移植；甲状旁腺癌行整块切除\n手术指征：有症状者（骨、肾、消化道、神经精神）；无症状但血钙>0.25mmol/L超过正常上限、年龄<50岁、骨密度T值<-2.5、肾结石/肾钙化、24小时尿钙明显升高、肌酐清除率下降\n术前定位：超声+核素显像联合定位，必要时4D-CT或选择性静脉采血（再手术者）\n高钙危象处理：大量补液+利尿+双膦酸盐+降钙素，必要时血液透析（合并肾衰者），监测心电与意识\n术后管理：监测血钙（术后24～72小时每6～12小时）、补钙与维生素D（饥饿骨综合征）、监测PTH与肾功能\n不能手术者：西那卡塞（拟钙剂）控制血钙，监测血钙与肝功能；充分水化与避免高钙饮食\n长期随访：血钙、PTH、肾功能、骨密度（术后1年及此后每1～2年）\n\n【处理要点】\n术前管理：充分水化（鼓励饮水，必要时静脉补液）降低血钙；避免噻嗪类利尿剂、含钙抗酸剂与长期卧床（加重高钙）\n术后血钙监测：术后24～72小时内每6～12小时测血钙，观察口周麻木、手足抽搐（低钙）与Chvostek征\n术后补钙执行：按血钙与症状调整静脉/口服补钙与骨化三醇剂量，记录剂量与反应\n颈部术后观察：颈部肿胀、呼吸、声音与引流（同甲状腺术后护理，警惕血肿压迫气道）\n肾脏与骨骼随访：术后评估肾结石与骨密度变化，指导长期钙与维生素D摄入\n宣教：遵医嘱补钙与复查（不可自行停药）、充分饮水（防结石）、避免长期卧床与高钙饮食（不能手术者）\n\n【护理】\n术前护理：鼓励充分饮水（每日2000～3000ml）降低血钙；避免含钙抗酸剂与噻嗪类利尿剂；评估高钙症状\n术后血钙监测与观察：术后24～72小时每6～12小时测血钙，观察口周麻木、手足抽搐与Chvostek征，异常立即报告\n补钙护理：按医嘱给予静脉/口服钙剂与骨化三醇，记录剂量与反应（葡萄糖酸钙静推速度需缓慢并监测心电图）\n颈部术后护理：观察颈部肿胀、呼吸、声音与引流液，床旁备气管切开包（同甲状腺术后）\n骨骼与肾脏护理：评估骨痛与活动能力，指导防跌倒（骨质疏松）、充分饮水与低钙饮食宣教\n出院宣教：坚持补钙与维生素D（不可自行停药）、定期复查血钙与PTH、出现麻木抽搐立即就诊\n\n【饮食】\n术前：充分饮水（每日2000～3000ml）稀释尿钙、预防结石；避免高钙食物（大量牛奶、钙片）与含钙抗酸剂\n避免长期卧床（加重骨钙流失与高钙），鼓励适度活动\n术后：高钙饮食（牛奶、豆制品、小鱼虾）配合钙剂与维生素D补充（饥饿骨综合征期需求增加）\n限制钠盐（减少尿钙排泄）与咖啡因、酒精\n肾结石患者：充足饮水、低草酸饮食（避免菠菜、坚果、巧克力）、适量钙摄入（不过度限制）\n\n【注意事项】\n原发性甲旁亢常为'偶然发现'（体检血钙升高），典型表现为'骨痛、肾结石、消化道症状与神经精神改变'\n高钙危象（血钙>3.5mmol/L）是急症：补液为首要措施，禁用噻嗪类利尿剂\n术后低钙（饥饿骨综合征）常见且可持续数周至数月，需充分补钙与活性维生素D并密切监测\n术中PTH监测（切除后10分钟下降>50%）可提高手术成功率、减少不必要的双侧探查\n继发性甲旁亢（CKD）以药物治疗为主（磷结合剂、活性维生素D、西那卡塞），手术仅用于难治性病例\n\n【急诊/急救】\n血钙>3.5mmol/L伴恶心呕吐、脱水、意识障碍或心律失常（高钙危象）→ 立即大量补液+利尿+双膦酸盐，必要时透析\n术后手足抽搐、喉痉挛（重度低钙）→ 立即缓慢静推葡萄糖酸钙并心电监护\n术后颈部迅速肿胀伴呼吸困难（血肿压迫气道）→ 立即床旁拆线清除血肿，必要时气管切开\n肾绞痛伴少尿（肾结石梗阻）→ 急诊评估并解除梗阻","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「甲状旁腺功能亢进（外科治疗）」原文）"},"icd10_diagnosis":"E21.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2527,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"d5258367de5d5b59a8341730c4947a4a3d5839ca1536e2720d774043e31bfada","pinyin":"jiazhuangpangxiangongnengkangjin(waikezhiliao)","initials":"jzpxgnkj(wkzl)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","E21.0",30]]},{"id":"templates-2fc93befb066e658cad9","key":"v1-c9ccc21dfe2a3058|templates-2fc93befb066e658cad9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺术后并发症处理","category":"甲状腺乳腺外科","raw":{"name":"甲状腺术后并发症处理","category":"甲状腺乳腺外科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】颈部肿胀、切口渗血、引流血量增多（术后出血）、呼吸困难、发绀、颈部紧迫感（血肿压迫气管，危急）、声音嘶哑、饮水呛咳（喉返神经/喉上神经损伤）、口周及手足麻木、手足抽搐（甲状旁腺损伤致低钙）、高热、心率>120次/分、烦躁（甲状腺危象）。\n【待人工确认·本机素材无此段原文】","现病史":"甲状腺手术后常见并发症包括术后出血（可致窒息）、喉返神经与喉上神经损伤、甲状旁腺功能减退（低钙）、甲状腺危象、切口感染等。术后48小时内以出血与呼吸困难最危险，需重点观察。\n常见表现：颈部肿胀、切口渗血、引流血量增多（术后出血）、呼吸困难、发绀、颈部紧迫感（血肿压迫气管，危急）、声音嘶哑、饮水呛咳（喉返神经/喉上神经损伤）、口周及手足麻木、手足抽搐（甲状旁腺损伤致低钙）、高热、心率>120次/分、烦躁（甲状腺危象）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压、血氧（重点：呼吸与颈部情况）\n颈部：切口有无渗血渗液、颈部肿胀程度、有无皮下瘀斑与波动感\n呼吸道：呼吸频率与深度、有无喘鸣、三凹征、声音嘶哑程度\n神经系统：面部与口周感觉、Chvostek征与Trousseau征（低钙）、声带功能\n引流管：位置、引流量与性状、是否通畅\n一般情况：精神状态（烦躁提示危象或缺氧）、皮肤温度与湿度\n心脏：心率、心律（低钙可致QT延长、心律失常）","辅助检查":"1. 血钙+血磷+白蛋白+镁：术后1～2天必查，低钙者每日复查至稳定\n2. 甲状旁腺激素（PTH）：评估甲状旁腺损伤程度与恢复可能\n3. 甲状腺功能（FT3、FT4、TSH）：术后评估甲状腺功能与替代治疗剂量\n4. 血常规+CRP：评估出血、感染情况\n5. 血气分析+血氧饱和度：呼吸困难者评估缺氧与二氧化碳蓄积\n6. 凝血功能：术后出血者评估凝血状态\n7. 心电图（必要时）：低钙时监测QT间期延长；危象时监测心律失常","初步诊断":"1. 术后监测：生命体征、颈部肿胀、引流量（每1～2小时观察，术后6～12小时最关键）\n2. 血钙+血磷+白蛋白：术后1～2天查，低钙者每日复查\n3. 血甲状旁腺激素（PTH）：评估甲状旁腺功能\n4. 甲状腺功能（FT3/FT4/TSH）：评估术后甲状腺功能状态\n5. 血气分析+血氧：呼吸困难者评估缺氧程度\n6. 颈部超声/床旁检查：评估血肿范围与气道受压\n7. 间接喉镜/纤维喉镜：评估声带运动（声音嘶哑者）\n1. 甲状腺术后并发症处理（ICD-10：T81.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 按并发症选择方案，切勿全部同时使用！\n\n方案1（低钙抽搐）：\n 用法：10%葡萄糖酸钙 10～20ml + 5%葡萄糖 20ml 缓慢静推（10min以上），必要时重复；继以10%葡萄糖酸钙 30～60ml + 0.9%氯化钠 500ml 静滴维持（监测血钙、心电图QT间期）\n\n方案2（甲状腺危象）：\n 用法：丙硫氧嘧啶 600mg 鼻饲/口服后 200mg q8h + 碘剂（服PTU后1小时给复方碘溶液）+ 普萘洛尔 20～40mg q6h + 氢化可的松 100mg 静滴 q8h\n\n方案3（止血/支持）：\n 用法：氨甲环酸 0.5g 静滴（必要时）；维生素C、补液支持；必要时输血\n\n📌 葡萄糖酸钙静推速度必须缓慢（<2ml/min），防止心脏抑制；监测心电图与血钙。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：同类药物选一种，切勿重复用药！\n\n药物1（补钙，低钙者长期）：\n 用法：碳酸钙D3 600mg bid～tid + 骨化三醇 0.25～0.5μg qd（血钙正常后可逐渐减停）\n\n药物2（甲状腺功能替代/抑制）：\n 用法：左甲状腺素钠 25～50μg qd 起（术后甲减，晨起空腹服）或 根据TSH调整\n\n药物3（镇痛）：\n 用法：对乙酰氨基酚 0.5g 必要时 或 洛索洛芬钠 60mg tid（餐后）\n\n📌 左甲状腺素需空腹服用，与钙剂间隔4小时以上；补钙方案需按血钙动态调整。\n\n【治疗】\n术后出血：颈部肿胀、呼吸困难立即床旁打开切口清除血肿，必要时急诊气管插管/气管切开+手术探查止血\n喉返神经损伤：多为暂时性，予神经营养药（甲钴胺、维生素B1）、理疗，观察3～6个月；双侧损伤致呼吸困难需气管切开\n低钙抽搐：静脉补钙（葡萄糖酸钙）+ 口服钙剂与骨化三醇，监测血钙至稳定\n甲状腺危象：禁食、物理降温、PTU、碘剂、β受体阻滞剂、糖皮质激素、补液与支持治疗\n喉上神经损伤：进水呛咳者改为固体食物+小口饮水，多数可代偿恢复\n切口感染/积液：换药、必要时引流+抗生素\n\n【处理要点】\n术后体位：取半卧位，利于呼吸与引流；颈部勿过度活动\n引流观察：记录引流液量与性状，术后24小时引流量<50ml可考虑拔管\n呼吸道管理：床旁备气管切开包、吸引器；观察有无呼吸困难、喘鸣、颈部肿胀\n声音评估：每日评估声音变化并记录，声嘶者避免长时间说话\n血钙监测与宣教：告知低钙症状（口周麻木、手足抽搐），出现时立即报告\n术后随访：术后1个月复查甲功、血钙，评估是否需要激素替代治疗\n\n【护理】\n重点观察：术后6～12小时内每30～60分钟观察颈部肿胀、呼吸、引流量与声音变化\n体位护理：血压平稳后取半卧位，头颈部制动，避免剧烈咳嗽与颈部过伸\n急救准备：床旁备气管切开包、吸引器、氧气、葡萄糖酸钙，随时配合抢救\n低钙观察：询问口周麻木、手足麻刺感，观察Chvostek征，出现抽搐立即报告并备钙剂\n引流管护理：妥善固定，记录引流量与性状，防止脱出与逆行感染\n\n【饮食】\n术后6小时可进温凉流质（避免过热引起切口渗血）\n逐步过渡到半流质、软食，1～2天内恢复正常饮食\n高蛋白、高维生素饮食促进切口愈合\n低钙者增加含钙食物（牛奶、豆制品、虾皮），并按医嘱服钙剂与维生素D\n呛咳者进食固体食物、小口慢咽，避免稀薄液体呛入气道\n\n【注意事项】\n术后48小时内最危险的并发症是出血致气道压迫，必须床旁观察，随时准备打开切口\n暂时性甲状旁腺功能减退多在数周内恢复，永久性者需终身补钙与维生素D\n喉返神经损伤多为暂时性（术后3～6个月恢复），双侧损伤须警惕窒息\n甲状腺危象多发生于术前准备不充分的甲亢患者，重在预防（术前控制甲功、服碘）\n\n【急诊/急救】\n术后颈部迅速肿胀、呼吸困难、喘鸣、发绀 → 立即床旁拆线清除血肿，必要时气管插管/切开\n手足抽搐伴喉痉挛、意识改变（重度低钙）→ 立即静脉缓慢推注葡萄糖酸钙\n高热>39℃、心率>140次/分、烦躁谵妄（甲状腺危象）→ 立即按危象抢救","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T81.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2528,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"81bc7d75f7c72de04d81c5783a6ccbca0e6014950906f0647f025ba5e3c9cb17","pinyin":"jiazhuangxianshuhoubingfazhengchuli","initials":"jzxshbfzcl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T81.0",30]]},{"id":"templates-18292bea014b3d9cb4f9","key":"v1-c9ccc21dfe2a3058|templates-18292bea014b3d9cb4f9","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状腺良性肿瘤","category":"普通外科临床路径（2019年版）","raw":{"name":"甲状腺良性肿瘤","category":"普通外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【待人工确认·本机素材无此段原文】","现病史":"【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\r（1）血常规、尿常规、大便常规；\r（2）肝功能、肾功能、电解质、血糖、凝血功能、感染性疾病筛查（乙型肝炎、丙型肝炎、艾滋病、梅毒等）和甲状旁腺素检查；\r（3）心电图、胸部X线检查；\r（4）甲状腺功能检查、抗甲状腺抗体、甲状腺球蛋白、血清降钙素，甲状腺及颈部淋巴结超声、颈部CT检查（平扫或者增强）；\r（5）请耳鼻喉科会诊了解声带情况。\r2.根据患者病情可选择：\r（1）肺功能、超声心动图检查和血气分析等；\r（2）甲状腺同位素扫描(考虑高功能腺瘤时)。\r（3）对于困难和双侧手术术中可选择使用：\n纳米碳\n（保护甲状旁腺）、\n神经监测\n（保护喉返神经）。\r（七）预防性抗菌药物选择与使用时机\r按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行。通常不需预防用抗菌药物。\r（八）手术日为入院第3～4天\r1.麻醉方式：气管内插管全身麻醉、局部麻醉或颈丛麻醉。\r2.手术方式：根据甲状腺肿物大小及其部位、性质选择甲状腺部分切除、甲状腺次全切除或甲状腺近全切除术。\r3.术中用药：麻醉常规用药。\r4.输血：根据术前血红蛋白状况及术中出血情况而定。 \r5.病理学检查：术中行冰冻病理学检查，术后行石蜡切片病理学检查。\r（九）术后住院恢复2～5天\r1.生命体征监测，严密观察有无出血等并发症发生。\r2.根据病情，按照《国家基本药物》目录选择使用喷喉、止血药、补液等治疗，时间1～2 天（视具体情况而定）。\r3.根据病情，尽早拔除尿管、引流管。\r4.实验室检查：必要时复查血常规、血生化等，可选择甲状旁腺素检查和血钙检查。\r（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\r根据《临床诊疗指南\n普通外科分册》（中华医学会编著，人民卫生出版社，2006年，第1版），《甲状腺外科》（陈国锐主编，人民卫生出版社，第1版）及全国高等学校教材《外科学》（吴在德，吴肇汉主编，人民卫生出版社，第7版）。\r1.发现颈前区肿物，无或伴有甲状腺功能亢进临床表现。\r2.体检提示颈前区肿块，随吞咽而上下活动。\r3.颈部超声提示甲状腺良性肿瘤。\r4.甲状腺功能正常或有甲状腺功能亢进表现。\r（三）\n1. 甲状腺良性肿瘤（ICD-10：D34）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\r根据《临床诊疗指南\n普通外科分册》（中华医学会编著，人民卫生出版社，2006年，第1版），《甲状腺外科》（陈国锐主编，人民卫生出版社，第1版）及全国高等学校教材《外科学》（吴在德，吴肇汉主编，人民卫生出版社，第7版）。\r手术方式选择应保证甲状腺肿物连同周边少量正常组织一并切除（视术中情况可选择甲状腺部分切除、甲状腺次全切除或甲状腺近全切除术），术中应行标本冰冻检查以除外恶变。\r（四）临床路径","临床路径·进入路径标准":"进入路径标准\r1.第一诊断必须符合甲状腺良性肿瘤（ICD-10：D34），结节性甲状腺肿（ICD-10：E04）编码。\r2.当患者合并其他疾病，但住院期间不需要特殊处理也不影响第一诊断的临床路径流程实施时，可以进入路径。\r（六）术前准备1～2天\r 1.","临床路径·标准住院日":"标准住院日为6～9天\r（五）","临床路径·出院标准":"出院标准\r1.无切口感染。\r2.生命体征平稳，可自由活动。\r3.饮食恢复，无需静脉补液。\r4.无需要住院处理的其他并发症或合并症。\r（十一）","临床路径·变异及原因分析":"变异及原因分析\r1.术中冰冻提示甲状腺炎或甲状腺癌等转入相应路径。\r2.胸骨后巨大甲状腺肿有可能需要开胸手术。\r3.合并甲状腺功能亢进症的甲状腺良性肿瘤转入相应路径。\r4.术后出现并发症需要进行相关的诊断和治疗。\r\r\r\r\r\r\r\r\r二、甲状腺良性肿瘤","资料来源":"国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 普通外科临床路径（2019年版） · 甲状腺良性肿瘤临床路径（2019年版）.doc"},"icd10_diagnosis":"D34","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2529,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"942690004f5709fc8ce53ea8174a2aebf7402316e94c296cefa64eaaca257a90","pinyin":"jiazhuangxianliangxingzhongliu","initials":"jzxlxzl","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","D34",30]]},{"id":"templates-3df3488a4153cd08b59b","key":"v1-c9ccc21dfe2a3058|templates-3df3488a4153cd08b59b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲状舌管囊肿或鳃源性囊肿","category":"小儿外科临床路径（2019年版）","raw":{"name":"甲状舌管囊肿或鳃源性囊肿","category":"小儿外科临床路径（2019年版）","case":{"case_name":"门诊病历","templates":{"主诉":"【卫健委临床路径原文】颈中线或侧部囊性肿块；如囊肿继发感染可自发破溃或被切开引流，可反复发作，形成瘘管。。\n【待人工确认·本机素材无此段原文】","现病史":"常见表现：颈中线或侧部囊性肿块；如囊肿继发感染可自发破溃或被切开引流，可反复发作，形成瘘管。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"【待人工确认·本机素材无此段原文】","辅助检查":"【临床路径·住院期间检查项目】\n必需的检查项目：\n1.实验室检查：血常规、C反应蛋白（必要时）、血型、尿常规、肝肾功能、电解质、凝血功能、感染性疾病筛查；\n2.影像学检查：超声、X线胸片(正位)、心电图。\n（七）预防性抗菌药物选择与使用时机\n1.按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号），并结合患儿病情决定选择。\n2.推荐药物治疗方案（使用《国家基本药物》的药物）。\n3.预防性用药时间为1天，术前因感染已患者抗菌药物或术中发现有明显炎症者不在此列。\n（八）手术日为入院第2～3天\n1.麻醉方式：气管插管全身麻醉。\n2.预防性抗菌药物的给药方法：半合成青霉素、一代或二代头孢抗菌药静脉输入，切开皮肤前30分钟开始给药，手术延长到3小时以上时补充一个剂量。\n3.手术方式：甲状舌管囊肿切除术或鳃源性囊肿切除术。\n4.手术内置物：切口皮片引流（必要时）。\n（九）术后住院恢复2～5天\n1.根据当时患儿情况而定：血常规。\n2.术后抗菌药物：用于术中发现局部有炎症者，按照《抗菌药物临床患者指导原则》（卫医发〔2015〕43号）执行，用药时间一般为3～5天。\n（十）","初步诊断":"【临床路径·诊断依据】\n诊断依据\n根据《张金哲小儿外科学》（张金哲主编，人民卫生出版社，2013年）,《临床诊疗指南\n小儿外科学分册》（中华医学会编著，人民卫生出版社，2005年）,《临床技术操作规范\n小儿外科学分册》（中华医学会编著，人民军医出版社，2005年）,《小儿外科学》（施诚仁等主编，人民卫生出版社，2010年）。\n1.临床表现：颈中线或侧部囊性肿块；如囊肿继发感染可自发破溃或被切开引流，可反复发作，形成瘘管。\n2.体格检查：为圆形囊性肿块，边缘清楚，光滑，较固定，无压痛，可有大小变化；如形成瘘管则在颈中线或侧部见瘘管开口，时有分泌物或脓液溢出。\n3.辅助检查：超声、CT（必要时），了解肿块与甲状腺的关系。\n4.当肿块不能与甲状腺特别是异位甲状腺鉴别时，应当进行甲状腺核素扫描和T3、T4等检查。\n（三）\n1. 甲状舌管囊肿或鳃源性囊肿（ICD-10：Q89.202）","鉴别诊断":"1. 4.当肿块不能与甲状腺特别是异位甲状腺鉴别时，应当进行甲状腺核素扫描和T3、T4等检查","处理方案":"【临床路径·治疗方案的选择】\n选择治疗方案的依据\n根据《张金哲小儿外科学》（张金哲主编，人民卫生出版社，2013年）,《临床诊疗指南\n小儿外科学分册》（中华医学会编著，人民卫生出版社，2005年）,《临床技术操作规范\n小儿外科学分册》（中华医学会编著，人民军医出版社，2005年）,《小儿外科学》（施诚仁等主编，人民卫生出版社，2010年）。\n行甲状舌管囊肿切除术（ICD-9-CM-3：06.7）或鳃源性囊肿切除术(ICD-9-CM-3：29.2）。\n（四）","临床路径·进入路径标准":"进入路径标准\n1.第一诊断必须符合ICD-10：Q89.202甲状舌管囊肿疾病编码或ICD-10：Q18.0鳃源性囊肿疾病编码。\n2.当患儿合并其他疾病，但住院期间不需特殊处理，也不影响第一诊断的临床路径实施时，可以进入路径。\n3.如囊肿或瘘存在明显感染，不进入路径，需抗菌药物控制感染后2～3个月后再行手术。\n（六）术前准备（术前评估）1～2天","临床路径·标准住院日":"标准住院日为5～7天\n（五）","临床路径·出院标准":"出院标准\n1.一般情况良好。\n2.伤口愈合良好，无出血、感染或瘘。\n3.无其他需要住院处理的并发症。\n（十一）","临床路径·变异及原因分析":"变异及原因分析\n1.围术期并发症等造成住院日延长和费用增加。\n2.术后切口感染、瘘复发等并发症，进入其他路径。","资料来源":"鉴别诊断库 ddx_local.json（条目「甲状舌管囊肿或鳃源性囊肿」原文）；国家卫健委《224个病种临床路径（2019年版）》（国卫办医函〔2019〕933号）· 小儿外科临床路径（2019年版） · 甲状舌管囊肿或鳃源性囊肿临床路径（2019年版）.docx"},"icd10_diagnosis":"Q89.202","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2530,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"eb9b5909a8856b348f10d8845843d6b0f31d3100408c903d98c02ef5276b964e","pinyin":"jiazhuangsheguannangzhonghuosaiyuanxingnangzhong","initials":"jzsgnzhsyxnz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","临床路径·进入路径标准","临床路径·标准住院日","临床路径·出院标准","临床路径·变异及原因分析","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 临床路径·进入路径标准 临床路径·标准住院日 临床路径·出院标准 临床路径·变异及原因分析 资料来源",30],["主要诊断编码","Q89.202",30]]},{"id":"templates-06eea98f55c850cfcd15","key":"v1-c9ccc21dfe2a3058|templates-06eea98f55c850cfcd15","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"甲醇中毒","category":"中毒/理化","raw":{"name":"甲醇中毒","category":"中毒/理化","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】潜伏期：12-24小时（最长可达2-3天）、中枢神经系统：头痛、头晕、乏力、嗜睡、昏迷、眼部：视力模糊、畏光、眼痛、复视、视力骤降甚至失明、消化系统：恶心呕吐、腹痛、代谢性酸中毒：呼吸深快（Kussmaul呼吸）、严重者：昏迷、抽搐、呼吸循环衰竭。\n【待人工确认·本机素材无此段原文】","现病史":"甲醇（工业酒精、假酒）中毒，代谢为甲醛和甲酸，致代谢性酸中毒和视神经损害\n常见表现：潜伏期：12-24小时（最长可达2-3天）、中枢神经系统：头痛、头晕、乏力、嗜睡、昏迷、眼部：视力模糊、畏光、眼痛、复视、视力骤降甚至失明、消化系统：恶心呕吐、腹痛、代谢性酸中毒：呼吸深快（Kussmaul呼吸）、严重者：昏迷、抽搐、呼吸循环衰竭。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（高热/低体温）、脉搏（过速/过缓/心律失常）、呼吸（频率/节律/气味）、血压（升高/降低/休克）、血氧饱和度\n一般情况：神志（清醒/嗜睡/昏睡/昏迷/谵妄/抽搐）、精神状态、面容、体位\n皮肤黏膜：颜色（潮红-阿托品/酒精/一氧化碳樱桃红/发绀-亚硝酸盐/肠源性青紫/苍白-休克/出血）、湿度（多汗-有机磷/吗啡/干燥-阿托品/抗组胺）、皮疹/水疱/灼伤（腐蚀性毒物）、黄疸（毒蕈/对乙酰氨基酚/鱼胆）、发绀、出血点\n呼出气/呕吐物气味：蒜臭味（有机磷）、苦杏仁味（氰化物）、酒味（酒精）、酚味（苯酚）、臭鸡蛋味（硫化氢）、梨味（水合氯醛）\n头颈部：瞳孔（缩小-有机磷/吗啡/针尖样-阿片类/扩大-阿托品/抗组胺/氰化物、对光反射）、眼球震颤、口腔黏膜灼伤/溃疡、流涎（有机磷）、口干（阿托品）\n胸部：呼吸节律（抑制-镇静催眠药/吗啡/兴奋-咖啡因/回苏灵）、肺水肿（有机磷/刺激性气体）、双肺啰音/哮鸣音、心率心律/心音/杂音\n腹部：压痛/反跳痛、肝脾肿大、肠鸣音（亢进-有机磷/减弱-阿托品/抗胆碱）、呕吐物性状\n神经系统：意识状态、抽搐（有机磷/毒鼠强/氰化物/异烟肼）、肌力肌张力、病理征、脑膜刺激征、震颤（有机磷/酒精戒断）\n四肢：肌束颤动（有机磷）、瘫痪（肉毒/河豚/蛇毒）、水肿\n其他：呕吐物/洗胃液/尿液性状、现场毒物残留","辅助检查":"1. 血甲醇浓度及血清甲酸浓度测定（入院即刻采血送检，动态复查；用于确诊、评估中毒程度及决定解毒剂疗程与血液透析指征）\n2. 动脉血气分析（重点观察代谢性酸中毒程度、阴离子间隙及乳酸；治疗期间每2-4小时复查，评估碳酸氢钠纠酸效果）\n3. 血浆渗透压及渗透压间隙测定（计算渗透压间隙估算甲醇浓度，辅助早期快速诊断）\n4. 血电解质、血糖及血乳酸（动态监测血钾，防纠酸过程中低钾血症；评估代谢紊乱）\n5. 肝肾功能、血常规及凝血功能（评估甲醇所致肝肾损伤，为血液透析及支持治疗提供依据）\n6. 心电图及眼科检查（心电图排除心律失常；眼底、视力、瞳孔及视野检查评估视神经损伤，必要时头颅CT/MRI排除脑水肿）","初步诊断":"1. 饮用假酒/工业酒精/甲醇接触史\n2. 代谢性酸中毒（高AG型）\n3. 血甲醇浓度>6.25mmol/L（20mg/dl）\n4. 眼底检查：视乳头充血、水肿，视网膜水肿\n5. 血渗透压间隙升高\n1. 甲醇中毒（ICD-10：T51.1）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（【特效解毒一】乙醇）：\n 用法：10%乙醇500ml ivgtt，维持血乙醇浓度21.7-32.6mmol/L（100-150mg/dl）\n\n方案2：\n 用法：【特效解毒二（推荐）】甲吡唑（4-MP）：负荷量15mg/kg ivgtt（30分钟）→ 10mg/kg q12h × 4次 → 15mg/kg q12h\n\n方案3：\n 用法：5%碳酸氢钠250ml ivgtt（纠正酸中毒，根据血气调整）\n\n方案4（血液透析（指征）：\n 用法：血甲醇>15.6mmol/L、严重酸中毒、视力损害、肾衰竭）\n\n方案5：\n 用法：叶酸50mg iv q4h（促进甲酸代谢为CO2）\n\n方案6：\n 用法：维生素B1 100mg im qd\n\n方案7：\n 用法：甘露醇125ml ivgtt（防治脑水肿和视神经水肿）\n\n方案8：\n 用法：洗胃（服药1小时内），活性炭口服\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（乙醇口服（无静脉制剂时））：\n 用法：白酒稀释至5%，首剂0.8ml/kg，随后0.1ml/kg/h维持\n\n药物2：\n 用法：叶酸口服\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n特效解毒：甲吡唑（首选）或乙醇（竞争性抑制醇脱氢酶）\n纠正代谢性酸中毒：碳酸氢钠\n血液透析（清除甲醇和甲酸）\n营养支持：叶酸、维生素B1、B6\n对症支持：防治脑水肿、视神经损害、呼吸循环衰竭\n\n【处理要点】\n监测血气分析、血甲醇浓度、血乳酸\n监测视力、眼底\n监测意识、生命体征\n记录出入量\n避光（减少视神经损害）\n\n【护理】\n洗胃配合：口服中毒2小时内或大量摄入者配合洗胃，取左侧卧位、头偏向一侧防误吸；昏迷者先气管插管再行洗胃，洗胃后妥善固定胃管\n解毒剂观察：遵医嘱予乙醇或甲吡唑（4-甲基吡唑）静脉泵入，密切观察意识、呼吸、共济失调等不良反应，防止乙醇过量致中枢抑制及低血糖\n生命体征与视力监测：持续心电监护，定时评估意识、瞳孔、呼吸，主动询问并记录视力变化（视物模糊、视野缺损），早期发现视神经损伤\n纠酸补液护理：遵医嘱静脉碳酸氢钠纠正酸中毒，保持静脉通路通畅、防止药液外渗，动态复查血气与血钾，预防低钾及高钠\n并发症预防：观察有无脑水肿、抽搐、心力衰竭表现；昏迷及长期卧床者加强口腔、皮肤护理，防误吸、压疮及深静脉血栓\n\n【饮食】\n洗胃后暂禁食4-6小时，禁食期间遵医嘱静脉补液维持水电解质平衡，观察有无恶心、呕吐及胃出血\n恢复进食后先予温凉流质（米汤、藕粉、稀粥），少量多餐，逐渐观察胃肠耐受情况\n忌辛辣刺激、过酸过甜、油炸及生冷食物，避免浓茶、咖啡刺激胃黏膜，加重胃肠道症状\n禁食含乙醇食物（酒类、酒酿、醪糟等），避免干扰乙醇/甲吡唑解毒剂疗效判断及加重肝脏负担\n病情稳定后过渡至半流质、软食，适量补充B族维生素（维生素B1、叶酸）及新鲜果蔬，促进视神经修复\n\n【注意事项】\n甲醇代谢缓慢，中毒症状延迟出现，即使早期无症状也应密切观察\n甲吡唑是首选解毒剂，副作用比乙醇小\n乙醇治疗期间需监测血乙醇浓度，避免低血糖\n视力损害可能不可逆，早期治疗关键\n假酒中毒常群体发病，注意排查同饮者\n\n【急诊/急救】\n【第一步】评估生命体征、意识、视力，建立静脉通路\n【第二步】保持呼吸道通畅，吸氧，必要时气管插管\n【第三步】清除毒物：服药1小时内洗胃，活性炭50-100g口服\n【第四步】立即查血气、血甲醇、血乳酸、电解质、血糖、肝肾功能\n【第五步】特效解毒（立即！不要等结果）：\n甲吡唑：15mg/kg ivgtt（30分钟）→ 10mg/kg q12h\n或乙醇：10%乙醇500ml ivgtt，维持血浓度100-150mg/dl\n【第六步】纠正酸中毒：5%碳酸氢钠250ml ivgtt，根据血气调整，目标pH>7.3\n【第七步】血液透析（指征：血甲醇>15.6mmol/L、严重酸中毒pH<7.25、视力损害、肾衰竭）\n【第八步】叶酸50mg iv q4h，维生素B1 100mg im qd，促进甲酸代谢\n【第九步】防治脑水肿和视神经水肿：甘露醇125ml ivgtt q6-8h，地塞米松10mg iv qd\n【第十步】监测：血气每2-4小时，血甲醇每4-6小时，视力眼底每日，生命体征\n【注意】潜伏期长需密切观察；甲吡唑首选；乙醇注意低血糖；视力损害可能不可逆","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T51.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2531,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0b719602a748ee219d33121acda8c6182f845fb7ace601193e0dcc546b49742b","pinyin":"jiachunzhongdu","initials":"jczd","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T51.1",30]]},{"id":"templates-5958de9bf6db95bac8a3","key":"v1-c9ccc21dfe2a3058|templates-5958de9bf6db95bac8a3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"电烧伤","category":"烧伤整形科","raw":{"name":"电烧伤","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】局部：入口/出口创面（入口多在上肢，出口在下肢/接地部位），创面中心炭化、周围红肿；深部组织损伤：肢体肿胀、麻木、运动障碍、脉搏减弱/消失（血管栓塞）；全身：触电后意识丧失、抽搐、心律失常（室颤）、呼吸心跳骤停（高压电）；肌红蛋白尿：尿色呈酱油色；筋膜间隙综合征：肢体进行性肿胀、剧痛、被动牵拉痛、感觉异常。。\n【待人工确认·本机素材无此段原文】","现病史":"电流通过人体引起的损伤，包括入口/出口的局部烧伤和电流路径上深部组织（肌肉、神经、血管、骨骼）的广泛损伤。特点：\"口小底大\"（体表创面小、深部损伤重）、进行性血管栓塞、肌红蛋白尿/急性肾衰、心律失常、猝死。分为电弧烧伤（体表）和接触电烧伤（深部）。\n常见表现：局部：入口/出口创面（入口多在上肢，出口在下肢/接地部位），创面中心炭化、周围红肿；深部组织损伤：肢体肿胀、麻木、运动障碍、脉搏减弱/消失（血管栓塞）；全身：触电后意识丧失、抽搐、心律失常（室颤）、呼吸心跳骤停（高压电）；肌红蛋白尿：尿色呈酱油色；筋膜间隙综合征：肢体进行性肿胀、剧痛、被动牵拉痛、感觉异常。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"详细询问电压（低压<1000V/高压>1000V）、电流类型（交流/直流）、接触时间、触电后是否坠落；检查入口/出口创面；肢体评估：肿胀、皮温、颜色、感觉、运动、远端动脉搏动（桡动脉/足背动脉）；神经系统：意识、瞳孔、肢体活动；心脏：心率、心律、心音。","辅助检查":"血常规、肌酸激酶(CK)（显著升高提示肌肉坏死）、肌红蛋白、电解质（高钾血症-组织坏死释放）、肝肾功能、凝血功能、血气分析、心电图（心律失常、心肌损伤）、尿常规（肌红蛋白尿）、肢体CTA/血管造影（评估血管损伤）、筋膜间隙压力测定（怀疑筋膜间隙综合征）、心肌酶谱。","初步诊断":"明确触电史 + 入口/出口创面 + 深部组织损伤体征。注意：体表创面大小不能反映深部损伤程度，\"口小底大\"是电烧伤特点。\n1. 电烧伤（ICD-10：T31）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n【补液】电烧伤深部渗出多，补液量需比热力烧伤公式多（可增加50-100%），维持尿量>1.5-2ml/kg/h（冲刷肌红蛋白）；【碱化尿液】5%碳酸氢钠100-250ml ivgtt，维持尿pH>6.5（防止肌红蛋白在肾小管沉积）；【利尿】甘露醇125ml ivgtt q4-6h（维持尿量，保护肾功能）；【抗感染】广谱抗生素（哌拉西林他唑巴坦+甲硝唑，覆盖厌氧菌）；【抗凝】低分子肝素（预防血管栓塞）。\n\n【药物治疗·口服】\n止痛（重度疼痛用阿片类）；抗感染口服序贯；营养支持。\n\n【治疗】\n【急救】切断电源（不可直接接触患者）、心肺复苏（呼吸心跳骤停时）、检查心律。【筋膜切开减压】肢体肿胀、筋膜间隙综合征时立即行筋膜切开术（沿肢体长轴切开深筋膜，不要等待），这是挽救肢体的关键。【清创】电烧伤坏死组织界限不清，需多次清创（\"蚕蚀（蚕食）式\"多次逐步清除坏死组织，不追求一次切净，以防误切存活组织），首次清创在伤后24-48小时；血管结扎（防止继发性出血）。【创面修复】清创后植皮或皮瓣转移（深部组织暴露时需皮瓣）；截肢（肢体广泛坏死、感染无法控制、威胁生命时）。【监测】持续心电监护至少24-48小时（高压电）；监测肾功能和尿量。\n\n【处理要点】\n心电监护（高压电烧伤后24-48小时内可能发生迟发性心律失常）；监测尿量和尿色（肌红蛋白尿）；肢体评估（每小时检查远端血运、感觉、运动）；营养支持（高分解代谢）；多次手术的心理准备；康复治疗（功能锻炼、支具、抗瘢痕）。\n\n【护理】\n持续心电监护；每小时记录尿量、尿色；肢体抬高、观察末梢循环；筋膜切开后创面护理（暴露/湿敷）；疼痛管理；心理护理（多次手术、可能截肢）。\n\n【饮食】\n高蛋白高热量；多饮水（促进肌红蛋白排出）；戒烟酒。\n\n【注意事项】\n①电烧伤\"口小底大\"，体表创面小不代表损伤轻，必须按重伤处理；②高压电烧伤后必须心电监护24-48小时，迟发性心律失常可发生；③肌红蛋白尿是电烧伤特征，需大量补液+碱化+利尿保护肾功能；④筋膜间隙综合征是急症，\"5P征\"（疼痛、苍白、无脉、感觉异常、麻痹）出现时已晚期，被动牵拉痛是早期信号，应立即切开；⑤电烧伤坏死组织界限不清，需多次清创，不要追求一次切净；⑥继发性出血是电烧伤严重并发症，床旁应备止血带和压迫包。\n\n【急诊/急救】\n【呼吸心跳骤停】立即心肺复苏+电除颤（触电后室颤常见）；【筋膜间隙综合征】肢体剧痛、肿胀、被动牵拉痛、感觉异常→立即筋膜切开减压（不可等待）；【急性肾衰】少尿/无尿、肌红蛋白尿→血液净化；【继发性大出血】电烧伤后血管腐蚀可突发大出血→压迫止血+急诊手术结扎。","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"T31","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2532,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"a3047bd2a453154c6bd5140787c0728d56e61fb3c1db6d11fd3a2fd79842690d","pinyin":"dianshaoshang","initials":"dss","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","T31",30]]},{"id":"templates-5e2be5b8fe390c42fd81","key":"v1-c9ccc21dfe2a3058|templates-5e2be5b8fe390c42fd81","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疔疮(中医辨证)","category":"中医","raw":{"name":"疔疮(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】火毒炽盛：疮形如粟，坚硬根深，红肿热痛，伴发热恶寒，口渴便秘，舌红苔黄，脉数、热毒入营（走黄）：疮顶黑陷无脓，肿势扩散，高热烦躁，神昏谵语，或见痉厥，舌红绛苔黄燥，脉洪数。\n【待人工确认·本机素材无此段原文】","现病史":"疔疮是发病迅速、危险性较大的急性化脓性疾病，多生于颜面及手足，疮形如粟、坚硬根深、状如钉丁之状。分火毒炽盛、热毒入营（走黄）等。疔疮走黄是危重证候，需急诊处理。\n常见表现：火毒炽盛：疮形如粟，坚硬根深，红肿热痛，伴发热恶寒，口渴便秘，舌红苔黄，脉数、热毒入营（走黄）：疮顶黑陷无脓，肿势扩散，高热烦躁，神昏谵语，或见痉厥，舌红绛苔黄燥，脉洪数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者颜面及手足部见粟米样硬结，根深坚硬，红肿热痛，伴发热恶寒、口渴便秘，为火毒炽盛之象；入院即刻完善血常规检查，明确白细胞及中性粒细胞有无升高，评估感染严重程度并排除血液系统异常；查CRP评估炎症反应程度，作为疗效观察指标；患者疮顶黑陷无脓、肿势扩散、高热烦躁甚或神昏谵语，需警惕疔疮走黄之危候，完善降钙素原(PCT)检查明确有无全身细菌感染，指导抗菌药物使用；高热寒战时完善血培养明确致病菌及药敏，排除菌血症、脓毒症；疔疮多为金黄色葡萄球菌等化脓性细菌所致，如局部已成脓，留取脓液培养+药敏明确致病菌，指导精准抗感染治疗；患者口渴、便秘、纳差，完善血糖检查排除糖尿病等基础疾病所致感染迁延；查肝肾功能了解基础状况，指导清热解毒类药物及抗菌药物选择；因疔疮走黄可迅速出现脓毒症休克及多器官功能障碍，动态复查血常规、CRP、PCT，并完善心电图及胸片检查评估心肺基础情况，必要时行创面B超检查明确有无深部脓肿形成。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 颜面手足部粟米样硬结，根深坚硬，红肿热痛\n2. 血常规、血培养（重症时）\n3. 疔疮走黄为危候，需急诊抢救\n1. 疔疮(中医辨证)（ICD-10：L02.8）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（火毒炽盛）：六神丸10粒 tid，或梅花点舌丹2粒 tid\n药物2（配合）：头孢呋辛0.5g bid（感染时，遵医嘱）\n药物3（外治）：玉露膏外敷，或如意金黄散调敷\n\n【治疗】\n火毒炽盛：清热解毒，凉血消肿，五味消毒饮合黄连解毒汤加减\n热毒入营（走黄）：凉血清热，解毒开窍，犀角地黄汤合五味消毒饮加减\n\n【处理要点】\n疔疮严禁挤压、挑刺、过早切开\n卧床休息，少言语\n忌食辛辣、荤腥发物\n\n【护理】\n病情观察：密切观察疔疮疮顶、肿势及脓液情况，警惕\"走黄\"先兆——若疮顶黑陷无脓、肿势漫延，伴高热寒战、头痛、神昏谵语者，立即报告医生；面部危险三角区疔疮严禁挤压、挑刺、碰撞。\n外治护理：初起未成脓者以金黄散或玉露散用金银花露调敷，保持敷药湿润；成脓后遵医嘱切开引流，换药严格无菌操作，保持引流通畅，脓尽后改用生肌散收口；换药前后嘱其洗手，防止交叉感染。\n起居调护：急性期卧床休息，患肢抬高制动，减少活动；嘱勿搔抓皮损、勤剪指甲，衣物床单保持清洁干燥；保持环境凉爽通风，避免暑热环境助长火毒。\n煎药服药护理：内服五味消毒饮、仙方活命饮等清热解毒方药宜温凉服用，药后观察汗出、体温及二便变化；高热者予物理降温，慎用发汗太过之品，防汗出伤津、耗气助毒。\n情志护理：患者常因疼痛剧烈或面部疔疮影响容貌而焦虑烦躁，应耐心解释病情转归，疏导情志，避免郁怒化火、加重热毒。\n\n【饮食】\n忌口：忌辛辣炙煿、肥甘厚味及鱼腥发物（辣椒、葱蒜、酒、羊肉、海鲜、鹅肉、韭菜等），以免助火生毒、促使毒势扩散。\n宜食清热解毒之品：绿豆、赤小豆、冬瓜、丝瓜、苦瓜、马齿苋、金银花、菊花等，多饮温水，保持大便通畅，使热毒从下焦而泄。\n药膳食疗：火毒炽盛期可服绿豆金银花甘草汤（绿豆、金银花、生甘草煮水代茶饮）、蒲公英粳米粥、马齿苋薏苡仁粥，每日1次，连用3～5日。\n恢复期（余毒未清、气阴两伤者）宜益气养阴、清解余毒：山药、百合、莲子、薏苡仁、梨汁、藕汁等，忌过早进补温燥滋腻之品，防毒邪留恋。\n\n【注意事项】\n走黄（高热神昏、肿势蔓延）立即急诊转院\n面部疔疮尤其危险，注意观察\n糖尿病患者疔疮易走黄，加强控糖\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】疔疮\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、热毒蕴结（初起）\n    症状舌脉：患处红肿热痛，根脚收束，坚硬如钉，顶白无头或白头，可伴发热、恶寒、口渴；舌红苔黄，脉数\n    治法：清热解毒、消肿散结\n    方剂：五味消毒饮合黄连解毒汤加减（金银花、野菊花、蒲公英、紫花地丁、紫背天葵、黄连、黄芩、黄柏、栀子）\n\n二、火毒炽盛（走黄）\n    症状舌脉：疮顶黑陷，无脓，肿势散漫，迅速向四周扩散，伴寒战高热、头痛烦躁、神昏谵语；舌红绛、苔黄糙，脉洪数\n    治法：凉血清热、解毒散瘀\n    方剂：犀角地黄汤合黄连解毒汤加减（水牛角、生地黄、赤芍、牡丹皮、黄连、黄芩、黄柏、栀子）\n\n三、气血两虚（溃后）\n    症状舌脉：溃后脓水稀少，疮口愈合缓慢，伴面色少华、神疲乏力、低热；舌淡苔薄，脉细数无力\n    治法：补益气血、托毒生肌\n    方剂：托里消毒散加减（人参、黄芪、当归、白芍、白术、茯苓、川芎、金银花、白芷、皂角刺）\n\n【西医诊断】\n  疖 / 痈 / 脓毒症等\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ **颜面部疔疮严禁挤压**；出现寒战高热、神志改变须立即急诊（警惕脓毒症/颅内感染）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L02.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2533,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"7acbc642747bf0b1fa68b5c4c4c36a0b6e9c54dd4ae03bbde1c5594c5de70bf8","pinyin":"dingchuang(zhongyibianzheng)","initials":"dc(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L02.8",30]]},{"id":"templates-1f9123ec1c70acd1115e","key":"v1-c9ccc21dfe2a3058|templates-1f9123ec1c70acd1115e","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"疖(中医辨证)","category":"中医","raw":{"name":"疖(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】暑湿热毒：发于夏秋，单个或多个红肿热痛小硬结，根脚浅，3-5天成脓，脓出黄稠，伴发热口渴，便秘溲赤，苔黄腻，脉滑数、体虚毒恋：疖肿此愈彼起，不断发生，或散发全身，脓液稀薄，面色萎黄，神疲乏力，纳少便溏，舌淡苔薄，脉细弱。\n【待人工确认·本机素材无此段原文】","现病史":"疖是生于皮肤浅表的急性化脓性疾患，局部红肿热痛、范围较小（3cm内）、脓出即愈。分暑疖（暑湿热毒）、蝼蛄疖、疖病（体虚毒恋）。可见于毛囊炎、皮脂腺感染等。\n常见表现：暑湿热毒：发于夏秋，单个或多个红肿热痛小硬结，根脚浅，3-5天成脓，脓出黄稠，伴发热口渴，便秘溲赤，苔黄腻，脉滑数、体虚毒恋：疖肿此愈彼起，不断发生，或散发全身，脓液稀薄，面色萎黄，神疲乏力，纳少便溏，舌淡苔薄，脉细弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者夏秋之季见单个或多个红肿热痛小硬结，根脚浅，脓出黄稠，伴发热口渴、便秘溲赤，为暑湿热毒蕴结肌肤之象；完善血常规检查明确白细胞及中性粒细胞有无升高，评估感染轻重并指导是否需抗菌治疗；查CRP及降钙素原(PCT)了解炎症反应程度，用于排除深部感染及脓毒症；疖肿脓成未溃或反复发作，留取脓液培养+药敏明确致病菌，为外用及口服抗菌药物选择提供依据，避免盲目用药；患者反复疖肿、此愈彼起或散发全身，属体虚毒恋，完善血糖及糖化血红蛋白检查排除糖尿病，因高血糖是疖病反复发作及感染难以控制的常见基础病因；同时查免疫球蛋白及淋巴细胞亚群了解免疫功能状态，排除免疫低下所致感染迁延；患者长期服用清热利湿中药并经肝肾代谢，完善肝肾功能检查排除肝肾功能不全，指导用药剂量；若出现寒战高热、全身中毒症状，完善血培养排除菌血症；局部红肿范围较大、按之应指者，行浅表组织B超检查明确有无脓腔形成及范围，必要时在超声引导下切开引流。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 局部红肿热痛小硬结，范围较小，脓出即愈\n2. 血常规（感染时白细胞升高）\n3. 血糖筛查（反复疖肿需排除糖尿病）\n1. 疖(中医辨证)（ICD-10：L02.9）","鉴别诊断":"1. 血糖筛查（反复疖肿需排除糖尿病）","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（暑湿热毒）：六神丸10粒 tid，或牛黄解毒片3片 tid\n药物2（体虚毒恋）：补中益气丸6g tid，或防风通圣丸6g tid\n药物3（外治）：鱼石脂软膏外敷，或金黄膏外敷\n\n【治疗】\n暑湿热毒：清暑化湿，解毒消肿，清暑汤加减\n体虚毒恋：扶正托毒，托里消毒散加减\n\n【处理要点】\n保持皮肤清洁干燥\n疖肿未成熟不宜挤压，防脓毒扩散\n忌辛辣、油腻、甜食\n\n【护理】\n病情观察：每日观察疖肿大小、色泽、疼痛程度及有无脓头，注意体温变化；若见高热寒战、头痛烦躁、疖肿四患者晕迅速扩大，提示毒邪走黄内陷，立即报告医师处理。\n外治护理：未成脓者用金黄散或玉露散以凉开水调敷患处，每日1～2次，保持敷药湿润；已成脓者由医师切开排脓后，按无菌操作换药，保持引流通畅；面部危险三角区疖肿严禁挤压、挑刺，防毒邪内陷。\n起居调护：保持皮肤清洁干燥，勤洗澡、勤换衣，修剪指甲，避免搔抓患处；暑季汗出后及时擦干，衣被宜宽松透气；红肿期减少患处活动与摩擦。\n煎药服药护理：清热解毒、消肿散结之剂宜温服，每日2次分服；观察服药后有无恶心、腹泻等反应；外用敷药、洗剂按医嘱定时更换，敷前清洁患处皮肤。\n情志护理：向患者解释本病经正规治疗多可痊愈，疏导急躁、焦虑情绪，避免郁怒化火加重热毒；体虚反复发作者嘱其静养，忌劳神过度。\n\n【饮食】\n忌口：忌食辛辣炙煿（辣椒、生姜、葱蒜、酒）、肥甘厚味及鱼腥发物（牛羊肉、海鲜、虾蟹、韭菜），少食甜腻之品，以免助热生火、蕴毒加重。\n适宜食物：宜食清凉解毒之品，如绿豆、赤小豆、冬瓜、丝瓜、苦瓜、黄瓜、马齿苋、蒲公英嫩叶、梨等，多饮温开水，保持二便通畅以利热毒外泄。\n药膳食疗：绿豆薏米粥（绿豆、薏苡仁各30g煮粥，每日1次）；冬瓜马齿苋汤（冬瓜200g、鲜马齿苋100g煎汤代茶饮），适用于热毒蕴结、暑热浸淫证。\n体虚毒恋者：宜食益气托毒之品，如黄芪炖鸡、山药莲子粥，以扶正托毒外出；忌盲目厚腻进补，以防留邪碍胃。\n饮食规律：三餐定时定量，宜清淡易消化，忌暴饮暴食；疖肿反复发作或血糖偏高者，尤须控制甜食与高糖饮品摄入。\n\n【注意事项】\n面部危险三角区疖肿严禁挤压，防海绵窦感染\n反复疖病需查血糖、免疫功能\n糖尿病者积极控制血糖\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「疖（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】疖\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、疖·热毒蕴结\n    症状舌脉：常见于气实火盛患者，好发于项后发际、背部、臀部，轻者疖肿只有一两个，多则可散发全身，或簇集一处，或此愈彼起，伴发热、口渴、溲赤、便秘，苔黄，脉数\n    治法：清热解毒\n    方剂：五味消毒饮合黄连解毒汤\n\n二、疖·暑热浸淫\n    症状舌脉：发于夏秋季节，以小儿及产妇多见，局部皮肤红肿结块，灼热疼痛，根脚很浅，范围局限，可伴发热、口干、便秘、溲赤等，舌苔薄腻，脉滑数\n    治法：清暑化湿解毒\n    方剂：清暑汤\n\n三、疔·热毒蕴结（颜面部疔疮初起）\n    症状舌脉：红肿高突，根脚收束，发热头痛，舌红、苔黄，脉数\n    治法：清热解毒\n    方剂：五味消毒饮合黄连解毒汤\n\n四、疔·火毒炽盛（走黄）\n    症状舌脉：疮形平塌，肿势散漫，皮色紫暗，焮热疼痛，伴高热、头痛、烦渴、呕恶，甚则神昏谵语、抽搐，舌红绛、苔黄糙，脉洪数\n    治法：凉血清热解毒\n    方剂：犀角地黄汤合黄连解毒汤（水牛角代犀角）。来源：《中医外科学》（中国中医药出版社“十四五”规划教材）·疮疡·疖、疔疮。提示：颜面部疔疮严禁挤压，走黄（脓毒血症）须急诊抗感染治疗\n\n【方剂参考】\n  黄连解毒汤：组成 黄连9g、黄芩6g、黄柏6g、栀子9g；功效 泻火解毒\n      用法：水煎温服，日二至三次；亦可为末制水丸，每次6g，温开水送服。\n      注意：苦寒伤胃，脾胃虚寒、阴虚火旺及非火毒炽盛者忌用；孕妇慎用；不宜久服，中病即止。\n  黄连解毒汤：组成 黄连9g、黄芩6g、黄柏6g、栀子9g；功效 泻火解毒\n      用法：水煎温服，日二至三次；亦可为末制水丸，每次6g，温开水送服。\n      注意：苦寒伤胃，脾胃虚寒、阴虚火旺及非火毒炽盛者忌用；孕妇慎用；不宜久服，中病即止。\n\n【西医诊断】\n  疖 / 毛囊炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L02.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2534,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c8a20d97d9c48565d039b4e6cc39330f8103b2cf03900dbce1fd36ecbe4fc394","pinyin":"jie(zhongyibianzheng)","initials":"j(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L02.9",30]]},{"id":"templates-360c751da85e21817846","key":"v1-c9ccc21dfe2a3058|templates-360c751da85e21817846","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痄腮(中医辨证)","category":"中医","raw":{"name":"痄腮(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】温毒在表：轻微发热恶寒，一侧或两侧耳下腮部漫肿疼痛，咀嚼不便，咽红，舌红苔薄白或薄黄，脉浮数、热毒蕴结：壮热烦躁，头痛，口渴饮水，腮部漫肿，胀痛拒按，咀嚼困难，咽红肿痛，舌红苔黄，脉滑数。\n【待人工确认·本机素材无此段原文】","现病史":"痄腮是由腮腺炎时邪（病毒）引起的急性传染病，以发热、耳下腮部漫肿疼痛为主要特征。分温毒在表、热毒蕴结等证型。可见于流行性腮腺炎。\n常见表现：温毒在表：轻微发热恶寒，一侧或两侧耳下腮部漫肿疼痛，咀嚼不便，咽红，舌红苔薄白或薄黄，脉浮数、热毒蕴结：壮热烦躁，头痛，口渴饮水，腮部漫肿，胀痛拒按，咀嚼困难，咽红肿痛，舌红苔黄，脉滑数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压、体重\n望诊：神（得神/少神/失神）、色（常色/病色）、形态（胖瘦/发育）、头面五官、指纹（3岁以下看虎口三关：风关/气关/命关）、舌诊（舌质/舌苔）\n闻诊：哭声、咳声、呼吸声、口气、二便气味\n问诊：年龄（月龄）、喂养史、生长发育史、预防接种史、既往史、现病史、大小便、睡眠\n切诊：脉诊（小儿脉象：浮沉迟数有力无力）、按诊（囟门/腹部/四肢）\n辨证：八纲辨证、脏腑辨证、卫气营血辨证、指纹辨证","辅助检查":"检查计划：患者发热恶寒、一侧或两侧耳下腮部漫肿疼痛、咀嚼不便、咽红，为感受腮腺炎时邪、温毒在表之象；完善血常规检查明确白细胞计数及淋巴细胞分类，鉴别病毒性感染与化脓性腮腺炎，排除细菌感染所致白细胞显著升高；患者腮部漫肿、胀痛拒按，急诊完善血淀粉酶及尿淀粉酶检查，流行性腮腺炎时淀粉酶常明显升高，可明确诊断并评估病情程度，同时排除胰腺炎所致淀粉酶升高；完善腮腺炎病毒抗体检查，包括特异性IgM/IgG，明确病原学诊断并鉴别其他病毒所致腮腺肿大；患者壮热烦躁、头痛、口渴，需警惕并发脑膜炎，完善脑电图检查了解脑功能状况，如出现剧烈头痛、呕吐、颈项强直，必要时行腰椎穿刺查脑脊液，明确有无病毒性脑膜炎；男性患者查睾丸B超、女性患者查妇科B超，明确有无并发睾丸炎、卵巢炎；患者进食减少、需静脉补液用药，完善电解质及肝肾功能检查排除电解质紊乱及肝肾功能不全；因痄腮属法定报告传染病，确诊后应即时网络直报并做好隔离。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 发热、耳下腮部漫肿疼痛（以耳垂为中心）\n2. 血常规、血尿淀粉酶、腮腺炎病毒抗体\n3. 注意并发脑膜炎、睾丸炎（男）、卵巢炎（女）\n1. 痄腮(中医辨证)（ICD-10：B26.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！儿童用药剂量务必按体重精确计算！\n\n方案1：\n 用法：一般不需输液，口服中药为主\n\n方案2（发热/脱水）：\n 用法：5%GS 100-250ml+维生素C1.0g ivgtt qd（按体重调整）；口服补液盐（ORS）按需\n\n方案3（合并细菌感染）：\n 用法：NS 50-100ml+头孢呋辛50mg/kg·d 分2次 ivgtt（皮试后，按体重计算）\n\n📌 儿童输液务必严格控制滴速与液体量，用药前核对体重、剂量、过敏史！\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患儿病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n儿童剂量需按体重/年龄精确计算，务必遵医嘱。\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（温毒在表）：银翘解毒颗粒（小儿量）5g tid，或蒲地蓝消炎口服液10ml tid\n药物2（热毒蕴结）：普济消毒丸（遵医嘱），或板蓝根颗粒5g tid\n药物3（外治）：如意金黄散/青黛散醋调外敷腮部，每日2次\n\n【治疗】\n温毒在表：疏风清热，散结消肿，银翘散加减\n热毒蕴结：清热解毒，软坚散结，普济消毒饮加减\n\n【处理要点】\n隔离至腮肿完全消退（约3周）\n卧床休息，清淡流质饮食，忌酸辣硬食\n保持口腔清洁\n\n【护理】\n病情观察：每日监测体温、腮肿范围及压痛变化，若见高热不退、神昏嗜睡、项强抽搐，为邪陷心肝之变证，须立即报告并配合急救；男孩注意观察阴囊有无红肿坠痛，警惕毒窜睾腹之并发症。\n起居调护：按呼吸道传染病隔离至腮肿完全消退后3日；发热及腮肿期卧床休息，居室定时通风，避免剧烈活动，以防余毒内窜。\n外治护理：腮肿处用青黛散或如意金黄散以醋调敷，外敷药宜保持湿润、每日更换，注意观察局部皮肤有无过敏；每日以银花甘草液或生理盐水漱口，保持口腔清洁，防止腮腺管口继发感染。\n情志护理：患儿因腮肿疼痛、张口进食困难易烦躁哭闹，应耐心安抚、轻声疏导，解释病情与预后，鼓励其配合治疗，避免哭闹加重腮痛。\n煎药服药护理：中药宜温服，疏风清热、解毒透邪之品（如银翘散、普济消毒饮）不宜久煎；发热者药后观察汗出情况，汗出及时擦干更衣、避风，忌发汗太过以防耗伤阴津。\n\n【饮食】\n忌酸辣及干硬粗糙食物（如醋、辣椒、坚果、油条、煎炸物）：酸味刺激唾液分泌增多，加重腮腺肿痛；辛辣助热生火，不利解毒。\n忌肥甘厚味及鱼虾海鲜等发物，以免酿生湿热、助长热毒，使腮肿缠绵难消。\n宜食清淡流质、半流质软食，如米粥、藕粉、烂面条、蒸蛋羹、冬瓜汤，少食多餐，减轻咀嚼吞咽牵动腮部之疼痛。\n多饮温开水，频饮金银花、连翘、板蓝根煎水代茶，以清热解毒消肿；亦可常食绿豆汤、赤小豆汤以助利湿泄热，忌过食生冷以防冰伏邪气。\n药膳食疗：热毒壅结者可用银花、连翘、薄荷煎汁入粳米煮粥食用，或食凉拌马齿苋、蒲公英汤清热解毒；恢复期腮肿消退后宜百合粥、山药粥养阴生津，助正气恢复。\n\n【注意事项】\n高热不退、头痛呕吐、嗜睡（并发脑膜炎）立即住院\n男孩睾丸肿痛（并发睾丸炎）及时治疗\n青春期后患者重点观察并发症\n\n【急诊/急救】\n一般不需急救\n高热惊厥：物理降温，地西泮0.3-0.5mg/kg iv（遵医嘱）\n呼吸困难/发绀/精神萎靡：立即转儿科急诊","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痄腮\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、邪犯少阳（轻证）\n    症状舌脉：轻微发热恶寒，一侧或两侧耳下腮部漫肿疼痛，咀嚼不便，或有咽红，舌质红、苔薄白或薄黄，脉浮数\n    治法：疏风清热、散结消肿\n    方剂：柴胡葛根汤\n\n二、热毒蕴结（重证）\n    症状舌脉：高热，一侧或两侧耳下腮部肿胀疼痛，坚硬拒按，张口、咀嚼困难，烦躁不安，口渴，或伴头痛、呕吐，咽部红肿，食欲不振，尿少黄赤，舌红、苔黄，脉滑数\n    治法：清热解毒、软坚散结\n    方剂：普济消毒饮\n\n三、毒陷心肝（变证）\n    症状舌脉：腮部肿胀，高热不退，嗜睡，项强，反复抽搐，神志昏迷，舌红绛、苔黄糙，脉洪数\n    治法：清热解毒、息风开窍\n    方剂：清瘟败毒饮合紫雪散\n\n四、邪窜肝经（变证）\n    症状舌脉：腮部肿胀，发热，男性睾丸肿痛，女性少腹疼痛，舌红、苔黄，脉弦数\n    治法：清肝泻火、活血止痛\n    方剂：龙胆泻肝汤。来源：《中医儿科学》（中国中医药出版社“十四五”规划教材）·传染病·痄腮。提示：痄腮为流行性腮腺炎，须隔离治疗并接种疫苗；合并脑炎、睾丸炎者须住院\n\n【方剂参考】\n  普济消毒饮：组成 黄芩15g、黄连15g、连翘3g、薄荷3g、马勃3g、牛蒡子3g、玄参6g、僵蚕2g、升麻2g、柴胡6g、桔梗6g、甘草6g、板蓝根3g、陈皮6g；功效 清热解毒，疏风散邪\n      用法：上药为末，每次15g，水煎，食后徐徐温服（或含漱后咽下）；亦可作汤剂，日二次。\n      注意：虚寒体质及脾胃虚弱者慎用；孕妇慎用；本方苦寒，中病即止。（本方黄连15g、黄芩15g超《中国药典》2020年版一部用量，系教材原方折算，临床宜酌减）\n  清瘟败毒饮：组成 生石膏60g（先煎）、水牛角30g（先煎）、生地黄30g、黄连6g、栀子9g、黄芩9g、知母9g、赤芍9g、玄参9g、连翘9g、牡丹皮9g、淡竹叶9g、桔梗6g；功效 清热解毒，凉血泻火\n      用法：先煎石膏数十沸，再入诸药同煎；水牛角先煎或磨汁兑服，去滓温服，日一至二剂，分二至三次服。\n      注意：本方大寒，非气血两燔之实热证不可妄用；脾胃虚寒、阳虚及素体虚弱者忌用；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·清热剂（清营凉血）；原方出自《疫疹一得》\n  龙胆泻肝汤：组成 龙胆草6g、黄芩9g、栀子9g、泽泻12g、川木通6g（禁用关木通）、车前子9g、当归3g、生地黄9g、柴胡6g、生甘草6g；功效 清泻肝胆实火，清利肝经湿热\n      用法：水煎温服，日二次，饭后服；亦可制丸，每次6-9g，日二次。\n      注意：脾胃虚寒、孕妇及阴虚阳亢者忌用；苦寒渗利之品久服伤胃耗阴，一般不超过7-14剂；木通用量宜小。木通须用川木通；关木通含马兜铃酸、2005 年起取消药用标准，禁止使用。\n\n【西医诊断】\n  流行性腮腺炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"B26.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2535,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"babd18d3dadf21b6d39db6220046574c7a76ceda0668501b04cc757439cdaee2","pinyin":"zhasai(zhongyibianzheng)","initials":"zs(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","B26.9",30]]},{"id":"templates-429ba84e1dd0dfd8ff87","key":"v1-c9ccc21dfe2a3058|templates-429ba84e1dd0dfd8ff87","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痈(中医辨证)","category":"中医","raw":{"name":"痈(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】火毒凝结（初期）：患处红肿灼热疼痛，肿块边界不清，伴发热恶寒，舌红苔黄腻，脉洪数、热盛肉腐（成脓期）：肿势高突，疼痛加剧，痛如鸡啄，按之中软应指，壮热不退，口渴便秘，舌红苔黄厚腻，脉滑数、气血两虚（溃后期）：脓水稀薄，疮面新肉不生，愈合缓慢，面色萎黄，神疲乏力，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","现病史":"痈是气血为毒邪壅塞而不通，发于皮肉之间的急性化脓性疾病，局部光软无头、红肿疼痛、范围较大（6-9cm），发病迅速。分火毒凝结、热盛肉腐、气血两虚等期。可见于蜂窝织炎、深部脓肿等。\n常见表现：火毒凝结（初期）：患处红肿灼热疼痛，肿块边界不清，伴发热恶寒，舌红苔黄腻，脉洪数、热盛肉腐（成脓期）：肿势高突，疼痛加剧，痛如鸡啄，按之中软应指，壮热不退，口渴便秘，舌红苔黄厚腻，脉滑数、气血两虚（溃后期）：脓水稀薄，疮面新肉不生，愈合缓慢，面色萎黄，神疲乏力，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者患处红肿灼热疼痛、肿块边界不清、范围较大，伴发热恶寒，为火毒凝结、气血壅滞之象；完善血常规检查明确白细胞及中性粒细胞有无升高，评估感染严重程度并动态复查判断疗效；查CRP及降钙素原(PCT)了解炎症反应水平，排除脓毒症及全身性感染；患者热盛肉腐、痛如鸡啄、按之中软应指，为已成脓之征，完善浅表组织B超检查明确脓腔部位、大小、深度及有无分隔，为切开引流时机与切口选择提供依据；患者需行切开引流手术，术前完善血糖及糖化血红蛋白检查排除糖尿病，因糖尿病是痈多发及创面难愈的重要基础病因，并直接影响手术时机与预后；完善肝肾功能、凝血功能及心电图检查，评估手术耐受性、排除凝血障碍及心脏疾病；患者壮热不退、口渴便秘，若寒战高热则完善血培养明确致病菌及药敏；局部脓液留取分泌物培养+药敏，指导抗菌药物精准选择并排除特殊耐药菌感染；溃后期脓水稀薄、新肉不生者，复查血常规了解有无贫血，必要时查血清白蛋白了解营养状况，指导营养支持与创面处理。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 局部光软无头、红肿疼痛、范围较大之急性化脓性疾患\n2. 血常规、B超（判断成脓）、血糖\n3. 糖尿病、免疫低下者病情易加重\n1. 痈(中医辨证)（ICD-10：L02.8）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（初期）：牛黄解毒片3片 tid，或六神丸10粒 tid\n药物2（成脓期）：配合头孢呋辛0.5g bid（遵医嘱）\n药物3（溃后期）：八珍颗粒6g tid，或十全大补丸6g bid\n药物4（外治）：初期金黄膏外敷；成脓切开引流；溃后生肌散外用\n\n【治疗】\n火毒凝结：清热解毒，行瘀活血，仙方活命饮加减\n热盛肉腐：清热透脓，托里排脓，透脓散加减\n气血两虚：补益气血，托毒生肌，托里消毒散或八珍汤加减\n\n【处理要点】\n成脓后及时切开引流，保持引流通畅\n卧床休息，抬高患肢\n加强营养，忌辛辣发物\n\n【护理】\n外治护理：未成脓期以金黄散（或玉露膏）外敷，宜厚涂、随干随换，勿使药膏干燥脱落；已成脓及时配合切开排脓，换药严格无菌操作，观察疮面大小、脓液之色质气味及有无脓栓、死肉。\n病情观察：动态观察局部红肿热痛范围是否扩散、疮顶有无透脓点；警惕高热寒战、神昏谵语、咳吐脓血、疮色紫黑等脓毒内陷（走黄）之象，发现立即报告处理。\n起居调护：患处制动防挤压——上肢痈者抬高患肢以利消肿，下肢痈者减少行走负重；保持疮周皮肤清洁干燥，忌用手挤压、搔抓、碰撞疮口，忌热水烫洗，防邪毒扩散。\n煎药服药护理：清热解毒方药（如仙方活命饮）宜温凉服、饭后服，勿与辛辣同进；服用托里透脓之剂（如托里消毒散）时注意观察局部排脓是否通畅增多，勿中断服药。\n情志护理：痈证疼痛剧烈或反复不愈者易生焦虑烦躁，宜耐心安抚疏导，嘱其静心调养、勿忧思恼怒，以免气郁化火、助长热毒。\n\n【饮食】\n忌口：忌辛辣炙煿、肥甘厚味（辣椒、烈酒、羊肉、油炸炙烤之品），忌鱼腥发物（海鲜、公鸡、鹅、猪头肉、香椿等），以免助热生痰、煽动火毒，致肿势加重。\n适宜：宜清淡易消化饮食，多饮温开水；可常食绿豆、冬瓜、苦瓜、丝瓜、赤小豆、薏苡仁等清热解毒利湿之品，使热毒从小便而去。\n药膳（未成脓期）：金银花、蒲公英适量煎水代茶饮，或绿豆甘草汤（绿豆、生甘草同煮），清解热毒、消肿散结。\n药膳（透脓期·热盛肉腐）：赤小豆薏苡仁粥，或黄芪、皂角刺炖汤，托里透脓，促脓成熟速溃。\n药膳（溃后·气血两虚）：食黄芪炖母鸡、山药红枣粥、乌鸡汤以补益气血、生肌敛疮，忌寒凉生冷伤胃滞邪；畏寒血虚者酌加桂圆、大枣。\n\n【注意事项】\n痈肿范围大、全身中毒症状重者住院治疗\n糖尿病者积极控糖\n深部脓肿切开后注意引流与换药\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痈\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、瘀滞证（初期）\n    症状舌脉：转移性右下腹痛，呈持续性、进行性加剧，右下腹局限性压痛或拒按，伴恶心纳差，可有轻度发热，苔白腻，脉弦滑或弦紧\n    治法：行气活血、通腑泄热\n    方剂：大黄牡丹汤合红藤煎剂\n\n二、湿热证（酿脓期）\n    症状舌脉：腹痛加剧，右下腹或全腹压痛、反跳痛，腹皮挛急，右下腹可摸及包块，壮热，纳呆，恶心呕吐，便秘或腹泻，舌红、苔黄腻，脉弦数或滑数\n    治法：通腑泄热、利湿解毒\n    方剂：复方大柴胡汤\n\n三、热毒证（溃脓期）\n    症状舌脉：腹痛剧烈，全腹压痛、反跳痛，腹皮挛急，高热不退或恶寒发热，时时汗出，烦渴，恶心呕吐，腹胀，便秘或似痢不爽，舌红绛而干、苔黄糙，脉洪数或细数\n    治法：通腑排脓、养阴清热\n    方剂：大黄牡丹汤合透脓散。来源：《中医外科学》（中国中医药出版社“十四五”规划教材）·疮疡·肠痈。提示：急性阑尾炎属外科急症，须外科评估，穿孔、腹膜炎者立即手术，中药仅适用于瘀滞期轻症并在严密观察下使用\n\n【方剂参考】\n  大黄牡丹汤：组成 大黄12g（后下）、牡丹皮3g、桃仁9g、冬瓜仁30g、芒硝9g（冲服）；功效 泻热破瘀，散结消肿\n      用法：水煎，大黄后下，芒硝冲入溶化，日一剂，分两次服；原方为顿服。\n      注意：肠痈已成脓、或痈溃之后，以及寒湿瘀滞者不宜用；孕妇、年老体弱及脾胃虚寒者忌用；本方攻下破瘀力峻，中病即止。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·泻下剂（寒下）；原方出自《金匮要略·疮痈肠痈浸淫病脉证并治》\n  大柴胡汤：组成 柴胡12g、黄芩9g、芍药9g、半夏9g、生姜15g、枳实9g、大枣4枚、大黄6g；功效 和解少阳，内泻热结\n      用法：水煎温服，日二次；大黄后下，用量视大便情况调整，得利即止。\n      注意：少阳证未兼阳明腑实者不宜用大黄；孕妇忌用；脾胃虚寒者慎用。\n  大黄牡丹汤：组成 大黄12g（后下）、牡丹皮3g、桃仁9g、冬瓜仁30g、芒硝9g（冲服）；功效 泻热破瘀，散结消肿\n      用法：水煎，大黄后下，芒硝冲入溶化，日一剂，分两次服；原方为顿服。\n      注意：肠痈已成脓、或痈溃之后，以及寒湿瘀滞者不宜用；孕妇、年老体弱及脾胃虚寒者忌用；本方攻下破瘀力峻，中病即止。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·泻下剂（寒下）；原方出自《金匮要略·疮痈肠痈浸淫病脉证并治》\n\n【西医诊断】\n  急性阑尾炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L02.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2536,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"2278269535058e59df9b9c44a8b6689751ec3aed4d211cd59ce10e7a4e062fd1","pinyin":"yong(zhongyibianzheng)","initials":"y(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L02.8",30]]},{"id":"templates-5906844494df27781366","key":"v1-c9ccc21dfe2a3058|templates-5906844494df27781366","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痉挛状态管理(肌张力增高)","category":"康复医学","raw":{"name":"痉挛状态管理(肌张力增高)","category":"康复医学","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肌肉僵硬与张力增高（被动活动阻力增大，速度依赖）、阵挛（踝阵挛常见）与深腱反射亢进、关节活动受限与畸形（内收肌痉挛致剪刀步态、屈肘与屈腕畸形）、疼痛与不适（痉挛性疼痛影响睡眠）、功能与护理影响：会阴清洁困难、穿脱衣物困难、坐位平衡差、压疮风险增加。\n【待人工确认·本机素材无此段原文】","现病史":"痉挛是上运动神经元损伤（脑卒中、脊髓损伤、脑瘫、多发性硬化）后肌张力速度依赖性增高，表现为肌肉僵硬、关节活动受限、疼痛与 Care 困难（清洁与会阴护理），可致挛缩与畸形。管理包括去除诱因、物理治疗、口服药物、局部注射（肉毒毒素）与手术（鞘内巴氯芬泵、选择性周围神经切断）。\n常见表现：肌肉僵硬与张力增高（被动活动阻力增大，速度依赖）、阵挛（踝阵挛常见）与深腱反射亢进、关节活动受限与畸形（内收肌痉挛致剪刀步态、屈肘与屈腕畸形）、疼痛与不适（痉挛性疼痛影响睡眠）、功能与护理影响：会阴清洁困难、穿脱衣物困难、坐位平衡差、压疮风险增加。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"肌张力评估：改良Ashworth量表（MAS）分级（各肌群）、速度依赖性阻力与阵挛\n深腱反射：亢进程度（与上运动神经元损伤一致）\n关节活动度：主动与被动范围、挛缩与畸形（内收、屈肘与马蹄足）\n疼痛评估：部位、性质与程度（NRS），痉挛与疼痛的关系\n功能评估：坐位与站立平衡、转移能力、步行能力与日常生活活动（ADL）\n诱因检查：尿路（尿混浊与叩击痛）、肠道（腹胀与便秘）、皮肤（压疮）与下肢（深静脉血栓：肿胀与压痛）\n病因体征：脑卒中（偏瘫侧）、脊髓损伤（平面与感觉运动缺失）与脑瘫（运动发育异常）","辅助检查":"1. 改良Ashworth量表（MAS）+Tardieu量表：肌张力评估（治疗前后对比核心指标）\n2. 尿常规+尿培养：尿路感染（痉挛加重的最常见诱因）\n3. 电解质（钾、钠、钙、镁）+肾功能：电解质紊乱与巴氯芬剂量调整（肾功能不全者）\n4. 肝功能（替扎尼定、丹曲林）：药物不良反应监测（每月）\n5. 下肢静脉超声（疑深静脉血栓）：肿胀与疼痛时\n6. 肌电图/超声（肉毒毒素注射）：定位与剂量指导\n7. 影像学（必要时）：X线（关节挛缩与异位骨化）、MRI（病因评估）","初步诊断":"1. 改良Ashworth量表（MAS）或Tardieu量表：评估肌张力增高的程度（0～4级）\n2. 功能评估：关节活动度、坐位与站立平衡、步行能力（步态分析）与日常生活活动（ADL）\n3. 疼痛评估：痉挛相关疼痛的部位与程度（NRS评分）\n4. 诱因寻找（关键）：尿路感染、便秘、压疮、深静脉血栓、疼痛、体位不当与药物（可加重痉挛）\n5. 病因评估：脑卒中（病程与部位）、脊髓损伤（平面与完全性）、脑瘫与多发性硬化\n6. 目标设定：明确治疗目标（改善功能、减轻疼痛、便于护理或预防挛缩）——决定治疗方式\n7. 必要时电生理检查：肌电图引导肉毒毒素注射定位\n1. 痉挛状态管理(肌张力增高)（ICD-10：R25.2）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 以康复与局部治疗为主，静脉用药用于诱因与重症！\n\n方案1（去除诱因，首要）：\n 用法：尿路感染——左氧氟沙星 0.5g 静滴 qd（按药敏）；便秘——乳果糖（口服为主）；压疮感染——抗感染+换药；深静脉血栓——抗凝（低分子肝素 0.4ml 皮下注射 qd）\n\n方案2（鞘内巴氯芬泵试验与调整，重症，专科）：\n 用法：巴氯芬 50～100μg 鞘内注射（试验剂量，监测反应与呼吸抑制）——需神经外科/康复科专科操作\n\n方案3（严重痉挛伴疼痛与睡眠障碍）：\n 用法：0.9%氯化钠 静滴；地西泮 5～10mg 缓慢静推（短期，注意呼吸与镇静）；必要时静脉镇痛（曲马多）\n\n方案4（营养与支持）：\n 用法：0.9%氯化钠/葡萄糖 静滴；维生素B族与钙镁补充；营养支持（营养不良影响肌力与恢复）\n\n📌 痉挛处理先去除诱因（感染、便秘、压疮与疼痛常致痉挛突然加重）；肉毒毒素注射与鞘内巴氯芬是重症的有效治疗（需专科）。\n\n【药物治疗·口服】\n⚠️ 口服药物为全身治疗（注意副作用与剂量滴定）：\n\n药物1（一线口服，巴氯芬）：\n 用法：巴氯芬 5mg tid 起（逐渐加量至有效，最大80mg/日；不可骤停——可致戒断与癫痫）；肾功能不全者减量\n\n药物2（二线/联合）：\n 用法：替扎尼定 2mg tid 起（α2激动剂，注意低血压与肝损）；或 丹曲林 25mg qd 起（注意肝毒性与肌无力）；苯二氮卓类（地西泮，短期）\n\n药物3（局部注射，专科）：\n 用法：A型肉毒毒素 局部肌肉注射（按肌肉大小与痉挛程度选择剂量，效果维持3～6个月）；需肌电图或超声引导\n\n药物4（神经病理性疼痛与辅助）：\n 用法：加巴喷丁 0.3g tid 或 普瑞巴林 75mg bid；甲钴胺 0.5mg tid（神经修复辅助）\n\n📌 巴氯芬不可骤停（可致戒断综合征与癫痫）；替扎尼定与丹曲林需监测肝功能；肉毒毒素注射后需观察疗效与不良反应（无力、吞咽困难）。\n\n【治疗】\n去除诱因（首要）：治疗尿路感染、便秘、压疮、深静脉血栓与疼痛；调整体位与护理方式\n物理治疗：被动关节活动度训练（每日多次，防挛缩）、牵伸（缓慢持续）、体位摆放（良肢位）、冷热疗与电刺激\n口服药物治疗：巴氯芬（一线）、替扎尼定、丹曲林与苯二氮卓类（按疗效与副作用滴定）\n局部注射：A型肉毒毒素（局灶性痉挛，如内收肌、屈肘肌群，效果3～6个月）；酚或酒精神经阻滞（部分患者）\n鞘内巴氯芬泵：重度全身性痉挛（口服无效或副作用大者），需专科评估与泵管理（注意过量致呼吸抑制）\n手术治疗：选择性周围神经切断术（SPN）、肌腱延长/转移术与矫形手术（挛缩与畸形）\n康复训练与功能训练：结合痉挛管理进行坐位平衡、转移与步行训练，提高日常生活能力\n随访与评估：定期评估MAS评分、关节活动度、疼痛与功能（每1～3个月），调整治疗方案与目标\n\n【处理要点】\n痉挛评估与记录：按MAS评分记录各肌群张力、关节活动度与疼痛，评估功能影响（护理、坐位与步行）\n诱因监测与处理：密切观察尿路感染（尿混浊、发热）、便秘、压疮与疼痛（痉挛加重的最常见原因）\n体位与护理：良肢位摆放、定时更换体位（每2小时）、避免不良体位诱发痉挛；会阴与皮肤护理（痉挛致清洁困难）\n用药护理：巴氯芬按时给药（不可骤停）、观察副作用（嗜睡、乏力、呼吸抑制）、替扎尼定监测血压与肝功能\n康复训练配合：按计划进行被动活动、牵伸与功能训练，记录关节活动度与耐受情况\n肉毒毒素注射后护理：观察疗效（2～4周起效）与不良反应（肌无力、吞咽困难与呼吸影响），记录注射部位\n宣教：痉挛管理需长期综合治疗、去除诱因的重要性、口服药不可骤停、按时复诊与功能评估\n\n【护理】\n痉挛与功能评估：按MAS评分记录肌张力、关节活动度与疼痛，观察功能与护理影响\n诱因观察：每日检查尿路（尿混浊、发热）、肠道（便秘）、皮肤（压疮）与下肢（深静脉血栓），异常立即报告\n体位与皮肤护理：良肢位摆放、每2小时更换体位、会阴与皮肤清洁（痉挛致清洁困难者需耐心与技巧）\n用药护理：巴氯芬按时给药并观察副作用（嗜睡、乏力）与戒断风险（不可骤停）；替扎尼定监测血压\n康复训练配合：协助被动活动与牵伸（每日多次）、记录关节活动度与耐受，鼓励主动参与功能训练\n肉毒毒素注射后观察：记录疗效（2～4周）与不良反应（无力、吞咽困难），异常报告\n宣教：去除诱因的重要性、口服药不可骤停、坚持康复训练与预防挛缩、按时复诊评估\n\n【饮食】\n均衡饮食，保证蛋白与热量（康复训练需求增加）\n高纤维饮食与充足水分（防便秘——便秘加重痉挛）\n钙与维生素D补充（长期卧床与抗癫痫药者防骨质疏松）\n巴氯芬与替扎尼定服用者避免饮酒（加重镇静与低血压）\n吞咽障碍者按评估调整食物性状（防误吸）\n\n【注意事项】\n痉挛突然加重首先寻找诱因（尿路感染、便秘、压疮、深静脉血栓与疼痛），而非立即加药\n巴氯芬口服不可骤停（可致戒断综合征、幻觉与癫痫）；鞘内巴氯芬过量可致呼吸抑制（急症）\n治疗目标应个体化：有的患者需要一定肌张力维持站立（过度降低张力反而影响功能）\n肉毒毒素是局灶性痉挛的首选（效果维持3～6个月，需重复注射）\n预防挛缩需早期、持续的被动活动与牵伸（每日多次），不可依赖药物\n\n【急诊/急救】\n鞘内巴氯芬过量（嗜睡、呼吸抑制与意识障碍）→ 立即停药、支持呼吸（必要时机械通气）并急诊评估\n口服巴氯芬突然停药（幻觉、躁动、癫痫）→ 立即恢复用药并监护（戒断综合征）\n痉挛突然加重伴高热与尿混浊（尿路感染）→ 尿培养+抗感染+去除诱因\n严重痉挛致关节挛缩急性疼痛或骨折（骨质疏松者）→ 影像评估与镇痛，调整治疗\n肉毒毒素注射后出现吞咽困难与呼吸困难 → 立即评估气道与吞咽功能，必要时住院观察","资料来源":"疾病库 diseases.json"},"icd10_diagnosis":"R25.2","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2537,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"053aaee9b9f1c81540a0ea9f5ac49058c9fb20a3c66bc91a86eb5f989928cce5","pinyin":"jingluanzhuangtaiguanli(jizhanglizenggao)","initials":"jlztgl(jzlzg)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","R25.2",30]]},{"id":"templates-bd97fe057c1249cca2cb","key":"v1-c9ccc21dfe2a3058|templates-bd97fe057c1249cca2cb","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痉证(中医辨证)","category":"中医","raw":{"name":"痉证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】项背强直、四肢抽搐、角弓反张（重者）、发热与恶寒（邪壅经络或热甚发痉）、神志改变（昏迷与谵妄，颅内感染）、牙关紧闭、苦笑面容与吞咽困难（破伤风）、手足搐搦与肌肉痉挛（低钙抽搐）。\n【待人工确认·本机素材无此段原文】","现病史":"痉证是以项背强直、四肢抽搐甚至角弓反张为主症的病证，相当于西医破伤风、颅内感染（脑膜炎与脑炎）、癫痫、高热惊厥与低钙抽搐。辨证分邪壅经络、热甚发痉、阴血亏虚与瘀血内阻四型；治疗需先明确西医病因（颅内感染与破伤风为急症）。\n常见表现：项背强直、四肢抽搐、角弓反张（重者）、发热与恶寒（邪壅经络或热甚发痉）、神志改变（昏迷与谵妄，颅内感染）、牙关紧闭、苦笑面容与吞咽困难（破伤风）、手足搐搦与肌肉痉挛（低钙抽搐）。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温（感染与高热）、心率、呼吸（痉挛致呼吸抑制）与血压\n神经系统：意识（GCS）、瞳孔与对光反射、脑膜刺激征（颈项强直与Kernig征）与病理反射\n肌肉与姿势：角弓反张、四肢抽搐形式与肌张力、牙关紧闭与苦笑面容（破伤风）\n皮肤与伤口：外伤史与伤口情况（破伤风）、皮疹与出血点（感染）\n低钙体征：Chvostek征与Trousseau征、腱反射亢进\n中医四诊：舌质与舌苔（辨证）、脉象（弦紧或细弱）\n其他：呼吸音（吸入性肺炎）、颈静脉充盈（颅压增高）与球结膜水肿","辅助检查":"1. 腰椎穿刺（疑颅内感染，先评估颅压）：脑脊液细胞数、生化、涂片与培养\n2. 头颅CT/MRI：颅内感染、出血、占位与脑水肿\n3. 电解质（钙、钠、镁）+血糖：低钙、低钠与低血糖（可逆抽搐病因）\n4. 血气分析+乳酸：酸碱与灌注状态\n5. 脑电图（癫痫）：痫样放电与发作类型\n6. 血培养+CRP+PCT（感染）：病原学\n7. 伤口培养（破伤风与感染）：必要时","初步诊断":"1. 中医辨证分型：邪壅经络（项背强直伴恶寒发热与苔白腻）、热甚发痉（高热与抽搐、舌红苔黄）、阴血亏虚（抽搐无力伴面色苍白与舌淡）、瘀血内阻（抽搐伴头痛与舌紫暗）\n2. 西医检查（必做）：腰椎穿刺（脑脊液检查，颅内感染）、头颅CT/MRI、血钙与电解质、脑电图（癫痫）与破伤风临床诊断\n3. 辨证要点：项背强直+四肢抽搐+角弓反张（虚实夹杂，需分标本）\n4. 鉴别：痫病（发作性意识丧失与抽搐、缓解期如常）、厥证（突然昏倒但无抽搐）与颤证（震颤但不强直）\n5. 急症识别：颅内感染（发热+头痛+颈项强直）、破伤风（牙关紧闭+苦笑面容+外伤史）与低钙（手足搐搦+Chvostek征）\n6. 注意：痉证需先明确病因（不可仅用熄风止痉中药延误颅内感染与破伤风的治疗）\n7. 疗效评估：抽搐控制与意识恢复、电解质与脑脊液改善\n1. 痉证(中医辨证)（ICD-10：R56.8）","鉴别诊断":"1. 鉴别：痫病（发作性意识丧失与抽搐、缓解期如常）、厥证（突然昏倒但无抽搐）与颤证（震颤但不强直）","处理方案":"【药物治疗·输液】\n⚠️ 抽搐发作需立即止惊；颅内感染与破伤风为急症！\n\n方案1（止惊治疗）：\n 用法：地西泮 10mg 缓慢静推（速度≤2mg/min，监测呼吸）；或 咪达唑仑 5～10mg 肌注；持续发作者 苯巴比妥 15～20mg/kg 静滴（负荷）或 丙戊酸钠 15～20mg/kg 静滴\n\n方案2（颅内感染，经验性抗感染）：\n 用法：头孢曲松 2g 静滴 q12h + 万古霉素 1g 静滴 q12h（疑MRSA）+ 阿昔洛韦 10mg/kg 静滴 q8h（疑病毒性脑炎）；颅压增高者 20%甘露醇 125～250ml 静滴 q6～8h\n\n方案3（破伤风，综合治疗）：\n 用法：破伤风抗毒素 2万～5万U + 0.9%氯化钠 500ml 静滴（或 破伤风免疫球蛋白 3000～6000IU 肌注）；青霉素 480万U 静滴 q8h（杀灭破伤风梭菌）；地西泮 10～20mg 静推 q4～6h（控制痉挛）；必要时 硫酸镁 静滴与气管切开（重症）\n\n方案4（低钙与代谢性抽搐）：\n 用法：10%葡萄糖酸钙 10～20ml 缓慢静推（低钙抽搐）；25%硫酸镁 10ml 静滴（低镁）；纠正低钠与低血糖（10%葡萄糖 静滴）\n\n📌 痉证治疗需先明确病因（颅内感染与破伤风必须急诊处理）；止惊以地西泮为主（缓慢静推并监测呼吸）；破伤风需隔离、避光与安静环境（减少痉挛诱因）。\n\n【药物治疗·口服】\n⚠️ 病因治疗与中药辨证方（需在明确西医诊断后使用）：\n\n药物1（中药辨证方）：\n 用法：邪壅经络——羌活胜湿汤（祛风散寒除湿）；热甚发痉——增液承气汤或白虎汤合羚角钩藤汤（清热熄风）；阴血亏虚——四物汤合大定风珠（养血滋阴熄风）；瘀血内阻——通窍活血汤（活血通窍）\n\n药物2（中成药）：\n 用法：安宫牛黄丸 1丸 鼻饲（热闭神昏，急症）；紫雪散（高热抽搐）或 至宝丹（痰热内闭）；牛黄清心丸（恢复期）\n\n药物3（西医病因治疗）：\n 用法：抗癫痫药（左乙拉西坦 500mg bid 或 丙戊酸钠 500mg bid，不可骤停）；抗感染（抗生素与抗病毒药按方案）；补钙与维生素D（低钙者）\n\n药物4（支持与营养）：\n 用法：复合维生素B 2片 tid；甲钴胺 0.5mg tid（神经修复）；维生素D 800IU/日 + 碳酸钙D3 600mg qd（低钙与骨质疏松）\n\n📌 安宫牛黄丸等开窍剂用于热闭急症（鼻饲，孕妇慎用）；抗癫痫药不可骤停（可诱发持续状态）；破伤风与颅内感染需住院治疗。\n\n【治疗】\n病因治疗（首要）：颅内感染（抗生素与抗病毒药+降颅压）、破伤风（抗毒素+镇静解痉+抗生素+伤口处理）、癫痫（抗癫痫药）、低钙与电解质紊乱（纠正）与高热（退热与物理降温）\n止惊与镇静：地西泮（一线）、咪达唑仑、苯巴比妥与丙泊酚（难治性需ICU与机械通气）\n中医辨证治疗：邪壅经络（祛风散寒）、热甚发痉（清热熄风）、阴血亏虚（滋阴养血熄风）、瘀血内阻（活血通窍）\n针灸辅助：人中、合谷、太冲、阳陵泉与涌泉（熄风止痉，急症辅助）\n环境与护理（破伤风）：隔离、避光、安静与减少刺激（声光刺激可诱发痉挛）、避免不必要的操作\n支持治疗：气道保护（吸氧与必要时插管）、营养支持（鼻饲或静脉营养）、纠正电解质与酸碱失衡\n并发症处理：感染（吸入性肺炎）、横纹肌溶解（补液与碱化尿液）、骨折（痉挛致）与颅内压增高\n随访：神经系统后遗症（癫痫与认知）、抗癫痫药调整与康复治疗；破伤风需疫苗接种（主动免疫）\n\n【处理要点】\n止惊与气道护理：发作时侧卧与保护气道（防误吸）、吸氧、记录抽搐时间与形式、备插管与吸引设备\n用药护理：地西泮缓慢静推并监测呼吸（备复苏设备）；观察抗癫痫药与镇静药不良反应\n环境护理（破伤风重点）：单间隔离、避光与安静、减少刺激与操作（声光与触碰可诱发痉挛）\n生命体征与意识监测：体温、心率、呼吸、血压与意识（GCS），神经体征变化（瞳孔与肌力）\n营养与输液护理：不能进食者鼻饲或静脉营养（破伤风患者需高热量与高蛋白）；记录出入量\n并发症观察：吸入性肺炎（发热与肺部啰音）、骨折（痉挛致剧痛与畸形）与横纹肌溶解（尿色深）\n宣教：抗癫痫药不可骤停、破伤风需疫苗接种与伤口正确处理、按时随访（神经系统后遗症与康复）\n\n【护理】\n止惊护理：发作时侧卧保护气道、吸氧与吸引、记录发作时间与表现，>5分钟立即报告\n用药护理：地西泮缓慢静推并监测呼吸；抗癫痫药与镇静药按时给药并观察不良反应\n环境护理（破伤风）：单间隔离、避光安静、减少刺激与操作、集中护理以减少痉挛诱发\n生命体征与神经观察：每1～2小时（急性期）监测意识、瞳孔与生命体征，异常立即报告\n营养与管道护理：不能进食者鼻饲（高热量与高蛋白）或静脉营养，记录出入量；口腔护理\n宣教：抗癫痫药不可骤停、破伤风需疫苗接种与伤口正确处理、按时随访神经系统与康复指导\n\n【饮食】\n急性期：禁食（防误吸与抽搐时窒息），静脉营养支持；稳定后鼻饲\n破伤风患者：高热量（30～40kcal/kg/日）与高蛋白（1.5～2g/kg/日）营养（痉挛消耗大）\n癫痫患者：规律进餐（避免低血糖诱发）、生酮饮食（药物难治性癫痫，需专科指导）\n低钙者：高钙饮食（牛奶、豆制品与小鱼虾）+ 维生素D\n避免酒精与咖啡因（降低发作阈值）；抽搐控制后逐步恢复经口进食（防误吸）\n\n【注意事项】\n痉证需先明确西医病因——颅内感染与破伤风为急症（不可仅用中药熄风止痉延误治疗）\n破伤风的关键处理是抗毒素（中和游离毒素）+镇静解痉+抗生素+伤口清创，环境需避光安静\n颅压增高者腰椎穿刺需谨慎（先脱水与CT评估，防脑疝）\n地西泮静推须缓慢（≤2mg/min）并监测呼吸（呼吸抑制风险）\n抗癫痫药不可骤停（漏服与停药是癫痫持续状态最常见诱因）；破伤风患者需主动免疫（疫苗）\n\n【急诊/急救】\n抽搐持续>5分钟或反复发作（癫痫持续状态）→ 立即地西泮静推+二线负荷药，保护气道\n破伤风痉挛发作伴呼吸困难（喉痉挛与呼吸肌痉挛）→ 立即镇静解痉+吸氧，必要时气管切开与机械通气\n颅内感染伴意识恶化与瞳孔不等大（脑疝）→ 立即甘露醇脱水+激素，急诊CT与神经外科会诊\n低钙抽搐伴喉痉挛 → 立即缓慢静推葡萄糖酸钙+吸氧\n高热抽搐（体温>40℃）→ 立即物理降温与退热药，止惊与补液","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「痉证（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痉证\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、邪壅经络\n    症状舌脉：头痛，项背强直，恶寒发热，肢体酸重，甚至口噤不语，四肢抽搐；舌苔白腻，脉浮紧\n    治法：祛风散寒、燥湿和营\n    方剂：羌活胜湿汤加减（羌活、独活、防风、藁本、川芎、蔓荆子、甘草）\n\n二、热甚发痉\n    症状舌脉：发热胸闷，口噤齿介齿，项背强直，甚至角弓反张，手足挛急，腹胀便秘；舌红苔黄腻，脉弦数\n    治法：泄热存津、养阴增液\n    方剂：增液承气汤加减（玄参、麦冬、生地黄、大黄、芒硝）\n\n三、阴血亏虚\n    症状舌脉：项背强急，四肢抽搐，头目昏眩，自汗，神疲气短；舌淡红、苔薄白，脉弦细\n    治法：滋阴养血、柔筋止痉\n    方剂：四物汤合大定风珠加减（当归、熟地黄、白芍、川芎、阿胶、龟板、牡蛎、鳖甲）\n\n四、肝经热盛\n    症状舌脉：高热头痛，口噤齿介齿，手足躁动，项背强急，四肢抽搐，甚则角弓反张；舌红绛、苔黄燥，脉弦细数\n    治法：清肝潜阳、息风镇痉\n    方剂：羚角钩藤汤加减（羚羊角、钩藤、桑叶、菊花、生地黄、白芍、川贝母、竹茹、茯神）\n\n【西医诊断】\n  破伤风 / 脑膜炎 / 癫痫等\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ **须立即查明病因**（脑膜炎、破伤风、癫痫、低钙等），不可仅对症止痉\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R56.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2538,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"c1e3b85bb1dabfc9fd155b46a279db6833fbd069dead812f5ccd00ff3af769ea","pinyin":"jingzheng(zhongyibianzheng)","initials":"jz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R56.8",30]]},{"id":"templates-465342403452cf2d91f1","key":"v1-c9ccc21dfe2a3058|templates-465342403452cf2d91f1","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痔(中医辨证)","category":"中医","raw":{"name":"痔(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】便血、痔核脱出、肛门疼痛、肛门瘙痒、便秘。\n【待人工确认·本机素材无此段原文】","现病史":"痔是直肠末端黏膜下和肛管皮肤下的直肠静脉丛发生扩大、曲张所形成的柔软静脉团。\n常见表现：便血、痔核脱出、肛门疼痛、肛门瘙痒、便秘。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者反复便血、痔核脱出、肛门疼痛瘙痒伴便秘，为湿热下注、脉络瘀阻之象；首先完善肛门视诊及肛门指检，了解痔核部位、数目、脱出程度及肛管有无狭窄，并排除直肠下段肿物；完善肛门镜检查明确内痔的分期与出血点，是确诊痔及选择治疗方式的直接依据；患者反复便血，完善血常规检查明确有无失血性贫血及感染，评估贫血程度以决定是否需要输血或纠正贫血；查凝血功能检查排除凝血功能障碍所致出血，为可能的手术治疗做准备；患者需行痔切除或套扎等手术治疗，术前完善肝肾功能及心电图检查评估手术耐受性、排除手术禁忌，并查血型+交叉配血做好术中输血准备；患者反复便血、年龄偏大或有排便习惯改变者，完善结肠镜检查排除结直肠肿瘤、息肉、炎症性肠病等其他便血原因，尤其便血伴黏液、体重下降时不可仅按痔处理；患者便秘明显，查甲状腺功能排除甲状腺功能减退所致便秘，并查血糖评估创面愈合能力。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 内痔：便血，痔核脱出，肛门不适。\n2. 外痔：肛门坠胀，疼痛，有异物感。\n3. 混合痔：兼有内外痔的症状。\n4. 肛门指检或肛门镜检查可确诊。\n1. 痔(中医辨证)（ICD-10：K64.9）","鉴别诊断":"1. 痔与肛裂鉴别：肛裂以肛门周期性疼痛、便血、便秘为特征，肛门检查可见裂口","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（湿热下注）：\n 用法：清开灵注射液40ml+5%GS250ml静滴qd\n\n方案2（脾虚气陷）：\n 用法：参麦注射液40ml+5%GS250ml静滴qd\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（风热肠燥）：\n 用法：凉血地黄汤加减（生地9g 当归9g 槐角9g 黄连6g 黄芩9g 升麻3g 赤芍9g 枳壳9g 荆芥6g 甘草3g）\n\n药物2（湿热下注）：\n 用法：脏连丸加减（黄连6g 黄芩9g 赤芍9g 当归9g 阿胶9g 荆芥6g 地榆9g 槐花9g）\n\n药物3（气滞血瘀）：\n 用法：止痛如神汤加减（秦艽9g 桃仁9g 皂角刺9g 苍术9g 防风9g 黄柏9g 当归尾9g 泽泻9g 槟榔6g 大黄6g）\n\n药物4（脾虚气陷）：\n 用法：补中益气汤加减（黄芪15g 人参6g 白术9g 炙甘草3g 当归9g 陈皮6g 升麻3g 柴胡6g 生姜3片 大枣3枚）\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n针灸：取长强、承山、二白、百会；湿热加阴陵泉，气虚加脾俞、足三里\n外治：苦参汤煎水熏洗（苦参、蛇床子、白芷、金银花、菊花、黄柏、地肤子、石菖蒲），外敷马应龙麝香痔疮膏\n塞药：痔疮栓纳入肛内\n挑治：在背部寻找痔点，用三棱针挑破\n\n【处理要点】\n养成定时排便习惯，保持大便通畅\n多吃蔬菜水果，多饮水\n忌辛辣刺激，戒烟酒\n避免久坐久站，适当运动\n\n【护理】\n情志护理：痔病反复出血、脱出易致患者焦虑恐惧，需耐心疏导，嘱其避免恼怒忧思，因肝郁化火、心火下迫可加重便血肿痛；手术前后尤应安定情绪，防止紧张致排便困难。\n起居调护：忌久坐久站、负重屏气，每坐1小时起身活动；养成定时排便习惯，如厕勿久蹲努挣，便后温水清洗肛门；避免熬夜、劳累过度，脾虚气陷者尤须注意休息，防中气下陷加重脱出。\n病情观察：密切观察便血颜色、量及血色（鲜红多属风热/湿热下注，暗淡多为脾虚气陷），有无滴血、射血及贫血、头晕；观察痔核脱出程度、能否自行回纳，嵌顿者见剧烈疼痛、肿胀应立即报告；注意有无发热、脓血便等感染征象。\n煎药服药护理：凉血止血、清热利湿药宜温服或凉服，饭前服用以利药力下达；服活血化瘀药时观察有无出血倾向；外用熏洗药煎好后先熏后洗，水温40℃左右，每次15～20分钟，注意防止烫伤，经期、痔核急性嵌顿出血期慎用。\n外治护理：遵医嘱予中药坐浴、肛内纳栓或外涂膏药，操作前排空二便，动作轻柔；保持肛周清洁干燥，勤换内裤，穿宽松透气棉质内裤；术后患者注意伤口敷料渗血情况，便后换药，避免用力擦拭。\n\n【饮食】\n辨证忌口：湿热下注及风伤肠络者忌辛辣炙煿、肥甘厚味及醇酒，以免助热生湿、迫血妄行；脾虚气陷者忌生冷寒凉及滑肠之品（如冷饮、冰镇瓜果），防伤脾阳、中气愈陷；阴虚肠燥者忌辛辣温燥、煎炸之品，防伤阴动血。\n通便宜忌：多食富含膳食纤维之品（芹菜、菠菜、韭菜、香蕉、火龙果、粗粮等），晨起饮温蜂蜜水或淡盐水润肠；忌久服泻药及刺激性泻下之品，以免损伤脾胃、加重脱出；大便干燥者勿强行努挣。\n湿热下注证：宜食清热利湿、凉血解毒之品，如绿豆、赤小豆、薏苡仁、马齿苋、冬瓜、丝瓜；药膳可选槐花蜜饮（槐花15g煎水兑蜂蜜）凉血止血，或赤小豆薏米粥利湿消肿。\n脾虚气陷证：宜食健脾益气、升提固脱之品，如山药、莲子、芡实、大枣、黄芪炖鸡、猪大肠炖黄芪；药膳可选黄芪升麻粥或山药芡实粥，补中气以助痔核回纳。\n阴虚肠燥证：宜食滋阴润燥、养血通便之品，如黑芝麻、核桃仁、桑葚、松子仁、蜂蜜、香蕉、银耳；药膳可选木耳柿饼汤（黑木耳、柿饼同煮）养血润肠，或桑葚蜂蜜膏滋阴润肠，忌浓茶、烈酒。\n\n【注意事项】\n痔与肛裂鉴别：肛裂以肛门周期性疼痛、便血、便秘为特征，肛门检查可见裂口；痔以便血、痔核脱出为特征，肛门镜可见痔核。\n\n【急诊/急救】\n痔伴大量便血、贫血、痔核嵌顿坏死，及时肛肠科处理。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「痔（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痔\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、风伤肠络\n    症状舌脉：大便带血，血色鲜红，滴血或喷射状，量较多，肛门不痛或有轻微坠胀，大便干结，舌红苔薄黄，脉浮数\n    治法：清热凉血、疏风止血\n    方剂：凉血地黄汤\n\n二、湿热下注\n    症状舌脉：肛门肿痛，痔核脱出嵌顿，局部灼热，便血鲜红，肛门潮湿瘙痒，大便黏滞不爽，小便黄，舌红苔黄腻，脉滑数\n    治法：清热利湿、止血消肿\n    方剂：脏连丸\n\n三、气滞血瘀\n    症状舌脉：肛门坠胀疼痛，痔核脱出，色暗红或青紫，触痛明显，排便时加重，舌暗红有瘀点、苔薄，脉弦涩\n    治法：行气活血、化瘀止痛\n    方剂：止痛如神汤\n\n四、脾虚气陷\n    症状舌脉：肛门坠胀，痔核脱出需手托回纳，便血色淡，神疲乏力，气短懒言，面色萎黄，食少便溏，舌淡苔薄白，脉细弱\n    治法：补中益气、升阳举陷\n    方剂：补中益气汤\n\n【方剂参考】\n  凉血地黄汤：组成 生地黄15g、当归尾9g、地榆12g、槐角9g、黄连6g、天花粉12g、甘草3g、升麻6g、赤芍9g、枳壳9g、黄芩9g、荆芥9g；功效 清热凉血，祛风润燥\n      用法：水煎温服，日一剂，分二次服。\n      注意：脾胃虚寒者忌用；孕妇慎用；便血须先经肛肠专科检查（含肛门指检、肠镜）除外直肠癌等恶性病变。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂；原方出自《外科大成·卷二》\n  脏连丸：组成 黄连9g（研末）、公猪大肠1尺（约30cm，煮烂捣为丸，现代多作汤剂以猪大肠适量煎汤代水）；功效 清肠化湿，凉血止血\n      用法：水煎（以猪大肠煎汤代水），温服，日一剂，分二次服；原方为丸剂，每服6-9g，日二次。\n      注意：脾胃虚寒者不宜；黄连苦寒，中病即止；便血须先经肛门直肠专科检查除外直肠癌等恶性病变；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂；原方出自《外科正宗·卷三》\n  止痛如神汤：组成 秦艽9g、桃仁9g、皂角子9g、苍术9g、防风9g、黄柏9g、当归尾9g、泽泻9g、槟榔6g、熟大黄9g；功效 清热祛风，活血止痛\n      用法：水煎，空腹温服，日一剂，分二次服。\n      注意：孕妇禁用；脾胃虚寒者慎用；须先经专科检查明确诊断；便血反复者须除外直肠恶性病变。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂；原方出自《外科启玄·卷十二》\n  补中益气汤：组成 黄芪18g、炙甘草9g、人参6g、当归3g、橘皮6g、升麻6g、柴胡6g、白术9g；功效 补中益气，升阳举陷\n      用法：水煎温服，日二次，食远（饭后较久）服；亦可作丸剂，每次6-9g，日二次，姜枣汤或温开水送下。\n      注意：阴虚火旺、肝阳上亢及感冒发热者忌用（甘温易助热）；升麻、柴胡升提，高血压及气逆喘满者慎用。\n\n【西医诊断】\n  痔\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"K64.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2539,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"0a8993d5263e0e8db9b7e7076f51417c677e593846366ef3d4957564a9f10378","pinyin":"zhi(zhongyibianzheng)","initials":"z(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","K64.9",30]]},{"id":"templates-67525bd14f49091cbc8f","key":"v1-c9ccc21dfe2a3058|templates-67525bd14f49091cbc8f","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痛经(中医辨证)","category":"中医","raw":{"name":"痛经(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】气滞血瘀：经前或经期小腹胀痛拒按，经行不畅，色紫暗有块，块下痛减，乳房胀痛、寒凝血瘀：经前或经期小腹冷痛拒按，得热痛减，经量少色暗有块，畏寒、湿热瘀阻：经前或经期小腹疼痛拒按，有灼热感，经色暗红质稠有块，带下量多黄稠、气血虚弱：经期或经后小腹隐痛喜按，月经量少色淡，神疲乏力、肾气亏损：经期或经后小腹绵绵作痛，喜按，经量少色暗淡，腰膝酸软。\n【待人工确认·本机素材无此段原文】","现病史":"妇女经期或经行前后出现周期性小腹疼痛或痛引腰骶，甚至剧痛晕厥。分气滞血瘀、寒凝血瘀、湿热瘀阻、气血虚弱、肾气亏损等证型。\n常见表现：气滞血瘀：经前或经期小腹胀痛拒按，经行不畅，色紫暗有块，块下痛减，乳房胀痛、寒凝血瘀：经前或经期小腹冷痛拒按，得热痛减，经量少色暗有块，畏寒、湿热瘀阻：经前或经期小腹疼痛拒按，有灼热感，经色暗红质稠有块，带下量多黄稠、气血虚弱：经期或经后小腹隐痛喜按，月经量少色淡，神疲乏力、肾气亏损：经期或经后小腹绵绵作痛，喜按，经量少色暗淡，腰膝酸软。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神（得神/少神/失神/假神/神乱）、色（常色/病色：青/赤/黄/白/黑，光泽/晦暗）、形态（形体胖瘦/动静姿态/异常动作）、头面（头颅/囟门/头发/面肿/口眼歪斜）、五官（目/耳/鼻/口/齿/龈/咽喉）、躯体（颈项/胸胁/腹部/腰背/四肢/皮肤）、舌诊（舌质：颜色/形质/动态；舌苔：苔色/苔质/润燥/厚薄/腻腐/剥落；舌底络脉）、排泄物（痰涎/呕吐物/大便/小便/经血/带下）\n闻诊：声音（语声/呼吸/咳嗽/喘哮/呃逆/嗳气/太息/肠鸣）、气味（口气/汗气/痰涕气味/二便气味/经带气味/病室气味）\n问诊：一般情况（姓名/性别/年龄/职业/籍贯）、主诉、现病史（起病情况/主症特点/病因诱因/病情发展/诊治经过/伴随症状）、既往史、个人史、家族史、十问歌（一问寒热二问汗，三问头身四问便，五问饮食六胸腹，七聋八渴俱当辨，九问旧病十问因，再兼服药参机变，妇女尤必问经期，迟速闭崩皆可见，再添片语告儿科，天花麻疹全占验）\n切诊：脉诊（部位：寸关尺；脉象：浮沉迟数虚实滑涩洪细濡弱弦紧结代促等，注意平脉/病脉/真脏脉）、按诊（按肌肤/按手足/按胸腹/按腧穴/按腹部，温度/湿度/压痛/包块/波动感）\n辨证：八纲辨证（表里/寒热/虚实/阴阳）、脏腑辨证、气血津液辨证、六经辨证、卫气营血辨证、三焦辨证、经络辨证","辅助检查":"检查计划：患者经前或经期小腹疼痛、拒按或喜按，伴经行不畅、色暗有块或腰膝酸软，为冲任气血运行不畅之象；首先完善妇科检查了解子宫大小、位置、活动度及附件有无压痛包块，排除盆腔炎性疾病及子宫内膜异位症所致继发性痛经；完善妇科B超检查了解子宫内膜厚度、有无子宫肌瘤、子宫腺肌症及卵巢子宫内膜异位囊肿，明确有无器质性病变，是鉴别原发性与继发性痛经的关键；患者小腹疼痛拒按、带下量多黄稠，完善血常规及CRP检查排除盆腔感染，如白细胞及CRP升高需考虑盆腔炎性疾病并规范抗感染治疗；患者腰膝酸软、经量少色暗淡，查性激素六项及抗苗勒管激素了解卵巢功能与内分泌状态，指导中医补肾调周治疗；查CA125协助诊断子宫内膜异位症，其升高常与内膜异位病灶活动相关；患者长期服用活血化瘀中药，完善肝肾功能及凝血功能检查排除肝肾功能不全及凝血异常，避免出血风险；查甲状腺功能排除甲状腺功能减退所致月经异常，经上述检查仍不能明确者，必要时行宫腔镜或腹腔镜检查明确宫腔内及盆腔病变，明确病因后再予辨证论治。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 经期周期性腹痛\n2. 妇科检查排除子宫内膜异位症、盆腔炎等\n3. B超辅助诊断\n1. 痛经(中医辨证)（ICD-10：N94.6）","鉴别诊断":"1. 妇科检查排除子宫内膜异位症、盆腔炎等","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液\n\n方案2（剧痛）：\n 用法：山莨菪碱10mg im，或阿托品0.5mg im\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（气滞血瘀）：\n 用法：血府逐瘀胶囊6粒 tid，或元胡止痛片4片 tid\n\n药物2（寒凝血瘀）：\n 用法：少腹逐瘀颗粒1袋 tid，或艾附暖宫丸1丸 tid\n\n药物3（湿热瘀阻）：\n 用法：清热调血汤1袋 tid，或妇科千金片4片 tid\n\n药物4（气血虚弱）：\n 用法：八珍颗粒1袋 tid，或乌鸡白凤丸1丸 tid\n\n药物5（肾气亏损）：\n 用法：调肝汤1袋 tid，或五子衍宗丸1丸 tid\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n气滞血瘀：理气行滞，化瘀止痛，膈下逐瘀汤\n寒凝血瘀：温经散寒，化瘀止痛，少腹逐瘀汤\n湿热瘀阻：清热除湿，化瘀止痛，清热调血汤\n气血虚弱：益气养血，调经止痛，圣愈汤\n肾气亏损：补肾益精，养血止痛，调肝汤\n\n【处理要点】\n经期注意保暖，忌生冷\n保持心情舒畅\n热敷下腹部\n避免剧烈运动\n\n【护理】\n情志护理：痛经多与情志不遂、肝气郁结相关，经前及经期避免恼怒、抑郁，引导患者听舒缓音乐、深呼吸以疏解情绪；气血虚弱者忌思虑过度、劳神耗血，多予鼓励安慰。\n起居调护：经期注意下腹及足部保暖，忌冒雨涉水、久坐凉地；寒凝血瘀者可用热水袋敷小腹、睡前温水泡脚；气血虚弱者经期宜静养，避免剧烈运动及重体力劳动；湿热者居处宜干燥通风，勤换卫生用品以防感染。\n病情观察：观察经色、经量、经质及血块情况，记录腹痛部位、性质、时间及与经期关系；注意是否伴恶心呕吐、冷汗、晕厥等；若腹痛剧烈难忍、经量暴增或经期延长不止，及时报告医师，警惕器质性病变。\n煎药服药护理：辨证属寒者汤药宜温服，属热者宜凉服；经前3～5天即开始服药以调理气血、预防发作，经期痛时按医嘱及时服药；气滞者饭后半小时温服，服后稍事活动助药力行散。\n外治护理：寒凝血瘀证可予艾灸关元、气海、三阴交，或中药热敷小腹，注意防烫伤；气滞血瘀证可循经按摩小腹及腰骶部，力度适中；湿热瘀阻证慎用灸法，可予清凉外敷并保持局部清洁。\n\n【饮食】\n寒凝血瘀证：忌食生冷瓜果、冰镇饮料及寒凉之品，经期尤忌；宜食温热食物，如生姜红糖水、桂圆、羊肉汤，可饮艾叶煮鸡蛋温经散寒止痛。\n气滞血瘀证：忌食酸涩收敛之物（如乌梅、柿子）以防气机壅滞，忌肥甘厚味助湿生痰；宜食行气活血之品，如山楂红糖水、玫瑰花茶、佛手陈皮饮，经前连饮数日。\n湿热瘀阻证：忌辛辣燥热、肥甘厚腻及酒类，以免助湿生热；宜食清热利湿之品，如薏苡仁赤小豆粥、冬瓜汤、绿豆汤，保持二便通畅。\n气血虚弱证：忌食生冷及辛辣耗气之品，忌暴饮暴食；宜食补气养血之品，如当归生姜羊肉汤、红枣桂圆粥、乌鸡汤，经后进补更宜。\n肾气亏损证：忌食寒凉伤阳之品；宜食补肾填精之品，如枸杞山药粥、黑芝麻核桃糊、桑葚，平时可常食，以固肾气、调冲任。\n\n【注意事项】\n继发性痛经需治疗原发病\n止痛药不宜长期大量服用\n不孕者需排查子宫内膜异位症\n\n【急诊/急救】\n剧痛晕厥：平卧，阿托品0.5mg im，及时就诊","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「痛经（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痛经\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、气滞血瘀\n    症状舌脉：经前或经期小腹胀痛拒按，经血量少不畅，色紫暗有块，块下痛减，胸胁乳房胀痛，舌紫暗有瘀点，脉弦\n    治法：行气活血、化瘀止痛\n    方剂：膈下逐瘀汤\n\n二、寒凝血瘀\n    症状舌脉：经前或经期小腹冷痛，得热痛减，经量少色暗有块，畏寒肢冷，面色青白，舌暗苔白，脉沉紧\n    治法：温经散寒、化瘀止痛\n    方剂：少腹逐瘀汤\n\n三、湿热瘀阻\n    症状舌脉：经前或经期小腹灼痛拒按，得热痛增，经色暗红质稠有块，带下黄稠臭秽，小便黄赤，舌红苔黄腻，脉滑数\n    治法：清热除湿、化瘀止痛\n    方剂：清热调血汤\n\n四、气血虚弱\n    症状舌脉：经期或经后小腹隐痛喜按，经量少色淡质稀，神疲乏力，气短懒言，面色萎黄，舌淡苔薄白，脉细弱\n    治法：益气养血、和中止痛\n    方剂：圣愈汤\n\n五、肝肾亏虚\n    症状舌脉：经后小腹绵绵作痛，腰骶酸胀，经量少色淡，头晕耳鸣，腰膝酸软，舌淡红少苔，脉沉细\n    治法：滋养肝肾、调经止痛\n    方剂：调肝汤\n\n【方剂参考】\n  膈下逐瘀汤：组成 五灵脂6g（炒）、当归9g、川芎6g、桃仁9g、牡丹皮6g、赤芍6g、乌药6g、延胡索3g、甘草9g、香附4.5g、红花9g、枳壳4.5g；功效 活血逐瘀，破癥消结\n      用法：水煎温服，日一剂，分二次服；病轻者少服，病重者多服，病去药止。\n      注意：孕妇忌用；有出血倾向者及体虚无瘀者忌用；本方法瘀破结力强，不可多服久服。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷上》\n  少腹逐瘀汤：组成 小茴香1.5g（炒）、干姜3g（炒）、延胡索3g、没药6g（研）、当归9g、川芎6g、肉桂3g、赤芍6g、蒲黄9g（生）、五灵脂6g（炒）；功效 活血祛瘀，温经止痛\n      用法：水煎温服，日一剂，分二次服；亦可研末为散，每次6g，温酒送服。\n      注意：孕妇忌用（本方原书用于安胎，须身体壮实、确有瘀血可据者，且应遵医嘱）；月经过多、有出血倾向者慎用；体虚无瘀者不宜。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n  清热调血汤：组成 牡丹皮9g、黄连6g、生地黄12g、当归9g、白芍12g、川芎6g、红花6g、桃仁9g、莪术9g、香附9g、延胡索9g；功效 清热除湿，化瘀止痛\n      用法：水煎温服，日一剂，分二次服。\n      注意：孕妇禁用；气血虚弱、虚寒性痛经者忌用；黄连苦寒，脾胃虚寒者慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《古今医鉴·卷十一》\n  圣愈汤：组成 熟地黄15g、白芍12g、当归9g、川芎6g、人参6g（另煎兑服，或党参15g代）、黄芪15g；功效 益气，补血，摄血\n      用法：水煎温服，日一剂，分二次服；人参宜另煎兑服。\n      注意：血热妄行之月经先期、量多色深者忌用；瘀血阻滞者不宜；服人参期间忌萝卜、浓茶。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补气）；原方出自《医宗金鉴·删补名医方论》（《兰室秘藏》方）\n  调肝汤：组成 山药15g、阿胶12g（烊化）、当归9g、白芍12g、山茱萸12g、巴戟天9g、甘草3g；功效 补益肾水，平调肝气\n      用法：水煎，阿胶烊化，温服，日一剂，分二次服。\n      注意：湿热瘀阻、气滞血瘀之痛经忌用；脾虚湿盛、食少便溏者慎用；痛经进行性加重者须除外子宫内膜异位症、子宫腺肌病。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂；原方出自《傅青主女科·卷上·调经》\n\n【西医诊断】\n  原发性痛经\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"N94.6","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2540,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"57378dd9968d4d9339e62d594f1ae5d3814701f7c084c1dd2860fa27d348e31e","pinyin":"tongjing(zhongyibianzheng)","initials":"tj(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","N94.6",30]]},{"id":"templates-56de2fefb57f89055f6d","key":"v1-c9ccc21dfe2a3058|templates-56de2fefb57f89055f6d","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痞满(中医辨证)","category":"中医","raw":{"name":"痞满(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】饮食内停：脘腹痞闷而胀，进食尤甚，嗳腐吞酸，恶食呕吐，苔厚腻，脉弦滑、痰湿中阻：脘腹痞塞不舒，胸膈满闷，头晕目眩，身重困倦，呕恶纳呆，苔白厚腻，脉沉滑、湿热阻胃：脘腹痞闷，或嘈杂不舒，恶心呕吐，口干不欲饮，口苦，纳少，舌红苔黄腻，脉滑数、肝胃不和：脘腹痞闷，胸胁胀满，心烦易怒，善太息，呕恶嗳气，舌淡红苔薄白，脉弦、脾胃虚弱：脘腹满闷，时轻时重，喜温喜按，纳呆便溏，神疲乏力，少气懒言，舌淡苔薄白，脉细弱、胃阴不足：脘腹痞闷，嘈杂，饥不欲食，恶心嗳气，口燥咽干，大便干结，舌红少苔，脉细数。\n【待人工确认·本机素材无此段原文】","现病史":"痞满是心下痞塞、胸膈满闷、触之无形、按之不痛为主要症状的脾胃病证。分实痞（食积、痰湿、湿热、气滞）与虚痞（脾胃虚弱）。可见于功能性消化不良、慢性胃炎、胃下垂等。\n常见表现：饮食内停：脘腹痞闷而胀，进食尤甚，嗳腐吞酸，恶食呕吐，苔厚腻，脉弦滑、痰湿中阻：脘腹痞塞不舒，胸膈满闷，头晕目眩，身重困倦，呕恶纳呆，苔白厚腻，脉沉滑、湿热阻胃：脘腹痞闷，或嘈杂不舒，恶心呕吐，口干不欲饮，口苦，纳少，舌红苔黄腻，脉滑数、肝胃不和：脘腹痞闷，胸胁胀满，心烦易怒，善太息，呕恶嗳气，舌淡红苔薄白，脉弦、脾胃虚弱：脘腹满闷，时轻时重，喜温喜按，纳呆便溏，神疲乏力，少气懒言，舌淡苔薄白，脉细弱、胃阴不足：脘腹痞闷，嘈杂，饥不欲食，恶心嗳气，口燥咽干，大便干结，舌红少苔，脉细数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以脘腹痞塞、胸膈满闷、触之无形、按之不痛为主症，进食后加重，伴嗳腐吞酸、恶食呕吐、纳呆便溏、神疲乏力，舌苔厚腻，脉弦滑或细弱，初步诊断为痞满（ICD-10：K30），可见于功能性消化不良、慢性胃炎、胃下垂等，需完善检查明确病因并排除器质性疾病。完善血常规检查排除感染、贫血所致；完善CRP检查了解有无炎症反应；患者长期纳差、饮食内停，用药治疗需经肝肾代谢，完善肝肾功能检查排除肝肾功能不全；患者恶食呕吐、苔厚腻，有幽门螺杆菌感染可能，查幽门螺杆菌检测明确有无感染，以指导是否根除治疗；患者便溏、神疲乏力、少气懒言，完善粪常规加隐血检查排除消化道出血、肠道寄生虫感染；腹部B超排除肝胆胰脾病变所致痞满；胃镜入院后择期完善，排除消化性溃疡、慢性胃炎、胃部肿瘤等器质性疾病。患者恶心呕吐、纳呆明显，完善电解质及血糖检查排除电解质紊乱、糖尿病胃轻瘫所致；查心电图排除心脏疾病所致上腹不适，动态观察病情变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 心下痞塞、胸膈满闷、按之不痛为主症\n2. 胃镜、腹部B超排除器质性疾病\n3. 慢性病程，反复发作\n1. 痞满(中医辨证)（ICD-10：K30）","鉴别诊断":"1. 胃镜、腹部B超排除器质性疾病","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（饮食内停）：保和丸6-9g tid，或枳术宽中胶囊3粒 tid\n药物2（痰湿中阻）：香砂六君丸6g tid，或木香顺气丸6g tid\n药物3（湿热阻胃）：三九胃泰颗粒10g bid，或枳实导滞丸6g tid\n药物4（肝胃不和）：舒肝和胃丸6g tid，或气滞胃痛颗粒5g tid\n药物5（脾胃虚弱）：补中益气丸6g tid，或参苓白术散6g tid\n药物6（胃阴不足）：养胃舒胶囊3粒 tid，或阴虚胃痛颗粒10g tid\n\n【治疗】\n饮食内停：消食导滞，行气消痞，保和丸加减\n痰湿中阻：除湿化痰，理气和中，二陈汤加减\n湿热阻胃：清热化湿，和胃消痞，泻心汤合连朴饮加减\n肝胃不和：疏肝解郁，和胃消痞，越鞠丸合枳术丸加减\n脾胃虚弱：补气健脾，升清降浊，补中益气汤加减\n胃阴不足：养阴益胃，调中消痞，益胃汤加减\n\n【处理要点】\n少食多餐，细嚼慢咽，忌暴饮暴食\n饮食清淡，忌辛辣油腻生冷\n保持情志舒畅，适当运动\n\n【护理】\n情志护理：肝胃不和者多由情志抑郁、恼怒诱发，应主动疏导劝解，嘱其戒怒解郁，可配合听舒缓音乐、静坐调息以疏肝理气；忧思伤脾致虚者宜移情易性、避免思虑过度，可引导其参与散步、园艺等分散注意力。\n病情观察：观察脘腹痞满程度、部位及有无加重，注意嗳气、泛酸、恶心呕吐、大便性状等变化；若痞满进行性加重，伴剧烈腹痛、呕血黑便、进行性消瘦，须立即报告医师，排除器质性病变。\n起居调护：劳逸结合，饭后勿立即久坐或平卧，宜缓行散步以助运化；脘腹注意保暖防受凉，虚寒者可用热水袋温熨中脘，忌贪凉露卧。\n煎药服药护理：理气、芳香化湿类药（如砂仁、木香、厚朴、豆蔻）宜后下、不宜久煎；汤药宜温服、少量频服，理气消胀药宜在两餐间或饭前服用，补益药宜饭前温服。\n外治护理：虚寒证可行中脘、足三里、脾俞温和灸或艾条悬灸，每次10～15分钟；或以丁香、吴茱萸研末敷脐（神阙穴）；食积腹胀者顺时针摩腹5～10分钟，以腹部微热为度。\n\n【饮食】\n饮食停滞：宜清淡少食，暂进米粥、藕粉等流质半流质，忌暴饮暴食、油腻厚味及糯米等难消化之品；可食山楂、萝卜，或以炒麦芽、焦山楂煎汤代茶以消食导滞。\n脾胃虚弱：少食多餐，进食温软易消化之品，如山药粥、小米莲子粥、茯苓糕、芡实；忌生冷瓜果、黏腻碍胃之品，餐后不宜立即卧床。\n肝胃不和：忌辛辣、煎炸及浓茶咖啡等刺激性饮食，恼怒时不宜进食；可饮陈皮玫瑰花茶、佛手茶疏肝理气，佐以芹菜、茼蒿、金橘等疏肝解郁之品。\n痰湿中阻：忌肥甘厚味、甜腻生痰之品（如甜食、酒类、肥肉），宜食薏苡仁、白扁豆、冬瓜、萝卜、陈皮粥等健脾化湿之品。\n胃阴不足：忌辛辣燥热、煎炸及烧烤之品，忌饮酒；宜甘凉濡润之品，如梨汁、甘蔗汁、石斛麦冬煎汤代茶，常食银耳、百合、山药以养阴和胃。\n\n【注意事项】\n痞满反复发作需胃镜排查\n老年人新发痞满伴消瘦黑便者警惕胃癌\n忌久坐久卧，饭后适当散步\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「痞满（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痞满\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肝郁气滞\n    症状舌脉：脘腹痞满胀痛，攻窜两胁，嗳气频作，食少纳呆，情志不畅则加重，舌淡红苔薄白，脉弦\n    治法：疏肝解郁、理气消痞\n    方剂：柴胡疏肝散\n\n二、饮食停滞\n    症状舌脉：脘腹胀满，嗳腐吞酸，厌食呕恶，吐出宿食后减轻，大便臭秽或秘结，舌苔厚腻，脉滑\n    治法：消食导滞、和胃降逆\n    方剂：保和丸\n\n三、脾胃虚弱\n    症状舌脉：脘腹痞闷，食后加重，食欲不振，神疲乏力，面色萎黄，大便溏薄，舌淡苔白，脉缓弱\n    治法：健脾益气、和胃消痞\n    方剂：香砂六君子汤\n\n四、寒热错杂\n    症状舌脉：心下痞满，按之柔软不痛，呕恶肠鸣，食少便溏，口干口苦，舌淡红苔黄白相兼，脉弦细数\n    治法：苦辛通降、调中和胃\n    方剂：半夏泻心汤\n\n【方剂参考】\n  柴胡疏肝散：组成 陈皮（醋炒）6g、柴胡6g、川芎4.5g、香附4.5g、枳壳（麸炒）4.5g、白芍4.5g、炙甘草1.5g；功效 疏肝解郁，行气止痛\n      用法：水煎温服，日一剂，分两次服；亦可研末为散，每服6~9g，开水送下。\n      注意：阴虚火旺、气郁化火及孕妇慎用；本方辛散，久服易耗气伤阴。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理气剂（行气）；原方出自《景岳全书·古方八阵》\n  保和丸：组成 山楂18g、神曲6g、半夏9g、茯苓9g、陈皮6g、连翘6g、莱菔子6g；功效 消食和胃\n      用法：上药为末，炊饼为丸如梧桐子大，每次6-9g，麦芽汤或温开水送服，日二至三次；亦可作汤剂。\n      注意：脾虚无食积者不宜久服（消导伤正）；孕妇慎用山楂、莱菔子；忌与滋补药同服。\n  香砂六君子汤：组成 人参9g、白术9g、茯苓9g、炙甘草6g、陈皮6g、半夏6g、木香6g、砂仁6g（后下）；功效 益气健脾，行气化痰，醒脾和胃\n      用法：加生姜3片，水煎温服，日一剂，分二次服；砂仁后下，久煎则香气耗散；亦可制丸，每次6-9g，日二次。\n      注意：阴虚火旺、胃阴不足（舌红少津）者不宜；气虚下陷而无气滞者不宜过用木香、砂仁等辛香耗气之品；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补气）；本方系六君子汤加木香、砂仁，《古今名医方论》\n  半夏泻心汤：组成 半夏12g、黄芩9g、干姜9g、人参9g、黄连3g、炙甘草9g、大枣4枚；功效 寒热平调，消痞散结\n      用法：水煎去滓，再煎浓缩，分三次温服，日一剂。\n      注意：气滞或食积所致的心下痞满不宜用；脾胃虚寒、阴虚火旺者慎用；本方为辛开苦降甘调之剂，不可一味苦寒攻下。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·和解剂（调和肠胃）；原方出自《伤寒论·辨太阳病脉证并治下》\n\n【西医诊断】\n  功能性消化不良\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"K30","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2541,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"3e061793f097d0238edbaac776e26dcc889fa719667e32cc7b068eddc217cf3c","pinyin":"piman(zhongyibianzheng)","initials":"pm(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","K30",30]]},{"id":"templates-4a85bdcbfc3fb33483e3","key":"v1-c9ccc21dfe2a3058|templates-4a85bdcbfc3fb33483e3","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痢疾(中医辨证)","category":"中医","raw":{"name":"痢疾(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】湿热痢：腹痛，里急后重，下痢赤白相杂，肛门灼热，小便短赤，舌红苔黄腻，脉滑数、疫毒痢：起病急骤，壮热口渴，头痛烦躁，甚至神昏痉厥，痢下鲜紫脓血，舌红绛苔黄燥，脉滑数、寒湿痢：腹痛拘急，痢下赤白黏冻，白多赤少，脘腹胀满，头身困重，舌淡苔白腻，脉濡缓、虚寒痢：下痢稀薄，带有白冻，甚则滑脱不禁，腹部隐痛，食少神疲，四肢不温，腰酸怕冷，舌淡苔薄白，脉沉细弱、休息痢：下痢时发时止，日久难愈，倦怠怯冷，饮食减少，舌淡苔腻，脉濡软。\n【待人工确认·本机素材无此段原文】","现病史":"痢疾是因外感时邪疫毒、内伤饮食所致，以腹痛、里急后重、下痢赤白脓血为主症的肠道传染病。分湿热痢、疫毒痢、寒湿痢、虚寒痢、阴虚痢、休息痢等证型。可见于细菌性痢疾、阿米巴痢疾等。\n常见表现：湿热痢：腹痛，里急后重，下痢赤白相杂，肛门灼热，小便短赤，舌红苔黄腻，脉滑数、疫毒痢：起病急骤，壮热口渴，头痛烦躁，甚至神昏痉厥，痢下鲜紫脓血，舌红绛苔黄燥，脉滑数、寒湿痢：腹痛拘急，痢下赤白黏冻，白多赤少，脘腹胀满，头身困重，舌淡苔白腻，脉濡缓、虚寒痢：下痢稀薄，带有白冻，甚则滑脱不禁，腹部隐痛，食少神疲，四肢不温，腰酸怕冷，舌淡苔薄白，脉沉细弱、休息痢：下痢时发时止，日久难愈，倦怠怯冷，饮食减少，舌淡苔腻，脉濡软。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以腹痛、里急后重、下痢赤白脓血为主症，肛门灼热，小便短赤，舌红苔黄腻，脉滑数，初步诊断为痢疾（ICD-10：A09），为外感时邪疫毒、内伤饮食所致肠道传染病，可见于细菌性痢疾、阿米巴痢疾等，需完善检查明确病原并评估病情严重程度。患者壮热口渴、痢下脓血，入院即刻完善血常规检查了解白细胞及中性粒细胞情况，排除感染、贫血所致；完善CRP、降钙素原检查了解炎症反应程度，评估感染严重性；大便常规加隐血检查了解脓血便程度及有无消化道出血；大便培养加药敏试验明确病原，鉴别细菌性痢疾与阿米巴痢疾，以指导抗感染用药；患者下痢赤白黏冻、小便短赤，完善电解质检查排除低钾血症等电解质紊乱；完善肾功能检查评估脱水及肾前性肾功能损害；腹部B超排除肠梗阻、腹腔脓肿等其他腹部病变；若病程迁延或需与炎症性肠病、肠道肿瘤鉴别，病情稳定后完善结肠镜检查以进一步明确诊断。患者起病急骤、壮热烦躁者警惕疫毒痢，需急诊抢救并动态监测生命体征。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 腹痛、里急后重、下痢赤白脓血为主症\n2. 大便常规+培养明确病原\n3. 疫毒痢（中毒性菌痢）需急诊抢救\n1. 痢疾(中医辨证)（ICD-10：A09）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（湿热痢）：香连丸6g tid，或葛根芩连丸3g tid\n药物2（寒湿痢）：藿香正气水10ml tid\n药物3（虚寒痢）：附子理中丸1丸 tid，或四神丸6g bid\n药物4（休息痢）：补中益气丸6g tid，或乌梅丸6g tid\n药物5（配合西药）：诺氟沙星0.4g bid（成人，遵医嘱）\n\n【治疗】\n湿热痢：清肠化湿，调气和血，芍药汤加减\n疫毒痢：清热解毒，凉血止痢，白头翁汤合芍药汤加减\n寒湿痢：温化寒湿，调气和血，胃苓汤加减\n虚寒痢：温补脾肾，收涩固脱，桃花汤合真人养脏汤加减\n休息痢：温中清肠，调气化滞，连理汤加减\n\n【处理要点】\n卧床休息，隔离治疗，餐具消毒\n流质或半流质饮食，忌生冷油腻\n注意肛周卫生，便后清洗\n\n【护理】\n严密观察大便次数、性状、色泽、气味及脓血黏液情况，记录每日排便量，判断里急后重程度；注意有无高热、神昏、抽搐等疫毒痢危象，发现异常立即报告。\n严格执行消化道隔离：餐具、便器专用并消毒，排泄物以石灰或含氯消毒剂处理，便后洗手，防止交叉感染。\n急性期卧床休息，腹部保暖防寒，虚寒痢、寒湿痢可艾灸神阙、天枢、足三里温中止痛；湿热痢、疫毒痢不宜艾灸，可予冷敷或温水擦浴降温。\n中药煎服护理：湿热痢服白头翁汤、芍药汤宜温凉小量频服，防呕防吐；虚寒痢服真人养脏汤宜温热服；服药期间忌浓茶，以免鞣质影响药效。\n加强肛周护理：便后温水清洗坐浴，勤换内衣裤，保持局部清洁干燥，防止肛周湿疹及脱肛；久痢脱肛者指导做提肛运动。\n\n【饮食】\n急性期饮食宜清淡、少渣、易消化，进流质或半流质，如米汤、藕粉、山药粥，少量多餐；忌油腻、辛辣、生冷及韭菜、芹菜等粗纤维食物。\n湿热痢忌肥甘厚味、酒类及辛辣炙煿之品，宜食马齿苋粥、薏苡仁赤小豆粥清热化湿；疫毒痢高热者可予绿豆汤、鲜梨汁清热生津。\n寒湿痢、虚寒痢忌生冷瓜果、凉拌菜，宜温热饮食，可食生姜红糖粥、白扁豆山药粥温中散寒；虚寒痢久泻者可饮乌梅煎水或石榴皮煎水涩肠止泻。\n阴虚痢忌羊肉、辣椒、葱姜蒜等辛辣燥热之品，宜滋阴润肠，可食山药莲子粥、银耳羹，配乌梅、麦冬煎汤酸甘化阴。\n休息痢缓解期忌暴饮暴食及不洁饮食，宜健脾益气，常食黄芪山药粥、莲子芡实粥，饭前便后洗手，以固肠止泻、防止复发。\n\n【注意事项】\n疫毒痢（高热、抽搐、神昏、休克）立即转急诊\n老年人、儿童腹泻易脱水，及时补液\n连续2次便培养阴性方可解除隔离\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痢疾\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、湿热内蕴\n    症状舌脉：腹痛腹泻，便下脓血黏液，里急后重，肛门灼热，身热口渴，小便短赤，舌红苔黄腻，脉滑数\n    治法：清热化湿、调气行血\n    方剂：白头翁汤合芍药汤\n\n二、脾虚湿阻\n    症状舌脉：腹泻日久，便溏夹黏液，腹痛绵绵，食少腹胀，神疲乏力，面色萎黄，肢体困重，舌淡胖有齿痕、苔白腻，脉濡缓\n    治法：健脾益气、化湿止泻\n    方剂：参苓白术散合胃苓汤\n\n三、脾肾阳虚\n    症状舌脉：久泻不愈，黎明前腹痛即泻，便下清稀或夹黏液，完谷不化，形寒肢冷，腰膝酸冷，舌淡胖苔白滑，脉沉细无力\n    治法：温补脾肾、涩肠止泻\n    方剂：四神丸合附子理中丸\n\n四、阴血亏虚\n    症状舌脉：大便干结夹少量脓血，或泻下不爽，腹中隐痛，午后潮热，心烦口干，消瘦乏力，舌红少苔，脉细数\n    治法：滋阴养血、清热止痢\n    方剂：驻车丸\n\n五、气滞血瘀\n    症状舌脉：腹痛固定拒按，便下紫暗血色，或腹部积块，面色晦暗，肌肤甲错，舌紫暗有瘀斑、苔薄，脉弦涩\n    治法：行气活血、化瘀止痛\n    方剂：少腹逐瘀汤\n\n【方剂参考】\n  芍药汤：组成 芍药30g、当归15g、黄连15g、槟榔6g、木香6g、甘草6g、大黄9g、黄芩15g、肉桂5g；功效 清热燥湿，调气和血\n      用法：水煎温服，日二次；大黄后下，肉桂宜后下或少量冲服；下痢赤多者可加白头翁、黄柏。\n      注意：虚寒痢疾、久痢滑脱者及孕妇忌用；苦寒之剂中病即止，以免伤胃。（本方黄连15g、黄芩15g超《中国药典》2020年版一部用量，系教材原方折算，临床宜酌减）\n  参苓白术散：组成 人参9g、白术9g、茯苓9g、甘草9g、山药15g、莲子肉9g、白扁豆12g、薏苡仁15g、砂仁6g、桔梗6g；功效 益气健脾，渗湿止泻\n      用法：上药为末，每次6g，以大枣汤（或温开水）调服，日二至三次；亦可作汤剂，日二次。\n      注意：湿热内盛、实热泄泻者忌用；感冒发热期间停服；本方偏温补，阴虚者慎用。\n  理中丸：组成 人参9g、干姜9g、白术9g、炙甘草9g；功效 温中祛寒，补气健脾\n      用法：上药为末，蜜丸如鸡子黄大，每次1丸，沸汤化服，日二至三次；亦可作汤剂水煎温服，或研末冲服。\n      注意：湿热内蕴、阴虚内热及外感发热者忌用；服后腹中未热者可稍加量，见热象即减停。\n  驻车丸：组成 黄连18g、干姜6g、当归9g、阿胶12g（烊化，原方用醋制阿胶）；功效 清热燥湿，养阴止痢\n      用法：水煎，阿胶烊化，温服，日一剂，分二次服；原方为丸剂，每服6-9g，日三次，米饮送下。\n      注意：痢疾初起湿热壅盛者不宜；须先明确病原（细菌性痢疾、阿米巴痢疾、溃疡性结肠炎等）并规范治疗；久痢不止伴消瘦、便血者须做肠镜检查。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·收涩剂；原方出自《备急千金要方·卷十五》\n  少腹逐瘀汤：组成 小茴香1.5g（炒）、干姜3g（炒）、延胡索3g、没药6g（研）、当归9g、川芎6g、肉桂3g、赤芍6g、蒲黄9g（生）、五灵脂6g（炒）；功效 活血祛瘀，温经止痛\n      用法：水煎温服，日一剂，分二次服；亦可研末为散，每次6g，温酒送服。\n      注意：孕妇忌用（本方原书用于安胎，须身体壮实、确有瘀血可据者，且应遵医嘱）；月经过多、有出血倾向者慎用；体虚无瘀者不宜。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《医林改错·卷下》\n\n【西医诊断】\n  溃疡性结肠炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"A09","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2542,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"032082601e43c870b33b74a563164139b14389cf692ed285db31e9127df1e250","pinyin":"liji(zhongyibianzheng)","initials":"lj(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","A09",30]]},{"id":"templates-a2a93bd3afd3938f6585","key":"v1-c9ccc21dfe2a3058|templates-a2a93bd3afd3938f6585","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痤疮(中医辨证)","category":"中医","raw":{"name":"痤疮(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肺经风热：颜面潮红，粉刺焮热疼痛，或有脓疱，伴口渴，小便黄，大便干结，舌红苔薄黄，脉浮数、湿热蕴结：皮疹红肿疼痛，或有脓疱，口臭，便秘，小便黄赤，苔黄腻，脉滑数、痰湿瘀滞：皮疹颜色暗红，以结节、囊肿、瘢痕为主，反复发作，经久难愈，舌暗红苔腻，脉弦滑。\n【待人工确认·本机素材无此段原文】","现病史":"痤疮是一种毛囊皮脂腺的慢性炎症性皮肤病，好发于颜面、胸背。分肺经风热、湿热蕴结、痰湿瘀滞等证型。\n常见表现：肺经风热：颜面潮红，粉刺焮热疼痛，或有脓疱，伴口渴，小便黄，大便干结，舌红苔薄黄，脉浮数、湿热蕴结：皮疹红肿疼痛，或有脓疱，口臭，便秘，小便黄赤，苔黄腻，脉滑数、痰湿瘀滞：皮疹颜色暗红，以结节、囊肿、瘢痕为主，反复发作，经久难愈，舌暗红苔腻，脉弦滑。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者颜面、胸背反复出现粉刺、丘疹、脓疱、结节、囊肿，皮疹红肿疼痛，或有口臭、便秘、小便黄赤，苔黄腻，脉滑数，初步诊断为痤疮（ICD-10：L70.0），属毛囊皮脂腺慢性炎症性皮肤病，一般不需特殊检查，以临床诊断为主，但需完善检查明确有无内分泌异常及继发感染。患者皮疹焮热疼痛、有脓疱，完善血常规及CRP检查排除继发细菌感染及炎症反应程度；患者病程反复、经久难愈，查性激素六项了解雄激素水平，评估有无内分泌紊乱；女性患者月经前加重者，需排查多囊卵巢综合征，完善妇科B超检查了解卵巢形态，明确有无多囊卵巢改变；完善空腹血糖及血脂检查排除代谢综合征、胰岛素抵抗所致；若需长期口服异维A酸等药物治疗，查肝肾功能及血脂四项了解肝肾功能与血脂水平，评估用药安全性，以指导用药方案；患者皮疹红肿明显、脓疱反复，完善皮损分泌物细菌培养及药敏试验明确致病菌，鉴别细菌性毛囊炎，指导抗生素选择；若皮疹以结节、囊肿为主且久治不愈，必要时完善皮肤病理活检排除其他皮肤肿瘤性疾病。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 颜面胸背粉刺、丘疹、脓疱、结节、囊肿，反复发作\n2. 一般不需特殊检查\n3. 女性月经前加重者需排查多囊卵巢综合征\n1. 痤疮(中医辨证)（ICD-10：L70.0）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肺经风热）：清热暗疮丸4粒 tid，或皮肤病血毒丸20粒 tid\n药物2（湿热蕴结）：防风通圣丸6g tid，或一清胶囊3粒 tid\n药物3（痰湿瘀滞）：大黄蛰虫丸3g bid，或血府逐瘀胶囊4粒 tid\n药物4（外治）：阿达帕林凝胶睡前涂患处，或过氧苯甲酰凝胶涂患处\n\n【治疗】\n肺经风热：疏风清肺，枇杷清肺饮加减\n湿热蕴结：清热利湿，通腑解毒，茵陈蒿汤合五味消毒饮加减\n痰湿瘀滞：除湿化痰，活血散结，二陈汤合血府逐瘀汤加减\n\n【处理要点】\n温水洗脸，避免挤压\n忌辛辣、油腻、甜食，少饮奶制品\n规律作息，避免熬夜，保持大便通畅\n\n【护理】\n情志护理：痤疮多发于面部，患者易有容貌焦虑，且情志不遂、肝气郁结可加重病情，应多倾听疏导，嘱其保持心情舒畅，忌急躁恼怒，避免郁而化火。\n起居调护：嘱规律作息、忌熬夜（熬夜耗伤阴液，虚火上炎则皮损加重）；面部以温水和温和洁面用品每日清洗1～2次，切忌用手挤压、挑刺皮疹，以防感染留疤；避免油性及遮盖性化妆品，保持枕巾、毛巾清洁。\n病情观察：观察皮损部位、色泽、形态、数量及脓头消长，注意有无红肿热痛加剧、脓液增多、发热等感染征象；肺经风热者留意额部、鼻周皮损变化，湿热蕴结者观察口苦口臭、大便干结、小便黄等伴随症，及时记录。\n煎药服药护理：肺经风热用枇杷清肺饮、湿热蕴结用茵陈蒿汤等清热方，宜饭后温服，服药期间观察有无胃脘不适；外治药如颠倒散以凉开水调成糊状均匀涂于患处，避开破损皮肤，若涂后灼热瘙痒即停用洗净并报告。\n外治护理：行中药面膜、火针、刺络放血等治疗后，治疗区24小时内保持干燥，勿沾水、勿搔抓；结痂后任其自然脱落，勿强行撕揭，痂下如有红肿渗液及时报告。\n\n【饮食】\n辨证忌口：忌辛辣刺激之品（辣椒、花椒、大蒜、酒等），以免助热生火；忌肥甘厚味及甜食（油炸食品、肥肉、奶油、奶茶、巧克力等），以免湿热内生、皮脂分泌增多；痰湿瘀滞者尤忌甜腻之品。\n适宜食物：宜食清淡、富含维生素与纤维素之品，如绿豆、冬瓜、苦瓜、黄瓜、丝瓜、芹菜、番茄、苹果、梨等，以清热利湿、通腑排毒。\n药膳食疗：肺经风热者宜饮金银花甘草茶、枇杷叶粥；湿热蕴结者宜食薏苡仁赤小豆粥、冬瓜薏米汤；痰湿瘀滞者宜食山楂陈皮饮、海带绿豆汤，坚持服用以化痰散结。\n忌食发物：少食或忌食牛羊肉、虾蟹等海鲜及公鸡等发物，以免诱发或加重皮损。\n调畅二便：多饮水，保持大便通畅（肺与大肠相表里，腑气通降则热毒得以外泄）；便秘者晨起饮温蜂蜜水或食香蕉，忌烟酒及浓茶咖啡。\n\n【注意事项】\n重度结节囊肿型痤疮需皮肤科规范治疗（异维A酸等）\n女性伴多毛、月经不调者排查内分泌\n外用药需避光（阿达帕林）\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痤疮\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肺经风热\n    症状舌脉：颜面潮红，丘疹色红，或有脓疱，痒痛，鼻息气热，口干，大便干，舌红苔薄黄，脉浮数\n    治法：疏风清肺、清热散结\n    方剂：枇杷清肺饮\n\n二、肠胃湿热\n    症状舌脉：面部丘疹红肿疼痛，或有脓疱，口臭口苦，便秘溲黄，纳呆腹胀，舌红苔黄腻，脉滑数\n    治法：清热化湿、通腑解毒\n    方剂：茵陈蒿汤合黄连解毒汤\n\n三、痰湿瘀滞\n    症状舌脉：皮损以结节、囊肿、瘢痕为主，色暗红，经久不消，或伴纳呆便溏，舌暗红苔白腻，脉弦滑\n    治法：化痰除湿、活血散结\n    方剂：海藻玉壶汤合血府逐瘀汤\n\n四、冲任失调\n    症状舌脉：皮损多在经前加重，经后减轻，伴月经不调、痛经，乳房胀痛，心烦易怒，腰膝酸软，舌淡红苔薄白，脉弦细\n    治法：调理冲任、理气散结\n    方剂：二仙汤合逍遥散\n\n【方剂参考】\n  枇杷清肺饮：组成 枇杷叶9g（包煎）、桑白皮9g、黄连6g、黄柏9g、人参6g（另煎兑服，或党参15g代）、甘草3g；功效 清肺泄热，解毒散结\n      用法：水煎，枇杷叶包煎，人参另煎兑服，温服，日一剂，分二次服。\n      注意：脾胃虚寒者忌用；黄连、黄柏苦寒，中病即止；重症痤疮（结节、囊肿）须皮肤科规范治疗；勿自行挤压以免留瘢。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·清热剂；原方出自《外科正宗·卷四》\n  黄连解毒汤：组成 黄连9g、黄芩6g、黄柏6g、栀子9g；功效 泻火解毒\n      用法：水煎温服，日二至三次；亦可为末制水丸，每次6g，温开水送服。\n      注意：苦寒伤胃，脾胃虚寒、阴虚火旺及非火毒炽盛者忌用；孕妇慎用；不宜久服，中病即止。\n  血府逐瘀汤：组成 桃仁12g、红花9g、当归9g、生地黄9g、川芎4.5g、赤芍6g、牛膝9g、桔梗4.5g、柴胡3g、枳壳6g、甘草6g；功效 活血化瘀，行气止痛\n      用法：水煎温服，日二次；亦可制为丸剂或口服液，每次10ml，日三次。\n      注意：孕妇忌用；有出血倾向（血小板减少、活动性溃疡、月经量多）者慎用；体虚无瘀者不可用。\n  逍遥散：组成 柴胡9g、当归9g、白芍9g、白术9g、茯苓9g、炙甘草4.5g、薄荷3g、生姜3g；功效 疏肝解郁，养血健脾\n      用法：上药为散，每次6-9g，加煨姜、薄荷少许煎汤送服；亦可作汤剂水煎温服，日二次。\n      注意：肝郁化火、阴虚火旺者不宜单用；月经量过多者经期慎用；忌恼怒忧思，宜配合情志调摄。\n\n【西医诊断】\n  痤疮\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L70.0","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2543,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"835d8d0be1367a3670664fcc2b7c7c363a7cad808ebcfc0fa2452d250716bd8c","pinyin":"cuochuang(zhongyibianzheng)","initials":"cc(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L70.0",30]]},{"id":"templates-2aa730092fc3ab1ae9ba","key":"v1-c9ccc21dfe2a3058|templates-2aa730092fc3ab1ae9ba","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痰饮(中医辨证)","category":"中医","raw":{"name":"痰饮(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】痰饮（胃肠）：脘腹痞满、胃中振水音、呕吐清涎与肠鸣、悬饮（胸胁）：胸胁胀痛、咳唾引痛与气短（胸腔积液）、溢饮（四肢）：肢体沉重与浮肿、无汗与恶寒、支饮（胸肺）：咳逆倚息、气短不得卧与痰多色白（哮喘与心衰）、伴随：苔白滑或白腻、脉弦滑或沉弦。\n【待人工确认·本机素材无此段原文】","现病史":"痰饮是水液代谢障碍所形成的病理产物与病证，'稠者为痰，稀者为饮'，按部位分痰饮（饮停胃肠）、悬饮（饮停胸胁）、溢饮（饮溢四肢）与支饮（饮停胸肺）四类。相当于西医胸腔积液、心包积液、慢性支气管炎与胃肠功能紊乱，治疗以温化水饮为原则。\n常见表现：痰饮（胃肠）：脘腹痞满、胃中振水音、呕吐清涎与肠鸣、悬饮（胸胁）：胸胁胀痛、咳唾引痛与气短（胸腔积液）、溢饮（四肢）：肢体沉重与浮肿、无汗与恶寒、支饮（胸肺）：咳逆倚息、气短不得卧与痰多色白（哮喘与心衰）、伴随：苔白滑或白腻、脉弦滑或沉弦。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：呼吸频率与形态、血氧、心率与体温\n胸部：呼吸动度、叩诊（浊音提示积液）、呼吸音减弱与胸膜摩擦音\n心脏：心率与心律、心音遥远与颈静脉怒张（心包积液与心脏压塞）\n腹部：脘腹痞满、振水音（胃中水饮）、肠鸣音与腹水\n四肢与水肿：肢体浮肿与沉重（溢饮）、下肢凹陷性水肿\n中医四诊：舌质与舌苔（白滑或白腻）、脉象（弦滑或沉弦）与痰的性状\n其他：体重与尿量（水饮消退评估）、肝脾大小（心衰）","辅助检查":"1. 胸部X线/CT+超声：胸腔与心包积液（部位与量）\n2. 心脏超声+BNP：心功能与心包积液（心衰与心脏压塞）\n3. 胸水检查（诊断性穿刺）：常规、生化（SAAG）、细胞学与培养（明确病因）\n4. 肝肾功能+白蛋白+电解质：低蛋白与电解质紊乱（利尿治疗）\n5. 腹部超声+胃镜：胃肠疾病与腹水\n6. 结核相关（PPD/T-SPOT与胸水ADA）：结核性胸膜炎\n7. 尿常规+尿蛋白：肾病性水肿评估","初步诊断":"1. 中医辨证分型：痰饮（饮停胃肠：苓桂术甘汤与己椒苈黄丸）、悬饮（饮停胸胁：十枣汤或葶苈大枣泻肺汤）、溢饮（饮溢四肢：小青龙汤或大青龙汤）、支饮（饮停胸肺：小青龙汤或木防己汤）\n2. 西医检查：胸部X线/CT与超声（胸腔与心包积液）、心脏超声（心功能与心包积液）、腹部超声与胃镜（胃肠疾病）与肝肾功能（低蛋白与水肿）\n3. 辨证要点：水饮内停的部位与性质（稠痰与稀饮）+ 舌苔白滑与脉弦（寒饮特征）\n4. 鉴别：水肿（水液泛溢肌肤，从头面或下肢起）与鼓胀（腹部胀大如鼓，单腹胀大）\n5. 注意：悬饮（胸腔积液）需明确病因（结核、肿瘤、感染与心衰）——不可仅用逐水方延误诊断\n6. 治疗原则：'病痰饮者当以温药和之'（温化水饮为主，慎用攻逐）\n7. 疗效评估：痰量、胸水与水肿消退（1～2周评估），必要时复查影像\n1. 痰饮(中医辨证)（ICD-10：J94.8）","鉴别诊断":"1. 鉴别：水肿（水液泛溢肌肤，从头面或下肢起）与鼓胀（腹部胀大如鼓，单腹胀大）\n2. 注意：悬饮（胸腔积液）需明确病因（结核、肿瘤、感染与心衰）——不可仅用逐水方延误诊断\n3. 悬饮（胸腔积液）必须先明确病因（结核、肿瘤、感染与心衰），不可仅用逐水方延误诊断","处理方案":"【药物治疗·输液】\n⚠️ 痰饮以中药口服为主；积液与心衰需西医治疗！\n\n方案1（胸腔积液（悬饮）与心衰（支饮））：\n 用法：呋塞米 20～40mg 静推（心衰与积液）；螺内酯 40mg 口服；必要时胸腔穿刺引流（大量积液，每次≤1000～1500ml）；白蛋白 10g 静滴（低蛋白者）\n\n方案2（感染性痰饮（肺炎旁积液与脓胸））：\n 用法：头孢曲松 2g 静滴 qd + 甲硝唑 0.5g 静滴 q8h（按药敏）；脓胸需充分引流（胸腔闭式引流）\n\n方案3（结核性胸膜炎（悬饮））：\n 用法：抗结核方案（异烟肼 0.3g + 利福平 0.45g + 吡嗪酰胺 1.5g + 乙胺丁醇 0.75g，口服为主）；必要时激素（泼尼松 30mg qd，减少胸膜增厚）\n\n方案4（支饮（哮喘与心衰）急性发作）：\n 用法：雾化吸入（布地奈德+特布他林）；甲泼尼龙 40mg 静滴 q12h（支气管痉挛）；心衰者加 硝酸甘油 5～10μg/min 泵入与吸氧\n\n📌 痰饮治疗以'温药和之'为原则（苓桂术甘汤为代表）；悬饮（胸腔积液）必须先明确病因（结核、肿瘤、感染与心衰）；攻逐水饮之剂（十枣汤）峻猛需慎用。\n\n【药物治疗·口服】\n⚠️ 中药辨证方（温化水饮为主）：\n\n药物1（中药辨证方）：\n 用法：痰饮（胃肠）——苓桂术甘汤（茯苓、桂枝、白术与甘草）或 己椒苈黄丸（攻逐）；悬饮（胸胁）——十枣汤（甘遂、大戟与芫花，研末冲服，峻剂慎用）或 葶苈大枣泻肺汤（轻证）；溢饮（四肢）——小青龙汤（温肺化饮）或 大青龙汤；支饮（胸肺）——小青龙汤或 木防己汤\n\n药物2（中成药）：\n 用法：五苓胶囊 3粒 tid（利水渗湿）；苓桂咳喘宁胶囊 4粒 tid（寒饮咳喘）；或 二陈丸 6g bid（燥湿化痰）\n\n药物3（西医对症与病因）：\n 用法：利尿剂（呋塞米 20mg qd，按医嘱）；抗结核药（结核性胸膜炎）；抗感染（感染性积液）与心衰规范治疗（沙库巴曲缬沙坦与美托洛尔）\n\n药物4（营养与支持）：\n 用法：高蛋白饮食或口服营养补充剂（低蛋白者）；复合维生素B 2片 tid；必要时白蛋白静滴\n\n📌 十枣汤等峻逐水饮方毒性大（甘遂与大戟），医师指导下短期使用（体虚与孕妇禁用）；痰饮病需温化缓图（不可一味攻逐伤正）。\n\n【治疗】\n中医治疗（核心）：温化水饮（苓桂术甘汤为代表），按部位与虚实选择（发汗、利水与攻逐三法结合）\n西医病因治疗：胸腔积液（结核、肿瘤、感染与心衰）、心包积液（心包穿刺与病因治疗）、胃肠疾病与肾病（按病因）\n积液处理：胸腔穿刺引流（中大量积液）、心包穿刺（心脏压塞）与腹腔穿刺（腹水合并者）\n针灸与艾灸：水分、阴陵泉、三阴交、足三里与脾俞（利水化湿）；艾灸关元与气海（温阳化饮）\n饮食与生活调理：清淡饮食、限制钠盐与水分（积液与水肿者）、忌生冷寒凉（助湿生痰）\n温阳扶正：脾肾阳虚者用真武汤或金匮肾气丸（温阳利水，减少复发）\n监测与评估：痰量、胸水与水肿（超声与体重）、肾功能与电解质（利尿治疗）\n宣教：痰饮为'本虚标实'（需温化缓治与扶正），避免生冷受凉与过劳、按时复查与病因治疗\n\n【处理要点】\n辨证护理：观察痰的色质量、胸胁痛与呼吸、水肿部位（辨证与用药依据）\n呼吸与体位护理：支饮者半卧位（减轻呼吸困难）、吸氧与血氧监测；悬饮者患侧卧位（减轻疼痛）\n用药护理：中药温服（温化水饮需温服）、观察峻逐水饮方的腹泻与电解质紊乱（必要时停用）\n饮食护理：清淡饮食、限制钠盐与水分（积液与水肿者）；忌生冷寒凉与肥甘厚味\n监测护理：记录痰量、尿量、体重与胸围（积液与水肿消退评估）；复查电解质（利尿治疗）\n宣教：'病痰饮者当以温药和之'（坚持温化治疗与扶正）、避免受凉与生冷饮食、按时复查影像与病因治疗\n\n【护理】\n辨证护理：观察痰量性状、胸胁痛、呼吸与水肿（辨证与用药依据）\n呼吸与体位护理：半卧位（支饮）与患侧卧位（悬饮）；吸氧与血氧监测\n用药护理：中药温服；峻逐水饮方观察腹泻与电解质紊乱（必要时停用并报告）\n饮食护理：清淡、限盐限水（积液与水肿者）、忌生冷寒凉与肥甘厚味\n监测护理：记录痰量、尿量、体重与胸围；配合复查电解质与影像\n宣教：坚持温化治疗与扶正（'温药和之'）、避免受凉与生冷、按时复查与病因治疗（抗结核与心衰治疗依从性）\n\n【饮食】\n清淡饮食、限制钠盐（每日<3g，积液与水肿者更严格）与水分（按医嘱）\n忌生冷寒凉（冰饮与生冷瓜果）、肥甘厚味与甜食（助湿生痰）\n利水化湿食物辅助：薏苡仁、赤小豆、冬瓜与白萝卜（辨证选用）\n高蛋白饮食（低蛋白与胸水者）：鱼、瘦肉、蛋与豆制品；必要时口服营养补充剂\n脾肾阳虚者：温热食物（生姜、山药与羊肉）与健脾益气食物（大枣与小米）\n\n【注意事项】\n痰饮的治疗原则是'病痰饮者当以温药和之'（温化水饮为主，慎用攻逐）\n按部位分痰饮（胃肠）、悬饮（胸胁）、溢饮（四肢）与支饮（胸肺）——治疗方剂各异\n悬饮（胸腔积液）必须先明确病因（结核、肿瘤、感染与心衰），不可仅用逐水方延误诊断\n十枣汤（甘遂、大戟与芫花）等峻逐水饮方毒性大、易致剧烈腹泻与电解质紊乱（体虚与孕妇禁用）\n痰饮本虚标实（脾肾阳虚为本，水饮为标），需温化与扶正并举（真武汤与金匮肾气丸善后）\n\n【急诊/急救】\n大量胸腔积液致严重呼吸困难 → 紧急胸腔穿刺引流（每次≤1000～1500ml）\n心脏压塞（心脏超声示心包积液伴低血压与颈静脉怒张）→ 立即心包穿刺引流（急症）\n支饮急性发作（端坐呼吸与哮鸣）→ 半卧位、吸氧、雾化支气管扩张剂与激素，必要时无创通气\n峻逐水饮药致剧烈腹泻与脱水、低钾 → 立即停药、补液与纠正电解质\n痰阻气道致窒息 → 立即吸痰、拍背与海姆立克法，必要时插管","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「痰饮（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痰饮\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、痰湿蕴肺\n    症状舌脉：咳嗽反复发作，痰多色白黏腻，晨起或食后咳甚痰多，胸闷脘痞，食少体倦，舌苔白腻，脉濡滑\n    治法：燥湿化痰、理气止咳\n    方剂：二陈汤合三子养亲汤\n\n二、痰热郁肺\n    症状舌脉：咳嗽气粗，痰多黄稠或带血，咳吐不爽，胸胁胀满，口干欲饮，身热，舌红苔黄腻，脉滑数\n    治法：清热肃肺、豁痰止咳\n    方剂：清金化痰汤\n\n三、肝火犯肺\n    症状舌脉：气逆咳嗽阵作，痰少质黏难咳，咳时面赤咽干，胸胁引痛，烦躁易怒，舌红苔薄黄，脉弦数\n    治法：清肝泻肺、顺气降火\n    方剂：黛蛤散合泻白散\n\n四、肺肾阴虚\n    症状舌脉：干咳少痰，痰黏或带血丝，口干咽燥，午后潮热，盗汗颧红，腰膝酸软，舌红少苔，脉细数\n    治法：滋补肺肾、润燥止咳\n    方剂：六味地黄丸合生脉散\n\n五、脾肾阳虚\n    症状舌脉：咳喘日久，痰白清稀量多，气短乏力，形寒肢冷，腰膝酸冷，食少便溏，夜尿频多，舌淡胖有齿痕、苔白滑，脉沉细\n    治法：温补脾肾、化痰平喘\n    方剂：金匮肾气丸合苓桂术甘汤\n\n【方剂参考】\n  二陈汤：组成 半夏15g、橘红15g、白茯苓9g、炙甘草4.5g、生姜3g、乌梅1枚；功效 燥湿化痰，理气和中\n      用法：加生姜3片、乌梅1枚，水煎温服，日二次；乌梅收敛制半夏之燥，不可随意去之。\n      注意：燥痰、血痰（痰中带血）及阴虚咳嗽（痰少而黏、舌红少津）者忌用；孕妇慎用半夏。\n  清金化痰汤：组成 黄芩9g、栀子9g、桔梗6g、麦冬9g、桑白皮9g、贝母9g、知母9g、瓜蒌仁9g、橘红6g、茯苓9g、甘草3g；功效 清肺化痰止咳\n      用法：水煎温服，日一剂，分二次服。\n      注意：寒痰、湿痰咳嗽及脾胃虚寒者忌用；黄芩、栀子苦寒，久服易伤脾胃；孕妇慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛痰剂（清热化痰）；原方出自《医学统旨》\n  泻白散：组成 地骨皮30g、桑白皮30g、甘草3g、粳米9g；功效 清泻肺热，止咳平喘\n      用法：上药为末，每次6-9g，入粳米一撮，水煎，米熟汤成，食前温服；亦可作汤剂。\n      注意：风寒咳嗽、肺寒痰白者忌用；本方清而不峻，肺热重证须配伍他药；脾胃虚弱者不宜久服。\n  生脉散：组成 人参9g、麦冬9g、五味子6g；功效 益气生津，敛阴止汗\n      用法：水煎温服，日二至三次；气阴欲脱时可频服或代茶饮，亦可服生脉口服液、注射液（急症）。\n      注意：外感表证未解、湿热内盛及实热证者忌用；五味子酸收，痰多者慎用；人参反藜芦，不宜同用。\n  肾气丸：组成 干地黄24g、山药12g、山茱萸12g、泽泻9g、茯苓9g、牡丹皮9g、桂枝3g、附子3g；功效 补肾助阳\n      用法：上药为末，炼蜜为丸如梧桐子大，每次15-25丸（约6-9g），酒或温开水送服，日二次；亦可作汤剂。\n      注意：阴虚火旺、咽干口燥、小便黄赤者忌用；感冒发热及湿热下注者不宜；孕妇慎用附子、桂枝。【别名】本方在《中医内科学》等教材与临床常称「金匮肾气丸」（《金匮要略》肾气丸），另有「八味肾气丸」「桂附地黄丸」等异名；本库《名方》收作「肾气丸（金匮肾气丸／八味肾气丸）」。来源：《金匮要略·血痹虚劳病脉证并治第六》\n\n【西医诊断】\n  慢性支气管炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"J94.8","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2544,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8802b80ab30609c7459cfd5152cad82727289053414c07f6cf8d50b8895514f8","pinyin":"tanyin(zhongyibianzheng)","initials":"ty(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","J94.8",30]]},{"id":"templates-3a6477e673c474c17cb4","key":"v1-c9ccc21dfe2a3058|templates-3a6477e673c474c17cb4","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痹证(中医辨证)","category":"中医","raw":{"name":"痹证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】风寒湿痹-行痹：肢体关节酸痛，游走不定，屈伸不利，初起可有恶风发热，舌苔薄白，脉浮、风寒湿痹-痛痹：肢体关节疼痛较剧，痛有定处，得热痛减，遇寒痛增，关节不可屈伸，舌苔薄白，脉弦紧、风寒湿痹-着痹：肢体关节重着、酸痛，或有肿胀，痛有定处，手足沉重，活动不便，肌肤麻木不仁，舌苔白腻，脉濡缓、风湿热痹：关节疼痛，局部灼热红肿，痛不可触，得冷则舒，可累及多个关节，多伴发热、恶风、口渴、烦闷不安，舌红苔黄燥，脉滑数、痰瘀痹阻：痹证日久，肌肉关节刺痛，固定不移，或关节肌肤紫暗、肿胀，按之较硬，肢体顽麻或重着，关节僵硬变形，舌紫暗苔白腻，脉弦涩、肝肾亏虚：痹证日久不愈，关节屈伸不利，肌肉瘦削，腰膝酸软，或畏寒肢冷，或骨蒸劳热，舌淡红或红，脉细弱或细数。\n【待人工确认·本机素材无此段原文】","现病史":"痹证是由于风、寒、湿、热等邪气闭阻经络，影响气血运行，导致肢体筋骨、关节、肌肉等处发生疼痛、重着、酸楚、麻木，或关节屈伸不利、僵硬、肿大、变形等症状的疾病。分风寒湿痹、风湿热痹、痰瘀痹阻、肝肾亏虚等证型。可见于风湿性关节炎、类风湿关节炎、骨关节炎、痛风等。\n常见表现：风寒湿痹-行痹：肢体关节酸痛，游走不定，屈伸不利，初起可有恶风发热，舌苔薄白，脉浮、风寒湿痹-痛痹：肢体关节疼痛较剧，痛有定处，得热痛减，遇寒痛增，关节不可屈伸，舌苔薄白，脉弦紧、风寒湿痹-着痹：肢体关节重着、酸痛，或有肿胀，痛有定处，手足沉重，活动不便，肌肤麻木不仁，舌苔白腻，脉濡缓、风湿热痹：关节疼痛，局部灼热红肿，痛不可触，得冷则舒，可累及多个关节，多伴发热、恶风、口渴、烦闷不安，舌红苔黄燥，脉滑数、痰瘀痹阻：痹证日久，肌肉关节刺痛，固定不移，或关节肌肤紫暗、肿胀，按之较硬，肢体顽麻或重着，关节僵硬变形，舌紫暗苔白腻，脉弦涩、肝肾亏虚：痹证日久不愈，关节屈伸不利，肌肉瘦削，腰膝酸软，或畏寒肢冷，或骨蒸劳热，舌淡红或红，脉细弱或细数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以肢体关节疼痛、重着、酸楚、麻木、屈伸不利、僵硬肿大为主症，痛有定处或游走不定，或有局部灼热红肿、得冷则舒，舌苔白腻或黄燥，脉弦紧或滑数，初步诊断为痹证（ICD-10：M25.5），可见于风湿性关节炎、类风湿关节炎、骨关节炎、痛风等。患者关节疼痛、肿胀，完善血沉、CRP检查了解炎症活动度及病情活动性；完善类风湿因子、抗CCP抗体检查明确有无类风湿关节炎，鉴别其他关节病变；完善尿酸检查排除痛风性关节炎所致；查关节X线检查了解关节间隙、骨质破坏及退变情况，明确病因；患者关节红肿热痛、痛不可触，完善血常规检查排除感染、贫血所致；完善关节超声检查了解关节积液、滑膜增厚情况，评估关节病变性质；若关节红肿热痛明显需除外化脓性关节炎，必要时行关节腔穿刺抽液并送检，鉴别化脓性关节炎与痛风性关节炎；若关节疼痛持续不缓解或诊断仍不明确，病情稳定后完善关节MRI检查了解软骨、滑膜、韧带等软组织情况；必要时查自身免疫抗体谱排除系统性红斑狼疮等风湿免疫性疾病。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 肢体关节疼痛、重着、麻木、屈伸不利为主症\n2. 血沉、CRP、类风湿因子、抗CCP抗体、尿酸、关节X线明确病因\n3. 关节红肿热痛急性期需除外化脓性关节炎\n1. 痹证(中医辨证)（ICD-10：M25.5）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（风寒湿痹）：风湿骨痛胶囊4粒 tid，或小活络丸1丸 bid\n药物2（风湿热痹）：四妙丸6g tid，或痛风定胶囊4粒 tid\n药物3（痰瘀痹阻）：瘀血痹胶囊4粒 tid，或追风透骨丸6g bid\n药物4（肝肾亏虚）：独活寄生丸6g bid，或壮骨关节丸6g bid\n药物5（配合）：布洛芬缓释胶囊0.3g bid（疼痛明显时，饭后服）\n\n【治疗】\n行痹：祛风通络，散寒除湿，防风汤加减\n痛痹：散寒通络，祛风除湿，乌头汤加减\n着痹：除湿通络，祛风散寒，薏苡仁汤加减\n风湿热痹：清热通络，祛风除湿，白虎加桂枝汤合宣痹汤加减\n痰瘀痹阻：化痰行瘀，蠲痹通络，双合汤加减\n肝肾亏虚：培补肝肾，舒筋止痛，独活寄生汤加减\n\n【处理要点】\n急性期关节制动，缓解期适当活动\n避风寒湿邪，注意保暖\n痛风者低嘌呤饮食忌酒，肥胖者减重\n\n【护理】\n起居调护：居处宜干燥向阳、通风避湿，忌久处潮湿阴冷之地；关节局部注意保暖，秋冬及阴雨天加护膝、护腰，避免冷水洗浴，汗出后及时擦干更衣，切忌当风受凉，以防外邪复感。\n病情观察：观察疼痛关节的部位、性质、肿胀程度、皮温皮色及活动度；风寒湿痹见遇寒痛增、得温痛减，风湿热痹见关节红肿灼热，伴发热者按时测体温，并观察口渴、汗出、心悸等兼症，防温热之邪内陷。\n外治护理：风寒湿痹可行中药熏洗、热敷、艾灸、拔罐以温经散寒，熏洗水温40～45℃，防烫伤；风湿热痹急性期关节红肿灼热者不宜艾灸、热敷，可予冷敷或清热消肿膏外敷，注意观察皮肤有无过敏破溃。\n煎药服药护理：祛风散寒除湿之品宜温服、饭后服以护胃气；方中若含制川乌、制草乌等有毒之品须先煎久煎减毒，服药后观察有无口舌麻木、心悸等反应；清热通络药宜偏凉服，药后微汗即可，忌发汗太过而耗伤正气。\n情志及功能锻炼护理：痹证病程缠绵易反复，患者多焦虑悲观，宜多加疏导鼓励，讲解调护常识以增强信心；缓解期指导循序渐进进行关节屈伸、旋转等功能锻炼，防止关节强直畸形，注意劳逸结合，勿过劳伤筋。\n\n【饮食】\n风寒湿痹：忌食生冷寒凉及肥甘厚味，如冷饮、冰镇瓜果、蟹蚌海鲜、油腻肥肉；宜食温热散寒祛湿之品，如生姜、葱白、胡椒、羊肉、薏苡仁，可佐少量黄酒温经通络。\n风湿热痹：忌辛辣燥热、肥甘厚味及发物，如辣椒、羊肉、狗肉、酒及煎炸食品、海鲜虾蟹；宜食清热祛湿之品，如薏苡仁、冬瓜、赤小豆、绿豆、丝瓜、芹菜，多饮水以助湿热下行。\n痰瘀痹阻：忌肥甘厚味、甜腻黏滞之品，以免助湿生痰碍胃；宜食活血化瘀、化痰通络之品，如山楂、黑木耳、桃仁、陈皮、萝卜，配以适量鱼类蛋白。\n肝肾亏虚：忌辛燥耗阴之品，宜食补益肝肾、强筋壮骨之品，如枸杞子、山药、核桃、黑芝麻、杜仲、牛膝、桑寄生，可与猪脊骨、牛筋炖汤食用。\n药膳食疗：风寒湿痹宜生姜羊肉汤、薏苡仁粥以温散寒湿；风湿热痹宜薏苡仁赤小豆粥、冬瓜薏米汤以清热利湿；肝肾亏虚宜杜仲牛膝猪腰汤、桑寄生鸡蛋汤，长期调养以固本培元，注意定时定量，勿过饥过饱。\n\n【注意事项】\n类风湿关节变形者早期规范治疗\n长期用激素者注意监测副作用\n关节红肿热痛伴高热需排查化脓性关节炎\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痹证\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、行痹\n    症状舌脉：肢体关节、肌肉疼痛，屈伸不利，可涉及多个关节，疼痛呈游走性，初起可见有恶风、发热等表证，舌苔薄白，脉浮或浮缓\n    治法：祛风通络、散寒除湿\n    方剂：防风汤\n\n二、痛痹\n    症状舌脉：肢体关节疼痛，痛势较剧，部位固定，遇寒则痛甚，得热则痛缓，关节屈伸不利，局部皮肤或有寒冷感，舌质淡、舌苔薄白，脉弦紧\n    治法：散寒通络、祛风除湿\n    方剂：乌头汤（乌头须制用并先煎）\n\n三、着痹\n    症状舌脉：肢体关节、肌肉酸楚、重着、疼痛，肿胀散漫，关节活动不利，肌肤麻木不仁，舌质淡、舌苔白腻，脉濡缓\n    治法：除湿通络、祛风散寒\n    方剂：薏苡仁汤\n\n四、风湿热痹\n    症状舌脉：游走性关节疼痛，可涉及一个或多个关节，活动不便，局部灼热红肿，痛不可触，得冷则舒，可有皮下结节或红斑，常伴有发热、恶风、汗出、口渴、烦躁不安等全身症状，舌质红、舌苔黄或黄腻，脉滑数或浮数\n    治法：清热通络、祛风除湿\n    方剂：白虎加桂枝汤合宣痹汤\n\n五、痰瘀痹阻\n    症状舌脉：痹证日久，肌肉关节刺痛，固定不移，或关节肌肤紫暗、肿胀，按之较硬，肢体顽麻或重着，或关节僵硬变形，屈伸不利，有硬结、瘀斑，面色黯黧，眼睑浮肿，或胸闷痰多，舌质紫暗或有瘀斑、舌苔白腻，脉弦涩\n    治法：化痰行瘀、蠲痹通络\n    方剂：双合汤\n\n六、肝肾亏虚\n    症状舌脉：痹证日久不愈，关节屈伸不利，肌肉瘦削，腰膝酸软，或畏寒肢冷，阳痿，遗精，或骨蒸劳热，心烦口干，舌质淡红、舌苔薄白或少津，脉沉细弱或细数\n    治法：培补肝肾、舒筋止痛\n    方剂：独活寄生汤。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肢体经络病证·痹证\n\n【方剂参考】\n  桂枝汤：组成 桂枝9g、芍药9g、生姜9g、大枣3枚、炙甘草6g；功效 解肌发表，调和营卫\n      用法：水煎温服，服后啜热稀粥一碗以助药力，覆被取微汗；一服汗出病瘥即停，不汗更服，不必尽剂。\n      注意：表实无汗、外感风热、温热病及酒客湿热内蕴者忌用；服药期间忌生冷、油腻、酒酪、臭恶之物。\n  双合汤：组成 桃仁9g、红花9g、当归9g、川芎6g、白芍12g、熟地黄12g、陈皮9g、半夏9g、茯苓12g、甘草3g、白芥子6g、生姜3片（本方为桃红四物汤合二陈汤加白芥；功效 化痰祛瘀，通络止痛\n      用法：水煎温服，日一剂，分二次服。\n      注意：孕妇禁用；有出血倾向者慎用；体虚无痰瘀者不宜；关节肿痛持续或畸形者须先明确诊断（类风湿关节炎、痛风等）。注：本方即本库「桃红四物汤」合「二陈汤」加白芥子，三方本库均已单列。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·祛痰剂（燥湿化痰）；原方出自《杂病源流犀烛·卷十三》（桃红四物汤合二陈汤\n  独活寄生汤：组成 独活9g、桑寄生6g、杜仲6g、牛膝6g、细辛3g、秦艽6g、茯苓6g、肉桂心6g、防风6g、川芎6g、人参6g、甘草6g、当归6g、芍药6g、干地黄6g；功效 祛风湿，止痹痛，益肝肾，补气血\n      用法：水煎温服，日二次，食前服；亦可为丸剂，每次6-9g，日二次，温酒或温开水送下。\n      注意：湿热痹证（关节红肿热痛、苔黄腻）及阴虚火旺者忌用；孕妇慎用细辛、肉桂；感冒发热期间停服。细辛药典用量1-3g，本方已减为3g，宜久煎。\n\n【西医诊断】\n  类风湿关节炎 / 骨关节炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"M25.5","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2545,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e8e1f057059057e9ea8a696c8fb4a784f8b78d6ef1ee3664ea578959fa0967aa","pinyin":"bizheng(zhongyibianzheng)","initials":"bz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","M25.5",30]]},{"id":"templates-6f9ac1ac0c7a2c959111","key":"v1-c9ccc21dfe2a3058|templates-6f9ac1ac0c7a2c959111","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"痿证(中医辨证)","category":"中医","raw":{"name":"痿证(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】肺热津伤：病起发热，或热退后突然出现肢体软弱无力，皮肤枯燥，心烦口渴，咽干咳呛少痰，小便黄少，大便干燥，舌红苔黄，脉细数、湿热浸淫：四肢痿软，身体困重，或麻木微肿，尤以下肢多见，或足胫热气上腾，发热，胸脘痞闷，小便短赤涩痛，舌红苔黄腻，脉细数、脾胃虚弱：起病缓慢，肢体痿软无力逐渐加重，食少便溏，腹胀，面浮而色不华，气短，神疲乏力，舌淡苔薄白，脉细、肝肾亏损：起病缓慢，下肢痿软无力，腰脊酸软，不能久立，或伴眩晕耳鸣，遗精遗尿，或月经不调，舌红少苔，脉细数。\n【待人工确认·本机素材无此段原文】","现病史":"痿证是指肢体筋脉弛缓、软弱无力，日久因不能随意运动而致肌肉萎缩的一种病证。分肺热津伤、湿热浸淫、脾胃虚弱、肝肾亏损等证型。可见于格林-巴利综合征、脊髓病变、重症肌无力、周期性瘫痪等。\n常见表现：肺热津伤：病起发热，或热退后突然出现肢体软弱无力，皮肤枯燥，心烦口渴，咽干咳呛少痰，小便黄少，大便干燥，舌红苔黄，脉细数、湿热浸淫：四肢痿软，身体困重，或麻木微肿，尤以下肢多见，或足胫热气上腾，发热，胸脘痞闷，小便短赤涩痛，舌红苔黄腻，脉细数、脾胃虚弱：起病缓慢，肢体痿软无力逐渐加重，食少便溏，腹胀，面浮而色不华，气短，神疲乏力，舌淡苔薄白，脉细、肝肾亏损：起病缓慢，下肢痿软无力，腰脊酸软，不能久立，或伴眩晕耳鸣，遗精遗尿，或月经不调，舌红少苔，脉细数。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以肢体筋脉弛缓、软弱无力、日久肌肉萎缩、不能随意运动为主症，或起病发热后突然出现肢体软弱无力，伴腰脊酸软、食少便溏、神疲乏力，舌淡或红，脉细数或细弱，初步诊断为痿证（ICD-10：G62.9），可见于格林-巴利综合征、脊髓病变、重症肌无力、周期性瘫痪等。患者四肢痿软无力，完善肌电图检查明确有无神经源性损害及其分布范围，评估神经受损程度；完善神经传导速度检查明确有无周围神经脱髓鞘或轴索损害，鉴别格林-巴利综合征；完善肌酶谱检查了解有无肌肉损伤，鉴别肌源性损害；完善头颅及脊髓MRI检查明确有无中枢神经系统病变所致，了解病变部位及性质；患者或伴小便短赤、麻木微肿，完善电解质检查排除低钾血症所致周期性瘫痪；查甲状腺功能检查排除甲亢性肌病、甲状腺功能减退所致肌无力；完善维生素B12及叶酸检查排除营养代谢性周围神经病；若考虑重症肌无力，完善重复神经电刺激及乙酰胆碱受体抗体检查以进一步明确诊断；若考虑格林-巴利综合征，病情稳定后完善腰椎穿刺及脑脊液检查了解有无蛋白细胞分离；患者呼吸肌受累出现呼吸困难时，急诊完善血气分析及肺功能检查，评估呼吸功能。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 肢体筋脉弛缓、软弱无力、肌肉萎缩为主症\n2. 肌电图、神经传导速度、头颅/脊髓MRI、肌酶等明确病因\n3. 呼吸肌受累（呼吸困难）立即急诊\n1. 痿证(中医辨证)（ICD-10：G62.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（肺热津伤）：养阴清肺丸1丸 tid\n药物2（湿热浸淫）：二妙丸6g tid，或四妙丸6g tid\n药物3（脾胃虚弱）：补中益气丸6g tid，或参苓白术散6g tid\n药物4（肝肾亏损）：六味地黄丸6g bid，或健步虎潜丸6g bid\n药物5（配合）：甲钴胺0.5mg tid（营养神经）\n\n【治疗】\n肺热津伤：清热润燥，养阴生津，清燥救肺汤加减\n湿热浸淫：清热利湿，通利筋脉，加味二妙散加减\n脾胃虚弱：补脾益气，健运升清，参苓白术散加减\n肝肾亏损：补益肝肾，滋阴清热，虎潜丸加减\n\n【处理要点】\n急性期卧床休息，防压疮、深静脉血栓\n缓解期积极康复训练（被动+主动运动）\n加强营养，优质蛋白饮食\n\n【护理】\n情志护理：痿证病程缠绵、恢复缓慢，患者多悲观焦虑、情志抑郁，应主动沟通开导，讲解康复前景，鼓励树立信心，避免忧思伤脾、郁怒伤肝；可辅以音乐疗法、移情易性等舒缓情绪。\n起居调护：病室宜安静通风，肢体痿软者卧床注意良肢位摆放，定时协助翻身、按摩受压部位以防压疮；下床活动者加强陪护防跌仆，病情稳定后指导循序渐进的功能锻炼（床上抬举、关节被动活动、步行训练），防止肌肉萎缩加重及关节僵硬。\n病情观察：密切观察肢体痿软程度、肌力及肌肉萎缩变化，注意有无感觉障碍；重症者重点观察呼吸肌受累征象（胸闷气促、咳嗽无力、言语低微），一旦出现呼吸困难、吞咽呛咳等危候立即报告医生；久病卧床者观察皮肤、二便情况。\n煎药服药护理：中药宜温服、分次服；补益肝肾、健脾益胃之剂宜饭前温服，清热利湿之剂宜餐后服，服药后观察有无腹胀、恶心等反应；服药期间忌浓茶、咖啡，以免影响药效。\n外治护理：遵医嘱予针灸、穴位按摩（足三里、三阴交、脾俞、肾俞、环跳等）及中药熏洗、热敷患肢，以疏通经络、濡养筋脉；操作时控制温度适宜、力度轻柔，防止烫伤及损伤痿软肢体。\n\n【饮食】\n肺热津伤者忌辛辣燥热之品（辣椒、羊肉、煎炸之品），宜食梨、甘蔗、百合、荸荠、麦冬等清热生津之品；可用百合麦冬粥、雪梨蜂蜜饮。\n湿热浸淫者忌肥甘厚味、醇酒甜腻及助湿生痰之品，宜食薏苡仁、赤小豆、冬瓜、丝瓜、黄瓜等清热利湿之品；可用薏苡仁赤豆粥、冬瓜薏米汤。\n脾胃虚弱者忌生冷、油腻、硬滞难化之物，宜食山药、芡实、小米、大枣、莲子等健脾益气之品，少食多餐；可用山药芡实粥、黄芪炖母鸡汤健脾益气。\n肝肾亏虚者忌辛辣温燥，宜食牛脊髓、猪脊髓、枸杞子、黑芝麻、核桃仁、桑葚等填精益髓、滋补肝肾之品；可用枸杞羊肾粥、杜仲炖猪腰。\n各证型均宜进高蛋白、富含维生素之品，如蛋类、瘦肉、豆制品、新鲜蔬菜，以助气血生化、肌肉充养；吞咽困难者宜软烂流质饮食，少量多次进食防呛咳。\n\n【注意事项】\n呼吸困难、吞咽困难者立即转急诊/ICU\n明确病因后针对原发病治疗（重症肌无力、GBS等）\n长期卧床者预防感染、压疮\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】痿证\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、肺热津伤\n    症状舌脉：发病急，病起发热，或热后突然出现肢体软弱无力，皮肤枯燥，心烦口渴，咳呛少痰，咽干不利，小便黄少，大便干燥，舌质红、苔黄，脉细数\n    治法：清热润燥、养阴生津\n    方剂：清燥救肺汤\n\n二、湿热浸淫\n    症状舌脉：起病较缓，逐渐出现肢体困重，痿软无力，尤以下肢或两足痿弱为甚，兼见微肿、手足麻木、扪及微热、喜凉恶热，或有发热，胸脘痞闷，小便赤涩热痛，舌质红、舌苔黄腻，脉濡数或滑数\n    治法：清热利湿、通利经脉\n    方剂：加味二妙散\n\n三、脾胃虚弱\n    症状舌脉：起病缓慢，肢体软弱无力逐渐加重，神疲肢倦，肌肉萎缩，少气懒言，纳呆便溏，面色㿠白或萎黄无华，面浮，舌淡苔薄白，脉细弱\n    治法：补中益气、健脾升清\n    方剂：参苓白术散合补中益气汤\n\n四、肝肾亏损\n    症状舌脉：起病缓慢，渐见肢体痿软无力，尤以下肢明显，腰膝酸软，不能久立，甚至步履全废、腿胫大肉渐脱，或伴有眩晕耳鸣、舌咽干燥、遗精或遗尿、妇女月经不调，舌红少苔，脉细数\n    治法：补益肝肾、滋阴清热\n    方剂：虎潜丸\n\n五、脉络瘀阻\n    症状舌脉：久病体虚，四肢痿弱，肌肉瘦削，手足麻木不仁，四肢青筋显露，可伴有肌肉活动时隐痛不适，舌痿不能伸缩，舌质暗淡或有瘀点瘀斑，脉细涩\n    治法：益气养营、活血行瘀\n    方剂：圣愈汤合补阳还五汤。来源：《中医内科学》（中国中医药出版社“十四五”规划教材）·肢体经络病证·痿证。提示：痿证须查明病因（吉兰-巴雷综合征、脊髓病变、运动神经元病等），急性进展者急诊\n\n【方剂参考】\n  清燥救肺汤：组成 桑叶9g、生石膏15g（先煎）、麦冬6g、阿胶3g（烊化）、胡麻仁3g（炒，研）、杏仁3g、枇杷叶6g（刷去毛）、人参3g、生甘草3g；功效 清燥润肺，益气养阴\n      用法：水煎温服，日一剂，分二次服；生石膏先煎，阿胶烊化兑服，胡麻仁炒研入煎。原方为「水一碗，煎六分，频频二三次滚热服」。\n      注意：外感风寒咳嗽、痰湿内盛及脾胃虚寒者忌用；本方为清燥润肺之剂，非燥热伤肺者不宜；阿胶黏腻，脾虚便溏者慎用。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·治燥剂（轻宣外燥）；原方出自《医门法律·卷四·秋燥论》\n  补中益气汤：组成 黄芪18g、炙甘草9g、人参6g、当归3g、橘皮6g、升麻6g、柴胡6g、白术9g；功效 补中益气，升阳举陷\n      用法：水煎温服，日二次，食远（饭后较久）服；亦可作丸剂，每次6-9g，日二次，姜枣汤或温开水送下。\n      注意：阴虚火旺、肝阳上亢及感冒发热者忌用（甘温易助热）；升麻、柴胡升提，高血压及气逆喘满者慎用。\n  补阳还五汤：组成 黄芪120g、当归尾6g、赤芍4.5g、地龙3g、川芎3g、桃仁3g、红花3g；功效 补气，活血，通络\n      用法：水煎温服，日二次；黄芪宜由小量（30-60g）渐增至120g，久服方效（连服1-3个月）。\n      注意：中风急性期（出血性、血压极高）及阴虚阳亢、痰热壅盛者不宜；孕妇忌用；须待血压稳定后使用。\n\n【西医诊断】\n  （请结合具体病因补充）\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"G62.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2546,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"608aa86ab07f57ad4cdf6bcdb810496721c077017422b85d52e355700e39c828","pinyin":"weizheng(zhongyibianzheng)","initials":"wz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","G62.9",30]]},{"id":"templates-a940bb179cc2525d0465","key":"v1-c9ccc21dfe2a3058|templates-a940bb179cc2525d0465","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"瘢痕增生(增生性瘢痕)","category":"烧伤整形科","raw":{"name":"瘢痕增生(增生性瘢痕)","category":"烧伤整形科","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】局限于原伤口/创面范围内的红色/暗红色隆起性瘢痕，质地较硬，表面可见毛细血管扩张；瘙痒、刺痛、灼热感（增生期明显）；关节部位可致挛缩、功能障碍（如手部瘢痕挛缩致手指活动受限、颈部瘢痕致抬头困难）；烧伤后大面积增生性瘢痕可影响外观和功能；一般在伤后1-3个月开始增生，6-12个月达高峰，之后逐渐软化消退（部分可持续数年）。。\n【待人工确认·本机素材无此段原文】","现病史":"皮肤损伤（烧伤、创伤、手术）后，胶原纤维过度增生形成的局限性瘢痕，局限于原损伤范围内，早期充血发红、瘙痒疼痛，6-12个月后可逐渐软化、变平、颜色变淡。与瘢痕疙瘩的关键区别：不超出原损伤范围、有自限性。\n常见表现：局限于原伤口/创面范围内的红色/暗红色隆起性瘢痕，质地较硬，表面可见毛细血管扩张；瘙痒、刺痛、灼热感（增生期明显）；关节部位可致挛缩、功能障碍（如手部瘢痕挛缩致手指活动受限、颈部瘢痕致抬头困难）；烧伤后大面积增生性瘢痕可影响外观和功能；一般在伤后1-3个月开始增生，6-12个月达高峰，之后逐渐软化消退（部分可持续数年）。。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"视诊：部位、范围（是否超出原损伤）、颜色（红/暗红/淡白）、厚度、表面；触诊：质地（软/中/硬）、弹性、压痛、关节活动度；瘢痕评估量表：温哥华瘢痕量表(VSS)（色素、血管性、厚度、柔软度，0-14分）；测量厚度（超声）。","辅助检查":"一般不需特殊检查；术前常规；病理（鉴别诊断时）：真皮层胶原纤维增生，排列较规则，结节状成肌纤维细胞，与瘢痕疙瘩相比玻璃样变不明显。","初步诊断":"皮肤损伤史 + 局限于原损伤范围内的增生性瘢痕 + 典型病程（增生→稳定→软化）。与瘢痕疙瘩鉴别：①范围：增生性瘢痕不超出原损伤，瘢痕疙瘩超出；②病程：增生性瘢痕有自限性（可软化），瘢痕疙瘩持续生长；③好发部位：增生性瘢痕可发生于任何部位，瘢痕疙瘩好发于胸骨前/肩背/耳垂；④病理：增生性瘢痕胶原结节状，瘢痕疙瘩玻璃样变明显。\n1. 瘢痕增生(增生性瘢痕)（ICD-10：L91.1）","鉴别诊断":"1.与瘢痕疙瘩鉴别：①范围：增生性瘢痕不超出原损伤，瘢痕疙瘩超出\n2. ⑤与瘢痕疙瘩的鉴别非常重要，因为治疗方案和预后不同","处理方案":"【药物治疗·输液】\n一般不需输液；手术（瘢痕松解/植皮）后预防感染：头孢唑林1g ivgtt 术前30分钟。\n\n【药物治疗·口服】\n【止痒】抗组胺药：氯雷他定10mg qd 或 西替利嗪10mg qd；【辅助】积雪苷片2-4片tid、曲尼司特0.1g tid（常规剂量，勿超说明书加倍）（连续6个月）；【止痛】布洛芬0.3g prn。\n\n【治疗】\n【早期预防（伤后即开始，最重要）】①硅酮制剂：硅酮凝胶/瘢痕贴，每日使用12-24小时，持续至少6个月（一线，循证证据最强）；②压力治疗：弹力套/弹力绷带，压力20-30mmHg，每日23小时以上，持续6-12个月（烧伤后瘢痕金标准）；③防晒：避免紫外线照射（加重色素沉着）。【增生期治疗】①糖皮质激素注射：曲安奈德10-20mg/ml+利多卡因，瘢痕内多点注射，每4-6周1次，3-5次一疗程；②激光治疗：脉冲染料激光（595nm，改善充血和瘙痒，每4-6周1次）、点阵激光（改善质地和厚度）；③冷冻治疗：液氮冷冻（小面积）；④5-氟尿嘧啶注射：5-FU+曲安奈德联合（难治性）。【手术治疗（功能障碍或成熟期后）】①瘢痕切除缝合（直线型、小面积）；②瘢痕松解+植皮（大面积、关节挛缩）；③皮瓣转移（功能部位、瘢痕切除后深部组织暴露）；④皮肤扩张器（大面积瘢痕，需二期手术）；⑤术后必须联合硅酮+压力+激素注射预防复发。【康复治疗】关节活动度训练、按摩（瘢痕软化后）、支具固定（预防挛缩）。\n\n【处理要点】\n【分期管理】①增生期（伤后1-6个月）：硅酮+压力+激光+激素注射，避免手术；②稳定期（6-12个月）：继续非手术治疗，评估功能；③成熟期（>12个月，瘢痕软化变白）：可考虑手术矫正功能障碍和外观。【瘢痕评估】定期使用VSS量表评估，拍照记录；【功能评估】关节活动度测量，功能障碍者尽早康复干预；【患者教育】告知瘢痕增生的自然病程（6-12个月增生，之后逐渐软化），避免焦虑；强调早期预防的重要性（伤后2周内开始硅酮和压力治疗效果最好）。\n\n【护理】\n硅酮制剂使用指导（清洁皮肤、每日12小时以上、出现皮疹暂停）；压力治疗指导（弹力套穿戴方法、压力适中、观察末梢循环）；激光术后护理（冷敷、防晒、保湿）；激素注射后观察（皮肤萎缩、色素减退）；瘙痒护理（避免搔抓、冷敷、抗组胺药）；康复训练指导（关节活动度训练）；心理支持（大面积烧伤后瘢痕的心理问题）。\n\n【饮食】\n高蛋白、富含维生素C（促进愈合）；避免辛辣刺激（加重瘙痒）；戒烟（影响血液循环和瘢痕成熟）。\n\n【注意事项】\n①增生性瘢痕有自限性，多数在6-12个月后逐渐软化，治疗目标是控制增生、预防挛缩、促进成熟；②早期预防是关键：伤后上皮化后立即开始硅酮+压力治疗，效果远好于增生后再治疗；③压力治疗是烧伤后瘢痕预防的金标准，需坚持6-12个月，每日23小时以上；④增生期（前6个月）一般不建议手术（手术刺激可加重增生），除非严重功能障碍；⑤与瘢痕疙瘩的鉴别非常重要，因为治疗方案和预后不同；⑥激光治疗（脉冲染料激光）对改善充血和瘙痒效果好，需多次治疗；⑦瘢痕成熟后（变白、变软、无瘙痒），如仍有功能障碍或外观问题，可手术矫正。\n\n【急诊/急救】\n【瘢痕挛缩急性功能障碍】关节部位瘢痕突然活动受限加重→康复评估，必要时手术松解；【瘢痕破溃感染】瘢痕表面破溃、脓性分泌物→换药+抗生素，感染控制后评估手术。","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「瘢痕增生（增生性瘢痕）」原文）"},"icd10_diagnosis":"L91.1","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2547,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"e6102c8fa37be62827081fdf937d6a015708165df4c1af137390d3fb14159e69","pinyin":"banhenzengsheng(zengshengxingbanhen)","initials":"bhzs(zsxbh)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","L91.1",30]]},{"id":"templates-7f0ec9b1ae0e4b537236","key":"v1-c9ccc21dfe2a3058|templates-7f0ec9b1ae0e4b537236","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"瘰疬(中医辨证)","category":"中医","raw":{"name":"瘰疬(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】气滞痰凝：颈项结核如豆，一粒或数粒，皮色不变，按之坚实，推之能动，不热不痛，情志抑郁，胸胁胀闷，苔薄腻，脉弦滑、阴虚火旺：结核逐渐增大，皮色转暗，与皮肤粘连，融合成块，推之不动，午后低热，盗汗，咳嗽，舌红少苔，脉细数、气血两虚：溃后脓水清稀，夹有败絮状物，疮口潜行，久不愈合，面色苍白，神疲乏力，头晕，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","现病史":"瘰疬是发于颈项、腋下等处淋巴结的慢性感染性疾病，结核累累如串珠状。分气滞痰凝、阴虚火旺、气血两虚等证型。可见于颈淋巴结结核、慢性淋巴结炎等。\n常见表现：气滞痰凝：颈项结核如豆，一粒或数粒，皮色不变，按之坚实，推之能动，不热不痛，情志抑郁，胸胁胀闷，苔薄腻，脉弦滑、阴虚火旺：结核逐渐增大，皮色转暗，与皮肤粘连，融合成块，推之不动，午后低热，盗汗，咳嗽，舌红少苔，脉细数、气血两虚：溃后脓水清稀，夹有败絮状物，疮口潜行，久不愈合，面色苍白，神疲乏力，头晕，舌淡苔薄白，脉细弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者颈项淋巴结肿大如串珠状，初起结核如豆、皮色不变、按之坚实、推之能动、不热不痛，或逐渐增大、与皮肤粘连、推之不动，伴午后低热、盗汗、咳嗽，苔薄腻，脉弦滑或细数，初步诊断为瘰疬（ICD-10：L04.9），可见于颈淋巴结结核、慢性淋巴结炎等，需完善检查明确诊断并排除肿瘤转移。患者颈项淋巴结肿大，完善淋巴结B超检查了解淋巴结大小、形态、皮髓质结构及血流情况，评估病变性质；完善结核菌素试验明确有无结核感染，必要时完善γ干扰素释放试验进一步明确结核感染；完善胸部X线检查了解有无肺结核病灶，明确有无肺结核原发灶；完善胸部CT检查进一步明确肺部病变及纵隔淋巴结情况；患者午后低热、盗汗、消瘦，完善血沉、CRP检查了解炎症活动度，评估病情活动性；患者颈项结核融合成块、推之不动，完善淋巴结穿刺细胞学检查或淋巴结活检送病理及抗酸染色检查，明确诊断，鉴别结核性淋巴结炎、淋巴瘤及肿瘤转移；完善血常规检查排除感染、贫血所致；必要时查肿瘤标志物排除肿瘤转移所致淋巴结肿大；完善肝肾功能检查了解基础脏器功能，评估抗结核治疗用药安全性；查腹部B超排除腹腔淋巴结及脏器病变。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 颈项淋巴结肿大如串珠，初起不痛不热\n2. 结核菌素试验、淋巴结B超、胸片、病理活检明确诊断\n3. 颈部淋巴结肿大需排除肿瘤转移\n1. 瘰疬(中医辨证)（ICD-10：L04.9）","鉴别诊断":"1. 颈部淋巴结肿大需排除肿瘤转移","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（气滞痰凝）：内消瘰疬丸6g tid，或夏枯草膏10g tid\n药物2（阴虚火旺）：知柏地黄丸6g bid，或六味地黄丸6g bid\n药物3（气血两虚）：八珍颗粒6g tid\n药物4（配合）：异烟肼等抗结核治疗（确诊结核时，遵医嘱）\n\n【治疗】\n气滞痰凝：疏肝理气，化痰散结，逍遥散合二陈汤加减\n阴虚火旺：滋阴降火，软坚散结，知柏地黄丸合消瘰丸加减\n气血两虚：益气养血，托毒生肌，八珍汤加减\n\n【处理要点】\n保持情志舒畅\n加强营养，忌辛辣刺激\n肿核未溃者避免挤压\n\n【护理】\n情志护理：瘰疬多因肝郁气滞、痰凝成核而发，患者常因颈部肿块外观而焦虑自卑，应疏导情志，避免恼怒忧思，指导其通过听音乐、打太极拳、养花等怡情养性，保持肝气条达；同时耐心解释病情，消除对\"恶核\"的恐惧，增强治疗信心。\n病情观察：每日观察肿块大小、数目、质地、皮色及活动度，按医嘱动态记录；注意有无红肿热痛、是否成脓破溃，破溃后观察脓液色泽、量、气味，有无形成窦道、瘘管或串珠样新发肿块，发现异常及时报告医师。\n起居调护：注意休息，避免过劳；阴虚火旺者忌劳神、熬夜、房劳过度，保证充足睡眠以养阴；颈部注意保暖防寒，衣领宜宽松柔软，避免摩擦、压迫肿块；嘱患者切勿自行挤压、挑刺肿块，以防感染扩散。\n外治护理：外敷药物（如阳和解凝膏、冲和膏）前清洁局部皮肤，观察敷药处有无皮疹、瘙痒等过敏反应；已破溃者按疮疡换药法处理，严格无菌操作，保持引流通畅，观察脓液变化，防止形成瘘管。\n煎药服药护理：疏肝解郁、化痰软坚之剂宜温服，以利药力运行；滋阴降火之剂宜文火久煎、温服，忌与辛辣、浓茶同服；服药期间观察有无胃脘不适等反应，饭前服可增强疗效。\n\n【饮食】\n肝郁气滞、痰凝者忌辛辣刺激、肥甘厚味及黏腻生痰之品（如油炸食品、肥肉、甜腻糕点），忌饮酒；宜食疏肝理气、化痰散结之品，如海带、紫菜、萝卜、荸荠、陈皮等。\n阴虚火旺者忌羊肉、狗肉、桂圆、辣椒、胡椒、酒类等辛温助火之品，忌烧烤煎炸；宜食滋阴降火之品，如银耳、百合、梨、山药、黑芝麻、枸杞等，可配百合银耳羹、麦冬粥。\n气血两虚、溃后久不收口者宜食补益气血之品，如黄芪炖鸡、当归红枣汤、瘦肉、蛋类、牛奶等，以托毒生肌、促进收口。\n药膳食疗：可用夏枯草、猫爪草煎汤代茶饮，以清肝火、软坚散结；芋艿（芋头）粥、海带牡蛎汤佐餐化痰软坚；萝卜陈皮汤理气化痰，均可作为日常调护之品。\n\n【注意事项】\n确诊淋巴结结核后规范全程抗结核治疗\n肿块增大、融合、破溃或疑肿瘤者及时活检\n随访观察治疗反应\n\n【急诊/急救】\n一般不需急救\n脓毒血症/高热寒战/神志改变：立即急诊\n疔疮走黄（火毒内陷）为危候，立即转院","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「瘰疬（中医辨证）」原文）","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】瘰疬\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、气滞痰凝（初期）\n    症状舌脉：颈项耳后结核如豆，数目不等，皮色不变，按之坚实，推之能动，不热不痛；舌淡红、苔薄白，脉弦滑\n    治法：疏肝理气、化痰散结\n    方剂：逍遥散合二陈汤加减（柴胡、当归、白芍、白术、茯苓、半夏、陈皮、夏枯草、牡蛎）\n\n二、阴虚火旺（中期）\n    症状舌脉：结核增大，与皮肤粘连，皮色暗红，微热，按之微痛，或伴午后潮热、盗汗、心烦失眠；舌红少苔，脉细数\n    治法：滋阴降火\n    方剂：知柏地黄丸加减（知母、黄柏、熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓）\n\n三、气血两虚（后期）\n    症状舌脉：溃后脓水清稀，夹有败絮样物，疮口呈潜行性空腔，伴面色㿠白、精神倦怠、头晕失眠；舌淡苔薄，脉细弱\n    治法：益气养血\n    方剂：香贝养荣汤加减（人参、白术、茯苓、当归、白芍、熟地黄、川芎、香附、贝母、陈皮）\n\n【西医诊断】\n  淋巴结结核 / 慢性淋巴结炎\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ 须与淋巴瘤、转移癌鉴别；确诊结核者须规范抗结核治疗\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L04.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2548,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5f4f7a9f6534d1b13b1def9c8758fc82c08d902881ebf1e45d152dc0e60c4eb0","pinyin":"luoli(zhongyibianzheng)","initials":"ll(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L04.9",30]]},{"id":"templates-dd325caac34251f597af","key":"v1-c9ccc21dfe2a3058|templates-dd325caac34251f597af","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"瘾疹(中医辨证)","category":"中医","raw":{"name":"瘾疹(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】风寒束表：皮疹色白，遇冷加重，得暖则减，恶寒怕冷，口不渴，苔薄白，脉浮紧、风热犯表：皮疹色红，灼热瘙痒，遇热加重，发热恶风，口渴，咽喉肿痛，苔薄黄，脉浮数、胃肠湿热：皮疹色红，瘙痒剧烈，伴脘腹疼痛，恶心呕吐，便秘或腹泻，苔黄腻，脉滑数、血虚风燥：反复发作，迁延日久，午后或夜间加剧，心烦易怒，口干，手足心热，舌红少津，脉沉细。\n【待人工确认·本机素材无此段原文】","现病史":"瘾疹是一种皮肤出现红色或苍白色风团、时隐时现的瘙痒性皮肤病，又称荨麻疹。分风寒束表、风热犯表、胃肠湿热、血虚风燥等证型。\n常见表现：风寒束表：皮疹色白，遇冷加重，得暖则减，恶寒怕冷，口不渴，苔薄白，脉浮紧、风热犯表：皮疹色红，灼热瘙痒，遇热加重，发热恶风，口渴，咽喉肿痛，苔薄黄，脉浮数、胃肠湿热：皮疹色红，瘙痒剧烈，伴脘腹疼痛，恶心呕吐，便秘或腹泻，苔黄腻，脉滑数、血虚风燥：反复发作，迁延日久，午后或夜间加剧，心烦易怒，口干，手足心热，舌红少津，脉沉细。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：局部皮损（红肿/化脓/成脓/破溃/肉芽）、舌诊（舌质/舌苔）\n闻诊：脓液气味、口气\n问诊：发病诱因、局部疼痛性质、伴随全身症状、既往史（糖尿病/免疫低下）\n切诊：局部触诊（皮温/波动感/压痛/边界）、脉诊、淋巴结检查\n辨证：疮疡辨证（善恶顺逆）、八纲辨证、气血津液辨证","辅助检查":"检查计划：患者皮肤反复出现红色或苍白色风团，时隐时现，瘙痒明显，或遇冷遇热加重，伴恶寒怕冷、发热恶风、咽喉肿痛，或伴脘腹疼痛、恶心呕吐、便秘腹泻，苔薄白或黄腻，脉浮紧或滑数，初步诊断为瘾疹（ICD-10：L50.9），即荨麻疹，多与过敏、感染及免疫因素相关。患者皮疹反复发作、瘙痒剧烈，必要时完善过敏原检测，包括血清特异性IgE及皮肤点刺试验，明确过敏原，以指导避免接触及脱敏治疗；患者皮疹色红灼热、咽痛，完善血常规及CRP检查排除感染、炎症所致；完善甲状腺功能及自身免疫抗体检查排除自身免疫性荨麻疹，鉴别甲状腺疾病相关荨麻疹；患者伴脘腹疼痛、恶心呕吐、腹泻，完善粪常规及隐血检查排除寄生虫感染及消化道疾病所致；完善幽门螺杆菌检测排除幽门螺杆菌相关慢性荨麻疹；完善肝肾功能检查了解肝肾功能，评估抗组胺药物长期用药安全性；患者反复发作、迁延日久、口干、手足心热，完善免疫球蛋白及补体检查了解免疫功能状态；若伴呼吸困难、腹痛、血压下降者，急诊完善生命体征监测及血气分析，警惕过敏性休克及内脏型荨麻疹。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 皮肤反复出现风团，色红或白，时隐时现，瘙痒\n2. 过敏原检测（必要时）\n3. 伴呼吸困难、腹痛、血压下降者警惕过敏性休克/内脏型荨麻疹\n1. 瘾疹(中医辨证)（ICD-10：L50.9）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，口服中药+外治为主\n\n方案2（感染较重/发热）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）；甲硝唑0.5g ivgtt bid\n\n方案3（糖尿病合并感染）：\n 用法：NS250ml+头孢哌酮舒巴坦2.0g ivgtt bid（皮试后），控制血糖\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（风寒束表）：荆防颗粒6g tid，或玉屏风颗粒5g tid\n药物2（风热犯表）：消风止痒颗粒6g tid，或防风通圣丸6g tid\n药物3（胃肠湿热）：防风通圣丸6g tid\n药物4（血虚风燥）：润燥止痒胶囊4粒 tid\n药物5（配合）：氯雷他定10mg qd（西药抗过敏，遵医嘱）\n\n【治疗】\n风寒束表：疏风散寒，止痒，麻黄桂枝各半汤加减\n风热犯表：疏风清热止痒，消风散加减\n胃肠湿热：疏风解表，通腑泄热，防风通圣散加减\n血虚风燥：养血润燥，祛风止痒，当归饮子加减\n\n【处理要点】\n寻找并避免过敏原\n忌辛辣海鲜发物\n瘙痒时避免搔抓，温水洗浴\n\n【护理】\n病情观察：密切观察风团出现的部位、大小、颜色、瘙痒程度及消长时间，若伴腹痛、恶心呕吐、胸闷气促、声音嘶哑，提示喉头水肿可能，须立即报告并做好抢救配合；血虚风燥者病程迁延反复，注意皮肤抓痕、破溃及继发感染情况；伴渗液水肿者准确记录出入量。\n起居调护：风寒束表者避风寒、勿当风而卧，洗澡水温不宜过高，忌热水烫洗及搔抓，修剪指甲、穿纯棉宽松衣物，勤换床单被褥；胃肠湿热者保持居处干燥通风、衣着宽松透气，避免潮湿环境诱发。\n情志护理：风团瘙痒剧烈易使患者烦躁恼怒，而恼怒伤肝、气郁化火反助风邪，宜多安慰疏导、讲解放松方法，指导患者听舒缓音乐、深呼吸转移注意力，忌忧思过度耗伤心血，以免血虚生风加重病情。\n煎药服药护理：风寒束表者汤剂宜温服、服药后加盖衣被助微汗出，忌发汗太过以防伤正；风热犯表者汤剂宜偏凉服；服药后观察皮疹是否增多或出现恶心、头晕等反应；外洗药液（如苦参、地肤子、白鲜皮煎水）水温宜40℃左右，外洗时避风，洗后及时擦干保暖。\n外治护理：瘙痒明显者可遵医嘱以中药煎水外洗或搽涂炉甘石洗剂，外洗前先行小面积试敏；嘱患者勿自行挤压抓破风团，破溃处保持清洁干燥，防止感染。\n\n【饮食】\n忌口：胃肠湿热及风热犯表者忌辛辣炙煿、肥甘厚味及酒类，忌鱼虾蟹、牛羊肉、鸡蛋、菌菇等发物，急性期尤须严格避食；风寒束表者忌生冷瓜果、冰饮，以免寒邪郁闭肌表。\n适宜食物：风热犯表者宜食清淡疏风之品，如冬瓜、丝瓜、绿豆、西瓜、芹菜、菊花茶；风寒束表者宜食温热散寒之品，如生姜、葱白、香菜、紫苏叶煮汤；胃肠湿热者宜食薏苡仁、赤小豆、白扁豆、冬瓜等清热利湿之品。\n血虚风燥及反复发作者宜食养血润燥之品，如红枣、桂圆、黑芝麻、桑椹、瘦肉、鸡蛋、菠菜，忌辛辣香燥耗血伤阴之品，并戒烟酒、浓茶、咖啡。\n药膳食疗：风寒束表者可服生姜红糖汤（生姜3片、红糖适量煎汤温服）助疏风散寒；风热者可用荆芥防风粥（荆芥、防风煎水取汁，入粳米煮粥）疏风清热；血虚者可用红枣山药粥或黄芪乌鸡汤益气养血；湿热者可用薏苡仁赤小豆粥清热利湿。\n饮食调护：饮食宜清淡、规律、少食多餐，进食宜细嚼慢咽；嘱患者记录每日饮食，留意并找出诱发风团的具体食物（如某类海鲜、香料或添加剂），反复发作期间避免盲目进补，忌食引起过敏及煎炸腌制品。\n\n【注意事项】\n伴喉头水肿（呼吸困难）立即急诊\n反复发作6周以上为慢性荨麻疹，需系统调理\n孕妇慎用抗组胺药，遵医嘱\n\n【急诊/急救】\n一般不需急救\n出现呼吸困难、喉头水肿、血压下降等过敏性休克表现时立即抢救：保持气道，肾上腺素0.3-0.5mg（1:1000）肌注可重复，按过敏性休克流程处理并急诊","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】瘾疹\n⚠️ 本条为通用辨证参考，尚未逐条核对教材原文，请务必结合患者实际四诊资料，\n   并核对相应教材（中医外科学/中医儿科学/中医内科学）后再使用；\n   方剂仅列组成药味，具体剂量请依药典、患者体质及本院药房规格确定。\n\n一、风寒束表\n    症状舌脉：风团色白，遇风寒加重，得暖则减，口不渴，冬重夏轻；舌苔薄白，脉浮紧\n    治法：疏风散寒、调和营卫\n    方剂：桂枝麻黄各半汤加减（桂枝、麻黄、白芍、杏仁、生姜、大枣、甘草）\n\n二、风热犯表\n    症状舌脉：风团鲜红，灼热剧痒，遇热加重，得冷则减，伴发热恶寒、咽喉肿痛；舌红苔薄白或薄黄，脉浮数\n    治法：疏风清热\n    方剂：消风散加减（荆芥、防风、牛蒡子、蝉蜕、苦参、苍术、石膏、知母、当归、生地黄）\n\n三、胃肠湿热\n    症状舌脉：风团色红，成块成片，瘙痒剧烈，伴脘腹疼痛、恶心呕吐、大便不爽或秘结；舌红苔黄腻，脉滑数\n    治法：疏风解表、通腑泄热\n    方剂：防风通圣散加减（防风、荆芥、连翘、麻黄、薄荷、大黄、芒硝、栀子、黄芩、石膏、滑石）\n\n四、血虚风燥\n    症状舌脉：风团反复发作，迁延日久，午后或夜间加重，伴心烦易怒、口干、手足心热；舌红少津，脉沉细\n    治法：养血祛风、润燥止痒\n    方剂：当归饮子加减（当归、川芎、白芍、生地黄、防风、荆芥、黄芪、何首乌、白蒺藜、甘草）\n\n【西医诊断】\n  荨麻疹\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n⚠️ **出现呼吸困难、喉头水肿、血压下降须立即急诊**（过敏性休克）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"L50.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2549,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"8f1b3e87f8e90ae2ab74b1c9ff9eeba794767f56a4e42cd7754fbf1c8ca03eb2","pinyin":"yinzhen(zhongyibianzheng)","initials":"yz(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","L50.9",30]]},{"id":"templates-e90ed5c48f5fbbcc3647","key":"v1-c9ccc21dfe2a3058|templates-e90ed5c48f5fbbcc3647","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"癃闭(中医辨证)","category":"中医","raw":{"name":"癃闭(中医辨证)","category":"中医","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】膀胱湿热：小便点滴不通，或量极少而短赤灼热，小腹胀满，口苦口黏，或口渴不欲饮，舌红苔黄腻，脉数、肺热壅盛：小便不畅或点滴不通，咽干口燥，烦渴欲饮，呼吸急促，或有咳嗽，舌红苔薄黄，脉数、肝郁气滞：小便不通或通而不爽，胁腹胀满，多烦善怒，舌红苔薄黄，脉弦、浊瘀阻塞：小便滴沥不畅，或尿如细线，或阻塞不通，小腹胀满疼痛，舌紫暗或有瘀点，脉涩、脾气不升：时欲小便而不得出，或量少而不爽利，气短声低，小腹坠胀，食少便溏，舌淡苔薄白，脉细弱、肾阳衰惫：小便不通或点滴不爽，排出无力，面色晄白，神气怯弱，畏寒肢冷，腰膝冷而酸软无力，舌淡苔白，脉沉细而尺弱。\n【待人工确认·本机素材无此段原文】","现病史":"癃闭是以小便量少、排尿困难、甚则小便闭塞不通为主症的肾系病证。分膀胱湿热、肺热壅盛、肝郁气滞、浊瘀阻塞、脾气不升、肾阳衰惫等证型。可见于前列腺增生、尿潴留、神经源性膀胱等。\n常见表现：膀胱湿热：小便点滴不通，或量极少而短赤灼热，小腹胀满，口苦口黏，或口渴不欲饮，舌红苔黄腻，脉数、肺热壅盛：小便不畅或点滴不通，咽干口燥，烦渴欲饮，呼吸急促，或有咳嗽，舌红苔薄黄，脉数、肝郁气滞：小便不通或通而不爽，胁腹胀满，多烦善怒，舌红苔薄黄，脉弦、浊瘀阻塞：小便滴沥不畅，或尿如细线，或阻塞不通，小腹胀满疼痛，舌紫暗或有瘀点，脉涩、脾气不升：时欲小便而不得出，或量少而不爽利，气短声低，小腹坠胀，食少便溏，舌淡苔薄白，脉细弱、肾阳衰惫：小便不通或点滴不爽，排出无力，面色晄白，神气怯弱，畏寒肢冷，腰膝冷而酸软无力，舌淡苔白，脉沉细而尺弱。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压\n望诊：神、色（青/赤/黄/白/黑）、形态、头面、五官、躯体、舌诊（舌质/舌苔/舌底络脉）、排泄物\n闻诊：声音（语声/呼吸/咳嗽/呃逆/嗳气/肠鸣）、气味\n问诊：一般情况、主诉、现病史、既往史、个人史、家族史、十问歌\n切诊：脉诊（浮沉迟数虚实滑涩洪细濡弱弦紧结代促）、按诊（肌肤/手足/胸腹/腧穴）\n辨证：八纲辨证、脏腑辨证、气血津液辨证、经络辨证","辅助检查":"检查计划：患者以小便量少、排尿困难、点滴不通、甚则闭塞不通为主症，或尿如细线、小腹胀满疼痛，伴口苦口黏、腰膝酸软、畏寒肢冷，舌红苔黄腻或舌淡苔白，脉数或沉细，初步诊断为癃闭（ICD-10：R33），可见于前列腺增生、尿潴留、神经源性膀胱等。患者排尿困难、小腹胀满，完善泌尿系B超检查了解双肾、输尿管、膀胱及前列腺形态，评估有无前列腺增生及尿潴留程度；完善膀胱残余尿量测定明确排尿功能障碍程度，判断有无尿潴留，以指导是否需要导尿；患者老年男性，完善PSA检查排除前列腺癌所致排尿困难；患者小便量少，完善肾功能检查排除肾后性肾功能损害，评估肾功能受损程度；完善尿常规检查排除尿路感染、血尿所致；患者小便短赤灼热、点滴不通，完善尿培养加药敏试验明确有无尿路感染并指导抗感染用药；完善电解质检查排除电解质紊乱所致排尿障碍；必要时完善尿动力学检查评估膀胱逼尿肌功能，明确有无神经源性膀胱；若需进一步明确梗阻部位及病因，完善泌尿系CT或MRI水成像检查以进一步明确诊断；完善空腹血糖及糖化血红蛋白检查排除糖尿病神经源性膀胱所致；若膀胱极度充盈、急性尿潴留，需立即导尿并监测肾功能变化。\n\n（检查清单）\n【待人工确认·本机素材无此段原文】","初步诊断":"1. 小便量少、排尿困难、闭塞不通为主症\n2. B超测残余尿量、PSA、肾功能等明确病因\n3. 急性尿潴留（膀胱极度充盈）需立即导尿\n1. 癃闭(中医辨证)（ICD-10：R33）","鉴别诊断":"【待人工确认·本机素材无此段原文】","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1：\n 用法：一般不需输液，以口服中药为主\n\n方案2（症状较重/脱水明显）：\n 用法：NS500ml+维生素C2.0g+维生素B6 0.2g ivgtt qd\n\n方案3（合并细菌感染）：\n 用法：NS250ml+头孢呋辛3.0g ivgtt bid（皮试后）\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n药物1（膀胱湿热）：三金片4片 tid，或热淋清颗粒8g tid\n药物2（浊瘀阻塞）：前列舒通胶囊4粒 tid，或前列康片4片 tid\n药物3（肾阳衰惫）：金匮肾气丸6g bid，或前列舒丸6g bid\n药物4（脾气不升）：补中益气丸6g tid\n药物5（配合）：坦索罗辛0.2mg qn（前列腺增生，遵医嘱）\n\n【治疗】\n膀胱湿热：清利湿热，通利小便，八正散加减\n肺热壅盛：清肺泄热，通利水道，清肺饮加减\n肝郁气滞：疏利气机，通利小便，沉香散加减\n浊瘀阻塞：行瘀散结，通利水道，代抵当丸加减\n脾气不升：升清降浊，化气行水，补中益气汤合春泽汤加减\n肾阳衰惫：温补肾阳，化气利水，济生肾气丸加减\n\n【处理要点】\n急性尿潴留立即导尿\n避免憋尿，保持大便通畅\n前列腺增生者注意保暖，避免久坐饮酒\n\n【护理】\n情志护理：肝郁气滞证者多因情志抑郁、恼怒诱发或加重，宜耐心疏导、分散注意力，避免情绪激动；久病或反复导尿者易焦虑自卑，多安慰鼓励，帮助树立信心、配合治疗。\n病情观察：准确记录24小时出入量、排尿次数、每次尿量及尿色性状，观察小腹胀满、尿潴留程度；膀胱高度充盈者切忌强力按压排尿，以防膀胱破裂，必要时遵医嘱导尿，并做好导尿管护理——保持引流通畅、会阴部清洁，观察尿液有无浑浊、血丝、絮状物。\n外治与诱导排尿：遵医嘱采用温水冲洗会阴、听流水声、热敷或顺时针轻揉小腹膀胱区等诱导排尿；膀胱湿热者可配合中药坐浴或保留灌肠，肾阳衰惫者可用艾灸关元、气海、中极等穴温阳助气化，针刺阴陵泉、三阴交等需由专业人员操作并观察针后反应。\n起居调护：注意腰腹及下肢保暖，避免受凉、憋尿，养成定时排尿习惯；肺热壅盛者居室宜凉爽通风、多饮温水（心衰或肾功能不全者按医嘱控制水量），脾肾气虚者勿过劳、忌久站久坐及负重，节制房事，睡前少饮水以免夜尿困扰。\n煎药服药护理：利尿通淋之剂宜温服，服后观察排尿量及小腹胀满变化；含木通、关木通等苦寒或毒性之品须遵医嘱小量、短程使用并密切观察；峻下逐水药宜晨起空腹小量频服、记录泻下量，补益之剂宜饭前温服，理气药宜饭后服。\n\n【饮食】\n膀胱湿热证：忌辛辣、肥甘厚味、酒类及煎炸烧烤之品（如辣椒、羊肉、油炸食物），以免助湿生热；宜清淡利湿，如冬瓜汤、赤小豆薏苡仁粥、绿豆汤，可用车前草、玉米须煎水代茶频饮。\n肺热壅盛证：忌煎炸、辛辣燥热之品（如狗肉、生姜、胡椒过量），以免加重肺热；宜清肺利水之品，如雪梨、荸荠、白茅根茶，鼓励适量多饮水以通调水道。\n肝郁气滞证：忌滋腻碍胃、产气过多之品，宜疏肝理气之食，如陈皮、佛手、玫瑰花茶、白萝卜汤；进食宜细嚼慢咽，避免边进食边生气郁怒。\n脾气不升证与肾阳衰惫证：忌生冷寒凉及过咸之品（如冷饮、凉拌菜、咸腌制品）；脾气虚者宜山药、莲子、芡实、粳米粥健脾益气，肾阳虚者宜温补肾阳，如羊肉、韭菜、核桃、桂圆炖汤，可配合核桃仁山药粥食疗。\n浊瘀阻塞证：忌肥甘厚腻及生冷之品，以免痰浊瘀血凝结加重梗阻；宜活血散结之食，如山楂、桃仁粥、黑木耳、海带，并适量饮水、适当活动以助气血运行。\n\n【注意事项】\n反复尿潴留、血尿、PSA升高者转泌尿外科\n肾功能不全者密切监测肌酐尿素氮\n禁用阿托品类药物（加重尿潴留）\n\n【急诊/急救】\n一般不需急救\n症状加重伴休克/昏迷：立即急救处理\n反复发作/黑便/消瘦：转上级医院进一步检查","资料来源":"疾病库 diseases.json","中医辨证参考":"首次病程记录\n\n拟诊讨论：\n\n【中医辨证参考】癃闭\n（本页列出该病常见证型，请根据患者实际四诊资料选择相应证型，切勿直接套用）\n\n一、湿热下注\n    症状舌脉：小便频数短赤，灼热涩痛，尿有余沥，小腹胀满，口苦口黏，大便秘结，舌红苔黄腻，脉滑数\n    治法：清热利湿、通利小便\n    方剂：八正散\n\n二、气滞血瘀\n    症状舌脉：小便点滴而下，尿线变细，排尿困难，小腹胀痛，会阴部刺痛，舌暗红有瘀斑、苔薄，脉弦涩\n    治法：行气活血、通窍利尿\n    方剂：代抵当丸\n\n三、脾肾气虚\n    症状舌脉：小便频数不畅，夜间尤甚，尿后余沥不尽，神疲乏力，气短懒言，纳少腹胀，舌淡胖有齿痕、苔薄白，脉细弱\n    治法：健脾补肾、益气利尿\n    方剂：补中益气汤合济生肾气丸\n\n四、肾阳虚衰\n    症状舌脉：小便不通或点滴不爽，排尿无力，腰膝酸冷，畏寒肢冷，面色㿠白，神疲嗜睡，舌淡胖苔白，脉沉细弱\n    治法：温补肾阳、化气行水\n    方剂：济生肾气丸\n\n【方剂参考】\n  八正散：组成 车前子9g、瞿麦9g、萹蓄9g、滑石9g、山栀子9g、甘草9g、川木通6g、大黄9g；功效 清热泻火，利水通淋\n      用法：上药为末，每次6-9g，加灯心草（或竹叶）煎汤送服，食后临卧服；亦可作汤剂，日二次。\n      注意：孕妇忌用；脾胃虚寒、久病体弱及无湿热者不宜；木通苦寒，肾功能不全者慎用，不宜久服。木通须用川木通；关木通含马兜铃酸、已禁用，肾功能不全者慎用。\n  代抵当丸：组成 大黄12g（酒洗）、芒硝9g、桃仁9g（研）、当归尾9g、生地黄12g、穿山甲（现禁用，代以皂角刺9g、王不留行9g）、肉桂3g（后下）；功效 活血化瘀，通络攻下\n      用法：水煎，芒硝冲服，肉桂后下，温服，日一剂，分二次服；原方为丸剂，每服6-9g。\n      注意：孕妇禁用；体虚无瘀、年老体弱者忌用；有出血倾向者慎用；穿山甲自2020年起《中国药典》不再收载、禁止药用，本方以皂角刺、王不留行替代；大黄、芒硝峻下，中病即止。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·理血剂（活血祛瘀）；原方出自《证治准绳·类方》；穿山甲替代依《中国药典》2020年版\n  补中益气汤：组成 黄芪18g、炙甘草9g、人参6g、当归3g、橘皮6g、升麻6g、柴胡6g、白术9g；功效 补中益气，升阳举陷\n      用法：水煎温服，日二次，食远（饭后较久）服；亦可作丸剂，每次6-9g，日二次，姜枣汤或温开水送下。\n      注意：阴虚火旺、肝阳上亢及感冒发热者忌用（甘温易助热）；升麻、柴胡升提，高血压及气逆喘满者慎用。\n  济生肾气丸：组成 熟地黄15g、山茱萸12g、山药12g、泽泻9g、茯苓9g、牡丹皮9g、炮附子6g（先煎）、肉桂3g、川牛膝9g、车前子9g（包煎）；功效 温肾化气，利水消肿\n      用法：上药为末，炼蜜为丸，每次6-9g，日二至三次，温开水或淡盐汤送服；亦可作汤剂，附子先煎、车前子包煎，水煎温服。\n      注意：阴虚火旺、湿热壅盛及外感发热者不宜；孕妇慎用附子、肉桂、牛膝；本方含附子，须久煎，用量宜遵医嘱。来源：《方剂学》（中国中医药出版社“十四五”规划教材）·补益剂（补阳）；本方系肾气丸加川牛膝、车前子，原方出自《济生方》卷四\n\n【西医诊断】\n  良性前列腺增生\n  （西医诊断依据与鉴别诊断请结合患者病史、体征、辅助检查补充）\n\n医师签名：＿＿＿＿"},"icd10_diagnosis":"R33","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2550,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"5f2c1337add1045b4c2455a4a0d18605cb115b5f4c813946d91cd441e94689b3","pinyin":"longbi(zhongyibianzheng)","initials":"lb(zybz)","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源","中医辨证参考"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源 中医辨证参考",30],["主要诊断编码","R33",30]]},{"id":"templates-82112687636da8bcd75b","key":"v1-c9ccc21dfe2a3058|templates-82112687636da8bcd75b","module":"templates","moduleKey":"v1-c9ccc21dfe2a3058|templates","version":"v1-c9ccc21dfe2a3058","title":"癫痫急性发作","category":"鉴别诊断速查","raw":{"name":"癫痫急性发作","category":"鉴别诊断速查","case":{"case_name":"门诊病历","templates":{"主诉":"【疾病库原文】全面强直-阵挛发作：意识丧失、全身抽搐、口吐白沫、牙关紧闭、尿失禁、失神发作：突发愣神、动作中止（儿童多见）、部分性发作：局部抽搐/感觉异常，可泛化、发作后嗜睡、头痛、肌肉酸痛、反复发作。\n【待人工确认·本机素材无此段原文】","现病史":"既往有癫痫病史，有抽搐，口吐白沫，大小便失禁等症状，头颅CT及脑电图可鉴别。\n常见表现：全面强直-阵挛发作：意识丧失、全身抽搐、口吐白沫、牙关紧闭、尿失禁、失神发作：突发愣神、动作中止（儿童多见）、部分性发作：局部抽搐/感觉异常，可泛化、发作后嗜睡、头痛、肌肉酸痛、反复发作。\n【待人工确认·本机素材无此段原文】","既往史":"【待人工确认·本机素材无此段原文】","个人史及过敏史":"【待人工确认·本机素材无此段原文】","体格检查":"生命体征：体温、脉搏、呼吸、血压（注意呼吸节律变化）\n一般情况：神志（清醒/嗜睡/昏睡/浅昏迷/深昏迷）、精神状态、言语（流利/失语/构音障碍）、体位\n颅神经检查：Ⅰ嗅神经、Ⅱ视力视野眼底、ⅢⅣⅥ眼球运动瞳孔（大小/对光反射/调节反射）、Ⅴ面部感觉咀嚼肌、Ⅶ面肌运动（中枢性/周围性面瘫）、Ⅷ听力前庭、ⅨⅩ吞咽咽反射、Ⅺ转颈耸肩、Ⅻ伸舌（偏斜/肌萎缩/纤颤）\n运动系统：肌力（0-5级）、肌张力（增高/降低）、肌萎缩、不自主运动（震颤/舞蹈样/手足徐动）、共济运动（指鼻试验/跟膝胫试验/轮替试验/Romberg征）、姿势步态\n感觉系统：浅感觉（痛觉/触觉/温度觉）、深感觉（位置觉/振动觉）、复合感觉（实体觉/图形觉/两点辨别觉）\n反射：浅反射（腹壁反射/提睾反射）、深反射（肱二头肌/肱三头肌/桡骨膜/膝腱/跟腱反射，亢进/减弱/消失）、病理征（Babinski征/Chaddock征/Oppenheim征/Gordon征）\n脑膜刺激征：颈强直、Kernig征、Brudzinski征\n自主神经：皮肤温度/湿度/营养、括约肌功能、直立性低血压","辅助检查":"1. 头颅MRI（3.0T，含海马冠状位薄层扫描）：新发癫痫或首次评估时完善，排查海马硬化、皮质发育不良、占位等结构性病因；急性期疑脑出血/外伤者优先行头颅CT\n2. 长程视频脑电图（24小时，含睡眠期）：明确发作类型、定位致痫灶，抗癫痫药物调整前及发作间期完成；疑心因性非癫痫发作时同步录像对照\n3. 常规脑电图（清醒+剥夺睡眠诱发，必要时加蝶骨电极）：药物复查或随访时评估痫样放电及背景活动变化\n4. 血液检查（血常规、肝肾功能、电解质钠钙镁、血糖、血气分析）：入院24小时内完成，排查代谢性/感染性诱因，并作为抗癫痫药物用药前基线\n5. 脑脊液检查（常规+生化+病原学，必要时自身免疫性脑炎抗体谱）：疑颅内感染、自身免疫性脑炎或新发难治性癫痫持续状态时尽早行腰穿\n6. 血药浓度监测及遗传学检测：服用丙戊酸、卡马西平、苯妥英钠者定期监测血药浓度；难治性癫痫或疑遗传性癫痫综合征者行癫痫相关基因panel","初步诊断":"1. 目击发作描述（最重要）\n2. 脑电图（EEG，可见痫样放电）\n3. 头颅MRI（查找病因）\n4. 血糖、电解质、血钙（排除代谢性）\n5. 心电图（排除晕厥）\n6. 肝肾功能（用药前基线）\n1. 癫痫急性发作（ICD-10：G40.9）","鉴别诊断":"1. 既往有癫痫病史，有抽搐，口吐白沫，大小便失禁等症状，头颅CT及脑电图可鉴别\n2. 诊断要点：既往有癫痫病史，有抽搐，口吐白沫，大小便失禁等症状，头颅CT及脑电图可鉴别。","处理方案":"【药物治疗·输液】\n⚠️ 方案选择提示：请根据患者病情选择以下其中一种或几种方案，切勿全部同时使用！\n\n方案1（癫痫持续状态）：\n 用法：地西泮 10mg 静推（<2mg/min），可重复\n\n方案2（后续）：\n 用法：丙戊酸钠（负荷量15-30mg/kg，静推速度≤6mg/kg/min）后维持（1-2mg/kg/h），或左乙拉西坦（负荷量40-60mg/kg，滴速≤5mg/kg/min，肾功能不全者减量）静滴，或苯妥英钠（负荷量15-20mg/kg，滴速≤50mg/min）\n\n方案3：\n 用法：甘露醇（脑水肿）\n\n方案4：\n 用法：0.9%氯化钠 静滴\n\n📌 用药前请核对药品名称、剂量、浓度、给药途径、滴速，确认无过敏史。\n\n【药物治疗·口服】\n⚠️ 用药选择提示：请根据患者病情选择以下药物，同类药物选择一种即可，切勿重复用药！\n\n药物1（部分性发作）：\n 用法：卡马西平 0.1g bid、奥卡西平、拉莫三嗪\n\n药物2（全面强直阵挛）：\n 用法：丙戊酸钠 0.2g tid、拉莫三嗪、托吡酯\n\n药物3（失神发作）：\n 用法：乙琥胺/丙戊酸钠\n\n药物4（广谱）：\n 用法：丙戊酸钠、拉莫三嗪、左乙拉西坦、托吡酯\n\n📌 用药前请核对药品名称、剂量、用法、疗程，确认无药物过敏史和禁忌症。\n\n【治疗】\n明确诊断后规范抗癫痫药物治疗\n单药起始，小剂量开始，逐渐加量\n单药无效可联合用药\n规律服药，不可自行停药/减药\n持续状态：地西泮静推+维持\n病因治疗（肿瘤、血管畸形等）\n难治性癫痫可手术/生酮饮食/迷走神经刺激\n\n【处理要点】\n规律服药，不可漏服或自行停药\n避免诱因：熬夜、饮酒、闪光刺激、漏服药\n禁止从事高空作业、驾驶、游泳（发作控制前）\n发作时：侧卧、头偏一侧、不要塞东西到嘴里、不要按压肢体\n记录发作日记\n定期复查脑电图、肝肾功能、血药浓度\n停药需在完全无发作2-5年后，在医生指导下逐渐减量\n\n【护理】\n发作期应急：发作时保护头部、移开床旁危险物品，置开口器或牙垫防舌咬伤，不强行按压肢体；抽搐停止后立即取侧卧位或头偏向一侧，清理口鼻分泌物防误吸\n意识瞳孔评估：每次发作后评估意识恢复程度、瞳孔大小及对光反射，记录发作时间、诱因、形式与频率；发作持续＞5分钟或发作间期意识未恢复时，考虑癫痫持续状态，立即报告并备好地西泮等急救药物\n安全防护：使用床栏防坠床，床旁避免放置锐器，洗浴、如厕需专人陪护，防跌倒；发作频繁者避免单独活动\n用药与依从性：指导规律服药、不可自行停药或减量，观察皮疹、共济失调、肝功能损伤等药物不良反应并及时报告\n心理与康复护理：缓解患者及家属对发作的恐惧，安排规律作息、避免熬夜及过度劳累，指导记录发作日记\n\n【饮食】\n吞咽评估：发作频繁或持续状态发作后先评估吞咽功能，意识完全恢复、无呛咳后方可进食；吞咽障碍者暂禁食，予留置胃管鼻饲\n进食方式：少量多餐，避免过饱或过饥、避免一次性大量饮水，进食清淡易消化的软食或半流质\n忌口：禁辛辣刺激食物，忌浓茶、咖啡、酒精及含兴奋成分饮品；服用丙戊酸期间绝对禁酒\n营养推荐：均衡膳食，保证钙、镁及B族维生素摄入；难治性癫痫患儿可遵医嘱在营养科指导下试用生酮饮食（需监测血酮、血脂及肝肾功能）\n药物与饮食配伍：抗癫痫药物与牛奶、葡萄柚汁间隔1小时以上服用，避免影响吸收；营养不良或长期鼻饲者评估营养支持，必要时肠内营养制剂补充\n\n【注意事项】\n【鉴别要点】既往有癫痫病史，有抽搐，口吐白沫，大小便失禁等症状，头颅CT及脑电图可鉴别。\n癫痫持续状态（>5min或反复发作意识不恢复）是急症，可致死致残\n不要在发作时往嘴里塞任何物品（可致牙齿损伤/误吸）\n不要用力按压抽搐肢体（可致骨折）\n丙戊酸钠育龄期女性需注意致畸风险\n拉莫三嗪需缓慢加量（防皮疹）\n【来源】字段对齐库内同名基础条目，未新增医学内容（核查报告_B B-H1/B-H2/B-M12 修复）\n\n【急诊/急救】\n癫痫持续状态（抽搐>5min或反复发作意识不恢复）→立即急诊，地西泮10mg静推","资料来源":"疾病库 diseases.json；鉴别诊断库 ddx_local.json（条目「癫痫急性发作」原文）"},"icd10_diagnosis":"G40.9","icd10_secondary":[],"icd9cm3_procedure":[]}},"locator":{"file":"门诊住院病历模板/病历模板包_全部_20261111.json","arrayRow":2551,"caseRow":1},"sourceHash":"10e4fdb435986b7b85f847c3951d0cb0eafdce0f372c5617949c05b337149194","contentHash":"35b814b91ff941ef4eda89fc5652ede6c703132ffd08a5a23e70b08f756d8ea8","pinyin":"dianxianjixingfazuo","initials":"dxjxfz","setting":"out","caseName":"门诊病历","templateNames":["主诉","现病史","既往史","个人史及过敏史","体格检查","辅助检查","初步诊断","鉴别诊断","处理方案","资料来源"],"emptyTemplates":[],"escapedNewlines":[],"quickFields":[["病例名称","门诊病历",60],["模板名称","主诉 现病史 既往史 个人史及过敏史 体格检查 辅助检查 初步诊断 鉴别诊断 处理方案 资料来源",30],["主要诊断编码","G40.9",30]]}]);